# ---------------------------------------------------------------------
# Hourly Adventure-topic status update — separate from the "meanwhile"
# ambient heartbeat above (which only fires during long idle stretches).
# This one posts every real hour, regardless of activity, at whichever
# location the most recently active real player currently occupies:
# a short AI-narrated flavor beat (recent events + who's doing what)
# followed by a plain, deterministic readout (player counts, quest
# board) that never passes through the model — see narrate_hourly_
# update's docstring for why that split matters.
#
# _RECENT_WORLD_EVENTS is a rolling in-memory log (combat victories,
# level-ups, quest completions) tagged with the location they happened
# at; entries older than two update cycles are pruned on every append
# so this never grows unbounded. In-memory only, same reasoning as
# _DEFEATED_NPCS/_NPC_LOCATIONS — it's recap texture, not a game fact
# anything else depends on.
# ---------------------------------------------------------------------
HOURLY_UPDATE_INTERVAL_SECONDS = getattr(config, "HOURLY_UPDATE_INTERVAL_SECONDS", 3600)
# Chat-scoped (2026-08-01 Phase 2, made real Phase 4b) -- each tenant
# chat has its own independent "have I already fired this hour" gate,
# set from the real chat_id _maybe_post_hourly_status_update is called
# with per chat (see _idle_inactivity_loop).
_LAST_HOURLY_UPDATE_AT: dict[int, datetime] = {}
# Which clock hour (US Eastern, "%Y-%m-%d %H") the update last fired for —
# e.g. "2026-07-10 05" — so it lands on the top of the hour rather than
# drifting to whatever offset the bot process happened to start at.
EASTERN_TZ = ZoneInfo("America/New_York")
_LAST_HOURLY_UPDATE_BUCKET: dict[int, str] = {}
# 2026-08-01 Phase 2, made real Phase 4b: chat-scoped -- each tenant's
# own recent-events recap shouldn't include another tenant's combat
# victories/level-ups. Every real caller (a session/character/update in
# hand, or the background loop's own per-chat iteration) passes its own
# chat_id explicitly now.
_RECENT_WORLD_EVENTS: dict[int, list[tuple[datetime, str, str]]] = {}


def _log_world_event(location_id: str | None, text: str, chat_id: int | None = None) -> None:
    if not location_id:
        return
    chat_id = chat_id if chat_id is not None else _LAST_KNOWN_CHAT_ID
    now = datetime.now(timezone.utc)
    events = _RECENT_WORLD_EVENTS.setdefault(chat_id, [])
    events.append((now, location_id, text))
    cutoff = now.timestamp() - (HOURLY_UPDATE_INTERVAL_SECONDS * 2)
    events[:] = [e for e in events if e[0].timestamp() >= cutoff]


def _npc_currently_wanders(npc_id: str) -> bool:
    """
    Real bug fixed 2026-07-15 (Coffee): Sarah (sera_wanderer) is both
    `can_wander` AND `recruitable` in campaign.json, so the living-
    world wander tick was relocating her randomly around the map --
    exactly like any other wanderer -- making her genuinely unfindable
    at the location a player would look for her to recruit. A
    recruitable NPC needs to be reliably findable until recruited, so
    recruitable always wins over can_wander here: once actually
    recruited, an NPC becomes a real AI companion character that moves
    with the party through normal travel, not the wander system, so
    this exclusion only ever matters pre-recruitment anyway.
    """
    data = CAMPAIGN["npcs"].get(npc_id, {})
    return bool(data.get("can_wander")) and not data.get("recruitable")


def _wanderable_npc_ids() -> list[str]:
    return [npc_id for npc_id in CAMPAIGN["npcs"] if _npc_currently_wanders(npc_id)]


def _seed_npc_locations(chat_id: int | None = None) -> None:
    """Gives each wanderable NPC a real starting location, from wherever campaign.json first placed them."""
    chat_id = chat_id if chat_id is not None else _LAST_KNOWN_CHAT_ID
    locations = _chat_scoped_dict(_NPC_LOCATIONS, chat_id)
    for npc_id in _wanderable_npc_ids():
        if npc_id in locations:
            continue
        for layer_locations in CAMPAIGN["locations"].values():
            for loc_id, loc in layer_locations.items():
                if npc_id in loc.get("npcs", []):
                    locations[npc_id] = loc_id
                    break
            if npc_id in locations:
                break


def _npcs_at_location(location_id: str, chat_id: int | None = None) -> list[str]:
    """Fixed NPCs still listed in campaign.json for this location, plus any wanderers currently here."""
    chat_id = chat_id if chat_id is not None else _LAST_KNOWN_CHAT_ID
    location = cl.get_location(CAMPAIGN, location_id)
    static_npcs = [
        n for n in (location.get("npcs", []) if location else [])
        if not _npc_currently_wanders(n)
    ]
    locations = _chat_scoped_dict(_NPC_LOCATIONS, chat_id)
    wandering_here = [npc_id for npc_id, loc_id in locations.items() if loc_id == location_id]
    return static_npcs + wandering_here


def _wander_npcs(chat_id: int | None = None) -> None:
    chat_id = chat_id if chat_id is not None else _LAST_KNOWN_CHAT_ID
    # Self-healing seed (Phase 4b): setup_default_npcs() only seeds
    # chats known at startup -- a tenant chat that registers later (via
    # /set_topic) would otherwise never get its wanderers placed at all.
    # _seed_npc_locations is idempotent per NPC, so this is a cheap no-op
    # for any chat that's already seeded.
    _seed_npc_locations(chat_id)
    locations = _chat_scoped_dict(_NPC_LOCATIONS, chat_id)
    for npc_id in _wanderable_npc_ids():
        if random.random() > NPC_WANDER_CHANCE_PER_CYCLE:
            continue
        current_loc_id = locations.get(npc_id)
        if not current_loc_id:
            continue
        location = cl.get_location(CAMPAIGN, current_loc_id)
        connections = list(location.get("connections", [])) if location else []
        if not connections:
            continue
        locations[npc_id] = random.choice(connections)


OLLAMA_CONGESTION_LOAD_THRESHOLD = 12.0

# Real wall-clock circuit breaker (2026-07-24, see _post_narrated's and
# _resolve_ai_turns's docstrings): bounds how long a single player action
# can ever take waiting on AI-turn narration, regardless of AI turn count
# or whether load average happens to catch the contention.
#
# Real live report (2026-08-12, Coffee: "i am also not seeing banter
# still in battles"): this was originally set to 45.0 the day it shipped
# (v1.27.9), before real per-call Ollama latency on this hardware was
# ever measured -- CLAUDE.md's own documented post-migration baseline is
# ~46-73s typical, up to 160s+. A single real narration call almost
# always exceeded 45s by itself, and since this budget is ONE wall-clock
# deadline for the entire AI-turn-resolution sequence (every AI turn
# until a real player is up again), that meant only the very FIRST
# AI-narrated attack of a whole round could ever reach a real narration
# call (and therefore the enemy-banter roll inside it, task #9) -- every
# subsequent enemy attack in the same round was guaranteed to fall back
# to the plain template, confirmed via direct reproduction. Raised to
# 180.0: still a firm multiple below the original "HOURS" runaway-chain
# incident this breaker exists to prevent (an unbounded chain, not a
# 3-4x headroom over one real call), but enough for 2-3 typical real
# calls to land inside a single round instead of at most one.
AI_TURN_NARRATION_BUDGET_SECONDS = 180.0

# Enemy battle banter (2026-08-09, task #9, see _post_narrated): fraction
# of enemy-side attacks that roll a short in-character taunt/tease/coax
# line woven into the existing narration call. Deliberately well under
# 1.0 -- every enemy attack getting a quip would turn a fun surprise
# into noise, on top of the extra generation cost per real occurrence.
ENEMY_BANTER_CHANCE = 1 / 3


def _ollama_congested() -> bool:
    """
    Real live finding (2026-07-23): this box has exactly one Ollama
    generation slot (-np 1) shared by every real player, the autonomous
    AI party, hourly updates, AND any background test/simulation run --
    with no fairness/backpressure between them, sustained heavy demand
    from all of them at once can stack up into a single action taking
    HOURS to resolve (each individual 200s-timeout narration call gives
    up cleanly, but there's no limit on how many separate calls end up
    competing for the one slot in sequence). Load average is a cheap,
    real proxy for "is something already straining this shared
    resource" -- used to skip PURELY discretionary narration (nobody is
    actually blocked waiting on an ambient NPC line or an hourly-update
    flavor post) so it doesn't add to that same queue. Never gates a
    real player's own direct action -- only background flavor no one
    would notice going quiet for a while.
    """
    try:
        return os.getloadavg()[0] > OLLAMA_CONGESTION_LOAD_THRESHOLD
    except OSError:
        return False


async def _maybe_post_world_heartbeat(bot, chat_id: int) -> None:
    """
    "The world keeps living while everyone's away" — if real players
    have been quiet for a long stretch, narrate one small, grounded
    beat of NPC activity at wherever the last active/resting player
    actually is, so checking back in feels like a place that kept
    going, not a paused game. Never invents anything beyond a real
    NPC's real current location and their own listed activity_goals.

    Phase 4b: takes an explicit chat_id (the background loop calls this
    once per chat in db.get_all_chat_ids(), see _idle_inactivity_loop)
    rather than relying on the single-chat _LAST_KNOWN_CHAT_ID global --
    every query below is scoped to this one chat's own characters.
    """
    if _ollama_congested():
        return  # purely discretionary flavor -- not worth adding to an already-strained shared queue

    now = datetime.now(timezone.utc)
    with db.get_connection() as conn:
        row = conn.execute(
            "SELECT MAX(last_active_at) AS m FROM characters WHERE is_ai = 0 AND is_deleted = 0 AND chat_id = ?",
            (chat_id,),
        ).fetchone()
    if not row or not row["m"]:
        return  # nobody has ever actually played in this chat — nothing to be "meanwhile" about
    idle_for = (now - datetime.fromisoformat(row["m"])).total_seconds()
    if idle_for < WORLD_HEARTBEAT_IDLE_THRESHOLD_SECONDS:
        return
    last_heartbeat = _LAST_WORLD_HEARTBEAT_AT.get(chat_id)
    if last_heartbeat and (now - last_heartbeat).total_seconds() < WORLD_HEARTBEAT_MIN_GAP_SECONDS:
        return

    with db.get_connection() as conn:
        row = conn.execute(
            "SELECT current_location FROM characters WHERE is_ai = 0 AND is_deleted = 0 AND chat_id = ? "
            "ORDER BY last_active_at DESC LIMIT 1",
            (chat_id,),
        ).fetchone()
    location_id = row["current_location"] if row else SAFE_LOCATION_FALLBACK

    npcs_here = _npcs_at_location(location_id, chat_id)
    if not npcs_here:
        return

    location_name = cl.get_location(CAMPAIGN, location_id)["name"]
    update_like = _ChatOnlyUpdate(bot, chat_id)

    if len(npcs_here) >= 2:
        npc_a, npc_b = random.sample(npcs_here, 2)
        npc_a_data, npc_b_data = CAMPAIGN["npcs"][npc_a], CAMPAIGN["npcs"][npc_b]
        line = await asyncio.to_thread(
            generate_ambient_line, npc_a, npc_b_data["name"],
            f"has just crossed paths with {npc_b_data['name']} here at {location_name}, with no one else around",
        )
        speaker_name = npc_a_data["name"]
    else:
        npc_id = npcs_here[0]
        npc_data = CAMPAIGN["npcs"][npc_id]
        activity = random.choice(npc_data.get("activity_goals", ["going about their day"]))
        line = await asyncio.to_thread(
            generate_ambient_line, npc_id, npc_data["name"],
            f"is {activity}, alone at {location_name}",
        )
        speaker_name = npc_data["name"]

    if not line:
        return
    _LAST_WORLD_HEARTBEAT_AT[chat_id] = now
    await _safe_send(update_like, f"🕯️ *(meanwhile, at {location_name})*\n💬 **{speaker_name}:** {line}")


def _find_location_for_monster(monster_key: str) -> tuple[str, dict] | None:
    """
    Real-data grounding for task #75: a world-boss announcement must
    name a REAL location that monster is actually native to (campaign.
    json's own location.monsters list), never an invented one --
    CAMPAIGN["locations"] is layered (surface/underground), so this
    searches both.
    """
    for layer_locations in CAMPAIGN["locations"].values():
        for location_id, location in layer_locations.items():
            if monster_key in location.get("monsters", []):
                return location_id, location
    return None


async def _maybe_spawn_world_boss(bot) -> None:
    """
    Task #75, per Coffee: "World events: rare world-boss spawns broadcast
    server-wide." Persisted via db.get_setting/set_setting (not an
    in-memory dict) so an active world boss survives a bot restart --
    same reasoning as task #159's persisted-pending-state work. Gated on
    BOTH a minimum real-time gap since the last spawn AND a low random
    roll on top of that, so it stays rare and unpredictable rather than
    firing like clockwork the instant the gap elapses. Never spawns a
    second boss while one is still out there unresolved.

    Phase 4b note: game_settings (where this is persisted) was a
    deliberate exclusion from the chat_id retrofit -- a single shared
    process-wide toggle store, not per-tenant gameplay state (see
    sequential-tinkering-quokka.md). This event is genuinely
    bot-process-wide, not per-chat, so it stays a single global boss
    rather than looping per chat; it announces to this bot's own real
    home chat (config.TELEGRAM_CHAT_ID) rather than the old
    _LAST_KNOWN_CHAT_ID global, which could silently redirect a
    server-wide announcement to whichever tenant chat happened to speak
    last. True per-tenant world bosses are a real future design
    question, not something this fix invents an answer for.
    """
    home_chat_id = getattr(config, "TELEGRAM_CHAT_ID", None)
    if home_chat_id is None:
        return
    if db.get_setting("active_world_boss"):
        return  # one's already out there -- resolve it before another can spawn

    now = datetime.now(timezone.utc)
    last_spawn_raw = db.get_setting("world_boss_last_spawn_at")
    if last_spawn_raw:
        elapsed = (now - datetime.fromisoformat(last_spawn_raw)).total_seconds()
        if elapsed < WORLD_BOSS_MIN_GAP_SECONDS:
            return
    if random.random() >= WORLD_BOSS_SPAWN_CHANCE_PER_TICK:
        return

    monster_key = random.choice(WORLD_BOSS_MONSTER_KEYS)
    found = _find_location_for_monster(monster_key)
    if found is None:
        return  # defensive -- campaign data changed out from under WORLD_BOSS_MONSTER_KEYS
    location_id, location = found
    template = cl.get_monster_template(CAMPAIGN, monster_key)
    if template is None:
        return

    db.set_setting("active_world_boss", json.dumps({
        "monster_key": monster_key, "location_id": location_id, "spawned_at": now.isoformat(),
    }))
    db.set_setting("world_boss_last_spawn_at", now.isoformat())

    update_like = _ChatOnlyUpdate(bot, home_chat_id)
    await _safe_send(
        update_like,
        f"🌍 **World Event!** A monstrous **{template['name']}** ({template['hp_max']} HP) has been "
        f"spotted at **{location['name']}** — head there and attack it to challenge it. "
        f"Whoever brings it down earns a real bonus on top of the usual spoils!",
        thread_id=_MAIN_TOPIC_SEND,
    )


async def _maybe_post_hourly_status_update(bot, chat_id: int) -> None:
    """
    Posts an hourly status update to Adventure: a short AI-narrated
    flavor beat (recent events + who's doing what) at whichever
    location the most recently active real player actually occupies IN
    THIS CHAT, followed by a plain factual readout (player counts, quest
    board) that never passes through the model — see narrate_hourly_
    update's docstring for why that split matters. Fires at the top of
    every real hour in US Eastern time (e.g. 5:00, 6:00 — within the
    ~60s granularity of the background loop this runs in), regardless
    of activity level, unlike _maybe_post_world_heartbeat above, which
    only fires during long idle stretches. Gated on an hour-bucket
    string rather than "N seconds since last fire" specifically so it
    lands on the clock hour instead of drifting to whatever offset the
    bot happened to start at.

    Phase 4b: takes an explicit chat_id (the background loop calls this
    once per chat in db.get_all_chat_ids()) -- every query below is
    scoped to this one chat's own characters/sessions/events.
    """
    now = datetime.now(timezone.utc)
    current_hour_bucket = datetime.now(EASTERN_TZ).strftime("%Y-%m-%d %H")
    if _LAST_HOURLY_UPDATE_BUCKET.get(chat_id) == current_hour_bucket:
        return

    # Real live bug (2026-07-18, Coffee: "What is happening here we were
    # in battle?!"): this used to fire unconditionally at the top of
    # every real hour with no regard for what was actually happening in
    # Adventure -- confirmed live it landed mid-combat (two goblins
    # still alive at 2/7 HP) and posted unrelated ambient flavor plus a
    # player-count/quest-board readout right in the middle of the fight,
    # with nothing to indicate combat was still ongoing. Deliberately
    # does NOT update _LAST_HOURLY_UPDATE_BUCKET when skipping for this
    # reason (unlike every other skip below, which commits the bucket
    # regardless) -- this retries every ~60s on the next background-loop
    # tick until combat actually ends, rather than silently losing that
    # hour's update entirely.
    if sessions.get_session(chat_id) is not None:
        return

    # Joined through active_characters so a player's old, no-longer-played
    # characters (from the character-slots feature — switching to a new
    # active character never deletes the old one) can't be counted here.
    # Without this join, an abandoned character's stale is_inactive flag
    # gets counted alongside real, currently-played characters, skewing
    # both numbers — confirmed as a real bug 2026-07-10 via code review
    # after Coffee reported the inactive count reading low.
    with db.get_connection() as conn:
        active_row = conn.execute(
            """
            SELECT COUNT(*) AS n FROM characters c
            JOIN active_characters a ON a.character_id = c.character_id
            WHERE c.is_ai = 0 AND c.is_deleted = 0 AND c.is_inactive = 0 AND c.chat_id = ?
            """,
            (chat_id,),
        ).fetchone()
        inactive_row = conn.execute(
            """
            SELECT COUNT(*) AS n FROM characters c
            JOIN active_characters a ON a.character_id = c.character_id
            WHERE c.is_ai = 0 AND c.is_deleted = 0 AND c.is_inactive = 1 AND c.chat_id = ?
            """,
            (chat_id,),
        ).fetchone()
        # Per Coffee's request (2026-07-14): AI players should count too,
        # not just real humans -- the design philosophy (CLAUDE.md) is
        # that AI-driven and human players sit at the same table under
        # the same rules, so the world's own reported player count
        # shouldn't quietly exclude half the table.
        ai_active_row = conn.execute(
            """
            SELECT COUNT(*) AS n FROM characters c
            JOIN active_characters a ON a.character_id = c.character_id
            WHERE c.is_ai = 1 AND c.is_deleted = 0 AND c.chat_id = ?
            """,
            (chat_id,),
        ).fetchone()
        last_active_row = conn.execute(
            """
            SELECT c.current_location FROM characters c
            JOIN active_characters a ON a.character_id = c.character_id
            WHERE c.is_ai = 0 AND c.is_deleted = 0 AND c.chat_id = ?
            ORDER BY c.last_active_at DESC LIMIT 1
            """,
            (chat_id,),
        ).fetchone()

    # Commit to firing this cycle regardless of what's found below —
    # an hour with nothing to report still gets a (quiet) update, and
    # either way we don't want to re-check every 60s until the next hour.
    _LAST_HOURLY_UPDATE_AT[chat_id] = now
    _LAST_HOURLY_UPDATE_BUCKET[chat_id] = current_hour_bucket

    if not last_active_row:
        return  # nobody has ever played — nothing to report on

    location_id = last_active_row["current_location"] or SAFE_LOCATION_FALLBACK
    location_data = cl.get_location(CAMPAIGN, location_id)
    location_name = location_data["name"] if location_data else location_id

    active_count = active_row["n"] if active_row else 0
    inactive_count = inactive_row["n"] if inactive_row else 0
    ai_active_count = ai_active_row["n"] if ai_active_row else 0

    cutoff = now.timestamp() - HOURLY_UPDATE_INTERVAL_SECONDS
    recent_events = [
        text for (when, loc, text) in _RECENT_WORLD_EVENTS.get(chat_id, [])
        if loc == location_id and when.timestamp() >= cutoff
    ]

    activity_lines = []
    for npc_id in _npcs_at_location(location_id, chat_id):
        npc_data = CAMPAIGN["npcs"].get(npc_id)
        if not npc_data:
            continue
        if npc_data.get("can_wander"):
            activity = random.choice(npc_data.get("activity_goals", ["going about their business"]))
            activity_lines.append(f"{npc_data['name']} is {activity}")
        else:
            role = (npc_data.get("role") or "").replace("_", " ")
            activity_lines.append(f"{npc_data['name']} is here, as always" + (f" ({role})" if role else ""))

    with db.get_connection() as conn:
        ai_companions = conn.execute(
            "SELECT name, race, char_class FROM characters "
            "WHERE is_ai = 1 AND is_deleted = 0 AND current_location = ? AND chat_id = ?",
            (location_id, chat_id),
        ).fetchall()
    for comp in ai_companions:
        activity_lines.append(f"{comp['name']} the {comp['race']} {comp['char_class']} is here")

    story_quests_here = [
        (q["title"], q.get("description", ""))
        for q in CAMPAIGN["quests"].values()
        if q.get("location") == location_id
    ]
    area_board_quests = board_quests_module.get_or_generate_all_board_quests(CAMPAIGN, location_id, chat_id)

    if _ollama_congested():
        # Same reasoning as _maybe_post_world_heartbeat -- no one's
        # blocked waiting on this post, so skip straight to the real
        # deterministic fallback rather than adding another 200s
        # attempt to an already-strained shared Ollama slot.
        flavor = _fallback_hourly_update(location_name, recent_events, activity_lines)
    else:
        flavor = await asyncio.to_thread(narrate_hourly_update, location_name, recent_events, activity_lines)

    lines = [f"🕐 *(the hour turns over — {location_name})*", flavor, ""]
    total_active = active_count + ai_active_count
    ai_note = f" ({ai_active_count} AI)" if ai_active_count else ""
    lines.append(f"👥 Players: {total_active} active{ai_note}, {inactive_count} resting.")
    lines.append(f"📋 Quest board at {location_name}:")
    if not story_quests_here and not area_board_quests:
        lines.append("  nothing posted right now.")
    for title, desc in story_quests_here:
        lines.append(f"  • {title} — {desc}" if desc else f"  • {title}")
    if area_board_quests:
        lines.append(board_quests_module.format_board_listings(area_board_quests))

    update_like = _ChatOnlyUpdate(bot, chat_id)
    await _safe_send(update_like, "\n".join(lines))


async def _maybe_check_moltbook_activity(bot) -> None:
    """
    Polls Moltbook's GET /api/v1/home on a timer, per Moltbook's own
    heartbeat.md guidance for agents, and pings the Development topic
    when there's new activity on PandoraMMO_Bot's profile — a comment,
    a DM request, anything worth a human's attention.

    Deliberately does NOT reply on Moltbook itself. That's a public
    reply under the project's name to a stranger's comment — a human
    call, not something a background loop should decide unsupervised.

    Phase 4b note: this is one shared bot-wide Moltbook profile, not a
    per-tenant concept, so it deliberately always notifies this bot's
    own real home chat (config.TELEGRAM_CHAT_ID) rather than looping
    per chat or trusting the old _LAST_KNOWN_CHAT_ID global, which
    could silently redirect this to whichever tenant chat spoke last.
    """
    global _LAST_MOLTBOOK_CHECK_AT, _LAST_MOLTBOOK_NOTIFIED_SIGNATURE
    api_key = getattr(config, "MOLTBOOK_API_KEY", None)
    home_chat_id = getattr(config, "TELEGRAM_CHAT_ID", None)
    if not api_key or home_chat_id is None:
        return

    now = datetime.now(timezone.utc)
    if _LAST_MOLTBOOK_CHECK_AT and (now - _LAST_MOLTBOOK_CHECK_AT).total_seconds() < MOLTBOOK_HEARTBEAT_INTERVAL_SECONDS:
        return
    _LAST_MOLTBOOK_CHECK_AT = now

    try:
        resp = await asyncio.to_thread(
            requests.get,
            "https://www.moltbook.com/api/v1/home",
            headers={"Authorization": f"Bearer {api_key}"},
            timeout=30,
        )
        resp.raise_for_status()
        data = resp.json()
    except Exception as e:
        logger.error(f"[moltbook_heartbeat] request failed: {e!r}")
        return

    account = data.get("your_account", {})
    unread = account.get("unread_notification_count", 0) or 0
    activity = data.get("activity_on_your_posts") or []
    dms = data.get("your_direct_messages") or {}
    pending_dms = dms.get("pending_requests") or dms.get("unread") or []

    # Confirmed live (2026-07-11): Coffee reported "we keep getting
    # notifications from Moltbook in Dev topic" every ~15 minutes. Root
    # cause -- this used to suppress only on `unread <= last_notified_count
    # and not activity and not pending_dms`, but activity_on_your_posts
    # stays populated across heartbeats (nothing here ever marks a post's
    # notifications "seen" on Moltbook's side), so `not activity` was
    # False on almost every check, bypassing the suppression and
    # re-sending the SAME activity/DM list over and over forever. Fixed
    # by comparing a full signature of the actual content (not just the
    # raw unread count) against what was last notified, so it only fires
    # again when something in it has genuinely changed.
    signature = (
        unread,
        tuple(sorted((item.get("post_id") or item.get("title"), item.get("new_notification_count"))
                     for item in activity)),
        tuple(sorted(str(d) for d in pending_dms)),
    )
    if signature == _LAST_MOLTBOOK_NOTIFIED_SIGNATURE:
        return

    lines = [f"🦞 Moltbook: {unread} unread notification(s) for PandoraMMO_Bot."]
    for item in activity[:5]:
        title = item.get("title") or item.get("post_id") or "a post"
        count = item.get("new_notification_count")
        lines.append(f"- New activity on \"{title}\" ({count} new)")
    if pending_dms:
        lines.append(f"- {len(pending_dms)} pending DM request(s) — needs your review before any reply goes out")
    lines.append("Check: https://www.moltbook.com/u/PandoraMMO_Bot")

    try:
        await bot.send_message(
            chat_id=home_chat_id,
            message_thread_id=topics.thread_id_for(home_chat_id, "development"),
            text="\n".join(lines),
        )
        # Only recorded as "notified" once the send actually succeeds —
        # otherwise a transient TimedOut here would mark this activity as
        # already-seen and it would never be retried on a later heartbeat.
        _LAST_MOLTBOOK_NOTIFIED_SIGNATURE = signature
    except TelegramError as e:
        logger.error(f"[moltbook_heartbeat] failed to notify Development topic: {e!r}")


MOLTBOOK_SOCIAL_TICK_INTERVAL_SECONDS = getattr(config, "MOLTBOOK_SOCIAL_TICK_INTERVAL_SECONDS", 1800)
_LAST_MOLTBOOK_SOCIAL_TICK_AT: datetime | None = None


async def _maybe_run_moltbook_social_tick(bot) -> None:
    """
    PandoraMMO_Bot's own autonomous participation on Moltbook -- posting,
    commenting, and upvoting on its own, per Coffee's explicit direction
    (2026-07-11): full autonomy, no human review before publishing. This
    was a deliberate, informed choice he made after the tradeoff was laid
    out directly (irreversible public posts under the project's real
    name, with no review step) -- not an oversight or a default.

    At most ONE action per tick (matching _ai_party_autonomous_tick's
    same reasoning: never flood, and a bounded blast radius even under
    full autonomy). Grounded strictly in the real feed just fetched from
    Moltbook and this game's own real recent activity (_RECENT_WORLD_
    EVENTS) -- ai/moltbook_agent.py's parser treats anything that
    doesn't cleanly match one of its four exact response formats as
    "skip", never guessing at a partial or malformed action.
    """
    global _LAST_MOLTBOOK_SOCIAL_TICK_AT
    api_key = getattr(config, "MOLTBOOK_API_KEY", None)
    if not api_key:
        return
    # 2026-07-14: a live pause switch (Development-topic "turn off
    # moltbook social"), on by default (missing setting == enabled) so
    # existing always-on behavior is unchanged unless explicitly paused.
    if db.get_setting("moltbook_social_enabled") == "0":
        return

    now = datetime.now(timezone.utc)
    if _LAST_MOLTBOOK_SOCIAL_TICK_AT and (now - _LAST_MOLTBOOK_SOCIAL_TICK_AT).total_seconds() < MOLTBOOK_SOCIAL_TICK_INTERVAL_SECONDS:
        return
    _LAST_MOLTBOOK_SOCIAL_TICK_AT = now

    try:
        feed_posts = await asyncio.to_thread(moltbook.get_feed, "new", 15)
    except Exception as e:
        logger.error(f"[moltbook_social] feed fetch failed: {e!r}")
        return

    # Phase 4b: grounds on real recent activity across every known chat
    # (not just whichever one last spoke, per the old _LAST_KNOWN_CHAT_ID
    # global) -- Moltbook is one shared bot-wide presence, so "this
    # game's own real recent activity" should reflect the whole game,
    # not just one tenant.
    cutoff = now.timestamp() - MOLTBOOK_SOCIAL_TICK_INTERVAL_SECONDS
    recent_activity = [
        text
        for chat_id in db.get_all_chat_ids()
        for (when, _loc, text) in _RECENT_WORLD_EVENTS.get(chat_id, [])
        if when.timestamp() >= cutoff
    ]

    decision = await asyncio.to_thread(decide_social_action, feed_posts, recent_activity)
    action = decision.get("action")
    if action == "skip":
        # Logged deliberately, even though there's nothing to act on --
        # without this, "no moltbook_social log lines" is ambiguous
        # between "ran fine and chose not to act" and "never actually
        # ran at all" (e.g. the idle loop silently failing before
        # reaching this call). A tick that ran and chose skip should
        # look different from a tick that never happened.
        logger.info(f"[moltbook_social] tick ran, {len(feed_posts)} feed post(s) considered, decided: skip")
        return

    try:
        if action == "upvote_post":
            await asyncio.to_thread(moltbook.upvote_post, decision["post_id"])
            logger.info(f"[moltbook_social] upvoted post {decision['post_id']!r}")
        elif action == "comment_post":
            await asyncio.to_thread(moltbook.add_comment, decision["post_id"], decision["content"])
            logger.info(f"[moltbook_social] commented on post {decision['post_id']!r}: {decision['content']!r}")
        elif action == "create_post":
            result = await asyncio.to_thread(
                moltbook.create_post, "general", decision["title"], decision["content"]
            )
            logger.info(f"[moltbook_social] created post {decision['title']!r}: {result!r}")
    except Exception as e:
        logger.error(f"[moltbook_social] action {action!r} failed: {e!r}")


class _ChatOnlyUpdate:
    """
    Minimal Update-like shim exposing only .effective_chat.send_message —
    lets the auto-idle background loop (which has no real incoming
    Update to hang off of) reuse _safe_send/_resolve_ai_turns/_go_inactive
    completely unchanged, the same as a real player action would.
    """

    class _Chat:
        def __init__(self, bot, chat_id: int):
            self._bot = bot
            self.id = chat_id

        async def send_message(self, text, message_thread_id=None, **kwargs):
            return await self._bot.send_message(
                chat_id=self.id, message_thread_id=message_thread_id, text=text, **kwargs
            )

        async def send_audio(self, audio=None, message_thread_id=None, **kwargs):
            # Real live bug (2026-07-22, caught by direct log monitoring,
            # not a dev-topic report): this shim only ever implemented
            # send_message, so any background loop routed through it
            # (the autonomous AI party's own turns, the hourly idle-check
            # loop) crashed with a bare AttributeError the moment Piper
            # TTS tried to send a real voice clip -- an unhandled
            # exception here aborted the ENTIRE autonomous turn/cycle,
            # not just the TTS attempt, since _speak_via_piper's except
            # clause below only ever caught TelegramError (see that
            # fix too). Delegates to the real bot the same way
            # send_message already does.
            return await self._bot.send_audio(
                chat_id=self.id, message_thread_id=message_thread_id, audio=audio, **kwargs
            )

        async def send_photo(self, photo=None, caption=None, message_thread_id=None, **kwargs):
            # Real live bug (2026-07-22, caught by direct log monitoring):
            # same missing-method shape as send_audio above, this time
            # for location images -- the autonomous AI party's own
            # moves into a new location kept raising a bare AttributeError
            # from _maybe_send_location_image, since this shim never
            # implemented send_photo either. Caught there by a broad
            # except (so it only silently skipped the image rather than
            # aborting the whole turn like the send_audio bug did), but
            # still a real, fixable gap. Delegates to the real bot the
            # same way send_message/send_audio already do.
            return await self._bot.send_photo(
                chat_id=self.id, message_thread_id=message_thread_id, photo=photo, caption=caption, **kwargs
            )

    def __init__(self, bot, chat_id: int):
        self.effective_chat = _ChatOnlyUpdate._Chat(bot, chat_id)


class _AiPlayerUpdate:
    """
    Full Update-like shim for an autonomous AI party character's own
    "turn" — unlike _ChatOnlyUpdate, this also carries a real
    effective_user.id (the character's own synthetic telegram_user_id)
    and a message.text/message_thread_id, so it can be routed through
    adventure_master_handler completely unchanged, exactly like a real
    incoming Telegram message would be. This is deliberate: the point
    is to actually exercise the same intent-parsing/action-dispatch
    pipeline a human hits, not a privileged shortcut around it.
    """

    class _User:
        def __init__(self, user_id: int):
            self.id = user_id

    class _Message:
        def __init__(self, text: str, thread_id: int):
            self.text = text
            self.message_thread_id = thread_id

    def __init__(self, bot, chat_id: int, user_id: int, text: str):
        self.effective_chat = _ChatOnlyUpdate._Chat(bot, chat_id)
        self.effective_user = _AiPlayerUpdate._User(user_id)
        self.message = _AiPlayerUpdate._Message(text, topics.thread_id_for(chat_id, "adventure"))
        # Real live regression (2026-07-25, caught within minutes of the
        # update.message -> update.effective_message edit-safety fix):
        # this shim never set effective_message at all, only .message --
        # every autonomous AI party turn immediately crashed with
        # "AttributeError: '_AiPlayerUpdate' object has no attribute
        # 'effective_message'" the instant it hit any of the 75 call
        # sites just switched over. Real Telegram Updates (and this
        # game's own FakeUpdate test double) always keep these in sync;
        # this shim just never did.
        self.effective_message = self.message


class _AiPlayerContext:
    """context.user_data equivalent, persisted per autonomous character across ticks."""

    def __init__(self):
        self.user_data = {}


# 2026-08-01 Phase 2: chat-scoped. Per the approved multi-tenant plan,
# each tenant chat gets its OWN independent autonomous AI party/wandering-
# companion state, not one shared "living world" bleeding across every
# group the bot is in -- that sharing would itself be the exact dilution
# the multi-tenant scaling work exists to avoid.
_AI_PLAYER_CONTEXTS: dict[int, dict[int, _AiPlayerContext]] = {}


# ---------------------------------------------------------------------
# Character creation — driven by free text, no /newcharacter needed.
# State is tracked per-user in context.user_data["creation"].
# ---------------------------------------------------------------------

def _get_party_members(chat_id: int) -> list[dict]:
    """
    Every currently-ACTIVE character — real players' active character
    slot, plus AI companions — IN THIS CHAT. Deleted characters and a
    player's inactive (non-active) character slots don't count as being
    "in the party."

    Real cross-tenant leak, found and fixed 2026-08-08 (multi-tenant
    audit): this used to have no chat_id filter at all, returning every
    active character across EVERY tenant chat -- since this feeds
    combat targeting, dueling, and "give item to nearby party member"
    (via _get_combat_eligible_party_members below), two different
    tenant chats' characters could target/duel/give-items to each
    other. `characters` has had a real chat_id column since Phase 4a
    (v1.27.84); this was simply never threaded through here.
    """
    with db.get_connection() as conn:
        rows = conn.execute(
            """
            SELECT c.* FROM characters c
            JOIN active_characters a ON a.character_id = c.character_id
            WHERE c.is_deleted = 0 AND c.chat_id = ?
            """,
            (chat_id,),
        ).fetchall()
    return [db._row_to_dict(r) for r in rows]


def _get_combat_eligible_party_members(location_id: str, chat_id: int) -> list[dict]:
    """
    Real party members who could actually join a fight breaking out at
    location_id right now (2026-07-14, per Coffee: "only characters
    that are active and at the same location shud be in the same
    battle... if a character is in the tavern and another is in the
    whispering woods they shud not be able to fight"). _get_party_members
    deliberately returns EVERY active character in this chat, with no
    location or resting filter at all, since it's also used for things
    like "who's in my party" listings where a global roster makes
    sense -- but _do_start_combat was reusing that same unfiltered list
    directly, so a fight breaking out anywhere pulled in the whole
    party regardless of where they actually were or whether they'd
    gone inactive/resting. Filters to characters actually AT this
    location and not currently resting (is_inactive).
    """
    return [
        p for p in _get_party_members(chat_id)
        if p["current_location"] == location_id and not p.get("is_inactive")
    ]


def _get_trade_eligible_members(chat_id: int) -> list[dict]:
    """
    Real independent economic actors in this chat: real players
    (is_ai=0) plus genuinely autonomous AI-played characters
    (is_ai=1, is_autonomous=1) -- explicitly EXCLUDING recruited AI
    companions (is_ai=1, is_autonomous=0). A companion isn't an
    independent agent (it travels with and is controlled by its
    recruiter), so letting it be a trade PARTNER would be a real
    gold/item laundering vector between two humans who each control
    one side. Not location-scoped (2026-08-26, per Coffee: "have it so
    trade is open to all players") -- unlike _get_combat_eligible_party_
    members, a formal trade requires the OTHER side's explicit accept,
    which already neutralizes the "unwanted item shows up" concern
    room-scoping exists to prevent for the unilateral _do_give_item.
    """
    return [p for p in _get_party_members(chat_id) if not p.get("is_ai") or p.get("is_autonomous")]


def _equipped_profession_bonus(character: dict, profession: str) -> int:
    """
    Magic item system Phase 4 (2026-08-02): sum of every equipped item's
    profession_bonus affix matching this specific skill_key/profession
    (e.g. "mining", "alchemy") -- live-summed at read time, same
    convention as _equipped_regen_bonus/_equipped_ring_ac_bonus, never
    baked into a stored column. Called as a third additive term
    alongside _practiced_bonus_for/class_profession_affinity_bonus in
    _do_gather/_do_craft's existing shared bonus accumulator.
    """
    total = 0
    equipped_ids = [
        character.get("equipped_weapon"), character.get("equipped_armor"), character.get("equipped_shield"),
    ] + character.get("equipped_accessories", [])
    for item_id in equipped_ids:
        if not item_id:
            continue
        item = items_module.get_item(item_id)
        if not item:
            continue
        for entry in item.get("profession_bonuses", []):
            if entry.get("profession") == profession:
                total += entry.get("value", 0)
    return total


def _effective_ability_check_bonus(character: dict, ability: str) -> int:
    """
    The real d20-total bonus an equipped ability_bonus affix contributes
    to a check/attack/save using this ability -- the REAL 5E modifier
    delta (ability_modifier(base+bonus) - ability_modifier(base)), not a
    flat 1:1 add, since ability_modifier's floor-division math means +1
    to a score doesn't always shift the modifier by a whole point (e.g.
    14->15 is a no-op, 15->16 is +1). Meant to be added into the same
    post-roll "bonus" accumulator every roll_ability_check call site in
    this file already uses for _practiced_bonus_for/class_profession_
    affinity_bonus/_equipped_profession_bonus, rather than mutating the
    character dict's own ability score before rolling -- keeps the DB-
    persisted base score always the true one, with zero risk of an
    equipped bonus ever accidentally getting written back as permanent.
    """
    bonus_score = items_module.equipped_ability_bonus(character, ability)
    if bonus_score == 0:
        return 0
    base_score = character.get(ability, 10)
    return ability_modifier(base_score + bonus_score) - ability_modifier(base_score)


def _compute_equipped_resist_profile(character: dict) -> dict:
    """
    Pure, read-only computation of a character's real defensive profile
    from their currently equipped gear -- extracted from _apply_
    equipped_elemental_profile (2026-08-14, per Coffee: "make sure
    players resistences and elemental stats are listed on the player
    sheet") so the character sheet can show this WITHOUT the side
    effects that function's own docstring is explicit about (mutating
    combat-only fields onto the character dict) -- checking your sheet
    happens far more often than starting a fight, and shouldn't leave
    stray resistance/immunity data sitting on the dict outside combat.
    """
    resistances, vulnerabilities, immunities = set(), set(), set()
    equipped_ids = [
        character.get("equipped_weapon"), character.get("equipped_armor"), character.get("equipped_shield"),
    ] + character.get("equipped_accessories", [])
    ignores_resistance = False
    free_extra_attack = False
    elemental_resistance_pct = {}
    for item_id in equipped_ids:
        if not item_id:
            continue
        item = items_module.get_item(item_id)
        if not item:
            continue
        resistances.update(item.get("resistances", []))
        vulnerabilities.update(item.get("vulnerabilities", []))
        immunities.update(item.get("immunities", []))
        if item.get("ignores_resistance"):
            ignores_resistance = True
        if item.get("free_extra_attack"):
            free_extra_attack = True
        for entry in item.get("elemental_resistances", []):
            dtype = entry["damage_type"]
            elemental_resistance_pct[dtype] = elemental_resistance_pct.get(dtype, 0) + entry["value"]
    return {
        "resistances": resistances, "vulnerabilities": vulnerabilities, "immunities": immunities,
        "ignores_resistance": ignores_resistance, "free_extra_attack": free_extra_attack,
        "elemental_resistance_pct": elemental_resistance_pct,
    }


def _apply_equipped_elemental_profile(character: dict) -> None:
    """
    Phase 2 of the magic item system (2026-08-02): rules.combat's
    apply_damage_type_modifier already reads resistances/vulnerabilities/
    immunities off ANY defender dict (monster templates have set these
    for a while) -- what was missing is a real PLAYER ever having them
    populated at all. Live-summed at combat-start time, same pattern as
    _equipped_regen_bonus/_equipped_ring_ac_bonus (never baked into a
    stored column), over armor/shield/accessories (a weapon's own
    damage_type is offense, handled separately by _weapon_for_attacker --
    this is purely the wearer's own defense). Mutates the character dict
    in place, matching how session participants already pick up other
    combat-only fields (conditions, raging, etc.) once they become part
    of session.participants.

    Also picks up two mythic-exclusive OFFENSE flags (Phase 6, 2026-08-02)
    -- ignores_resistance (checked by apply_damage_type_modifier) and
    free_extra_attack (checked by _attacks_per_turn) -- real, guaranteed
    mythic-tier effects, not bigger versions of an existing number.
    Checked across EVERY equipped slot (not just the weapon): a
    hand-authored unique wondrous item (e.g. Pandora's Answer) is just
    as real a source of these as a generated mythic weapon.
    """
    profile = _compute_equipped_resist_profile(character)
    resistances, vulnerabilities, immunities = profile["resistances"], profile["vulnerabilities"], profile["immunities"]
    ignores_resistance = profile["ignores_resistance"]
    free_extra_attack = profile["free_extra_attack"]
    elemental_resistance_pct = profile["elemental_resistance_pct"]
    if resistances:
        character["resistances"] = list(set(character.get("resistances", [])) | resistances)
    if vulnerabilities:
        character["vulnerabilities"] = list(set(character.get("vulnerabilities", [])) | vulnerabilities)
    if immunities:
        character["immunities"] = list(set(character.get("immunities", [])) | immunities)
    if ignores_resistance:
        character["ignores_resistance"] = True
    if free_extra_attack:
        character["free_extra_attack"] = True
    if elemental_resistance_pct:
        merged = dict(character.get("elemental_resistance_pct") or {})
        for dtype, pct in elemental_resistance_pct.items():
            merged[dtype] = merged.get(dtype, 0) + pct
        character["elemental_resistance_pct"] = merged


def _get_real_party_combatants(requester: dict) -> list[dict]:
    """
    Who actually fights ALONGSIDE requester when combat starts (2026-07-23,
    Coffee: "I don't remember inviting ZARA to our party is this a
    glitch? ... They have to be in our party" -- Elduinn said "attack
    the wolf" solo and Zara Windrift, an unrelated autonomous AI party
    member who simply happened to be standing in the same spot, was
    pulled in as an ally). _get_combat_eligible_party_members only ever
    filtered by location, which is deliberately right for give_item/
    equip-help/spell-target ("anyone physically here" is the natural
    reading there) but wrong for who's actually on YOUR side in a
    fight -- that has to be real party_id membership, not just
    happening to share a room. A character with no real party_id at all
    (the common case -- most characters never form or join one) fights
    solo: everyone else here, even another solo character, sits it out.

    Also excludes benched members (2026-07-31, per Coffee: "cap it at 6
    per fight" -- see is_benched) and caps the result at
    config.PARTY_ACTIVE_COMBAT_CAP, so a party that's grown past a
    comfortable battle size still only ever puts that many combatants
    into the actual fight regardless of button/data state. The requester
    is never the one dropped by that cap -- they're the one starting
    the fight.

    AI companions rush to the fight regardless of location (2026-08-01,
    per Coffee: "I want the AI players that are in the party to be in
    the battles -- that's the point of picking the active party members
    for combats" -- reported live after Grask, a real active/non-
    benched party member, sat out a fight purely because he'd wandered
    to a different location under the living-world system while
    levelling wasn't even in progress). A real human party member
    genuinely has to be standing here -- they can't be teleported into
    a fight they never walked into -- but an AI companion's own
    location is just flavor/wandering, not a deliberate choice to sit a
    fight out. Being in the active roster (not benched, not resting) IS
    the commitment, so an AI party member's current_location is pulled
    to the requester's on the way in (persisted, not just for this
    fight) rather than silently fighting from two places at once.
    _rushed_in is a transient, in-memory-only marker (never a DB
    column) so _do_start_combat's header can name who just rushed in.
    """
    location_id = requester["current_location"]
    party_id = requester.get("party_id")
    if not party_id:
        combatants = [requester]
    else:
        combatants = []
        for m in db.get_party_members_by_id(party_id):
            if m.get("is_benched") or m.get("is_inactive"):
                continue
            # A human can only ever pilot one character at a time
            # (2026-08-13, real live bug, Coffee: two real players --
            # Laurienna/Charvenna and Ravenloft/Pan -- each had BOTH of
            # their own characters counted as separate combatants,
            # eating 4 of the party's 6 active combat slots between just
            # 2 humans). get_party_members_by_id deliberately still
            # lists a dormant alt character (see db.get_active_character_
            # id's own docstring -- needed for revival/XP-sharing/death
            # handling), but it never actually fights: only the
            # character this owner is CURRENTLY piloting can.
            if m["telegram_user_id"] > 0 and m["character_id"] != db.get_active_character_id(m["telegram_user_id"], m["chat_id"]):
                continue
            if m.get("is_ai"):
                if m["current_location"] != location_id:
                    db.update_character_by_id(m["character_id"], current_location=location_id)
                    m["current_location"] = location_id
                    m["_rushed_in"] = True
                combatants.append(m)
            elif m["current_location"] == location_id:
                combatants.append(m)
        if len(combatants) > config.PARTY_ACTIVE_COMBAT_CAP:
            requester_id = requester["telegram_user_id"]
            others = [p for p in combatants if p["telegram_user_id"] != requester_id]
            combatants = [requester] + others[:config.PARTY_ACTIVE_COMBAT_CAP - 1]
    for combatant in combatants:
        _apply_equipped_elemental_profile(combatant)
    return combatants


def _presence_status(character: dict, now: datetime | None = None) -> str:
    """
    Derived presence (task #144), never stored as its own field -- it's
    computed fresh from real state every time so it can never drift out
    of sync with what actually governs it. Precedence: resting
    (is_inactive) is a real mechanical state (see natural healing) and
    wins over everything; do_not_disturb is the player's own explicit
    choice and shows next; otherwise online/away is judged against
    IDLE_WARNING_SECONDS -- the SAME threshold that already triggers
    this game's idle warning (_check_idle_characters), so "still online"
    here always agrees with what the idle system itself believes,
    rather than inventing a second, possibly-contradictory threshold.
    AI companions/NPCs have no real presence of their own; callers
    should only ever call this for real (is_ai=0) characters.
    """
    if character.get("is_inactive"):
        return "😴 Resting"
    if character.get("do_not_disturb"):
        return "🔕 Do Not Disturb"
    last_active_at = character.get("last_active_at")
    if not last_active_at:
        return "🌙 Away"
    try:
        last_active = datetime.fromisoformat(last_active_at)
    except (TypeError, ValueError):
        return "🌙 Away"
    now = now or datetime.now(timezone.utc)
    idle_seconds = (now - last_active).total_seconds()
    return "🟢 Online" if idle_seconds < IDLE_WARNING_SECONDS else "🌙 Away"


def _online_party_members_elsewhere(location_id: str, exclude_ids: set[int], chat_id: int) -> list[dict]:
    """
    Real (non-AI) party members who are currently online (see
    _presence_status), haven't opted into Do Not Disturb, and are
    somewhere OTHER than location_id -- used by _do_start_combat's
    join-a-fight nudge (task #144). Deliberately excludes resting
    players even at other locations: resting is a real, chosen state,
    not something a fight elsewhere should interrupt.
    """
    now = datetime.now(timezone.utc)
    others = []
    for p in _get_party_members(chat_id):
        if p.get("is_ai") or p["telegram_user_id"] in exclude_ids:
            continue
        if p["current_location"] == location_id or p.get("is_inactive") or p.get("do_not_disturb"):
            continue
        if _presence_status(p, now) == "🟢 Online":
            others.append(p)
    return others


def _format_party_names(party: list[dict]) -> str:
    """Shared formatter, e.g. 'Kara, Finn (AI companion) — 2 members'. Never guesses members."""
    if not party:
        return "No one has joined yet."
    names = [
        f"{p['name']} (AI companion)" if p.get("is_ai") else p["name"]
        for p in party
    ]
    return f"{', '.join(names)} — {len(party)} member{'s' if len(party) != 1 else ''}"


def _party_summary_text(chat_id: int) -> str:
    """
    A clear, factual description of who's currently in the party and how
    many, e.g. 'Kara, Finn (AI companion) — 2 members'. Never guesses or
    invents members; only reports what's actually in the database.
    """
    return _format_party_names(_get_party_members(chat_id))


def _match_member_by_name_or_username(text: str, members: list[dict]) -> dict | None:
    """
    Shared match logic behind every "name a party member in free text"
    lookup in this file (support-spell/use_item targeting, give/equip/
    auto-equip, and combat target picking). Real Telegram @username tag
    (2026-07-18, per Coffee: "use a potion on @ShesAQueen_78", "attack
    @tagged_player", "Revive @Tagged_player" -- wants this to "work for
    everything") is tried FIRST -- unambiguous by construction, unlike
    matching on a character's DISPLAY name, which could theoretically
    collide between two different players' characters. Falls back to
    the display-name substring match for players without a recorded
    username (db.update_telegram_username only ever captures one once
    they've sent a real message). Centralized here (instead of each
    call site rolling its own, as _do_give_item originally did on
    2026-07-17) so every future targeting call site gets @username
    support for free.
    """
    lowered = text.lower()
    tagged = next(
        (m for m in members if m.get("telegram_username") and f"@{m['telegram_username'].lower()}" in lowered),
        None,
    )
    if tagged is not None:
        return tagged
    # Real bug caught by the full-playthrough simulation (2026-07-24):
    # this checked `members` in whatever order they were passed with a
    # plain substring test, so "I attack the goblin boss" against a
    # fight with both a plain "Goblin" and a "Goblin Boss" present
    # matched the bare "Goblin" first ("goblin" IS a substring of the
    # text) and never reached "Goblin Boss" -- this is the single
    # shared matcher behind every targeting call site in the file
    # (combat target picking, support-spell/use_item targeting, give/
    # equip/auto-equip), so the bug silently affected all of them
    # whenever two candidates' names overlapped like this. Same fix
    # already used in _find_monster_mentioned_in_text: check the MOST
    # SPECIFIC (longest) name first, with a word-boundary match so
    # "Goblin" doesn't also wrongly match inside "Hobgoblin".
    for member in sorted(members, key=lambda m: -len(m["name"])):
        if re.search(r"\b" + re.escape(member["name"].lower()) + r"\b", lowered):
            return member

    # Real live bug (2026-08-09, Coffee, dev-topic screenshot): "Move
    # Vesh to the backrow" said 'No one named "Vesh" is in your party'
    # even though Vesh Nightglass was plainly fighting in the very same
    # battle status line shown moments earlier -- the check above only
    # ever matched a member's COMPLETE stored name verbatim ("vesh
    # nightglass"), with no fallback for the entirely natural way
    # players actually refer to someone by first name alone. Only
    # matches when EXACTLY ONE member's first word matches -- an
    # ambiguous shared first name is left unmatched rather than
    # guessed, same "don't guess when ambiguous" philosophy as every
    # other fallback in this codebase (interactables, locations, NPCs).
    # Real dev-bridge report (2026-08-23, Coffee, screenshot): "Show
    # pips affinity" ("pips affinity" is casual first-name possessive,
    # the entirely natural way to drop an apostrophe when typing on a
    # phone) matched nothing here -- \bpip\b requires a word boundary
    # immediately after "pip", but "pips" has no boundary there (the
    # "s" is contiguous), so a plain possessive/plural of a first name
    # silently fell through. `'?s?` optionally allows a trailing
    # apostrophe-s or bare s right in the boundary itself -- "pip",
    # "pip's", and "pips" all now match "Pip Thistledown" alike. Same
    # single-candidate safety net as before: an ambiguous match across
    # multiple members is still left unmatched, never guessed.
    first_name_matches = [
        member for member in members
        if re.search(r"\b" + re.escape(member["name"].lower().split()[0]) + r"'?s?\b", lowered)
    ]
    if len(first_name_matches) == 1:
        return first_name_matches[0]
    return None


def _match_all_members_by_name(text: str, members: list[dict]) -> list[dict]:
    """
    Real dev-bridge request (2026-08-23, Coffee, screenshot): "Move
    Grask and Wren to the front row" -- naming MULTIPLE party members
    for one shared formation action. _match_member_by_name_or_username
    deliberately returns nothing once more than one name matches (the
    right call for a genuinely single-target action, where an
    ambiguous match must never be guessed), but a formation-row command
    can legitimately target several real people on purpose. Returns
    every real member whose full name OR first name (same casual
    apostrophe-optional possessive the single-target matcher already
    allows) is actually mentioned in the text, in party order -- never
    guessing beyond an exact name match.
    """
    lowered = text.lower()
    matched = []
    for member in members:
        name_lower = member["name"].lower()
        first = name_lower.split()[0]
        if re.search(r"\b" + re.escape(name_lower) + r"\b", lowered) or re.search(
            r"\b" + re.escape(first) + r"'?s?\b", lowered
        ):
            matched.append(member)
    return matched


# Class/category-based bulk formation moves (2026-08-23, per Coffee,
# dev-bridge: "move the fighters to the front row and move magic users
# or specific classes to the back row"). Confirmed the split via
# AskUserQuestion: martial/front-line vs caster/"magic user", on top of
# always supporting a literal class name too (any of models.VALID_CLASSES).
MARTIAL_CLASSES = {"Fighter", "Barbarian", "Paladin", "Monk", "Rogue", "Ranger"}
CASTER_CLASSES = {"Wizard", "Sorcerer", "Cleric", "Druid", "Bard", "Warlock"}
_MARTIAL_CATEGORY_WORDS = ("fighters", "martial", "melee", "warriors", "front liners", "front-liners")
_CASTER_CATEGORY_WORDS = ("magic users", "magic-users", "casters", "spellcasters", "spell casters", "mages")


def _match_members_by_class_category(text: str, members: list[dict]) -> list[dict]:
    """
    Real dev-bridge request (2026-08-23, Coffee, screenshot): "move the
    fighters to the front row and move magic users or specific classes
    to the back row." Checked in this order: a category phrase
    ("magic users"/"fighters"/etc.) wins first since it's the more
    specific ask when both happen to be present; a literal class name
    (e.g. "move the wizards back") still works as its own real,
    single-class group. Returns every real member matching, or [] if
    neither a category phrase nor a real class name is mentioned --
    never guesses beyond an exact match, same philosophy as every
    other name/category matcher in this file.
    """
    lowered = text.lower()
    if any(phrase in lowered for phrase in _CASTER_CATEGORY_WORDS):
        return [m for m in members if m.get("char_class") in CASTER_CLASSES]
    if any(phrase in lowered for phrase in _MARTIAL_CATEGORY_WORDS):
        return [m for m in members if m.get("char_class") in MARTIAL_CLASSES]
    for class_name in VALID_CLASSES:
        if re.search(r"\b" + re.escape(class_name.lower()) + r"'?s?\b", lowered):
            return [m for m in members if m.get("char_class") == class_name]
    return []


def _find_party_target_by_name(text: str, chat_id: int) -> dict | None:
    """
    Finds a party member (real player, AI companion, or a currently
    inactive/resting real player — all still count as "in the party")
    named in free text, for support-spell targeting. Returns None if no
    party member's name appears, letting the caller default to self.
    """
    return _match_member_by_name_or_username(text, _get_party_members(chat_id))


def _find_live_summon_by_name(text: str, session: sessions.Session, caster_side: str) -> dict | None:
    """
    A synthetic (no-DB) party-side summon in the CURRENT combat session,
    matched by name -- real live gap (2026-08-21, per Coffee: "we can
    heal them"). _find_party_target_by_name is a pure `characters` table
    query, so a summon (negative telegram_user_id, never written to the
    DB at all) can never be found by it. Only ever matches a LIVE
    (hp_current > 0) summon on the caster's own side -- a defeated one
    is already gone from session.participants entirely (sessions.
    remove_defeated), so "can't revive them" holds structurally: there's
    simply nothing left here to find.
    """
    candidates = [
        p for p in session.participants
        if session.sides.get(p["telegram_user_id"]) == caster_side
        and p.get("is_ai") and p["telegram_user_id"] < 0 and p.get("hp_current", 0) > 0
    ]
    return _match_member_by_name_or_username(text, candidates)


async def _send_welcome_narration(update: Update, character: dict) -> None:
    """
    Sends a one-time, auto-generated welcome narration right after
    character creation, grounded strictly in the character's real
    starting location — no hints, no invented content, no spoilers.
    """
    location = cl.get_location(CAMPAIGN, character["current_location"])
    if location is None:
        return

    npc_names = [
        cl.get_npc(CAMPAIGN, n)["name"] for n in location.get("npcs", []) if cl.get_npc(CAMPAIGN, n)
    ]
    connection_names = [
        cl.get_location(CAMPAIGN, c)["name"] for c in location.get("connections", [])
    ]
    location_facts = {
        "name": location["name"],
        "layer": location.get("layer", "surface"),
        "description": location["description"],
        "npc_names": npc_names,
        "monster_names": [k for k in location.get("monsters", []) if _monster_visible_to_character(k, character)],
        "connection_names": connection_names,
    }

    party_summary = _party_summary_text(character["chat_id"])
    welcome_text = await asyncio.to_thread(
        narrate_welcome, character, location_facts, party_summary
    )

    await _safe_send(update, welcome_text)


