async def _do_choose_hybrid(update: Update, text: str) -> None:
    character = db.get_character(update.effective_user.id, update.effective_chat.id)
    if character is None:
        await update.effective_chat.send_message(
            "You don't have a character yet!", message_thread_id=topics.thread_id_for(update.effective_chat.id, "adventure")
        )
        return
    tier = hybrid_tier(character.get("rebirth_count", 0))
    if tier <= 0:
        await _safe_send(
            update, "Hybrid classes unlock after your first rebirth — say \"rebirth\" once you're level 99.",
            speak=False,
        )
        return

    lowered = text.lower()
    match = next((c for c in HYBRID_CLASS_FEATURES if c.lower() in lowered), None)
    if match is None:
        options = ", ".join(HYBRID_CLASS_FEATURES)
        await _safe_send(update, f"Which class do you want as your hybrid flavor? Options: {options}")
        return
    if match == character["char_class"]:
        await _safe_send(update, f"**{character['name']}** is already a {match} — pick a different class to hybridize with.")
        return

    db.update_character(update.effective_user.id, update.effective_chat.id, hybrid_class=match)
    perk = HYBRID_CLASS_FEATURES[match][tier - 1]
    await _safe_send(
        update,
        f"🌟 **{character['name']}** takes on a **{match}** hybrid flavor (tier {tier}/{HYBRID_MAX_TIER}): {perk}.",
    )


# Real subclass system (2026-07-24 pilot: Wizard's Arcane Tradition,
# grounded in spells.py's already-real "school" field. Extended
# 2026-07-25 to the other 11 classes via rules/leveling.CLASS_SUBCLASSES
# -- two genuine 5E archetypes per class. This comment used to claim the
# second (utility) pick had "no mechanical bonus wired up yet" -- stale
# even the same day it was written (rules/leveling.UTILITY_SUBCLASS_
# ABILITY_CHECK_BONUS/describe_subclass_effect cover it, plus Thief/
# Life/Totem Warrior's own bespoke hooks); corrected in a 2026-08-14
# full synergy audit. The first (combat) pick's own real +20% bonus
# (rules/leveling.COMBAT_SUBCLASS_DAMAGE_BONUS_PCT) also grew that same
# audit -- it now applies to spell damage too (spells.resolve_damage_
# spell), not just weapon attacks (rules/combat.py's resolve_attack),
# since several combat picks (Draconic/Fiend/War/Moon/Valor) belong to
# classes that deal most of their real damage through spells.
WIZARD_SCHOOLS = (
    "evocation", "abjuration", "conjuration", "divination",
    "enchantment", "illusion", "necromancy", "transmutation",
)
SUBCLASS_SCHOOL_DAMAGE_BONUS_PCT = 20


async def _do_choose_subclass(update: Update, text: str) -> None:
    character = db.get_character(update.effective_user.id, update.effective_chat.id)
    if character is None:
        await update.effective_chat.send_message(
            "You don't have a character yet!", message_thread_id=topics.thread_id_for(update.effective_chat.id, "adventure")
        )
        return
    lowered = text.lower()

    if character["char_class"] == "Wizard":
        match = next((s for s in WIZARD_SCHOOLS if s in lowered), None)
        if match is None:
            await _safe_send(update, f"Which school of magic? Options: {', '.join(WIZARD_SCHOOLS)}.")
            return
        db.update_character(update.effective_user.id, update.effective_chat.id, subclass=match)
        await _safe_send(
            update,
            f"📖 **{character['name']}** specializes in the **School of {match.capitalize()}** — "
            f"spells of that school now deal {SUBCLASS_SCHOOL_DAMAGE_BONUS_PCT}% more damage.",
        )
        return

    options = CLASS_SUBCLASSES.get(character["char_class"])
    if options is None:
        await _safe_send(update, f"Real subclass choice isn't built for {character['char_class']} yet.")
        return
    match = next((s for s in options if s.lower() in lowered), None)
    if match is None:
        # 2026-08-14, per Coffee: bare names alone left a player choosing
        # blind (see guilds.eligible_for_guild's own matching fix) --
        # describe_subclass_effect surfaces the real effect for each
        # option right here too, not just after they've already committed.
        option_lines = "; ".join(f"{o} ({describe_subclass_effect(o)})" for o in options)
        await _safe_send(update, f"Which subclass? Options for a {character['char_class']}: {option_lines}.")
        return
    db.update_character(update.effective_user.id, update.effective_chat.id, subclass=match)
    if match in COMBAT_SUBCLASS_NAMES:
        await _safe_send(
            update,
            f"⚔️ **{character['name']}** takes up the path of the **{match}** — weapon attacks now deal "
            f"{COMBAT_SUBCLASS_DAMAGE_BONUS_PCT}% more damage.",
        )
    elif match == "Assassin":
        updated_character = db.get_character(update.effective_user.id, update.effective_chat.id)
        multiplier = _effective_backstab_multiplier(updated_character)
        proficiency = updated_character.get("backstab_proficiency_pct", PROFICIENCY_STARTING_PCT)
        await _safe_send(
            update,
            f"🗡️ **{character['name']}** takes up the path of the **Assassin** — every attack is now a real "
            f"**Backstab attempt**, dealing **x{multiplier}** damage when it lands (growing further as you "
            f"level, up to x10 per life, permanently compounding with any past rebirths). Right now you "
            f"land it **{proficiency:.2f}%** of the time — a miss just falls back to a normal attack, "
            f"nothing lost — but every single attempt grinds that % up, so it only ever gets more reliable. "
            f"Throwing a weapon also lands a guaranteed hit, no roll needed.",
        )
    elif match == "Thief":
        await _safe_send(
            update,
            f"🗝️ **{character['name']}** takes up the path of the **Thief** — a trained hand at theft, "
            f"+{THIEF_SUBCLASS_STEAL_BONUS} on every steal attempt.",
        )
    elif match == "Life":
        await _safe_send(
            update,
            f"💚 **{character['name']}** takes up the path of **Life** — healing spells restore "
            f"+{LIFE_SUBCLASS_HEAL_BONUS} extra HP on top of Disciple of Life.",
        )
    elif match == TOTEM_WARRIOR_SUBCLASS_NAME:
        await _safe_send(
            update,
            f"🐻 **{character['name']}** takes up the path of the **{TOTEM_WARRIOR_SUBCLASS_NAME}** — "
            f"while raging, spell damage is halved too, not just weapon hits.",
        )
    elif match in UTILITY_SUBCLASS_ABILITY_CHECK_BONUS:
        ability = UTILITY_SUBCLASS_ABILITY_CHECK_BONUS[match]
        await _safe_send(
            update,
            f"📜 **{character['name']}** takes up the path of the **{match}** — "
            f"+{UTILITY_SUBCLASS_CHECK_BONUS_VALUE} on every {ability.capitalize()} check.",
        )
    else:
        await _safe_send(
            update,
            f"📜 **{character['name']}** takes up the path of the **{match}** — a real, chosen subclass, "
            f"though no mechanical bonus is built for it yet.",
        )


async def _do_choose_fighting_style(update: Update, text: str) -> None:
    """
    Real, chosen Fighting Style (2026-09-04) -- direct structural mirror
    of _do_choose_subclass above, for the exact reason that function's
    own "describe before commit" fix exists: a player choosing blind
    from bare names is a real gap. See FIGHTING_STYLES for the 6 real
    5E styles and their actual mechanical effects.
    """
    character = db.get_character(update.effective_user.id, update.effective_chat.id)
    if character is None:
        await update.effective_chat.send_message(
            "You don't have a character yet!", message_thread_id=topics.thread_id_for(update.effective_chat.id, "adventure")
        )
        return
    if character["char_class"] not in FIGHTING_STYLE_CLASSES:
        await _safe_send(update, f"Fighting Style isn't a real class feature for {character['char_class']}.")
        return
    lowered = text.lower()
    match = next((s for s in FIGHTING_STYLES if s.lower() in lowered), None)
    if match is None:
        option_lines = "; ".join(f"{s} ({desc})" for s, desc in FIGHTING_STYLES.items())
        await _safe_send(update, f"Which Fighting Style? Options: {option_lines}.")
        return
    # Real 5E lets you pick once, permanently -- but this game has no
    # "undo" concept for any other one-time class choice either
    # (subclass, ASI) and Coffee hasn't asked for one, so a re-pick here
    # just overwrites the old choice the same permissive way subclass
    # already does.
    db.update_character(update.effective_user.id, update.effective_chat.id, fighting_style=match)
    if match == "Defense" and character.get("equipped_armor"):
        # Folded in immediately if armor is already worn, same "apply
        # right now, not just on the next equip" discipline Draconic
        # Resilience's own rework already established -- otherwise a
        # Fighter who chose Defense mid-fight would see no real AC
        # change until their next unrelated armor swap.
        db.update_character(update.effective_user.id, update.effective_chat.id, armor_class=character["armor_class"] + 1)
    if match == "Two-Weapon Fighting":
        # Honest about the real precondition -- never a silent no-op
        # with no explanation, matching the same "grounded fact"
        # discipline behind e.g. _mentions_lighting_a_source's fix
        # earlier today. Its real bonus activates once dual wielding
        # is actually possible (mastery-gated, see db.can_dual_wield).
        await _safe_send(
            update,
            f"⚔️ **{character['name']}** adopts **Two-Weapon Fighting** — its real bonus (your ability "
            f"modifier added to your off-hand attack's damage) activates once you've mastered your main "
            f"weapon (100% proficiency) and can actually dual-wield.",
        )
        return
    await _safe_send(
        update,
        f"⚔️ **{character['name']}** adopts the **{match}** fighting style — {FIGHTING_STYLES[match]}.",
    )


async def _do_level_up(update: Update, text: str) -> None:
    """
    Real player-driven Ability Score Improvement (2026-07-16, per
    Coffee): replaces the old silent auto-apply-to-a-fixed-stat
    behavior. A character banks pending_asi_points at ASI levels
    (4/8/12/16/19, see db.add_xp) and spends them here, on their own
    schedule -- there's no expiry, matching real 5E's own "you can
    always defer an ASI" convention.
    """
    user_id = update.effective_user.id
    character = db.get_character(user_id, update.effective_chat.id)
    if character is None:
        await update.effective_chat.send_message(
            "You don't have a character yet!", message_thread_id=topics.thread_id_for(update.effective_chat.id, "adventure")
        )
        return

    if character.get("pending_asi_points", 0) <= 0:
        await _safe_send(update, "No ability score improvements waiting to be spent right now.")
        return

    resolved = _apply_asi_choice(character, text)
    if resolved:
        _chat_scoped_set(_PENDING_ASI_CHOICE, update.effective_chat.id).discard(user_id)
        await _safe_send(update, resolved)
        return

    _chat_scoped_set(_PENDING_ASI_CHOICE, update.effective_chat.id).add(user_id)
    # 2026-08-20, per Coffee's dev-bridge report: "I need to be able to
    # see the players stats so we know what we want to level" -- the
    # prompt now shows the character's real current ability scores
    # right alongside the choice, and offers the same tap-to-choose
    # buttons _do_show_level_menu already has (_do_asi_button_pick),
    # instead of free text being the only option.
    await _safe_send(
        update,
        f"You have {character['pending_asi_points']} ability point(s) to spend.\n"
        f"{_ability_score_line(character)}"
        f"Which ability would you like to raise — Strength, Dexterity, Constitution, Intelligence, Wisdom, or Charisma? "
        f"(Say \"auto\" or \"do it for me\" to let the game choose, or tap a button below.)",
        reply_markup=_with_menu_button(_level_keyboard()),
    )


async def _do_auto_level_up_party(update: Update) -> None:
    """
    Auto-applies every pending ability-score improvement (to each
    character's own class-primary ability, same default _apply_asi_
    choice's "auto"/"do it for me" phrasing already uses for a single
    character) AND every affordable, not-yet-owned skill-tree upgrade
    (each class has exactly one real upgrade right now -- see
    SKILL_TREE_UPGRADES -- so "auto" here is never a real judgment call,
    just "buy the one thing that exists if you can afford it") across
    the requester's WHOLE real party -- every member sharing the same
    party_id, not just whoever's typing. Real players' own characters
    get the same free, no-real-choice-to-make treatment healing/
    blessing actions already give the whole party (see
    _bless_present_party_to_full) -- this never spends anything a
    player would plausibly rather keep banked, since the ability
    target and the skill upgrade are both fixed, not optional builds.
    Uses update_character_by_id throughout (never update_character) so
    this can never land on the wrong character if a party member isn't
    currently their owner's active slot.
    """
    requester = db.get_character(update.effective_user.id, update.effective_chat.id)
    if requester is None:
        await update.effective_chat.send_message(
            "You don't have a character yet!", message_thread_id=topics.thread_id_for(update.effective_chat.id, "adventure")
        )
        return

    if requester.get("party_id"):
        members = [p for p in _get_party_members(update.effective_chat.id) if p.get("party_id") == requester["party_id"]]
    else:
        members = [requester]

    lines = []
    for member in members:
        pending = member.get("pending_asi_points", 0)
        if pending > 0:
            ability = CLASS_PRIMARY_ABILITY.get(member["char_class"].lower(), "strength")
            before_value = member[ability]
            after_value = before_value + pending  # no ability-score cap -- see _apply_asi_choice's own comment
            db.update_character_by_id(
                member["character_id"], **{ability: after_value}, pending_asi_points=0,
            )
            lines.append(f"📈 **{member['name']}**: +{after_value - before_value} {ability.capitalize()} (now {after_value})")

        skill_line = _apply_class_skill_investment(member)
        if skill_line:
            lines.append(skill_line)

    if not lines:
        await _safe_send(update, "Nothing to auto-apply right now — no one in the party has ability points or an affordable skill upgrade banked.")
        return
    await _safe_send(update, "🎯 **Auto Level-Up: Party**\n" + "\n".join(lines))


_INLINE_DESCRIPTION_RE = re.compile(
    r"description[^:]*:\s*(.+)", re.IGNORECASE
)


def _extract_inline_description(text: str) -> str | None:
    """
    A player asking to add a description usually just states intent with
    no content yet ("I'd like to add a character description to my
    player") -- but if they DID include the actual text in the same
    message ("set my description to: A grizzled dwarf who never
    smiles"), pull it out rather than prompting for something already
    given. Real bug caught by an isolated live test (2026-07-16): an
    earlier version of this regex matched on the bare words "to"/"is"/
    "as" with no colon required, so Coffee's own example phrasing --
    "I'd like to add a character description to my player", which has
    NO actual content in it -- got misread as content="my player" and
    silently saved as the description instead of prompting for one. A
    real, unambiguous colon is now required as the content separator,
    so bare trigger phrasing always falls through to the prompt.
    """
    match = _INLINE_DESCRIPTION_RE.search(text)
    if match:
        candidate = match.group(1).strip()
        return candidate or None
    return None


async def _do_set_description(update: Update, text: str, *, from_prompt: bool = False) -> None:
    """
    Character description (2026-07-16, per Coffee): freeform biography/
    appearance/personality text, settable at creation or any time after
    by asking ("I'd like to add a character description to my player").
    Shown on the character sheet once set.
    """
    user_id = update.effective_user.id
    character = db.get_character(user_id, update.effective_chat.id)
    if character is None:
        await _safe_send(update, "You don't have a character yet!")
        return

    description_text = text.strip() if from_prompt else _extract_inline_description(text)
    if description_text is None:
        _chat_scoped_set(_PENDING_DESCRIPTION, update.effective_chat.id).add(user_id)
        await _safe_send(
            update,
            "Sure — what would you like your character's description to be? (backstory, "
            "appearance, personality — whatever helps other players and NPCs get a sense of "
            "who they are.) Say \"skip\" to leave it blank.",
        )
        return

    if description_text.lower() in ("skip", "none", "no", "n/a", "nothing", "never mind"):
        await _safe_send(update, "No problem — you can add a description any time by asking.")
        return

    clean = " ".join(description_text.split())[:MAX_CHARACTER_DESCRIPTION_LENGTH]
    if not clean:
        _chat_scoped_set(_PENDING_DESCRIPTION, update.effective_chat.id).add(user_id)
        await _safe_send(update, "That didn't look like a description — try again?")
        return

    db.update_character(user_id, update.effective_chat.id, description=clean)
    await _safe_send(update, f"✅ Description saved for {character['name']}:\n\n{clean}")


_INLINE_PRONOUNS_RE = re.compile(
    r"pronouns?[^:]*:\s*(.+)", re.IGNORECASE
)


def _extract_inline_pronouns(text: str) -> str | None:
    """Same reasoning as _extract_inline_description: a real colon is required
    so a bare trigger phrase with no content ("set my pronouns") always falls
    through to the prompt instead of misreading trailing words as the answer."""
    match = _INLINE_PRONOUNS_RE.search(text)
    if match:
        candidate = match.group(1).strip()
        return candidate or None
    return None


async def _do_set_pronouns(update: Update, text: str, *, from_prompt: bool = False) -> None:
    """
    Character pronouns (2026-07-17, per Coffee, task #117): settable at
    creation or any time after. Narration reads this real fact instead
    of guessing (see ai/dm_agent.py's _pronoun_line) -- falls back to
    they/them when unset, never invented.
    """
    user_id = update.effective_user.id
    character = db.get_character(user_id, update.effective_chat.id)
    if character is None:
        await _safe_send(update, "You don't have a character yet!")
        return

    pronouns_text = text.strip() if from_prompt else _extract_inline_pronouns(text)
    if pronouns_text is None:
        _chat_scoped_set(_PENDING_PRONOUNS, update.effective_chat.id).add(user_id)
        await _safe_send(
            update,
            "Sure — what pronouns should the narration use for your character (he/him, "
            "she/her, they/them, or something else)? Say \"skip\" to leave it unset "
            "(defaults to they/them).",
        )
        return

    if pronouns_text.lower() in ("skip", "none", "no", "n/a", "nothing", "never mind"):
        await _safe_send(update, "No problem — narration will default to they/them. You can set this any time by asking.")
        return

    clean = " ".join(pronouns_text.split())[:MAX_PRONOUNS_LENGTH]
    if not clean:
        _chat_scoped_set(_PENDING_PRONOUNS, update.effective_chat.id).add(user_id)
        await _safe_send(update, "That didn't look like pronouns — try again?")
        return

    db.update_character(user_id, update.effective_chat.id, pronouns=clean)
    await _safe_send(update, f"✅ Pronouns saved for {character['name']}: {clean}")


async def donotdisturb_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """
    /donotdisturb (task #144): a real player-set flag, distinct from the
    automatic online/away presence -- see _presence_status. With DND on,
    a player's real online-ness is still tracked the same as ever, but
    they're skipped by the combat-join nudge in _do_start_combat.
    Bare command toggles; "/donotdisturb on"/"off" sets it explicitly.
    """
    user_id = update.effective_user.id
    character = db.get_character(user_id, update.effective_chat.id)
    if character is None:
        await _safe_send(update, "You don't have a character yet!")
        return

    arg = context.args[0].lower() if context.args else None
    if arg in ("on", "enable", "true"):
        new_state = True
    elif arg in ("off", "disable", "false"):
        new_state = False
    else:
        new_state = not character.get("do_not_disturb")

    db.set_do_not_disturb(user_id, update.effective_chat.id, new_state)
    if new_state:
        await _safe_send(update, "🔕 Do Not Disturb is now ON — you'll be skipped for join-a-fight nudges.")
    else:
        await _safe_send(update, "🔔 Do Not Disturb is now OFF.")


async def _do_set_status_note(update: Update, note_text: str) -> None:
    user_id = update.effective_user.id
    character = db.get_character(user_id, update.effective_chat.id)
    if character is None:
        await _safe_send(update, "You don't have a character yet!")
        return

    clean = note_text.strip()
    if not clean or clean.lower() in ("clear", "none", "remove", "delete"):
        db.set_status_note(user_id, update.effective_chat.id, None)
        await _safe_send(update, "Status note cleared.")
        return

    clean = " ".join(clean.split())[:MAX_STATUS_NOTE_LENGTH]
    db.set_status_note(user_id, update.effective_chat.id, clean)
    await _safe_send(update, f"✅ Status note set: \"{clean}\"")


async def note_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """
    /note <text> (task #144): a short, player-set status line shown
    alongside presence in the party roster and character sheet (e.g.
    "grinding the mines, back in 20"). Bare /note shows the current one
    instead of prompting -- there's nothing to prompt for, this command
    always carries its own argument.
    """
    text = " ".join(context.args) if context.args else ""
    if not text:
        character = db.get_character(update.effective_user.id, update.effective_chat.id)
        if character is None:
            await _safe_send(update, "You don't have a character yet!")
            return
        if character.get("status_note"):
            await _safe_send(
                update,
                f"Your current status note: \"{character['status_note']}\"\n"
                "Say \"/note clear\" to remove it, or \"/note <text>\" to change it.",
            )
        else:
            await _safe_send(
                update,
                "You don't have a status note set. Use \"/note <text>\" to set one, "
                "e.g. \"/note grinding the mines, back soon\".",
            )
        return
    await _do_set_status_note(update, text)


async def achievements_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    await _do_check_achievements(update)


async def title_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """/title <text> (task #73): reliable slash-command path alongside the NL "set my title to ..." trigger."""
