async def _do_show_party_formation(update: Update) -> None:
    character = db.get_character(update.effective_user.id, update.effective_chat.id)
    if character is None:
        await update.effective_chat.send_message(
            "You don't have a character yet!", message_thread_id=topics.thread_id_for(update.effective_chat.id, "adventure")
        )
        return
    lines = [f"🔮 **Formation** — tap a name to swap its row.\n", f"You: {character.get('formation_row', 'front').capitalize()} row"]
    party_id = character.get("party_id")
    if party_id:
        for m in db.get_party_members_by_id(party_id):
            if m["telegram_user_id"] == character["telegram_user_id"]:
                continue
            lines.append(f"{m['name']}: {m.get('formation_row', 'front').capitalize()} row")
    await _safe_send(
        update, "\n".join(lines), reply_markup=_with_menu_button(_formation_keyboard(character)), speak=False,
    )


async def _do_show_party_sheets_menu(update: Update) -> None:
    character = db.get_character(update.effective_user.id, update.effective_chat.id)
    if character is None:
        await update.effective_chat.send_message(
            "You don't have a character yet!", message_thread_id=topics.thread_id_for(update.effective_chat.id, "adventure")
        )
        return
    await _safe_send(
        update, "📄 **Party Sheets** — tap a name to view their real sheet.",
        reply_markup=_with_menu_button(_party_sheets_keyboard(character)), speak=False,
    )


async def _do_show_affinity_menu(update: Update, text: str = "") -> None:
    """
    Real request (2026-08-23, Coffee: "lets work on affinity menu so
    players arent guessing. i want info from the AI players (Lv, Class,
    and Description). Also include some quests that players can boost
    affinity for that player, use push buttons, Make it task based
    quests that are easy and attainable"). Before this, affinity was a
    completely invisible backend number -- a player only ever
    discovered a real trust gate (e.g. the_hush_below's own 40-affinity
    requirement to reach the_first_city) by hitting its deliberately
    vague in-fiction rejection message, with no way to see their actual
    number or what to do about it. One message per recruited AI
    companion, same one-card-per-member pattern _do_check_party's
    sheets view already uses.

    Real follow-up (2026-08-23, Coffee, dev-bridge screenshot): "Allow
    this to work for individual characters" -- naming one companion
    (e.g. "Show the affinity of PIP") used to still dump the WHOLE
    roster instead of just that one. Reuses the exact same free-text
    matcher (_match_member_by_name_or_username) every other "name a
    party member" targeting call site in this file already shares --
    full-name first, single-candidate first-name fallback. A named but
    unmatched companion falls back to showing everyone rather than a
    dead end.
    """
    telegram_user_id = update.effective_user.id
    chat_id = update.effective_chat.id
    character = db.get_character(telegram_user_id, chat_id)
    if character is None:
        await update.effective_chat.send_message(
            "You don't have a character yet!", message_thread_id=topics.thread_id_for(chat_id, "adventure")
        )
        return
    party_id = character.get("party_id")
    companions = [
        m for m in (db.get_party_members_by_id_including_inactive_slots(party_id) if party_id else [])
        if m.get("is_ai")
    ]
    if not companions:
        await _safe_send(
            update,
            "💞 **Affinity** — you haven't recruited any companions yet. Once you do, this is where "
            "you'll see how they feel about you, and small favors you can do to earn their trust.",
            speak=False,
        )
        return

    if text:
        named = _match_member_by_name_or_username(text, companions)
        if named is not None:
            companions = [named]

    # Real error-log hit (2026-08-23): a raw send_message here had no
    # flood-control retry, so a genuine Telegram RetryAfter during a
    # busy moment just dropped this header outright. _safe_send exists
    # for exactly this (up to 3 retries, honoring RetryAfter's own wait).
    await _safe_send(update, f"💞 **Companion trust ({len(companions)}):**", speak=False)
    for member in companions:
        npc_id = _find_npc_id_by_name(member["name"])
        npc_data = CAMPAIGN["npcs"].get(npc_id) if npc_id else None
        if npc_id is None or npc_data is None:
            continue
        relationship = db.get_relationship(telegram_user_id, chat_id, npc_id)
        affinity = relationship["affinity"]
        resolution = relationship.get("resolution", "unresolved")
        resolution_note = {
            "resolved_loyal": "\n🏅 Their story with you is settled — loyal.",
            "resolved_distant": "\n🏅 Their story with you is settled — distant.",
            "resolved_estranged": "\n🏅 Their story with you is settled — estranged.",
        }.get(resolution, "")

        lines = [
            f"💞 {_member_label(member)}",
            f"\"{npc_data['personality']}\"",
            f"Trust: {_trust_tier_label(affinity)} ({affinity}/100){resolution_note}",
            "\n_Raise trust by healing or buffing them in a fight, doing a favor, or completing "
            "their own personal quest._",
        ]
        rows = []

        favor = board_quests_module.get_or_generate_companion_favor(CAMPAIGN, npc_id, chat_id)
        if favor is not None:
            # Real dev-bridge report (2026-08-23, Coffee, screenshot):
            # "You need to show the task and how much is remaining for
            # completion of the task" -- follow-up: "If the task is
            # gather 2 moonpetal flowers, show it eg. (0 of 2) until
            # completion." Progress is now always shown, in every one
            # of the 3 favor states (not yet accepted, accepted by the
            # viewer, or accepted by another real party member) -- the
            # old "already being handled" line gave zero indication of
            # what the task even was or how far along it stood.
            progress = f"({favor['progress_count']} of {favor['objective_count']})"
            if favor.get("accepted_by") is None:
                lines.append(f"\n📋 Favor: \"{favor['title']}\" {progress} — {favor['description']}")
                rows.append([InlineKeyboardButton(
                    "✅ Accept Favor", callback_data=f"affinity|acceptfavor|{favor['board_quest_id']}",
                )])
            elif favor["accepted_by"] == telegram_user_id:
                lines.append(
                    f"\n📋 Favor in progress: \"{favor['title']}\" {progress} — {favor['description']}"
                )
            else:
                handler = db.get_character(favor["accepted_by"], chat_id)
                handler_name = handler["name"] if handler else "another party member"
                lines.append(
                    f"\n📋 Favor: \"{favor['title']}\" {progress} — being handled by {handler_name}."
                )

        quest_offer = _offerable_quest_for_specific_companion(character, npc_id)
        if quest_offer is not None:
            quest_id, quest = quest_offer
            lines.append(f"\n📜 Personal quest available: \"{quest['title']}\"")
            rows.append([InlineKeyboardButton(
                f"📜 Accept: {quest['title']}", callback_data=f"quest|accept|story|{quest_id}",
            )])

        await _safe_send(
            update, "\n".join(lines), speak=False,
            reply_markup=InlineKeyboardMarkup(rows) if rows else None,
        )


async def affinity_menu_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Handles taps on _do_show_affinity_menu's own buttons -- currently just Accept Favor."""
    query = update.callback_query
    parts = (query.data or "").split("|")
    action = parts[1] if len(parts) > 1 else ""
    await _safe_answer(query)
    if action == "acceptfavor" and len(parts) > 2:
        try:
            board_quest_id = int(parts[2])
        except ValueError:
            return
        accepted = db.accept_board_quest(board_quest_id, update.effective_user.id, update.effective_chat.id)
        if accepted is None:
            await update.effective_chat.send_message(
                "That favor's already been taken on — check the Affinity menu again for what's open now.",
                message_thread_id=topics.thread_id_for(update.effective_chat.id, "adventure"),
            )
            return
        npc_data = CAMPAIGN["npcs"].get(accepted["giver_npc"])
        npc_name = npc_data["name"] if npc_data else accepted["giver_npc"]
        await _safe_send(update, f"✅ Favor accepted for **{npc_name}**: \"{accepted['title']}\"")


async def party_menu_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Handles taps on _party_keyboard -- dispatches through the exact same real invite/accept/leave handlers free text already uses."""
    query = update.callback_query
    parts = (query.data or "").split("|")
    action = parts[1] if len(parts) > 1 else ""
    await _safe_answer(query)
    if action == "leave":
        await _do_leave_party(update)
    elif action == "accept":
        await _do_accept_party_invite(update)
    elif action == "auto_equip":
        await _do_auto_equip_gear(update, "auto equip the party")
    elif action == "showformation":
        await _do_show_party_formation(update)
    elif action == "showsheets":
        await _do_show_party_sheets_menu(update)
    elif action == "showaffinity":
        await _do_show_affinity_menu(update)
    elif action == "invite" and len(parts) > 2:
        try:
            target_id = int(parts[2])
        except ValueError:
            return
        target = db.get_character(target_id, update.effective_chat.id)
        if target is None:
            return
        await _do_invite_to_party(update, target["name"])
    elif action in ("bench", "unbench") and len(parts) > 2:
        try:
            target_id = int(parts[2])
        except ValueError:
            return
        target = db.get_character(target_id, update.effective_chat.id)
        if target is None:
            return
        if action == "bench":
            await _do_bench_member(update, target["name"])
        else:
            await _do_unbench_member(update, target["name"])
    elif action == "setrow" and len(parts) > 3:
        try:
            target_id = int(parts[2])
        except ValueError:
            return
        row = parts[3]
        if row not in ("front", "back"):
            return
        target = db.get_character(target_id, update.effective_chat.id)
        if target is None:
            return
        await _do_set_formation_row(update, target["name"], row)
    elif action == "viewsheet" and len(parts) > 2:
        # The per-member half of the merged Party/Party Sheets menu (see
        # _party_keyboard's own docstring) -- one member's real sheet on
        # demand, instead of the old top-level button that always
        # dumped every member's sheet as a wall of separate messages.
        try:
            target_id = int(parts[2])
        except ValueError:
            return
        target = db.get_character(target_id, update.effective_chat.id)
        if target is None:
            return
        await _safe_send(
            update, _format_character_sheet(target), speak=False,
            reply_markup=_member_level_skill_keyboard(target),
        )


async def _do_invite_to_party(update: Update, target_name: str) -> None:
    telegram_user_id = update.effective_user.id
    character = db.get_character(telegram_user_id, update.effective_chat.id)
    if character is None:
        await update.effective_chat.send_message(
            "You don't have a character yet!", message_thread_id=topics.thread_id_for(update.effective_chat.id, "adventure")
        )
        return
    if not target_name:
        await update.effective_chat.send_message(
            "Invite who, exactly? Try \"invite [name] to my party\".",
            message_thread_id=topics.thread_id_for(update.effective_chat.id, "adventure"),
        )
        return

    target = _find_party_target_by_name(target_name, update.effective_chat.id)
    if target is None:
        await update.effective_chat.send_message(
            f"No one named \"{target_name}\" is around to invite.", message_thread_id=topics.thread_id_for(update.effective_chat.id, "adventure")
        )
        return
    if target["telegram_user_id"] == telegram_user_id:
        await update.effective_chat.send_message(
            "You can't invite yourself.", message_thread_id=topics.thread_id_for(update.effective_chat.id, "adventure")
        )
        return

    party_id = character.get("party_id")
    if not party_id:
        party_id = db.create_party(telegram_user_id, update.effective_chat.id)

    if db.get_party_size(party_id) >= db.PARTY_MAX_MEMBERS:
        await update.effective_chat.send_message(
            f"Your party is already full ({db.PARTY_MAX_MEMBERS} members).",
            message_thread_id=topics.thread_id_for(update.effective_chat.id, "adventure"),
        )
        return

    if target.get("party_id") == party_id:
        # Real live bug (2026-08-13, dev-bridge screenshot, Coffee: "I
        # only have three characters in my battle party and it's not
        # letting me invite other members"). Confirmed live against the
        # real production database: the party (11/12 total members) was
        # nowhere near full, and every real/AI character in the whole
        # chat was ALREADY a member -- "invite" is for bringing in a
        # NEW member, so it correctly refused, but for anyone trying to
        # bring an already-a-member-but-BENCHED character back into
        # active combat (exactly what "I only have three in my battle
        # party" describes), the old flat "already in your party"
        # message was a dead end that never pointed at the real command
        # for that (unbench) -- same "name the concrete fact, point to
        # the real lever" gap as the guild rejection fixes above.
        if target.get("is_benched"):
            await update.effective_chat.send_message(
                f"{target['name']} is already in your party, just benched — say "
                f"\"bring {target['name']} back\" to add them to the active battle roster.",
                message_thread_id=topics.thread_id_for(update.effective_chat.id, "adventure"),
            )
        else:
            await update.effective_chat.send_message(
                f"{target['name']} is already in your party.", message_thread_id=topics.thread_id_for(update.effective_chat.id, "adventure")
            )
        return

    if target.get("is_ai"):
        # AI companions have no real turn to accept with — they join immediately.
        db.add_ai_companion_to_party(target["telegram_user_id"], update.effective_chat.id, party_id)
        await _safe_send(update, f"🎗️ **{target['name']}** joins your party!")
        await _balance_companion_level_to_party(update, target["telegram_user_id"], party_id)
        return

    db.set_pending_party_invite(target["telegram_user_id"], update.effective_chat.id, party_id)
    await _safe_send(
        update,
        f"🎗️ Invited **{target['name']}** to your party — they'll need to accept "
        f"(\"I accept the party invite\") to join.",
    )


async def _do_accept_party_invite(update: Update) -> None:
    success, message = db.accept_party_invite(update.effective_user.id, update.effective_chat.id)
    await _safe_send(update, ("🎗️ " if success else "") + message)


async def _do_leave_party(update: Update) -> None:
    left = db.leave_party(update.effective_user.id, update.effective_chat.id)
    message = "You've left your party." if left else "You're not in a party right now."
    await _safe_send(update, message)


async def _do_bench_member(update: Update, target_name: str) -> None:
    """
    Benches a real party member out of the next fight without them
    leaving the party (2026-07-31, per Coffee: "cap it at 6 per fight,
    all members in party get experience and gold tho"). Doesn't touch
    location or is_inactive -- a benched member can be standing right
    next to the battle, just choosing to sit it out. They still share
    in combat/quest rewards at the existing INACTIVE_PARTY_XP_SHARE
    rate (_award_victory_xp / _share_quest_rewards_with_party), same as
    any other real party_id member not physically in a given fight --
    no new reward logic needed, benching just adds a third reason
    (alongside being elsewhere or resting) a member can fall into that
    already-established "absent" bucket.
    """
    telegram_user_id = update.effective_user.id
    character = db.get_character(telegram_user_id, update.effective_chat.id)
    party_id = character.get("party_id") if character else None
    if character is None or not party_id:
        await _safe_send(update, "You're not in a party right now.")
        return
    if not target_name:
        await _safe_send(update, "Bench who, exactly? Try \"bench [name]\".")
        return
    target = _find_party_target_by_name(target_name, update.effective_chat.id)
    if target is None or target.get("party_id") != party_id:
        await _safe_send(update, f"No one named \"{target_name}\" is in your party.")
        return
    if target["telegram_user_id"] == telegram_user_id:
        await _safe_send(update, "You can't bench yourself.")
        return
    db.update_character(target["telegram_user_id"], update.effective_chat.id, is_benched=1)
    await _safe_send(update, f"🪑 **{target['name']}** is benched — sitting out the next fight, "
                              f"still earning their share of the party's XP and gold.")


async def _do_unbench_member(update: Update, target_name: str) -> None:
    """Reverses _do_bench_member. Refuses if the party's active (non-benched) roster is already at the combat cap -- bench someone else first, matches the existing "party is already full" UX _do_invite_to_party already uses."""
    telegram_user_id = update.effective_user.id
    character = db.get_character(telegram_user_id, update.effective_chat.id)
    party_id = character.get("party_id") if character else None
    if character is None or not party_id:
        await _safe_send(update, "You're not in a party right now.")
        return
    if not target_name:
        await _safe_send(update, "Un-bench who, exactly? Try \"bring [name] back\".")
        return
    target = _find_party_target_by_name(target_name, update.effective_chat.id)
    if target is None or target.get("party_id") != party_id:
        await _safe_send(update, f"No one named \"{target_name}\" is in your party.")
        return
    if not target.get("is_benched"):
        await _safe_send(update, f"{target['name']} isn't benched.")
        return
    # Same real-combat-slot dedup as _get_real_party_combatants
    # (2026-08-13, per Coffee): a human's dormant alt character never
    # actually occupies a combat slot, so it shouldn't count against
    # this cap either -- only counted once per real human owner (their
    # CURRENT active character), plus every AI companion individually.
    # is_inactive (2026-08-13, per Coffee: "inactive players shudnt be
    # included in the active party rooster") -- _get_real_party_
    # combatants already excludes is_inactive members from who
    # actually fights (`if m.get("is_benched") or m.get("is_inactive"):
    # continue`); this cap check was the one asymmetric place still
    # missing that same exclusion, letting a resting/AFK member wrongly
    # occupy a "full" slot they'd never actually fill in a real fight.
    counted_owners = set()
    active_count = 0
    for m in db.get_party_members_by_id(party_id):
        if m.get("is_benched") or m.get("is_inactive") or m["telegram_user_id"] == target["telegram_user_id"]:
            continue
        owner_id = m["telegram_user_id"]
        if owner_id > 0:
            if owner_id in counted_owners:
                continue
            if m["character_id"] != db.get_active_character_id(owner_id, m["chat_id"]):
                continue
            counted_owners.add(owner_id)
        active_count += 1
    if active_count >= config.PARTY_ACTIVE_COMBAT_CAP:
        await _safe_send(
            update,
            f"Your active party is already full ({config.PARTY_ACTIVE_COMBAT_CAP}/"
            f"{config.PARTY_ACTIVE_COMBAT_CAP}) — bench someone else first.",
        )
        return
    db.update_character(target["telegram_user_id"], update.effective_chat.id, is_benched=0)
    await _safe_send(update, f"🪑 **{target['name']}** is back in the active party.")


def _move_to_formation_row(update: Update, target: dict, row: str) -> None:
    """
    The actual real DB write + live-session sync for one target,
    shared by both the single- and multi-target paths of
    _do_set_formation_row below. Real-time mid-fight repositioning
    (2026-08-01, per Coffee: "let the party use formations to move
    forward and pull back in battle" -- meant to matter for THIS
    fight, not just the next one). A combat session's participants are
    a snapshot taken at _do_start_combat time; without this, the DB
    write would be correct for future fights but silently invisible to
    the targeting/AC math (_pick_formation_weighted_target, resolve_
    attack's formation_ac_bonus) for the fight actually in progress.
    Same "find and mutate the live participant dict too" pattern
    _do_use_item's heal branch already uses for hp_current.
    """
    db.update_character(target["telegram_user_id"], update.effective_chat.id, formation_row=row)
    session = sessions.get_session_for_user(update.effective_chat.id, target["telegram_user_id"])
    if session is not None:
        live_target = next(
            (p for p in session.participants if p["telegram_user_id"] == target["telegram_user_id"]), None,
        )
        if live_target is not None:
            live_target["formation_row"] = row


async def _do_set_formation_row(update: Update, target_name: str, row: str) -> None:
    """
    Real battle-formation customization (2026-08-01, per Coffee: "allow
    us to customize the formations"). Unlike bench/unbench, this
    DOES apply to yourself -- setting your own row is exactly as valid
    a choice as setting anyone else's. No party required either: a
    solo character can still set their own row (matters the moment
    they team up, or against a multi-enemy fight where formation still
    affects who gets targeted). A named target must be a real party
    member if the requester IS in a party; with no name given, it
    defaults to the requester themselves.

    Real dev-bridge request (2026-08-23, Coffee, screenshot): "Move
    Grask and Wren to the front row" used to resolve to NOTHING --
    _match_member_by_name_or_username's own single-candidate safety
    net (correct for a genuinely single-target action, where an
    ambiguous match must never be guessed) also silently blocked a
    command that named more than one real match ON PURPOSE. When the
    single-target lookup can't resolve one exact person, this now
    falls back to _match_all_members_by_name and moves every real
    party member actually named, all at once, in one combined message.
    A third tier, _match_members_by_class_category, handles "move the
    fighters to the front row"/"move magic users back"/a literal class
    name -- checked last so a real name always wins over a same-word
    class coincidence.
    """
    telegram_user_id = update.effective_user.id
    character = db.get_character(telegram_user_id, update.effective_chat.id)
    if character is None:
        await _safe_send(update, "You don't have a character yet!")
        return
    if not target_name or target_name.strip().lower() in ("me", "myself", "my own"):
        targets = [character]
    else:
        party_id = character.get("party_id")
        single = _find_party_target_by_name(target_name, update.effective_chat.id)
        single_valid = single is not None and (
            (party_id and single.get("party_id") == party_id)
            or (not party_id and single["telegram_user_id"] == telegram_user_id)
        )
        if single_valid:
            targets = [single]
        else:
            candidates = db.get_party_members_by_id(party_id) if party_id else [character]
            targets = _match_all_members_by_name(target_name, candidates)
            if not targets:
                # Class/category-based bulk moves (2026-08-23, per
                # Coffee: "move the fighters to the front row and move
                # magic users or specific classes to the back row") --
                # only tried once name-based matching (single AND
                # multi) has both come up empty, so a real party
                # member's own name always wins over a same-word class
                # coincidence.
                targets = _match_members_by_class_category(target_name, candidates)
            if not targets:
                await _safe_send(update, f"No one named \"{target_name}\" is in your party.")
                return

    already_there = [t["name"] for t in targets if t.get("formation_row", "front") == row]
    moving = [t for t in targets if t.get("formation_row", "front") != row]
    if not moving:
        verb = "is" if len(already_there) == 1 else "are"
        await _safe_send(update, f"{', '.join(already_there)} {verb} already in the {row} row.")
        return

    for target in moving:
        _move_to_formation_row(update, target, row)

    names = ", ".join(f"**{t['name']}**" for t in moving)
    plural = len(moving) > 1
    if row == "back":
        await _safe_send(
            update,
            f"🔮 {names} move{'' if plural else 's'} to the **back row** — less likely to be targeted, "
            f"harder to hit, free to heal, cast, or shoot from safety.",
        )
    else:
        await _safe_send(
            update,
            f"🛡️ {names} move{'' if plural else 's'} to the **front row** — takes point, "
            f"the enemy's first target.",
        )


def _feature_use_status(character: dict) -> str | None:
    """
    One line summarizing a character's per-rest limited-use class
    feature and how many uses remain, for the character sheet -- so a
    player can check before trying it, rather than only finding out via
    an "already used" reply when they attempt the command. Returns None
    for classes with no trackable per-rest feature (Rogue's Sneak
    Attack and Warlock's Pact Magic are both automatic, no uses to
    track; everything else not yet made mechanical has no state here).
    """
    telegram_user_id = character["telegram_user_id"]
    char_class = character["char_class"]
    if char_class == "Fighter":
        used = db.get_feature_uses(telegram_user_id, character["chat_id"], "second_wind")
        return f"Second Wind: {max(0, 1 - used)}/1 use(s) remaining this rest"
    if char_class == "Barbarian":
        used = db.get_feature_uses(telegram_user_id, character["chat_id"], "rage")
        return f"Rage: {max(0, RAGE_MAX_USES - used)}/{RAGE_MAX_USES} use(s) remaining this rest"
    if char_class == "Bard":
        max_uses = max(1, ability_modifier(character["charisma"]))
        used = db.get_feature_uses(telegram_user_id, character["chat_id"], "bardic_inspiration")
        return f"Bardic Inspiration: {max(0, max_uses - used)}/{max_uses} use(s) remaining this rest"
    if char_class == "Paladin":
        used = db.get_feature_uses(telegram_user_id, character["chat_id"], "lay_on_hands")
        return f"Lay on Hands: {max(0, 1 - used)}/1 use(s) remaining this rest"
    if char_class == "Wizard":
        used = db.get_feature_uses(telegram_user_id, character["chat_id"], "arcane_recovery")
        return f"Arcane Recovery: {max(0, 1 - used)}/1 use(s) remaining this rest"
    if char_class == "Druid":
        used = db.get_feature_uses(telegram_user_id, character["chat_id"], "wild_shape")
        return f"Wild Shape: {max(0, WILD_SHAPE_MAX_USES - used)}/{WILD_SHAPE_MAX_USES} use(s) remaining this rest"
    return None


def _find_campaign_npc_by_name(name: str) -> dict | None:
    """
    Looks up a campaign.json NPC (Grimsby, Old Maren, etc.) by display
    name, case-insensitive. Only for NPCs who were never recruited into
    a real character row -- once recruited (like Sarah), they show up
    via db.find_character_by_name/_find_party_target_by_name instead,
    with a real full sheet.
    """
    lowered = name.lower()
    for npc in CAMPAIGN["npcs"].values():
        if npc.get("name", "").lower() == lowered:
            return npc
    return None


def _format_npc_basic_info(npc: dict) -> str:
    """
    An un-recruited campaign NPC has no real 5E character sheet -- no
    ability scores/HP/AC in the player sense, just narrative fields in
    campaign.json (some do carry a 'stats' block used only if/when
    they're recruited, but showing it here would misrepresent an NPC
    who was never actually recruited as if they were already a party
    member with those exact numbers). Show what's actually true of them
    instead of fabricating or leaking a stat block.
    """
    lines = [f"**{npc['name']}** *(NPC — not currently recruited)*"]
    if npc.get("role"):
        lines.append(f"Role: {npc['role'].replace('_', ' ')}")
    if npc.get("personality"):
        lines.append(f"Personality: {npc['personality']}")
    if npc.get("disposition"):
        lines.append(f"Disposition: {npc['disposition']}")
    if npc.get("recruitable"):
        lines.append("They can be recruited — try inviting them to your party.")
    return "\n".join(lines)


def _format_equipped_line(character: dict) -> str:
    """
    Shared by _format_character_sheet and the character-creation
    summary (2026-07-15, per Coffee) -- what's actually worn, weapon/
    armor/shield each shown honestly as "none" rather than omitted
    when empty, so it's obvious at a glance there's nothing to equip.

    Real live gap (2026-08-06, per Coffee: "when it is added it shud
    show the stats also on the players sheet so they can clearly see
    it") -- this line used to show bare item NAMES only, with zero
    indication of a weapon's damage, an armor's AC, or any
    resistance/element tethered to it, even though the exact same
    stats were already computable via _format_item_stats_line (used
    elsewhere for market/examine/loot). Every real equipped item now
    gets its own indented stats sub-line underneath, same "📊" convention
    the market listing already uses -- nothing new invented, just the
    existing formatter finally reused here too.
    """
    weapon_item = items_module.get_item(character.get("equipped_weapon") or "")
    armor_item = items_module.get_item(character.get("equipped_armor") or "")
    shield_item = items_module.get_item(character.get("equipped_shield") or "")
    parts = [weapon_item["name"] if weapon_item else "no weapon",
             armor_item["name"] if armor_item else "no armor"]
    equipped_items = [weapon_item, armor_item]
    if shield_item:
        parts.append(shield_item["name"])
        equipped_items.append(shield_item)
    for acc_id in character.get("equipped_accessories") or []:
        acc_item = items_module.get_item(acc_id)
        if acc_item:
            parts.append(acc_item["name"])
            equipped_items.append(acc_item)
    lines = [f"Equipped: {', '.join(parts)}"]
    for equipped_item in equipped_items:
        if not equipped_item:
            continue
        stats_line = _format_item_stats_line(equipped_item)
        if stats_line:
            lines.append(f"     📊 {equipped_item['name']}: {stats_line}")
    return "\n".join(lines) + "\n"


def _format_carried_gear_line(character: dict) -> str:
    """
    Real weapons/armor/shields sitting in the backpack, NOT currently
    equipped (2026-07-15, per Coffee) -- a player asking "what could I
    equip" shouldn't have to cross-reference their own inventory list
    against items.py's type field by hand. Empty string (no line at
    all) if nothing equippable is being carried unequipped.
    """
    equipped_ids = {character.get("equipped_weapon"), character.get("equipped_armor"),
                    character.get("equipped_shield"), *(character.get("equipped_accessories") or [])}
    carried_names = []
    for item_id, qty in (character.get("inventory") or {}).items():
        if qty <= 0 or item_id in equipped_ids:
            continue
        item = items_module.get_item(item_id)
        if item and item.get("type") in ("weapon", "armor", "shield", "ring", "amulet", "wondrous"):
            carried_names.append(item["name"])
    if not carried_names:
        return ""
    return f"Carried but not equipped: {', '.join(sorted(carried_names))}\n"


def _format_proficiency_line(character: dict) -> str:
    """
    Real request (2026-08-22, per Coffee: "under our character sheets
    can u show our % to mastery or next lvl on proficiencies?"). Every
    real grindable proficiency/mastery this character has actually
    practiced at least once -- same "only show what's actually been
    used, never a wall of untouched baseline entries" discipline the
    Skills line right above this already follows (skill_uses > 0
    only). 100% is real Mastery for every one of these; a % past 100
    (this game's own uncapped overflow, e.g. Backstab/Spell Mastery)
    still shows the real number rather than clamping it, matching how
    every other mastery display in this game (the Magic menu, battle
    narration) already reads.

    spell_mastery_pct (one entry per individual spell) deliberately
    dropped from this list (2026-08-31, per Coffee, dev-bridge
    screenshot: "I don't want the individual spells to level up, but I
    want the spell types to level up... it cleans up the proficiency
    list and only focusses on the types") -- element_mastery_pct below
    already shows the same information at the type level (e.g. "Fire
    Magic 2%"), which used to sit right next to its own redundant
    per-spell twin ("Fireball 2%, Fire Magic 2%") on this exact line.
    """
    # Real live request (2026-09-03, Coffee, dev-bridge: "Where are my
    # weapon masters and why can't I see them?... clean up this list so
    # it looks a little bit better. You can use emojis and text styles,
    # consider future evolutions. We will need space for the stats,
    # make them clear and legible") -- every entry below was already
    # real and present, just crammed into one undifferentiated comma-
    # joined line (weapon %, armor %, professions, magic elements,
    # backstab/throw/steal/lockpick, and summoning all mixed together),
    # easy to lose track of any one category in. Grouped by real
    # category instead, one labeled line each -- no new data, same
    # underlying fields, just organized so "where's my weapon mastery"
    # has an obvious, dedicated answer. "future evolutions" (more
    # weapon/armor/magic/profession categories as they're added) is
    # already handled for free -- each group is built from whatever
    # keys actually exist on the character, never a fixed list.
    groups: list[tuple[str, str, list[tuple[str, float]]]] = [
        ("⚔️", "Weapons", []),
        ("🛡️", "Armor", []),
        ("🔨", "Professions", []),
        ("✨", "Magic", []),
        ("🗡️", "Combat Skills", []),
        ("🔮", "Summoning", []),
    ]
    weapons, armor, professions, magic, combat, summoning = (g[2] for g in groups)
    for key, pct in sorted((character.get("weapon_proficiency_pct") or {}).items()):
        if pct > PROFICIENCY_STARTING_PCT:
            weapons.append((key.replace("_", " ").capitalize(), pct))
    for key, pct in sorted((character.get("armor_proficiency_pct") or {}).items()):
        if pct > PROFICIENCY_STARTING_PCT:
            armor.append((key.replace("_", " ").capitalize(), pct))
    for key, pct in sorted((character.get("profession_mastery_pct") or {}).items()):
        if pct > PROFICIENCY_STARTING_PCT:
            professions.append((key.replace("_", " ").capitalize(), pct))
    for key, pct in sorted((character.get("element_mastery_pct") or {}).items()):
        if pct > PROFICIENCY_STARTING_PCT:
            magic.append((key.capitalize(), pct))
    for field, label in (
        ("backstab_proficiency_pct", "Backstab"), ("throw_proficiency_pct", "Throw"),
        ("steal_proficiency_pct", "Steal"), ("lockpick_proficiency_pct", "Lockpick"),
    ):
        pct = character.get(field, PROFICIENCY_STARTING_PCT)
        if pct > PROFICIENCY_STARTING_PCT:
            combat.append((label, pct))
    summon_pct = character.get("summoning_mastery_pct", PROFICIENCY_STARTING_PCT)
    if summon_pct > PROFICIENCY_STARTING_PCT:
        summoning.append(("Summoning", summon_pct))

    lines = [f"🎯 **Proficiencies** (100% = Mastery):"]
    for emoji, label, entries in groups:
        if not entries:
            continue
        formatted = ", ".join(f"{name} {pct:.0f}%" for name, pct in entries)
        lines.append(f"  {emoji} {label}: {formatted}")
    if len(lines) == 1:
        return ""
    return "\n".join(lines) + "\n"


def _format_character_sheet(character: dict) -> str:
    """
    Full sheet text for one character -- shared by _do_check_sheet (the
    asking player's own character) and the "show my party's sheets"
    path below (2026-07-14, per Coffee: asking for the whole party's
    sheets should show a real full sheet per member, including
    recruits/AI companions, not just names).
    """
    # Defensive fix (2026-09-06, found auditing scripts/check_error_
    # log.py's own history -- not the actual root cause of either real
    # crash logged there, both already fixed, see test_character_
    # sheet_never_crashes_while_deep_in_the_labyrinth's own docstring).
    # spells.get_spell's own real `-> dict | None` contract was never
    # actually honored here: a stale/renamed spell id lingering in a
    # character's own known_spells would crash this whole sheet with a
    # bare subscript. Skips anything the current catalog no longer
    # recognizes instead -- a sheet missing one unrecognized spell name
    # is a much smaller problem than a sheet that can't render at all.
    spell_names = [sp["name"] for s in character["known_spells"] if (sp := spells_module.get_spell(s)) is not None]
    race_data = races_module.get_race(character["race"])
    features = class_features_module.get_class_features(character["char_class"])
    slot_line = ""
    if character["spell_slots_max"] > 0:
        slot_line = f"Spell slots: {character['spell_slots_current']}/{character['spell_slots_max']}\n"
    feature_status = _feature_use_status(character)
    feature_use_line = f"{feature_status}\n" if feature_status else ""
    # Per Coffee's request (2026-07-14): show each practiced skill's
    # current level right next to it on the sheet, not just buried in
    # skill_uses. practiced_bonus (rules/proficiency.py) already existed
    # as a real "the more you do it, the better you get" mechanic --
    # this just surfaces it. Only lists abilities actually used at least
    # once, so a fresh character's sheet isn't cluttered with six zeros.
    skill_uses = character.get("skill_uses") or {}
    skill_lines = [
        f"{ability.capitalize()} +{practiced_bonus(uses)} ({uses} use{'s' if uses != 1 else ''})"
        for ability, uses in sorted(skill_uses.items())
        if uses > 0
    ]
    skills_line = f"Skills: {', '.join(skill_lines) if skill_lines else 'None practiced yet'}\n"
    proficiency_line = _format_proficiency_line(character)
    asi_line = ""
    if character.get("pending_asi_points"):
        asi_line = (
            f"📈 {character['pending_asi_points']} ability point(s) waiting to be spent — "
            f"say \"level up\" to choose.\n"
        )
    skill_points_line = ""
    if character.get("skill_points"):
        skill_points_line = (
            f"🌌 {character['skill_points']} Universal Manipulation point(s) banked — say \"skill tree\" to spend them.\n"
        )
    invested = len(character.get("skill_tree_upgrades") or [])
    if invested:
        skill_points_line += f"🌌 {invested} Universal Manipulation point(s) invested so far.\n"
    # Rebirth/hybrid (2026-07-22): only shown once a character has
    # actually gone through the rebirth loop at least once -- a never-
    # reborn character's sheet looks exactly as it always has.
    rebirth_line = ""
    if character.get("rebirth_count"):
        rebirth_line = f"✨ Reborn {character['rebirth_count']}x\n"
        if character.get("hybrid_class"):
            rebirth_line += (
                f"🌟 Hybrid: {character['hybrid_class']} "
                f"(tier {hybrid_tier(character['rebirth_count'])}/{HYBRID_MAX_TIER})\n"
            )
    subclass_line = ""
    if character.get("subclass"):
        if character["char_class"] == "Wizard":
            subclass_line = f"📖 School of {character['subclass'].capitalize()}\n"
        else:
            subclass_line = f"📖 Subclass: {character['subclass']}\n"
    # Class profession affinity (2026-07-25, per Coffee: "make sure all
    # classes and sub classes have a profession") -- shown so the real
    # +2 bonus (class_profession_affinity_bonus) isn't invisible.
    home_profession = CLASS_PROFESSIONS.get(character["char_class"])
    profession_line = f"🔨 Favored trade: {home_profession.capitalize()} (+{CLASS_PROFESSION_AFFINITY_BONUS})\n" if home_profession else ""
    echo_trial_line = f"🌀 Echo trial tier: {character['echo_trial_tier']}\n" if character.get("echo_trial_tier") else ""
    title_suffix = f" \"{character['active_title']}\"" if character.get("active_title") else ""
    name_line = f"**{character['name']}**{title_suffix}" + (" *(AI companion)*" if character.get("is_ai") else "")
    equipped_line = _format_equipped_line(character)
    carried_gear_line = _format_carried_gear_line(character)
    pronouns_line = f"Pronouns: {character['pronouns']}\n" if character.get("pronouns") else ""
    description_line = f"\"{character['description']}\"\n" if character.get("description") else ""
    # Presence (task #144): only real players have a meaningful status;
    # AI companions/NPCs have no presence of their own.
    presence_line = ""
    if not character.get("is_ai"):
        note_suffix = f" — \"{character['status_note']}\"" if character.get("status_note") else ""
        presence_line = f"Status: {_presence_status(character)}{note_suffix}\n"
    streak_line = ""
    if not character.get("is_ai") and character.get("login_streak_days", 0) > 0:
        days = character["login_streak_days"]
        streak_line = f"🔥 Login streak: {days} day{'s' if days != 1 else ''}\n"
    # Real live bug (2026-07-16, Coffee): ability scores were only ever
    # shown once, in the one-off creation sheet -- this shared sheet
    # (used by every later "check my sheet"/Support/party-sheet lookup)
    # never included them at all.
    ability_line = (
        f"STR {character['strength']} DEX {character['dexterity']} "
        f"CON {character['constitution']} INT {character['intelligence']} "
        f"WIS {character['wisdom']} CHA {character['charisma']}\n"
    )
    next_threshold = XP_THRESHOLDS.get(character["level"] + 1)
    xp_remaining_line = (
        f" ({max(next_threshold - character['xp'], 0)} XP to Level {character['level'] + 1})"
        if next_threshold is not None else " (Max level reached)"
    )
    # Damage resistances (2026-07-24, per Coffee: "when resistences
    # apply show it on char sheets" -- extended 2026-08-14: "make sure
    # players resistences and elemental stats are listed on the player
    # sheet when it becomes available"). Originally racial-only
    # (Dwarf/poison, Dragonborn+Tiefling/fire, the only source a player
    # carried at the time) -- now merged with real equipped-gear
    # resistances/vulnerabilities/immunities/elemental wards too
    # (_compute_equipped_resist_profile, the same read-only extraction
    # combat's own _apply_equipped_elemental_profile uses, without that
    # function's side effects -- checking your sheet shouldn't leave
    # stray combat-only fields sitting on the character dict). Magic
    # penetration (the rebirth-earned counter to any resistance an ENEMY
    # has) is shown alongside it, so a reborn character sees both sides
    # of the same system together.
    equipped_profile = _compute_equipped_resist_profile(character)
    all_resistances = set(races_module.racial_damage_resistances(character["race"])) | equipped_profile["resistances"]
    resist_bits = []
    if equipped_profile["immunities"]:
        resist_bits.append(f"immune to {', '.join(sorted(equipped_profile['immunities']))}")
    if all_resistances:
        resist_bits.append(f"resistant to {', '.join(sorted(all_resistances))}")
    if equipped_profile["vulnerabilities"]:
        resist_bits.append(f"vulnerable to {', '.join(sorted(equipped_profile['vulnerabilities']))}")
    for dtype, pct in sorted(equipped_profile["elemental_resistance_pct"].items()):
        if pct >= 150:
            resist_bits.append(f"heals from {dtype} damage")
        elif pct >= 100:
            resist_bits.append(f"nullifies {dtype} damage")
        else:
            resist_bits.append(f"{pct:.0f}% resistant to {dtype}")
    resistance_line = f"🌡️ {'; '.join(resist_bits)}\n" if resist_bits else ""
    penetration = magic_penetration_pct(character.get("rebirth_count", 0))
    magic_penetration_line = f"🔮 Magic penetration: {penetration:.0f}% (counters enemy resistances)\n" if penetration > 0 else ""

    # Real request (2026-08-20, per Coffee: "make the player sheets
    # more visually stimulating? clean up some of the long tests and
    # make it look more appealing") -- this screen was one dense,
    # ungrouped wall of ~25 lines. Restructured into real labeled
    # sections with the same "━━━" divider convention this session
    # already established for Bestiary/Remnants, and the two fields
    # that could grow genuinely long (Racial traits, Class features)
    # are now real bulleted sub-lists instead of one long semicolon-
    # joined line. Every existing label/value phrase is preserved
    # verbatim (only regrouped) so nothing a player or Support already
    # looks for on this sheet goes missing.
    divider = "\n━━━━━━━━━━━━━━━\n"
    traits_block = (
        "Racial traits:\n" + "\n".join(f"• {t}" for t in race_data["traits"])
        if race_data and race_data.get("traits") else "Racial traits: None"
    )
    features_block = (
        "Class features:\n" + "\n".join(f"• {f}" for f in features)
        if features else "Class features: None"
    )
    header_section = (
        f"{name_line} — {character['race']} {character['char_class']}\n"
        f"{pronouns_line}"
        f"{presence_line}"
        f"{streak_line}"
        f"{description_line}"
    ).rstrip("\n")
    vitals_section = (
        f"📊 **Vitals**\n"
        f"Level {character['level']} | XP {character['xp']}{xp_remaining_line}\n"
        f"{rebirth_line}"
        f"{subclass_line}"
        f"{profession_line}"
        f"{echo_trial_line}"
        f"HP {character['hp_current']}/{character['hp_max']} | AC {character['armor_class']}\n"
        f"{ability_line}"
        f"Alignment: {_alignment_label(character.get('alignment_law_chaos', 0), character.get('alignment_good_evil', 0))}"
    ).rstrip("\n")
    gear_section = (
        f"🎒 **Gear & Gold**\n"
        f"Gold: {character['gold']} | Guild: {character.get('guild') or 'None'}\n"
        f"{equipped_line}"
        f"{carried_gear_line}"
    ).rstrip("\n")
    magic_section = (
        f"✨ **Magic**\n"
        f"Spells known: {', '.join(spell_names) if spell_names else 'None'}\n"
        f"{slot_line}"
        f"{resistance_line}"
        f"{magic_penetration_line}"
    ).rstrip("\n")
    traits_section = (
        f"🧬 **Traits & Features**\n"
        f"{traits_block}\n"
        f"{features_block}\n"
        f"{feature_use_line}"
        f"{skills_line}"
        f"{proficiency_line}"
    ).rstrip("\n")
    # Real live crash (2026-09-04, error log: Sheri/Charvenna and,
    # independently, Coffee/Elduinn -- two unrelated players hitting
    # this hours apart): character["current_location"] is
    # LABYRINTH_LOCATION_SENTINEL for anyone genuinely inside a live
    # Labyrinth run -- a real, ordinary, expected state, not an edge
    # case -- and cl.get_location has no real CAMPAIGN entry for it,
    # so the old unconditional ['name'] subscript crashed the whole
    # sheet. Falls back to a plain, honest label for that (or any
    # other unresolvable) location instead of assuming one always
    # exists.
    if character["current_location"] == LABYRINTH_LOCATION_SENTINEL:
        location_section = "📍 Location: Deep in the Labyrinth"
    else:
        current_location_data = cl.get_location(CAMPAIGN, character["current_location"])
        location_section = f"📍 Location: {current_location_data['name'] if current_location_data else 'Unknown'}"
    # Per Coffee (2026-07-16): pending ASI points shown last, so a
    # player who missed the level-up prompt still sees it waiting every
    # time they check their sheet, not just buried mid-sheet.
    pending_section = (f"{asi_line}{skill_points_line}").rstrip("\n")

    sections = [
        header_section, vitals_section, gear_section, magic_section, traits_section, location_section,
    ]
    if pending_section:
        sections.append(pending_section)
    return divider.join(sections)


async def _do_check_sheet(update: Update, target_name: str | None = None) -> None:
    # Per Coffee's live report (2026-07-14): "Show me SERA's character
    # sheet" had nowhere to go -- check_sheet only ever showed the
    # asker's OWN sheet, so it fell through to "examine" and searched
    # for an interactable object named "Sarah" instead. A named target
    # is looked up among real party members first (same lookup used for
    # support-spell targeting), then broadened (2026-07-14, per Coffee:
    # "character sheets of all players AI, NPC and human") to any real
    # character row at all -- covers a human's other, non-currently-
    # active character slot -- and finally to un-recruited campaign
    # NPCs, who get honest basic info instead of a fabricated stat
    # block, since they don't have a real 5E sheet until recruited.
    if target_name:
        target = _find_party_target_by_name(target_name, update.effective_chat.id) or db.find_character_by_name(target_name, update.effective_chat.id)
        if target is not None:
            await _safe_send(update, _format_character_sheet(target), speak=False)
            return
        npc = _find_campaign_npc_by_name(target_name)
        if npc is not None:
            await _safe_send(update, _format_npc_basic_info(npc), speak=False)
            return
        # Real live bug (2026-07-16, Coffee): .title() on a hallucinated,
        # non-name target (the model can invent one when there's no real
        # action for a message to match -- see task #110/#112) mangled
        # ordinary text into nonsense like "Player'S Own Character".
        # target_name is echoed as given rather than reformatted.
        await update.effective_chat.send_message(
            f"Nobody named {target_name} is playing right now — can't show a sheet for them.",
            message_thread_id=topics.thread_id_for(update.effective_chat.id, "adventure"),
        )
        return

    character = db.get_character(update.effective_user.id, update.effective_chat.id)
    if character is None:
        await update.effective_chat.send_message(
            "You don't have a character yet — say something like "
            "'I want to create a character' to get started!",
            message_thread_id=topics.thread_id_for(update.effective_chat.id, "adventure"),
        )
        return
    # Task #176: spell-cast buttons only make sense on the ASKER's own
    # sheet (target_name is None here) -- nobody can tap a button to
    # cast someone else's spells.
    await _safe_send(
        update, _format_character_sheet(character), reply_markup=_with_menu_button(_spell_keyboard(character)),
        speak=False,
    )


_INVENTORY_SORT_TYPE_TO_CATEGORY = {
    "weapon": "Battle", "armor": "Battle", "shield": "Battle",
    "consumable": "Support",
    "scroll": "Magic", "ring": "Magic", "amulet": "Magic", "wondrous": "Magic",
}
_INVENTORY_SORT_CATEGORY_ORDER = ["Battle", "Support", "Magic", "Normal"]
_INVENTORY_SORT_CATEGORY_ICON = {"Battle": "⚔️", "Support": "💚", "Magic": "✨", "Normal": "📦"}


def _inventory_sort_category(item: dict | None) -> str:
    """
    Real, grounded 4-bucket mapping from an item's own real 'type'
    field (2026-08-27, per Coffee: "create a function so i can sort my
    inventory... Battle type, Support type, Magic type, Normal").
    Every real item type maps unambiguously (weapon/armor/shield ->
    Battle, consumable -> Support, scroll/ring/amulet/wondrous ->
    Magic, everything else -- material/tool/quest_item/book/map ->
    Normal) -- no per-item judgment calls, so this can never
    misclassify one item differently than its same-type neighbors.
    """
    return _INVENTORY_SORT_TYPE_TO_CATEGORY.get((item or {}).get("type"), "Normal")


def _inventory_sort_keyboard(character: dict) -> list[list[InlineKeyboardButton]]:
    """One-tap toggle for the backpack's persistent grouped view (character.inventory_sort_mode)."""
    if character.get("inventory_sort_mode") == "type":
        return [[InlineKeyboardButton("📋 Plain Order", callback_data="item|sort|off")]]
    return [[InlineKeyboardButton("🔀 Sort by Type", callback_data="item|sort|type")]]


async def _do_check_inventory(update: Update) -> None:
    character = db.get_character(update.effective_user.id, update.effective_chat.id)
    if character is None:
        await update.effective_chat.send_message(
            "You don't have a character yet!", message_thread_id=topics.thread_id_for(update.effective_chat.id, "adventure")
        )
        return
    if not character["inventory"]:
        await update.effective_chat.send_message(
            "Your backpack is empty.", message_thread_id=topics.thread_id_for(update.effective_chat.id, "adventure")
        )
        return
    if character.get("inventory_sort_mode") == "type":
        grouped: dict[str, list[str]] = {cat: [] for cat in _INVENTORY_SORT_CATEGORY_ORDER}
        for item_id, qty in character["inventory"].items():
            item = items_module.get_item(item_id)
            name = item["name"] if item else item_id
            grouped[_inventory_sort_category(item)].append(f"  {name} x{qty}")
        lines = []
        for cat in _INVENTORY_SORT_CATEGORY_ORDER:
            if grouped[cat]:
                lines.append(f"{_INVENTORY_SORT_CATEGORY_ICON[cat]} **{cat}**")
                lines.extend(grouped[cat])
    else:
        lines = []
        for item_id, qty in character["inventory"].items():
            item = items_module.get_item(item_id)
            name = item["name"] if item else item_id
            lines.append(f"  {name} x{qty}")
    item_rows = _item_keyboard(character)
    craft_rows = _craft_keyboard(character)
    # Scroll-cast buttons (2026-07-25, per Coffee: "No button for
    # scrolls?" -- reported from exactly this backpack screen). Known
    # spells already have their own buttons on the character sheet, so
    # only the scroll-derived ones show up here, not a duplicate set.
    scroll_rows = _scroll_spell_buttons(character)
    # Give buttons (2026-07-25, per Coffee: "anything the party might
    # need we need buttons for - like giving them item for their
    # backpack so they can use or cast them"). One per carried item,
    # only shown at all when someone real is actually here to give it
    # to (same presence scoping _do_give_item's own free-text already
    # uses) -- dispatches through that exact same handler.
    give_rows = _give_item_keyboard(character)
    # Real live bug (2026-07-25, caught in bot_live_tmp.log right after
    # this session's own give-buttons deploy): InlineKeyboardMarkup.
    # inline_keyboard is a real tuple (confirmed directly against the
    # installed python-telegram-bot), while _scroll_spell_buttons
    # returns a plain list -- concatenating a tuple to a list raises
    # TypeError, crashing this screen outright for any character with
    # actual usable consumables or craftable recipes (item_rows/
    # craft_rows non-None), which is the common case. list(...) on each
    # piece normalizes everything to the same type before combining.
    combined_rows = (
        _inventory_sort_keyboard(character)
        + list(item_rows.inline_keyboard if item_rows else [])
        + list(craft_rows.inline_keyboard if craft_rows else [])
        + scroll_rows
        + list(give_rows.inline_keyboard if give_rows else [])
    )
    keyboard = InlineKeyboardMarkup(combined_rows) if combined_rows else None
    await _safe_send(
        update, "🎒 Your backpack:\n" + "\n".join(lines), reply_markup=_with_menu_button(keyboard),
        speak=False,
    )


_SPELL_MENU_MECHANIC_NOTES = {
    # Real per-spell mechanics that don't reduce to a plain damage_dice/
    # heal_dice read -- same "ground it in what _cast_utility_spell
    # actually does, never invented flavor" discipline
    # ai/support_agent.py's own _SPELL_REAL_MECHANIC_OVERRIDES already
    # follows for these same four cantrips (2026-08-11 grounding fix).
    "counterspell": "Reaction-only -- automatically negates a monster's spell cast, can't be cast on your own turn.",
    "shield": f"+{spells_module.SPELLS['shield']['amount']} AC for a real 3-5 round window -- also auto-triggers instantly as a reaction against an attack that would've hit.",
    "guidance": "Gives a real +2 bonus to your own next skill/ability check.",
    "thaumaturgy": "Gives a real +2 bonus to your own next skill/ability check.",
    "mage_hand": "Gives a real +2 bonus to your own next skill/ability check.",
    "prestidigitation": "Gives a real +2 bonus to your own next skill/ability check.",
    "detect_magic": "Reveals which of your carried items are genuinely magical.",
    "revivify": "Revives a dead party member.",
    "spare_the_dying": "Stabilizes an ally at 0 HP so they stop making death saves.",
    "bless": "Buffs the whole present party for the spell's duration.",
    "misty_step": "A guaranteed escape from combat.",
    "dimension_door": "A guaranteed escape from combat.",
    "longstrider": "A guaranteed escape from combat.",
    "dispel_magic": "Strips an active buff/condition from a target.",
}


def _spell_menu_description(spell_id: str, spell: dict) -> str:
    """
    One real, grounded line per spell for the Magic menu -- built from
    the spell's own actual data fields (damage_dice/heal_dice/
    save_ability/amount/duration_rounds) or a hand-written note for the
    handful of spells whose real mechanic isn't just "roll this dice,"
    never invented flavor text (same grounding discipline
    ai/support_agent.py's catalog already follows).
    """
    if spell_id in _SPELL_MENU_MECHANIC_NOTES:
        return _SPELL_MENU_MECHANIC_NOTES[spell_id]
    effect = spell.get("effect")
    if effect == "damage":
        line = f"Deals {spell['damage_dice']} {spell.get('damage_type', '')} damage".replace("  ", " ")
        if spell.get("save_ability"):
            line += f" ({spell['save_ability']} save)"
        return line + "."
    if effect == "heal":
        return f"Heals {spell['heal_dice']} HP."
    if effect == "resurrect":
        return "Revives a dead party member."
    if effect == "summon":
        return "Summons a spirit ally to fight alongside you for the rest of combat."
    if effect == "ac_bonus":
        return f"+{spell.get('amount', 0)} AC for {spell.get('duration_rounds', 1)} round(s)."
    if effect == "negate":
        return "Negates a hostile effect on a target."
    if effect == "buff":
        return f"A real combat buff lasting {spell.get('duration_rounds', 10)} rounds."
    return "Utility spell."


async def _do_show_magic_menu(update: Update) -> None:
    """
    Real request (2026-08-22, per Coffee: "can you add a Menu for
    Magic? Once users get new magic it can be added into there in the
    menu. Put the menu underneath Inventory" -- then: "show the current
    lv of the spell and give a brief description of the spell, also
    allso them to click the spell (healing spells to heal party) and
    also passive spells like Shield or Counter can be cast from the
    menu"). A dedicated, always-current view of a character's own real
    known_spells -- the same cast buttons already exist buried at the
    bottom of the much longer Character Sheet screen (_spell_keyboard,
    reused here unchanged -- it already includes EVERY known spell
    regardless of effect type, and spell_menu_callback's "cast" action
    already routes any of them through the real _do_cast_spell/
    _cast_utility_spell pipeline, heal target-picking and Shield/
    Counterspell's own real reaction rules included, so no new casting
    logic was needed here), but a freshly Remnant-taught or newly
    learned spell was easy to miss there. Shows each spell's real
    level, a grounded one-line description (_spell_menu_description),
    and its real Element Mastery % and current AOE target reach
    (_spell_target_count) -- read-only display, never grinds mastery
    itself (grinding only ever happens on a real cast, via
    _grind_element_mastery).

    Consolidated 2026-08-31 (per Coffee: "I don't want the individual
    spells to level up, but I want the spell types to level up") --
    used to show a separate per-spell "X% mastery" figure alongside
    the element's own %; that per-spell tier no longer exists, so only
    the element figure remains. Also fixes a small pre-existing gap
    found while touching this: a heal spell's own damage_type is None
    (it grinds element_mastery_pct["heal"] instead, same convention
    _grind_heal_mastery uses), so the old `if damage_type:` guard
    silently never showed a heal spell's own Heal Magic % here at all
    -- now resolved the same way the real grind itself resolves it.
    """
    character = db.get_character(update.effective_user.id, update.effective_chat.id)
    if character is None:
        await update.effective_chat.send_message(
            "You don't have a character yet!", message_thread_id=topics.thread_id_for(update.effective_chat.id, "adventure")
        )
        return
    known = character.get("known_spells") or []
    if not known:
        await _safe_send(
            update,
            "🔮 You don't know any spells yet. Defeating a Remnant, or playing a "
            "spellcasting class/subclass, can teach you real magic.",
            reply_markup=_with_menu_button(None), speak=False,
        )
        return
    element_mastery = character.get("element_mastery_pct", {})
    lines = []
    for spell_id in known:
        spell = spells_module.get_spell(spell_id)
        if not spell:
            continue
        element_key = spell.get("damage_type") or "heal"
        element_pct = element_mastery.get(element_key, PROFICIENCY_STARTING_PCT)
        mastery_bits = [f"{element_key} magic {element_pct:.0f}%"]
        if spell.get("aoe"):
            count = _spell_target_count(element_pct)
            mastery_bits.append(f"targets: {'All' if count is None else count}")
        lines.append(
            f"**{spell['name']}** (Lv{spell['level']}) — {', '.join(mastery_bits)}\n"
            f"  _{_spell_menu_description(spell_id, spell)}_"
        )
    slot_line = ""
    if character.get("spell_slots_max", 0) > 0:
        slot_line = f"\n\nSpell slots: {character['spell_slots_current']}/{character['spell_slots_max']}"
    text = "🔮 **Your Magic**\n\n" + "\n\n".join(lines) + slot_line
    await _safe_send(
        update, text, reply_markup=_with_menu_button(_spell_keyboard(character)), speak=False,
    )


def _craft_keyboard(character: dict) -> InlineKeyboardMarkup | None:
    """
    Per Coffee (2026-07-24, right after the new named-professions split:
    "make sure characters have buttons for all that stuff too"): a real
    tap per recipe this character can actually afford to attempt right
    now (has_materials), same "only show what's actually usable"
    discipline as _item_keyboard. Tapping dispatches through the exact
    same _do_craft free text already uses.
    """
    craftable = [
        recipe_id for recipe_id, recipe in RECIPES.items()
        if has_materials(character.get("inventory", {}), recipe)
    ]
    if not craftable:
        return None
    return InlineKeyboardMarkup([
        [InlineKeyboardButton(f"⚗️ Craft {items_module.get_item(rid)['name']}", callback_data=f"craft|make|{rid}")]
        for rid in craftable
    ])


async def craft_menu_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Handles taps on _craft_keyboard -- dispatches through the exact same _do_craft free text already uses."""
    query = update.callback_query
    parts = (query.data or "").split("|")
    action = parts[1] if len(parts) > 1 else ""
    await _safe_answer(query)
    if action != "make" or len(parts) < 3:
        return
    item = items_module.get_item(parts[2])
    if item is None:
        return
    await _do_craft(update, f"craft {item['name']}")


def _item_keyboard(character: dict) -> InlineKeyboardMarkup | None:
    """
    Task #176 revision, per Coffee: real usable buttons for the backpack
    listing too, not just the sheet's spells -- his own stated example
    ("use a potion or charm a player") was a consumable, not a spell.
    Grounded in this character's actual carried consumables (qty > 0),
    same convention _battle_menu_keyboard's Items button already uses.
    Tapping opens the same shared _target_picker_keyboard as spells.

    Scrolls deliberately do NOT belong in this list (2026-08-01,
    confirmed while investigating a suspected gap here): they're cast,
    not "used" -- _do_use_item only ever accepts type in
    ("consumable", "map"), so a scroll button routed through this same
    item|use path would always fail with "Use what, exactly?". Scrolls
    already get their own real buttons via _scroll_spell_buttons
    (2026-07-25), shown on this exact same backpack screen through the
    spell|cast path instead -- see _do_show_inventory's combined_rows.
    """
    consumable_ids = [
        item_id for item_id, qty in character.get("inventory", {}).items()
        if qty > 0 and (items_module.get_item(item_id) or {}).get("type") == "consumable"
    ]
    if not consumable_ids:
        return None
    buttons = [
        [InlineKeyboardButton(f"🧪 {items_module.get_item(i)['name']}", callback_data=f"item|use|{i}")]
        for i in consumable_ids
    ]
    return InlineKeyboardMarkup(buttons)


async def item_menu_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Handles taps on _item_keyboard and its target picker -- see their docstrings."""
    query = update.callback_query
    parts = (query.data or "").split("|")
    action = parts[1] if len(parts) > 1 else ""
    await _safe_answer(query)

    if action == "sort":
        mode = parts[2] if len(parts) > 2 else "off"
        character = db.get_character(update.effective_user.id, update.effective_chat.id)
        if character is None:
            return
        db.update_character(update.effective_user.id, update.effective_chat.id, inventory_sort_mode=mode)
        await _do_check_inventory(update)
        return

    if action == "use":
        item_id = parts[2] if len(parts) > 2 else None
        item = items_module.get_item(item_id) if item_id else None
        character = db.get_character(update.effective_user.id, update.effective_chat.id)
        if item is None or character is None:
            return
        picker = _target_picker_keyboard("item", item_id, character)
        if picker is None:
            await _do_use_item(update, f"use {item['name']}")
            return
        await _safe_edit_markup(query, picker)
        return

    if action == "target":
        item_id = parts[2] if len(parts) > 2 else None
        target_token = parts[3] if len(parts) > 3 else None
        item = items_module.get_item(item_id) if item_id else None
        if item is None or target_token is None:
            return
        if target_token == "self":
            await _do_use_item(update, f"use {item['name']}")
            return
        target_character = db.get_character(int(target_token), update.effective_chat.id)
        if target_character is None:
            return
        await _do_use_item(update, f"use {item['name']} on {target_character['name']}")


def _give_item_keyboard(character: dict) -> InlineKeyboardMarkup | None:
    """
    Give buttons (2026-07-25, per Coffee: "anything the party might
    need we need buttons for - like giving them item for their
    backpack so they can use or cast them"). One button per carried
    item (any type, not just consumables -- a scroll or a piece of gear
    is just as giveable as a potion), only built when someone real is
    actually here to receive it (same presence scoping _do_give_item's
    own free-text path already uses) -- an empty room means no give
    buttons at all, same as _target_picker_keyboard's own "nothing to
    pick" case.
    """
    others = [
        p for p in _get_combat_eligible_party_members(character["current_location"], character["chat_id"])
        if p["telegram_user_id"] != character["telegram_user_id"]
    ]
    if not others or not character.get("inventory"):
        return None
    buttons = [
        [InlineKeyboardButton(f"🤝 Give {items_module.get_item(i)['name']}", callback_data=f"give|pick|{i}")]
        for i, qty in character["inventory"].items() if qty > 0 and items_module.get_item(i)
    ]
    return InlineKeyboardMarkup(buttons) if buttons else None


async def give_menu_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Handles taps on _give_item_keyboard -- picks an item, then a recipient, then dispatches through the exact same _do_give_item free text already uses."""
    query = update.callback_query
    parts = (query.data or "").split("|")
    action = parts[1] if len(parts) > 1 else ""
    await _safe_answer(query)

    if action == "pick":
        item_id = parts[2] if len(parts) > 2 else None
        item = items_module.get_item(item_id) if item_id else None
        character = db.get_character(update.effective_user.id, update.effective_chat.id)
        if item is None or character is None:
            return
        others = [
            p for p in _get_combat_eligible_party_members(character["current_location"], character["chat_id"])
            if p["telegram_user_id"] != character["telegram_user_id"]
        ]
        if not others:
            return
        buttons = [
            [InlineKeyboardButton(p["name"], callback_data=f"give|to|{item_id}|{p['telegram_user_id']}")]
            for p in others
        ]
        await _safe_edit_markup(query, InlineKeyboardMarkup(buttons))
        return

    if action == "to":
        item_id = parts[2] if len(parts) > 2 else None
        target_token = parts[3] if len(parts) > 3 else None
        item = items_module.get_item(item_id) if item_id else None
        if item is None or target_token is None:
            return
        target_character = db.get_character(int(target_token), update.effective_chat.id)
        if target_character is None:
            return
        await _do_give_item(update, f"give {item['name']} to {target_character['name']}")


def _find_resource_node(location: dict, action_text: str) -> dict | None:
    nodes = location.get("resource_nodes", [])
    if not nodes:
        return None
    lowered = action_text.lower()
    for node in nodes:
        if node["id"] in lowered or node["material"] in lowered or node["name"].lower() in lowered:
            return node

    # Fallback: a word from the input as a substring of the node's
    # skill name or material id, in either direction -- confirmed live
    # 2026-07-14 (Coffee): "I would like to chop for lumber" didn't
    # match the wood node at all (material id is "wood", display name
    # mentions "timber", and neither contains "lumber"), even though
    # "lumber" is exactly what its skill (lumberjacking) is named for.
    stopwords = {"the", "a", "an", "of", "at", "on", "in", "to", "for", "and"}
    words = [w for w in lowered.split() if len(w) >= 4]
    for node in nodes:
        skill = node.get("skill", "")
        material = node["material"]
        name_words = {w for w in node["name"].lower().split() if w not in stopwords and len(w) >= 4}
        if any(
            (skill and (w in skill or skill in w)) or w in material or material in w or w in name_words
            for w in words
        ):
            return node

    if len(nodes) == 1:
        return nodes[0]
    return None


def _missing_tools_for_gathering(character: dict, skill_key: str) -> list[str]:
    """
    Real tool requirements (2026-07-16, per Coffee): fishing needs a
    fishing pole AND bait; lumberjacking needs a woodcutter's axe;
    mining needs a pickaxe. Herbalism deliberately needs no tool at all
    (picking a plant by hand is free) -- items.py's "required_for" field
    is the single source of truth, so a new tool-gated skill only ever
    needs a new items.py entry, not a bot.py code change. Returns the
    display names of any REQUIRED tools the character doesn't currently
    carry (empty list if fully equipped or the skill needs no tool).
    """
    required_items = [
        item for item in items_module.ITEMS.values()
        if item.get("required_for") == skill_key
    ]
    return [
        item["name"] for item in required_items
        if character["inventory"].get(_item_id_for(item), 0) <= 0
    ]


def _gathering_tool_grounded_fact(character: dict, skill_key: str) -> str | None:
    """
    Real live bug (2026-08-11, dev-topic report): "Gather iron ore"
    narrated Laurienna's "fingers clawed at the rough stone floor"
    despite her actually carrying (and this same call already having
    confirmed, via _missing_tools_for_gathering) a real Pickaxe --
    narrate_skill_check's own grounded_fact parameter exists exactly
    to prevent this class of invented detail, but _do_gather never
    passed one at all. Returns a real, already-true fact naming the
    actual required tool for this skill (e.g. "Laurienna is using her
    Pickaxe for this."), or None for a tool-free skill like herbalism,
    where there's genuinely nothing to ground and bare hands ARE
    correct.
    """
    required_items = [
        item for item in items_module.ITEMS.values()
        if item.get("required_for") == skill_key
    ]
    owned_names = [
        item["name"] for item in required_items
        if character["inventory"].get(_item_id_for(item), 0) > 0
    ]
    if not owned_names:
        return None
    return f"{character['name']} is using {' and '.join(owned_names)} for this, not bare hands."


def _item_id_for(item: dict) -> str:
    return next(iid for iid, i in items_module.ITEMS.items() if i is item)


def _gather_quantity(character: dict, skill_key: str, practiced_bonus: int) -> int:
    """
    Real quantity bonus (2026-07-16, per Coffee): base gather is always
    1. Herbalism is the one tool-free skill, but owning Shears lets you
    harvest up to 3 per success (a dice roll, not a flat bonus) --
    Shears use "boosts_quantity_for" (items.py) since they're optional,
    unlike the required tools above. Extended 2026-07-21 (per Coffee:
    "add shovels to increase the amount of bait we can get... have it
    use a dice roll") to check ANY owned tool's "boosts_quantity_for"
    generically, instead of hardcoding Shears/herbalism specifically --
    Shovel/bait_gathering works the exact same way for free, and any
    future tool+skill pairing added to items.py needs zero new code
    here either. Separately, real practiced skill (the same
    practiced_bonus that already improves the success roll, see
    _practiced_bonus_for) has a small chance at one extra material on
    ANY gathering skill once it's capped out, rewarding repeated use
    beyond just a better roll target.
    """
    quantity = 1
    has_boost_tool = any(
        character["inventory"].get(item_id, 0) > 0 and item.get("boosts_quantity_for") == skill_key
        for item_id, item in items_module.ITEMS.items()
    )
    if has_boost_tool:
        quantity = roll(1, 3)[0]
    if practiced_bonus >= MAX_PRACTICE_BONUS and roll_d20() >= 15:
        quantity += 1
    return quantity


async def _do_gather(update: Update, action_text: str, forced_roll: int | None = None) -> None:
    """
    Gathering a raw material from a location's resource node — a real
    ability check (rules layer) decides success, matching every other
    outcome in this game; the AI only narrates it. Honors physical-dice
    mode (character.manual_dice_enabled) the same way _do_attack and
    _do_skill_check do -- real bug found live 2026-07-18 (Coffee: "if i
    have dice on shudnt i be rolling my own dice?"): this was the one
    outcome-deciding roll in the game that never checked
    manual_dice_enabled at all, silently always rolling internally
    regardless of the player's own preference.
    """
    character = db.get_character(update.effective_user.id, update.effective_chat.id)
    if character is None:
        await update.effective_chat.send_message(
            "You don't have a character yet!", message_thread_id=topics.thread_id_for(update.effective_chat.id, "adventure")
        )
        return

    location = cl.get_location(CAMPAIGN, character["current_location"])
    node = _find_resource_node(location, action_text) if location else None
    if node is None:
        resource_nodes = location.get("resource_nodes", []) if location else []
        hint = f" Things worth gathering here: {', '.join(n['name'] for n in resource_nodes)}" if resource_nodes else ""
        await update.effective_chat.send_message(
            f"🌿 **{character['name']}** doesn't spot anything worth gathering here.{hint}",
            message_thread_id=topics.thread_id_for(update.effective_chat.id, "adventure"),
        )
        return

    # 2026-07-14, per Coffee: named gathering professions (herbalism,
    # mining, fishing, lumberjacking) each level up independently, not
    # lumped into the shared ability-check practice track a combat skill
    # check would also feed. A node's "skill" field is the tracked
    # practice key; the dice roll itself still uses the node's "ability"
    # (e.g. mining is a Strength check, fishing is Wisdom) -- same
    # split db.py's skill_uses dict already supports for free, since
    # it's just an arbitrary string-keyed JSON dict, not one column per
    # ability. Falls back to the ability name for any node without an
    # explicit "skill" (keeps old behavior for anything not yet tagged).
    skill_key = node.get("skill", node["ability"])

    missing_tools = _missing_tools_for_gathering(character, skill_key)
    if missing_tools:
        await update.effective_chat.send_message(
            f"🌿 **{character['name']}** needs {' and '.join(missing_tools)} to do that — doesn't have "
            f"{'them' if len(missing_tools) > 1 else 'one'} yet. Check a shop.",
            message_thread_id=topics.thread_id_for(update.effective_chat.id, "adventure"),
        )
        return

    if forced_roll is None and character.get("manual_dice_enabled") and not character.get("is_ai"):
        forced_roll = _extract_combined_roll(action_text)
    if forced_roll is None and character.get("manual_dice_enabled") and not character.get("is_ai"):
        _chat_scoped_dict(_PENDING_DICE_ROLLS, update.effective_chat.id)[update.effective_user.id] = _new_pending_roll("gather", action_text, update.effective_chat.id)
        # Task #187: _safe_send, not a raw send_message -- this exact site
        # dropped a real prompt live to a transient TimedOut before this fix.
        await _safe_send(update, f"🎲 **{character['name']}**, roll a d20 for this {node['ability']} check and tell me the result (you have 1 minute, or I'll roll for you).")
        return

    result = roll_ability_check(character, node["ability"], proficient=False, forced_roll=forced_roll)
    bonus = _practiced_bonus_for(update.effective_user.id, update.effective_chat.id, skill_key)
    # Class profession affinity (2026-07-25, per Coffee), same real +2
    # as _do_craft's -- a Ranger foraging herbs, a Barbarian in a mine,
    # etc. See rules/crafting.py's CLASS_PROFESSIONS.
    bonus += class_profession_affinity_bonus(character["char_class"], skill_key)
    # Magic item system Phase 4 (2026-08-02): a third additive source,
    # live-summed off equipped gear -- same "just one more term in the
    # existing bonus accumulator" shape this function already uses for
    # the two sources above.
    bonus += _equipped_profession_bonus(character, skill_key)
    # Universal Manipulation "prof_X" (2026-08-06, per Coffee): a real
    # 4th additive source, +1 per point invested in this profession.
    bonus += _skill_points(character, f"prof_{skill_key}")
    bonus += _effective_ability_check_bonus(character, node["ability"])
    result["total"] += bonus
    result["practiced_bonus"] = bonus
    success = result["total"] >= SKILL_CHECK_DC
    material = items_module.get_item(node["material"])
    quantity = _gather_quantity(character, skill_key, bonus) if success else 0

    if success:
        db.record_skill_use(update.effective_user.id, update.effective_chat.id, skill_key)
        db.add_item(update.effective_user.id, update.effective_chat.id, node["material"], quantity)

    # Per Coffee (2026-07-19): fishing consumes bait by chance, not on a
    # fixed schedule -- whether the cast lands a fish or not, roll a d20
    # each time and lose 1 bait on a low roll (<=10, a flat 50/50), same
    # "real dice decide it" pattern as every other outcome in this game.
    bait_lost = False
    if skill_key == "fishing" and character["inventory"].get("bait", 0) > 0:
        bait_lost = roll_d20() <= 10
        if bait_lost:
            db.remove_item(update.effective_user.id, update.effective_chat.id, "bait", 1)

    flavor = await asyncio.to_thread(
        narrate_skill_check, character, action_text, node["ability"],
        {**result, "ability": node["ability"], "dc": SKILL_CHECK_DC, "success": success},
        _gathering_tool_grounded_fact(character, skill_key),
    )
    message = _format_skill_check_result(flavor, result, node["ability"], SKILL_CHECK_DC, success)
    if success:
        message += f"\n🌿 **{character['name']}** gathers **{quantity}x {material['name']}**."
    if bait_lost:
        message += "\n🪱 The bait comes free of the hook and is gone."

    if success:
        # Matches against this player's own accepted board quests (task
        # #149, 2026-07-17), not get_todays_board_quests -- a quest
        # accepted on a previous calendar day but still inside its real
        # 24h expires_at window must still be creditable; day_key is
        # only about what's currently postable, not what's still valid.
        candidates = [(q, character) for q in db.get_accepted_board_quests_for_user(update.effective_user.id, update.effective_chat.id)]
        seen_ids = {q["board_quest_id"] for q, _ in candidates}
        # Companion Favors are party-wide (2026-08-23) -- real live bug
        # (Coffee, screenshot: "I had two successful gathering of bait"
        # but the favor still showed 1 of 2): his own gather only ever
        # checked HIS OWN accepted quests above, never a party-mate's
        # -- a different real party member (Laurienna) had actually
        # accepted this exact favor. Same real gap already fixed for
        # defeat_monster crediting in v1.27.328, just missed here.
        # Reuses _accepted_companion_favors_for_party (built for the
        # My Quests fix, v1.27.329). Credit still goes to whoever
        # ACCEPTED the favor, matching the defeat_monster path's own
        # precedent -- not necessarily whoever's doing the gathering.
        for q in _accepted_companion_favors_for_party(character):
            if q["board_quest_id"] not in seen_ids:
                accepter = db.get_character(q["accepted_by"], update.effective_chat.id)
                if accepter:
                    candidates.append((q, accepter))
                    seen_ids.add(q["board_quest_id"])

        # Real live bug (2026-08-23, Coffee, screenshot: "I completed
        # this task and it didnt credit it"): this loop used to `break`
        # after crediting the FIRST matching candidate, so a player
        # with their OWN personal board quest for the same material at
        # the same location (very common -- both quests/favors for a
        # given node share that node's one material) silently ate the
        # single credit, and a party-mate's Companion Favor for that
        # same material never got touched even though the gather
        # genuinely succeeded and the item landed in inventory. Live DB
        # confirmed: Ravenloft's own "[Monthly] A supply run for
        # Moonpetal Flower" quest got the 3x credit (28->31 would have
        # been next) while Wren's favor (accepted by party-mate
        # Laurienna) stayed at 0/3. defeat_monster crediting
        # (_award_victory_xp) never had this bug -- it already credits
        # every eligible match with no break. Matching that precedent:
        # one real gather now credits EVERY matching quest/favor at
        # once, not just whichever happened to be first in the list.
        for board_quest, credited_character in candidates:
            # Companion Favors (2026-08-23) travel with the party, not
            # a location -- creditable regardless of where the player
            # currently stands, as long as the favor's own companion is
            # still actually in this player's party. Everything else
            # (a real location board quest) keeps the original
            # current-location requirement, unchanged.
            is_companion_favor = board_quest["location_id"].startswith(board_quests_module.COMPANION_FAVOR_LOCATION_PREFIX)
            if is_companion_favor:
                if not (board_quest["objective_type"] == "gather_material"
                        and board_quest["objective_target"] == node["material"]
                        and _companion_favor_giver_is_in_party(character, board_quest["giver_npc"])):
                    continue
            elif not (board_quest["location_id"] == character["current_location"]
                      and board_quest["objective_type"] == "gather_material"
                      and board_quest["objective_target"] == node["material"]):
                continue
            updated = db.record_board_quest_progress(board_quest["board_quest_id"], quantity)
            if updated["progress_count"] >= updated["objective_count"]:
                if is_companion_favor:
                    message += _complete_companion_favor(update, credited_character, updated, gathered_by=character)
                elif updated.get("branch_data"):
                    message += (
                        f"\n📜 **{updated['title']}** — objective complete. A decision awaits "
                        f"(check quests to see the choice)."
                    )
                else:
                    # Confirmed live 2026-07-12 (Coffee): a multi-step quest
                    # should tell the player where to go next instead of
                    # silently auto-granting the reward the instant the
                    # objective is met. The reward is now handed out by
                    # _check_board_quest_turnin, triggered on arrival at
                    # this same location_id (see _do_move/_do_fast_travel)
                    # -- exactly the same "objective done, come back here to
                    # collect" pattern as returning to a story quest-giver.
                    message += (
                        f"\n📜 **{updated['title']}** — objective complete! Return to "
                        f"**{location['name']}** to collect your reward."
                    )
            else:
                message += (
                    f"\n📋 Board quest progress: {updated['title']} "
                    f"({updated['progress_count']}/{updated['objective_count']})"
                )

    await _safe_send(update, message)
    if success:
        # Real image of what was actually gathered (2026-07-25/26, per
        # Coffee: "i want to see the silverleaf herb i gather and such
        # other actions" -- reuses the exact same real item-icon
        # function/convention _do_equip_item already sends on, just
        # triggered by a successful gather instead of an equip).
        await _maybe_send_item_image(update, node["material"], material)
    # Task #152, 2026-07-17: gathering always happens AT the quest's own
    # location (the crediting match above requires it), so a player who
    # completes the objective without ever having left never gets an
    # "arrival" event to trigger _check_board_quest_turnin's reward --
    # confirmed live, Coffee's "supply run for wood" sat at 4/4 with
    # completed_at still null because he was already standing in the
    # Whispering Wood the whole time. Checking turn-in right here (not
    # instead of the move-triggered checks, which still cover a player
    # who leaves and comes back later) closes that soft-lock without
    # changing the "come back to collect" framing for quests that
    # genuinely are fought/gathered somewhere else first.
    if success:
        await _check_board_quest_turnin(update, update.effective_user.id, character["current_location"])
        await _check_guild_curriculum_progress(
            update, update.effective_user.id, update.effective_chat.id, "gather_material", material_id=node["material"],
        )


PROFESSION_RANK_TITLES = {0: "Novice", 1: "Apprentice", 2: "Adept", 3: "Master"}


def _profession_rank_title(uses: int) -> str:
    return PROFESSION_RANK_TITLES[practiced_bonus(uses)]


async def _do_check_professions(update: Update) -> None:
    """
    Per Coffee ("continue with professions"): a real, single-screen
    view of every profession's actual progress -- reuses the exact
    same practiced_bonus/skill_uses data _do_craft/_do_gather already
    read and write, just never had one consolidated place to see all
    7 at once before. Rank titles reuse the dice-game's own
    Novice/Adept/Master naming (rules/proficiency.MAX_PRACTICE_BONUS
    caps out at exactly 15 uses either way, so "Master" means the same
    real threshold in both places).
    """
    character = db.get_character(update.effective_user.id, update.effective_chat.id)
    if character is None:
        await update.effective_chat.send_message(
            "You don't have a character yet!", message_thread_id=topics.thread_id_for(update.effective_chat.id, "adventure")
        )
        return
    skill_uses = character.get("skill_uses") or {}
    home_profession = CLASS_PROFESSIONS.get(character["char_class"])
    lines = [f"🛠️ **{character['name']}**'s professions:"]
    for prof in ALL_PROFESSIONS:
        uses = skill_uses.get(prof, 0)
        bonus = practiced_bonus(uses)
        rank = _profession_rank_title(uses)
        home_tag = " ⭐ *(favored trade)*" if prof == home_profession else ""
        lines.append(f"• {prof.capitalize()}: {rank} (+{bonus}, {uses} uses){home_tag}")
    await _safe_send(update, "\n".join(lines), speak=False)


_SUMMON_SECONDARY_DESCRIPTIONS = {
    "none": "no secondary effect — pure damage",
    "dot": "leaves the target poisoned",
    "self_heal": "heals you for a quarter of the damage dealt",
    "party_heal": "heals the whole party for a sixth of the damage dealt each",
}


async def _do_check_remnants(update: Update) -> None:
    """
    Real feature request (2026-08-18, Coffee, same session as the
    Support Remnants-grounding fix): "make a menu for 'Remnants' so
    players can see what the summons do for the players and their
    attack or ability" -- a real dev-bridge report the same day showed
    Support fabricating an entire fake summon ritual because it had
    nothing real to ground on, and even the real, correct mechanic
    ("summon [name]" in combat) had no in-game screen a player could
    just look at. Shows only THIS character's own real bound_remnants
    (remnants.py) -- never the full REMNANTS table, so it can't leak
    which of the 12 real Unbound exist or where they are before a
    player has genuinely earned one.

    Real request (2026-08-20, per Coffee: "i would like a Remnant menu
    in the player menu... make it like the Bestiary but only show
    Remnants and what they offer the player") -- added as a real
    "🔮 Remnants" row on the main menu (_main_menu_keyboard, routed via
    menu|remnants), and restyled to match _do_bestiary's own real
    visual convention (a real known-count header, a real "━━━" divider
    between entries) instead of this screen's older plain-blank-line
    layout. The shown avg damage now also folds in the source boss's
    own real damage_bonus (v1.27.268's "much stronger than a normal
    attack" buff) -- previously this screen quoted the summon's raw
    dice+bonus alone, understating what a cast actually does in combat.
    """
    character = db.get_character(update.effective_user.id, update.effective_chat.id)
    if character is None:
        await update.effective_chat.send_message(
            "You don't have a character yet!", message_thread_id=topics.thread_id_for(update.effective_chat.id, "adventure")
        )
        return
    bound = character.get("bound_remnants") or []
    if not bound:
        await _safe_send(
            update,
            "🔮 You haven't bound any Remnants yet — defeat a real Unbound (a rare, hidden boss-tier "
            "fight) to earn one.",
            speak=False,
        )
        return
    entries = []
    for remnant_id in bound:
        remnant = remnants_module.get_remnant(remnant_id)
        if not remnant:
            continue
        source_template = cl.get_monster_template(CAMPAIGN, remnant["monster_key"])
        source_bonus = source_template.get("damage_bonus", 0) if source_template else 0
        # Real live report (2026-08-20, per Coffee): the previewed avg
        # here must include the same REMNANT_SUMMON_POWER_BONUS
        # _do_summon_remnant's own real roll now does, or this screen
        # would understate what a cast actually deals again -- the
        # exact "screen says X, combat does Y" gap v1.27.269 already
        # had to fix once for the source-boss bonus alone. Same reason
        # this now also folds in the viewer's own real Charisma bonus
        # (see _do_summon_remnant's own comment for the floored-at-0
        # "bonus, never a penalty" reasoning) -- this screen previews
        # what THIS character's own cast actually does, not a generic
        # number.
        charisma_bonus = max(ability_modifier(character.get("charisma", 10)), 0)
        total_bonus = remnant["summon_damage_bonus"] + source_bonus + remnants_module.REMNANT_SUMMON_POWER_BONUS + charisma_bonus
        avg_dmg = average_damage(remnant["summon_damage_dice"], total_bonus)
        secondary_text = _SUMMON_SECONDARY_DESCRIPTIONS.get(remnant["summon_secondary"], "no secondary effect")
        entries.append(
            f"**{remnant['name']}**\n"
            f"⚔️ {remnant['summon_damage_dice']}+{total_bonus} "
            f"{remnant['element']} damage (~{avg_dmg:.1f} avg)\n"
            f"✨ {secondary_text}\n"
            f"_{remnant['lore']}_"
        )
    lines = [
        f"🔮 **{character['name']}**'s Remnants — {len(entries)} bound",
        "Say \"summon [name]\" in battle (or tap the Summon button) to call one.\n",
    ]
    lines.append("\n━━━━━━━━━━━━━━━\n".join(entries))
    await _safe_send(update, "\n\n".join(lines), speak=False)


async def _do_read_recipe_book(update: Update, item: dict) -> None:
    """
    Recipe books (2026-08-11, per Coffee: real "Cook Book"/"Herbalism
    Guide"/"Crafting Book" items, buyable in-world, that teach a
    profession's real level-1 recipes). Deliberately built from
    rules.crafting.RECIPES only, never ADVANCED_RECIPES/ENCHANT_RECIPES
    -- per Coffee: "Only show Lv 1 items tho (players must join guild
    for advanced recipies)" -- so a book can never leak guild-ladder
    content. Same real, dynamically-grounded-from-the-actual-catalog
    convention as ai/support_agent.py's deterministic answers, so this
    never goes stale if a recipe's materials/DC change later.

    "teaches_advanced_profession" (2026-09-08, task #7) is a real,
    DIFFERENT field on a higher-tier book -- routed to a separate
    function below rather than handled inline here, since it needs a
    live level/guild/rebirth gate this plain-RECIPES listing never did.
    """
    advanced_profession = item.get("teaches_advanced_profession")
    if advanced_profession:
        await _do_read_advanced_recipe_book(update, item, advanced_profession)
        return
    profession = item.get("teaches_profession")
    recipe_lines = [
        f"- **{items_module.get_item(r['result_item'])['name']}** (DC {r['dc']} {r['ability']}): needs "
        + ", ".join(f"{qty}x {items_module.get_item(mid)['name']}" for mid, qty in r["materials"].items())
        for r in RECIPES.values()
        # Real gap caught before shipping (2026-09-08): the new
        # greater_scroll_* RECIPES entries carry a real min_level (see
        # recipe_requirement_gate) and share the "alchemy" profession
        # with the Herbalism Guide -- without this filter they'd leak
        # straight into the SAME basic, Lv-1-only book this function's
        # own docstring says can "never leak guild-ladder content."
        # Any recipe carrying a real gate field belongs in the
        # advanced book (_do_read_advanced_recipe_book) only.
        if r.get("profession", "crafting") == profession
        and not (r.get("min_level") or r.get("requires_guild") or r.get("min_rebirth"))
    ]
    if not recipe_lines:
        await _safe_send(update, f"The {item['name']} is oddly blank — there's nothing written in it yet.")
        return
    await _safe_send(
        update,
        f"📖 **{item['name']}**\n" + "\n".join(recipe_lines) +
        "\n\nMore advanced recipes exist, but they're guild secrets — join the right guild to learn those.",
        speak=False,
    )


async def _do_read_advanced_recipe_book(update: Update, item: dict, profession: str) -> None:
    """
    Advanced/guild-tier recipe books (2026-09-08, task #7, per Coffee:
    "add any recipies needed and make them available in the books at lv
    20 +"). Deliberately a SEPARATE listing source from _do_read_recipe_
    book's own RECIPES-only convention (that function's own docstring:
    "so a book can never leak guild-ladder content") -- an advanced book
    is EXPECTED to leak that content, but only line-by-line to a reader
    who's actually earned each specific recipe (right level/guild/
    rebirth), checked live via recipe_requirement_gate -- the exact same
    gate a real craft/enchant attempt would apply, so a book can never
    show a recipe the reader couldn't actually use yet.
    """
    character = db.get_character(update.effective_user.id, update.effective_chat.id)
    if character is None:
        await update.effective_chat.send_message(
            "You don't have a character yet!", message_thread_id=topics.thread_id_for(update.effective_chat.id, "adventure")
        )
        return
    if character.get("level", 1) < 20:
        await _safe_send(
            update,
            f"The {item['name']}'s pages blur into nonsense — this knowledge is sealed until you're truly experienced (level 20+).",
        )
        return

    lines = []
    for r in ADVANCED_RECIPES.values():
        if r.get("profession") != profession or recipe_requirement_gate(character, r):
            continue
        lines.append(
            f"- **{r['name']}** ({r['tier']}, DC {r['dc']} {r['ability']}): needs "
            + ", ".join(f"{qty}x {items_module.get_item(mid)['name']}" for mid, qty in r["materials"].items())
        )
    for recipe_id, r in ENCHANT_RECIPES.items():
        if r.get("profession") != profession or recipe_requirement_gate(character, r):
            continue
        label = recipe_id.replace("enchant_", "").replace("_", " ").title()
        lines.append(
            f"- **{label}** (DC {r['dc']} {r['ability']}): needs "
            + ", ".join(f"{qty}x {items_module.get_item(mid)['name']}" for mid, qty in r["materials"].items())
        )

    if not lines:
        await _safe_send(
            update,
            f"The {item['name']} is written in a guild cipher you can't make sense of yet — the right guild membership unlocks it.",
        )
        return
    await _safe_send(update, f"📖 **{item['name']}**\n" + "\n".join(lines), speak=False)


async def _do_craft(update: Update, text: str) -> None:
    """
    Crafting is fully resolved by rules/crafting.py — material checks and
    the success roll are both deterministic; this handler only reports
    the outcome and applies the resulting inventory changes.
    """
    character = db.get_character(update.effective_user.id, update.effective_chat.id)
    if character is None:
        await _safe_send(update, "You don't have a character yet!")
        return

    # Magic item system Phase 7 (2026-08-02): advanced recipes are
    # matched SEPARATELY from the static ones, not merged into the same
    # candidate_ids list -- items_module.find_item_mentioned_in_text
    # calls get_item() on every candidate to sort by name length, and an
    # ADVANCED_RECIPES key (e.g. "masterwork_longsword") is neither a
    # static catalog item nor a generated "gi<n>" id, so get_item() on
    # one returns None and crashes that sort (real bug #1, caught live
    # before shipping via the mandatory regression run: "craft healing
    # potion" started crashing the instant advanced recipe ids were
    # merged into that same candidate list).
    #
    # Checked in THIS order -- advanced first, static second (real bug
    # #2, also caught live: checking static first made "craft a
    # masterwork longsword" silently craft a plain Longsword instead,
    # since items_module.find_item_mentioned_in_text does substring
    # matching and the static item name "Longsword" is itself a
    # substring of "masterwork longsword" -- the static recipe won
    # before the advanced one was ever even tried). Every advanced
    # recipe name is a real superset of its base item's name (adds a
    # descriptive prefix like "Masterwork"/"Runed"/"Wardstone"), so
    # trying the advanced match first and falling back to static can
    # never misfire the other way -- a plain "craft a longsword" simply
    # won't match any advanced recipe's fuller name.
    recipe_id = _find_advanced_recipe_in_text(text)
    is_advanced = recipe_id is not None
    if recipe_id is None:
        recipe_id = items_module.find_item_mentioned_in_text(text, candidate_ids=list(RECIPES.keys()))

    if recipe_id is None:
        recipe_names = ", ".join(items_module.get_item(r)["name"] for r in RECIPES)
        adv_names = ", ".join(r["name"] for r in ADVANCED_RECIPES.values())
        await _safe_send(
            update,
            f"Not sure what you're trying to craft. Known recipes: {recipe_names}. "
            f"Advanced recipes: {adv_names}.",
        )
        return

    recipe = get_advanced_recipe(recipe_id) if is_advanced else get_recipe(recipe_id)

    # Guild tier ladder (2026-08-11): checked before any material/roll
    # work, same as the missing-materials early-return just below --
    # gated recipes (Forge Guild's journeyman_blade and up) carry
    # requires_guild/min_rebirth; ungated recipes are unaffected.
    gate_rejection = recipe_requirement_gate(character, recipe)
    if gate_rejection:
        await _safe_send(update, gate_rejection)
        return

    # 2026-07-14, per Coffee: crafting is its own named, levelable
    # skill -- tracked separately from whichever ability a given recipe
    # happens to roll with (wisdom for a potion, intelligence for a
    # scroll), same split as the gathering professions above. Extended
    # 2026-07-24: each recipe now names its own profession (alchemy,
    # cooking, blacksmithing, ...) instead of everything sharing one
    # "crafting" bucket -- practicing potions no longer secretly makes
    # you better at forging weapons too. Recipes with no profession set
    # fall back to the old shared "crafting" key.
    profession = recipe.get("profession", "crafting")
    # Class profession affinity (2026-07-25, per Coffee): a real +2 on
    # top of the usual earned practiced_bonus when this is the
    # character's own class's home profession (rules/crafting.py's
    # CLASS_PROFESSIONS) -- e.g. a Wizard brewing alchemy, a Fighter
    # forging at the anvil. Every class has exactly one home
    # profession, so this never silently favors one build over another.
    bonus = _practiced_bonus_for(update.effective_user.id, update.effective_chat.id, profession)
    bonus += class_profession_affinity_bonus(character["char_class"], profession)
    # Magic item system Phase 4 (2026-08-02): same third additive source
    # as _do_gather's identical accumulator just above.
    bonus += _equipped_profession_bonus(character, profession)
    # Universal Manipulation "prof_X" (2026-08-06, per Coffee): a real
    # 4th additive source, +1 per point invested in this profession.
    bonus += _skill_points(character, f"prof_{profession}")
    # Masterwork quality roll (2026-08-11, per Coffee: "i want this
    # mechanic used anywhere its applicable" -- alchemy/cooking's own
    # RECIPES have no tier to bump, but every profession still deserves
    # a real payoff for grinding, so a static recipe's masterwork bonus
    # is +1 yield instead (see the success branch below). Rolled up
    # front against the crafter's own stored mastery %, independent of
    # the craft's own success check just below -- see
    # _roll_masterwork_quality's docstring for why.
    masterwork = _roll_masterwork_quality(character, profession)
    result = (
        resolve_advanced_craft(character, recipe_id, practiced_bonus=bonus, masterwork=masterwork) if is_advanced
        else resolve_craft(character, recipe_id, practiced_bonus=bonus)
    )

    if result["outcome"] == "missing_materials":
        need = ", ".join(
            f"{qty}x {items_module.get_item(i)['name']}" for i, qty in recipe["materials"].items()
        )
        # Real live crash (2026-09-07, error log, 3 occurrences): a raw
        # send here had no RetryAfter retry -- _safe_send exists
        # specifically for this, same fix already applied reactively
        # to _do_fast_travel/_do_use_item and siblings.
        await _safe_send(update, f"You don't have the materials for that. You need: {need}.")
        return

    for item_id, qty in result["materials_consumed"].items():
        db.remove_item(update.effective_user.id, update.effective_chat.id, item_id, qty)

    success = result["outcome"] == "success"
    result_item = None
    static_qty = result.get("result_qty", 0)
    if success:
        db.record_skill_use(update.effective_user.id, update.effective_chat.id, profession)
        _grind_profession_mastery(update.effective_user.id, update.effective_chat.id, character, profession)
        if is_advanced:
            loot_item = result["generated_item"]
            generated_item_id = _persist_generated_item(loot_item, source="crafted")
            db.add_item(update.effective_user.id, update.effective_chat.id, generated_item_id, 1)
            result_item = loot_item
        else:
            # Masterwork bonus yield (2026-08-11, per Coffee: alchemy/
            # cooking need this mechanic too, and their RECIPES have no
            # tier to bump -- +1 extra unit on a masterwork roll instead.
            if masterwork:
                static_qty += 1
            db.add_item(update.effective_user.id, update.effective_chat.id, result["result_item"], static_qty)
            result_item = items_module.get_item(result["result_item"])

    flavor = await asyncio.to_thread(
        narrate_skill_check, character, text, result["ability"],
        {**result["check"], "ability": result["ability"], "dc": result["dc"], "success": success},
    )
    message = _format_skill_check_result(flavor, result["check"], result["ability"], result["dc"], success)
    if success:
        if is_advanced:
            masterwork_note = " — a masterwork strike, forged above the recipe's usual tier!" if result.get("masterwork") else ""
            message += (
                f"\n⚗️ You craft a **{result_item['name']}** "
                f"({result_item['rarity'].replace('_', ' ')}) — a real magic item, ready to equip!{masterwork_note}"
            )
        else:
            masterwork_note = " — a masterwork batch, one extra made!" if masterwork else ""
            message += f"\n⚗️ You craft **{static_qty}x {result_item['name']}**.{masterwork_note}"
    else:
        message += "\n⚗️ The attempt fails, but your materials aren't wasted — you can try again."
    await _safe_send(update, message)
    if success:
        # Real image of what was actually crafted (2026-07-25/26, per
        # Coffee: images for professions/actions too) -- same reuse of
        # the existing item-icon convention as the gather fix above.
        image_item_id = generated_item_id if is_advanced else result["result_item"]
        await _maybe_send_item_image(update, image_item_id, result_item)
        # Real action buttons on a freshly crafted item (2026-08-11, per
        # Coffee: "after a player crafts, can you let them view the
        # weapon with a push button and give them options below with
        # push buttons like give, marketplace, reforge, equip") -- same
        # "🔍 Tap below to inspect" follow-up combat loot already gets
        # (see _grant_generated_loot), so crafting a magic item isn't
        # treated any differently from finding one.
        #
        # Real live gap (2026-08-14, per Coffee, dev-bridge screenshot:
        # "After I crafted this item, it didn't give me the option to
        # market it, sell it, give it, equip it, reforge or dismantle
        # it"): this used to be advanced-craft only, on the reasoning
        # that "a static-catalog craft has nothing to equip/forge/
        # list" -- true for a potion or scroll, but flatly wrong for a
        # plain static-catalog WEAPON/ARMOR craft (his own real example
        # was a plain crafted Longsword), which itemview_callback
        # already handles correctly and generically for equip/sell/
        # market/give (Reforge/Dismantle already gate themselves
        # correctly on real eligibility -- can_reforge requires
        # source == "crafted", which a static item never has, so the
        # button itself never shows for one; can_dismantle already
        # checks DISMANTLE_ELIGIBLE_TYPES). Scoped to real equippable
        # types only -- a crafted potion/scroll genuinely has nothing
        # these buttons would do, so it's still correctly excluded.
        view_item_id = generated_item_id if is_advanced else result["result_item"]
        if is_advanced or result_item.get("type") in ("weapon", "armor", "shield", "ring", "amulet", "wondrous"):
            await _safe_send(
                update, f"🔍 Tap below to inspect the {result_item['name']} you just crafted.",
                reply_markup=_item_view_keyboard(view_item_id), speak=False,
            )


# Magic item system Phase 7 (2026-08-02): forging bumps a real generated
# item ("gi<n>", db.create_item_instance) up ONE tier, in place, same
# item_id -- gated on gold + tier-scaled materials and a real
# blacksmithing ability check, exactly like every other rules/ outcome
# in this game. Only weapons/armor/shields are forgeable (matches
# db.FORGE_STAT_BONUS_FIELD, the fields that actually carry a tier
# bonus); a plain static-catalog item (no "gi" id) has no item_instances
# row to mutate, so it's refused with an honest reason rather than
# silently no-opping.
FORGE_ADVANCE_DC = {"common": 10, "uncommon": 13, "rare": 16, "very_rare": 19, "legendary": 22}
FORGE_MATERIAL_COST = {
    "common": {"iron_ore": 2}, "uncommon": {"iron_ore": 3}, "rare": {"iron_ore": 5},
    "very_rare": {"iron_ore": 8}, "legendary": {"iron_ore": 12},
}
FORGE_GOLD_COST = {"common": 50, "uncommon": 150, "rare": 400, "very_rare": 1000, "legendary": 3000}


async def _do_forge_item(update: Update, text: str) -> None:
    character = db.get_character(update.effective_user.id, update.effective_chat.id)
    if character is None:
        await update.effective_chat.send_message(
            "You don't have a character yet!", message_thread_id=topics.thread_id_for(update.effective_chat.id, "adventure")
        )
        return

    item_id = items_module.find_item_mentioned_in_text(text, candidate_ids=list(character["inventory"].keys()))
    item = items_module.get_item(item_id) if item_id else None
    if item_id is None or not item_id.startswith(db.GENERATED_ITEM_ID_PREFIX) or item is None:
        await _safe_send(
            update,
            "Only a real magic item you've found or crafted (not a plain shop item) can be forged to a higher tier.",
        )
        return
    await _forge_item_core(update, item_id, item, text)


async def _forge_item_core(update: Update, item_id: str, item: dict, text: str) -> None:
    """
    The real forge-to-higher-tier logic, factored out of _do_forge_item
    (2026-08-11, per Coffee: real push-button options -- give, market,
    reforge, equip -- on a freshly viewed item) so itemview_callback's
    "reforge" button can run the exact same cost/roll/apply path a
    free-text "forge my X" already does, instead of a second copy of it.
    `text` is only used as narrate_skill_check's flavor context.
    """
    character = db.get_character(update.effective_user.id, update.effective_chat.id)
    if item["type"] not in ("weapon", "armor", "shield"):
        await _safe_send(update, "Only weapons, armor, and shields can be forged.")
        return

    # Reforge-source gate (2026-08-12, per Coffee via dev-topic
    # screenshot: "Don't have reforging on the list unless it is a
    # forged weapon we found this weapon battle, so we shouldn't have the
    # option to reforge it") -- forging a higher tier is meant to reward
    # the player's OWN crafting, not let any battle/treasure drop get
    # upgraded the same way. item.get("source") comes from
    # db.materialize_item_instance; only "crafted" (set by the advanced
    # crafting path via _persist_generated_item) passes.
    if item.get("source") != "crafted":
        await _safe_send(
            update,
            f"The {item['name']} wasn't forged by you — only a weapon, armor piece, or shield you crafted yourself can be reforged to a higher tier.",
        )
        return

    current_tier = item["rarity"]
    if current_tier not in FORGE_ADVANCE_DC:
        await _safe_send(update, f"The {item['name']} is already at the highest tier — there's nowhere higher to forge it.")
        return

    cost = FORGE_MATERIAL_COST[current_tier]
    gold_cost = FORGE_GOLD_COST[current_tier]
    if character["gold"] < gold_cost or not all(character["inventory"].get(mid, 0) >= qty for mid, qty in cost.items()):
        need = ", ".join(f"{qty}x {items_module.get_item(mid)['name']}" for mid, qty in cost.items())
        await _safe_send(update, f"Forging the {item['name']} to the next tier needs {gold_cost} gold and {need}.")
        return

    profession = "blacksmithing"
    bonus = _practiced_bonus_for(update.effective_user.id, update.effective_chat.id, profession)
    bonus += class_profession_affinity_bonus(character["char_class"], profession)
    bonus += _equipped_profession_bonus(character, profession)
    # Universal Manipulation "prof_X" (2026-08-06, per Coffee): a real
    # 4th additive source, +1 per point invested in this profession.
    bonus += _skill_points(character, f"prof_{profession}")
    bonus += _effective_ability_check_bonus(character, "strength")
    check = roll_ability_check(character, "strength", proficient=False)
    check["total"] += bonus
    check["practiced_bonus"] = bonus
    dc = FORGE_ADVANCE_DC[current_tier]
    success = check["total"] >= dc

    flavor = await asyncio.to_thread(
        narrate_skill_check, character, text, "strength",
        {**check, "ability": "strength", "dc": dc, "success": success},
    )
    message = _format_skill_check_result(flavor, check, "strength", dc, success)
    if not success:
        message += f"\n🔨 The forging attempt fails — the {item['name']} is unharmed, and your materials aren't wasted."
        await _safe_send(update, message)
        return

    for mid, qty in cost.items():
        db.remove_item(update.effective_user.id, update.effective_chat.id, mid, qty)
    db.update_character(update.effective_user.id, update.effective_chat.id, gold=character["gold"] - gold_cost)
    db.record_skill_use(update.effective_user.id, update.effective_chat.id, profession)
    _forge_ok, forge_msg, forged_item = db.forge_item_instance(item_id)
    message += f"\n🔨 {forge_msg}"
    await _safe_send(update, message)
    if forged_item:
        await _maybe_send_item_image(update, item_id, forged_item)


async def _do_discard_item(update: Update, text: str) -> None:
    """
    Mastery-grind discard (2026-08-11, per Coffee: RNG crafting quality
    means a real chance of a weak roll, and grinding for a better one
    should mean "having to discard bad ones" -- a real, permanent,
    no-refund way to clear inventory space and try again. Works on ANY
    inventory item (not just generated magic gear), unlike forge/enchant
    which are real-magic-item-only.
    """
    character = db.get_character(update.effective_user.id, update.effective_chat.id)
    if character is None:
        await update.effective_chat.send_message(
            "You don't have a character yet!", message_thread_id=topics.thread_id_for(update.effective_chat.id, "adventure")
        )
        return

    item_id = items_module.find_item_mentioned_in_text(text, candidate_ids=list(character["inventory"].keys()))
    item = items_module.get_item(item_id) if item_id else None
    if item_id is None or item is None or character["inventory"].get(item_id, 0) < 1:
        await _safe_send(update, "You're not carrying that.")
        return

    db.remove_item(update.effective_user.id, update.effective_chat.id, item_id, 1)
    await _safe_send(
        update,
        f"🗑️ **{character['name']}** discards the {item['name']} — it's gone for good, no refund.",
    )


DISMANTLE_ELIGIBLE_TYPES = ("weapon", "armor", "shield", "ring", "amulet")


async def _apply_dismantle(update: Update, character: dict, item_id: str, item: dict) -> None:
    """
    Shared by _do_dismantle_item's free-text path and itemview_callback's
    "dismantle" button tap -- both already have a resolved item_id/item
    by the time they call this, so this is pure resolve-and-apply, no
    text parsing. See rules/crafting.py's resolve_dismantle for the real
    three-tier (very_successful/successful/not_successful) outcome logic.
    """
    profession = "blacksmithing"
    bonus = _practiced_bonus_for(update.effective_user.id, update.effective_chat.id, profession)
    bonus += class_profession_affinity_bonus(character["char_class"], profession)
    bonus += _equipped_profession_bonus(character, profession)
    bonus += _skill_points(character, f"prof_{profession}")

    result = resolve_dismantle(character, item_id, item, practiced_bonus=bonus)
    db.remove_item(update.effective_user.id, update.effective_chat.id, item_id, 1)
    for mat_id, qty in result["materials"].items():
        db.add_item(update.effective_user.id, update.effective_chat.id, mat_id, qty)

    materials_line = ", ".join(
        f"{qty}x {items_module.get_item(mat_id)['name'] if items_module.get_item(mat_id) else mat_id}"
        for mat_id, qty in result["materials"].items()
    )
    outcome = result["outcome"]
    if outcome == "very_successful":
        headline = f"🔧 **{character['name']}** expertly dismantles the {item['name']} — every scrap of material recovered!"
    elif outcome == "successful":
        headline = f"🔧 **{character['name']}** dismantles the {item['name']}, salvaging some of its materials."
    else:
        headline = f"🔧 **{character['name']}**'s attempt to dismantle the {item['name']} goes rough — only scraps survive."
    await _safe_send(update, f"{headline}\nRecovered: {materials_line}")


async def _do_dismantle_item(update: Update, text: str) -> None:
    """Free-text "dismantle the X" path -- see _apply_dismantle for the real resolution logic, shared with the item-view button."""
    character = db.get_character(update.effective_user.id, update.effective_chat.id)
    if character is None:
        await update.effective_chat.send_message(
            "You don't have a character yet!", message_thread_id=topics.thread_id_for(update.effective_chat.id, "adventure")
        )
        return

    item_id = items_module.find_item_mentioned_in_text(text, candidate_ids=list(character["inventory"].keys()))
    item = items_module.get_item(item_id) if item_id else None
    if item_id is None or item is None or character["inventory"].get(item_id, 0) < 1:
        await _safe_send(update, "You're not carrying that.")
        return
    if item.get("type") not in DISMANTLE_ELIGIBLE_TYPES:
        await _safe_send(update, f"The {item['name']} can't be dismantled — only weapons, armor, shields, rings, and amulets can.")
        return

    await _apply_dismantle(update, character, item_id, item)


def _find_advanced_recipe_in_text(text: str) -> str | None:
    """Matches an ADVANCED_RECIPES entry by its own "name" field -- see _do_craft's docstring comment for why this can't reuse items_module.find_item_mentioned_in_text."""
    lowered = text.lower()
    for recipe_id, recipe in sorted(ADVANCED_RECIPES.items(), key=lambda kv: -len(kv[1]["name"])):
        if recipe["name"].lower() in lowered:
            return recipe_id
    return None


def _find_enchant_recipe_in_text(text: str) -> str | None:
    lowered = text.lower()
    for recipe_id in ENCHANT_RECIPES:
        label = recipe_id.replace("enchant_", "").replace("_", " ")
        if label in lowered:
            return recipe_id
    return None


async def _do_enchant_item(update: Update, text: str) -> None:
    """
    Enchanting/imbuing (Phase 7): "enchant"/"imbue" both classify to this
    same handler (see ai/intent_parser.py) -- purely a player-facing/
    in-fiction distinction per the approved plan, not a different data
    operation. Appends one new affix from rules/crafting.py's
    ENCHANT_RECIPES to an existing generated item, gated on materials and
    a real alchemy ability check.
    """
    character = db.get_character(update.effective_user.id, update.effective_chat.id)
    if character is None:
        await update.effective_chat.send_message(
            "You don't have a character yet!", message_thread_id=topics.thread_id_for(update.effective_chat.id, "adventure")
        )
        return

    item_id = items_module.find_item_mentioned_in_text(text, candidate_ids=list(character["inventory"].keys()))
    item = items_module.get_item(item_id) if item_id else None
    if item_id is None or not item_id.startswith(db.GENERATED_ITEM_ID_PREFIX) or item is None:
        await _safe_send(
            update,
            "Only a real magic item you've found or crafted (not a plain shop item) can be enchanted.",
        )
        return

    recipe_id = _find_enchant_recipe_in_text(text)
    if recipe_id is None:
        recipe_names = ", ".join(r.replace("enchant_", "").replace("_", " ") for r in ENCHANT_RECIPES)
        await _safe_send(update, f"Not sure what enchantment you mean. Known enchantments: {recipe_names}.")
        return
    recipe = get_enchant_recipe(recipe_id)
    if item["type"] not in recipe["applies_to"]:
        await _safe_send(update, f"That enchantment can't be applied to a {item['type']}.")
        return
    # Guild tier ladder (2026-08-11): Enchanters' Guild recipes above
    # the base tier carry requires_guild/min_rebirth; ungated recipes
    # (enchant_flame, enchant_frost_ward, etc.) are unaffected.
    gate_rejection = recipe_requirement_gate(character, recipe)
    if gate_rejection:
        await _safe_send(update, gate_rejection)
        return
    # Spell-gated elemental enchanting (2026-08-11, per Coffee:
    # "enchanters shud be able to use thier own spells or abilities to
    # enchant also") -- any enchantment carrying a real damage_type
    # (the elemental retypes/wards) now requires the caster to actually
    # know a spell of that same damage_type, tying the Enchanters'
    # Guild's craft to the caster's own spellbook instead of materials
    # alone. Recipes with no damage_type (enchant_sharpen, enchant_warding,
    # enchant_arcana, the profession_bonus/ignore_resistance capstones)
    # are unaffected.
    affix_damage_type = recipe["affix"].get("damage_type")
    if affix_damage_type and not any(
        spells_module.get_spell(sid) and spells_module.get_spell(sid).get("damage_type") == affix_damage_type
        for sid in character["known_spells"]
    ):
        await _safe_send(
            update,
            f"You don't know any {affix_damage_type} spell — an enchanter channels their own magic into "
            f"the work, and you have nothing of that element to draw on yet.",
        )
        return
    if not has_materials(character["inventory"], recipe):
        need = ", ".join(f"{qty}x {items_module.get_item(mid)['name']}" for mid, qty in recipe["materials"].items())
        await _safe_send(update, f"You don't have the materials for that enchantment. You need: {need}.")
        return

    profession = recipe.get("profession", "alchemy")
    bonus = _practiced_bonus_for(update.effective_user.id, update.effective_chat.id, profession)
    bonus += class_profession_affinity_bonus(character["char_class"], profession)
    bonus += _equipped_profession_bonus(character, profession)
    # Universal Manipulation "prof_X" (2026-08-06, per Coffee): a real
    # 4th additive source, +1 per point invested in this profession.
    bonus += _skill_points(character, f"prof_{profession}")
    bonus += _effective_ability_check_bonus(character, recipe["ability"])
    check = roll_ability_check(character, recipe["ability"], proficient=False)
    check["total"] += bonus
    check["practiced_bonus"] = bonus
    dc = recipe["dc"]
    success = check["total"] >= dc
    # Masterwork quality roll (2026-08-11): same independent-of-success
    # roll as _do_craft's, against this same profession's mastery %.
    masterwork = _roll_masterwork_quality(character, profession)

    flavor = await asyncio.to_thread(
        narrate_skill_check, character, text, recipe["ability"],
        {**check, "ability": recipe["ability"], "dc": dc, "success": success},
    )
    message = _format_skill_check_result(flavor, check, recipe["ability"], dc, success)
    if not success:
        message += f"\n✨ The enchantment fizzles — the {item['name']} is unharmed, and your materials aren't wasted."
        await _safe_send(update, message)
        return

    for mid, qty in recipe["materials"].items():
        db.remove_item(update.effective_user.id, update.effective_chat.id, mid, qty)
    db.record_skill_use(update.effective_user.id, update.effective_chat.id, profession)
    _grind_profession_mastery(update.effective_user.id, update.effective_chat.id, character, profession)

    affix = dict(recipe["affix"])
    masterwork_note = ""
    bonus_affix = None
    if masterwork:
        if "value" in affix:
            affix["value"] = round(affix["value"] * 1.5)
            masterwork_note = " — a masterwork working, stronger than the usual result!"
        elif affix["kind"] == "grants_spell":
            affix["uses"] = affix.get("uses", 1) + 1
            masterwork_note = " — a masterwork working, one extra charge bound in!"
        elif affix["kind"] == "elemental_damage":
            bonus_affix = {"kind": "elemental_damage_bonus", "value": 20}
            masterwork_note = " — a masterwork working, biting harder than a plain retype!"
        else:
            masterwork_note = " — a masterwork working!"

    _ok, enchant_msg, enchanted_item = db.enchant_item_instance(item_id, affix)
    if bonus_affix:
        _ok, _bonus_msg, enchanted_item = db.enchant_item_instance(item_id, bonus_affix)
    message += f"\n✨ {enchant_msg}{masterwork_note}"
    await _safe_send(update, message)
    if enchanted_item:
        await _maybe_send_item_image(update, item_id, enchanted_item)


# Magic item system Phase 8 (2026-09-08, per Coffee: "player must be Min
# lv 20 to craft a magic item"). Tiers the pool of ability scores a
# forge_magic_upgrade roll can land on by the crafter's own forging
# mastery % -- higher mastery both widens the pool AND biases it toward
# the crafter's own class-primary ability (the "rarer/better stats"
# half of Coffee's own "Both" answer when asked how mastery should
# matter; the OTHER half, +1-vs-+2 odds, reuses _roll_masterwork_
# quality's existing 1.5x-the-value bump completely unchanged --
# round(1 * 1.5) == 2, so no new odds mechanism was needed at all).
_FORGE_MAGIC_UPGRADE_COMMON_ABILITIES = ["strength", "dexterity", "constitution"]
_FORGE_MAGIC_UPGRADE_ALL_ABILITIES = ["strength", "dexterity", "constitution", "intelligence", "wisdom", "charisma"]


def _roll_forge_magic_upgrade_ability(character: dict, profession: str) -> str:
    mastery_pct = _profession_mastery_pct(character, profession)
    if mastery_pct < 33:
        pool = list(_FORGE_MAGIC_UPGRADE_COMMON_ABILITIES)
    elif mastery_pct < 66:
        pool = list(_FORGE_MAGIC_UPGRADE_ALL_ABILITIES)
    else:
        primary = CLASS_PRIMARY_ABILITY.get(character["char_class"].lower(), "strength")
        pool = list(_FORGE_MAGIC_UPGRADE_ALL_ABILITIES) + [primary]
    return random.choice(pool)


async def _do_forge_magic_item(update: Update, text: str) -> None:
    """
    Magic item system Phase 8 (2026-09-08, per Coffee: "i want to be
    able to craft something better than a longsword... offer a new
    recipie to be able to generate a RNG magic item with a +1 to a RNG
    stat (they can craft any weapon or armour into a magic item that
    was looted or crafted previously)"). Deliberately a SEPARATE handler
    from _do_enchant_item, not a special case bolted onto it -- every
    existing enchant recipe legitimately requires an ALREADY-magic item
    (adding a 2nd+ affix to something special), while this one's whole
    point is turning an ORDINARY item magic for the first time, so the
    two need genuinely different eligibility gates at the top.
    """
    character = db.get_character(update.effective_user.id, update.effective_chat.id)
    if character is None:
        await update.effective_chat.send_message(
            "You don't have a character yet!", message_thread_id=topics.thread_id_for(update.effective_chat.id, "adventure")
        )
        return

    item_id = items_module.find_item_mentioned_in_text(text, candidate_ids=list(character["inventory"].keys()))
    item = items_module.get_item(item_id) if item_id else None
    if item_id is None or item is None:
        await _safe_send(update, "Not sure which weapon, armor, or accessory you mean.")
        return

    recipe = get_enchant_recipe("forge_magic_upgrade")
    if item["type"] not in recipe["applies_to"]:
        await _safe_send(update, f"A {item['type']} can't be forged into a magic item — only weapons, armor, and accessories.")
        return
    # min_level (character level 20+) + requires_guild (Forge Guild) --
    # see recipe_requirement_gate's own updated docstring.
    gate_rejection = recipe_requirement_gate(character, recipe)
    if gate_rejection:
        await _safe_send(update, gate_rejection)
        return
    if not has_materials(character["inventory"], recipe):
        need = ", ".join(f"{qty}x {items_module.get_item(mid)['name']}" for mid, qty in recipe["materials"].items())
        await _safe_send(update, f"You don't have the materials to forge a magic item. You need: {need}.")
        return

    profession = recipe.get("profession", "blacksmithing")
    bonus = _practiced_bonus_for(update.effective_user.id, update.effective_chat.id, profession)
    bonus += class_profession_affinity_bonus(character["char_class"], profession)
    bonus += _equipped_profession_bonus(character, profession)
    bonus += _skill_points(character, f"prof_{profession}")
    bonus += _effective_ability_check_bonus(character, recipe["ability"])
    check = roll_ability_check(character, recipe["ability"], proficient=False)
    check["total"] += bonus
    check["practiced_bonus"] = bonus
    dc = recipe["dc"]
    success = check["total"] >= dc
    # Masterwork quality (real, existing mastery-% roll): the "+1 vs +2"
    # half of Coffee's own "Both" answer -- round(recipe's own value=1 *
    # the existing 1.5x masterwork bump) == 2, reusing _roll_masterwork_
    # quality/the affix["value"] scaling below completely unchanged.
    masterwork = _roll_masterwork_quality(character, profession)

    flavor = await asyncio.to_thread(
        narrate_skill_check, character, text, recipe["ability"],
        {**check, "ability": recipe["ability"], "dc": dc, "success": success},
    )
    message = _format_skill_check_result(flavor, check, recipe["ability"], dc, success)
    if not success:
        message += f"\n🔨 The forging fails — the {item['name']} is unharmed, and your materials aren't wasted."
        await _safe_send(update, message)
        return

    for mid, qty in recipe["materials"].items():
        db.remove_item(update.effective_user.id, update.effective_chat.id, mid, qty)
    db.record_skill_use(update.effective_user.id, update.effective_chat.id, profession)
    _grind_profession_mastery(update.effective_user.id, update.effective_chat.id, character, profession)

    chosen_ability = _roll_forge_magic_upgrade_ability(character, profession)
    affix = {"kind": "ability_bonus", "ability": chosen_ability, "value": recipe["affix"]["value"]}
    masterwork_note = ""
    if masterwork:
        affix["value"] = round(affix["value"] * 1.5)
        masterwork_note = " — a masterwork working, stronger than the usual result!"

    # Promote a plain (not-yet-magic) item into a real generated
    # instance first -- an already-generated item (found or previously
    # crafted magic gear) is enchanted in place instead, same as
    # _do_enchant_item.
    if item_id.startswith(db.GENERATED_ITEM_ID_PREFIX):
        target_item_id = item_id
    else:
        base_stats = {k: v for k, v in item.items() if k != "affixes"}
        target_item_id = db.create_item_instance(
            item_type=item["type"], name=item["name"], rarity=item.get("rarity", "common"),
            price=item.get("price", 0), base_stats=base_stats, affixes=[], source="crafted",
        )
        db.remove_item(update.effective_user.id, update.effective_chat.id, item_id, 1)
        db.add_item(update.effective_user.id, update.effective_chat.id, target_item_id, 1)

    _ok, enchant_msg, enchanted_item = db.enchant_item_instance(target_item_id, affix)
    message += f"\n✨ {enchant_msg} A surge of magic settles into it, granting +{affix['value']} {chosen_ability.title()}!{masterwork_note}"
    await _safe_send(update, message)
    if enchanted_item:
        await _maybe_send_item_image(update, target_item_id, enchanted_item)


async def _do_make_campfire(update: Update) -> None:
    """
    Consumes 1 wood to make a campfire (2026-07-14, per Coffee's idea)
    -- a real, small, immediate HP benefit (1d4, deterministic dice roll
    same as every other outcome in this game), not full-rest-scale
    healing (that's what actually resting does, over real time). Doesn't
    require being combat-free -- unlike resting, a quick fire by the
    roadside isn't a multi-hour commitment, so it's allowed any time
    outside an active fight.
    """
    telegram_user_id = update.effective_user.id
    character = db.get_character(telegram_user_id, update.effective_chat.id)
    if character is None:
        await update.effective_chat.send_message(
            "You don't have a character yet!", message_thread_id=topics.thread_id_for(update.effective_chat.id, "adventure")
        )
        return
    if sessions.get_session_for_user(update.effective_chat.id, telegram_user_id) is not None:
        await update.effective_chat.send_message(
            "Not in the middle of a fight.", message_thread_id=topics.thread_id_for(update.effective_chat.id, "adventure")
        )
        return
    if character["inventory"].get("wood", 0) < 1:
        await update.effective_chat.send_message(
            "You don't have any wood to burn.", message_thread_id=topics.thread_id_for(update.effective_chat.id, "adventure")
        )
        return
    if character["hp_current"] >= character["hp_max"]:
        await update.effective_chat.send_message(
            "Already at full health — no need for a fire right now.",
            message_thread_id=topics.thread_id_for(update.effective_chat.id, "adventure"),
        )
        return

    db.remove_item(telegram_user_id, update.effective_chat.id, "wood", 1)
    heal = roll_damage("1d4")["total"]
    new_hp = min(character["hp_current"] + heal, character["hp_max"])
    actual_heal = new_hp - character["hp_current"]
    db.update_character(telegram_user_id, update.effective_chat.id, hp_current=new_hp)

    flavor = await asyncio.to_thread(
        narrate_action, character, "makes a campfire and warms up beside it",
        {"success": True},
    )
    await _safe_send(
        update,
        f"🔥 **{character['name']}** builds a campfire and rests beside its warmth.\n"
        f"> {flavor}\n\n"
        f"Recovers {actual_heal} HP ({new_hp}/{character['hp_max']}).",
    )


async def _do_second_wind(update: Update) -> None:
    """
    Real Fighter class feature: bonus action, once per rest, heal
    1d10 + fighter level HP. Uses the shared feature_uses resource
    (see db.use_feature/get_feature_uses) -- resets on a full rest,
    same as every other limited-use feature added in this pass.

    Real live request (2026-08-26, per Coffee: "use this proficiency
    for healing type... abilities that heal characters... make healing
    proficiency like an element" -- followed by: "when they have it
    mastered they can use it as many times a day as they want but it
    now uses a spell slot to cast so there is still a limit, but that
    limit can be eventually be broken"). Once element_mastery_pct
    "heal" reaches real mastery (PROFICIENCY_MAX_PCT, same 100%
    threshold every other mastery tier in this game uses), the
    once-per-rest cap is replaced entirely by spending a real spell
    slot instead -- unlimited uses per rest, genuinely gated only by
    how many slots are left, not a hard escape hatch bolted on top of
    the old limit. Below mastery, behaves exactly as before.
    """
    character = db.get_character(update.effective_user.id, update.effective_chat.id)
    if character is None:
        await update.effective_chat.send_message(
            "You don't have a character yet!", message_thread_id=topics.thread_id_for(update.effective_chat.id, "adventure")
        )
        return
    if character["char_class"] != "Fighter":
        await update.effective_chat.send_message(
            "Second Wind is a real Fighter class feature — your class doesn't have it.",
            message_thread_id=topics.thread_id_for(update.effective_chat.id, "adventure"),
        )
        return

    heal_pct = character.get("element_mastery_pct", {}).get("heal", PROFICIENCY_STARTING_PCT)
    mastered = heal_pct >= PROFICIENCY_MAX_PCT
    if mastered:
        spent, character = db.spend_spell_slot(update.effective_user.id, update.effective_chat.id)
        if not spent:
            await update.effective_chat.send_message(
                f"Your healing mastery has broken Second Wind's once-per-rest limit, but you're out of spell "
                f"slots to fuel it with ({character['spell_slots_current']}/{character['spell_slots_max']} left).",
                message_thread_id=topics.thread_id_for(update.effective_chat.id, "adventure"),
            )
            return
    elif db.get_feature_uses(update.effective_user.id, update.effective_chat.id, "second_wind") >= 1:
        await update.effective_chat.send_message(
            "You've already used Second Wind since your last rest — keep grinding your healing mastery to "
            "100% to break that limit and fuel it with spell slots instead.",
            message_thread_id=topics.thread_id_for(update.effective_chat.id, "adventure"),
        )
        return

    # Universal Manipulation "hardened_resolve" (2026-08-06, repeatable):
    # base 1d10, +1 extra 1d10 die per point invested, unlimited.
    heal_dice = f"{1 + _skill_points(character, 'hardened_resolve')}d10"
    healed = roll_damage(heal_dice, modifier=character["level"])["total"]
    # Real player-power rebalance (2026-07-26): keeps self-healing
    # abilities in step with the same rescaled HP pools resolve_heal_
    # spell now scales for real spellcasting.
    healed = int(healed * power_scale_ratio(character["level"], character.get("rebirth_count", 0)))
    healed = int(healed * _mastery_overflow_multiplier(_grind_heal_mastery(character)))
    new_hp = min(character["hp_max"], character["hp_current"] + healed)
    actual_healed = new_hp - character["hp_current"]
    db.update_character(update.effective_user.id, update.effective_chat.id, hp_current=new_hp)
    if not mastered:
        db.use_feature(update.effective_user.id, update.effective_chat.id, "second_wind")

    await _safe_send(
        update,
        f"💨 **{character['name']}** catches their breath with Second Wind, recovering "
        f"**{actual_healed} HP** ({new_hp}/{character['hp_max']}).",
    )
    await _maybe_send_ability_image(update, "Second Wind", "a warrior catching their breath in a burst of healing energy", "💨")


RAGE_MAX_USES = 2
RAGE_DAMAGE_BONUS = 2
WILD_SHAPE_MAX_USES = 2


def _wild_shape_bonus_temp_hp(character: dict) -> int:
    """
    Real live gap (2026-08-27, per Coffee's dev-bridge: "make the
    [Universal Manipulation abilities] have endgame purpose" -- found
    while auditing Primal Surge specifically). Second Wind, Lay on
    Hands, Bardic Inspiration, and every damage-dealing spell/attack in
    this game already run their own resulting HP/damage total through
    power_scale_ratio so they keep pace with the same 2026-07-26
    monster HP/damage rebalance -- Wild Shape's temp HP (and its
    Primal Surge skill-tree bonus) was the one ability left out, so
    both quietly became more and more negligible relative to real
    endgame HP pools every rebirth. Shared by both real call sites
    (the deterministic AI auto-resolve path and the real player action)
    so they can't drift out of sync with each other the way past
    duplicated-logic bugs in this codebase already have.
    """
    base = wild_shape_temp_hp(character["level"]) + 2 * _skill_points(character, "primal_surge")
    return int(base * power_scale_ratio(character["level"], character.get("rebirth_count", 0)))


async def _do_rage(update: Update) -> None:
    """
    Real Barbarian class feature: bonus action to enter a rage — bonus
    melee damage and resistance to bludgeoning/piercing/slashing damage.
    2 uses per rest at level 1 (real 5E). The "raging" flag lives on the
    LIVE combat participant dict (session.participants), the same way
    existing conditions like prone/poisoned already do -- in-memory
    only, resets when combat ends, not persisted to the DB. Simplified
    from real 5E: lasts until combat ends rather than tracking the real
    per-round "no attack/no damage taken" end conditions, and applies as
    a flat damage resistance (half incoming damage) rather than only to
    the three specific physical damage types, since this combat system
    doesn't model damage types at all -- an honest, documented
    simplification, not an oversight.
    """
    character = db.get_character(update.effective_user.id, update.effective_chat.id)
    if character is None:
        await update.effective_chat.send_message(
            "You don't have a character yet!", message_thread_id=topics.thread_id_for(update.effective_chat.id, "adventure")
        )
        return
    if character["char_class"] != "Barbarian":
        await update.effective_chat.send_message(
            "Rage is a real Barbarian class feature — your class doesn't have it.",
            message_thread_id=topics.thread_id_for(update.effective_chat.id, "adventure"),
        )
        return
    # Universal Manipulation "endless_fury" (2026-08-06, repeatable): +1 extra Rage use per point invested, unlimited.
    max_rages = RAGE_MAX_USES + _skill_points(character, "endless_fury")
    if db.get_feature_uses(update.effective_user.id, update.effective_chat.id, "rage") >= max_rages:
        await update.effective_chat.send_message(
            f"You've already raged {max_rages} times since your last rest.",
            message_thread_id=topics.thread_id_for(update.effective_chat.id, "adventure"),
        )
        return

    session = sessions.get_session_for_user(update.effective_chat.id, update.effective_user.id)
    if session is None:
        await update.effective_chat.send_message(
            "You can only enter a rage in combat.", message_thread_id=topics.thread_id_for(update.effective_chat.id, "adventure")
        )
        return
    participant = next(
        (p for p in session.participants if p["telegram_user_id"] == update.effective_user.id), None
    )
    if participant is None:
        await update.effective_chat.send_message(
            "You're not part of the current fight.", message_thread_id=topics.thread_id_for(update.effective_chat.id, "adventure")
        )
        return
    if participant.get("raging"):
        await update.effective_chat.send_message(
            "You're already raging.", message_thread_id=topics.thread_id_for(update.effective_chat.id, "adventure")
        )
        return

    participant["raging"] = True
    db.use_feature(update.effective_user.id, update.effective_chat.id, "rage")

    await _safe_send(
        update,
        f"😡 **{character['name']}** flies into a rage — bonus damage and resistance to "
        f"physical harm for the rest of this fight!",
    )
    await _maybe_send_ability_image(update, "Rage", "a barbarian roaring in a furious battle rage", "😡")


async def _do_join_battle(update: Update) -> None:
    """
    Per Coffee (2026-07-21): "if the AI is in battle and human players
    are not, let them continue [elsewhere] ... if the characters want
    to join the battle, let them travel to the battle and join." Real
    gap this closes: combat participants were previously fixed the
    instant _do_start_combat ran (via _get_combat_eligible_party_members
    at that one moment) with no way to add a live participant
    afterward, even for a player who deliberately traveled to the exact
    location where the fight is happening. This is the other half of
    that -- non-participants were already free to gather/move/act
    normally the whole time (_do_gather/_do_move never checked for an
    active session at all), so nothing needed fixing there.
    """
    telegram_user_id = update.effective_user.id
    character = db.get_character(telegram_user_id, update.effective_chat.id)
    if character is None:
        await update.effective_chat.send_message(
            "You don't have a character yet!", message_thread_id=topics.thread_id_for(update.effective_chat.id, "adventure")
        )
        return

    chat_id = update.effective_chat.id
    if sessions.get_session_for_user(chat_id, telegram_user_id) is not None:
        await update.effective_chat.send_message(
            "You're already part of a fight.", message_thread_id=topics.thread_id_for(update.effective_chat.id, "adventure")
        )
        return
    if character["hp_current"] <= 0:
        await update.effective_chat.send_message(
            "You can't join a fight at 0 HP.", message_thread_id=topics.thread_id_for(update.effective_chat.id, "adventure")
        )
        return

    # Multiple independent fights can now be running in the same chat
    # (2026-08-01 multi-fight rewrite), so "join the battle" has to pick
    # WHICH one -- the fight actually happening at this character's own
    # current location, same as before, just resolved across every
    # active session in the chat instead of assuming there's only one.
    candidate_sessions = sessions.get_sessions_in_chat(chat_id)
    if not candidate_sessions:
        await update.effective_chat.send_message(
            "There's no fight happening right now.", message_thread_id=topics.thread_id_for(update.effective_chat.id, "adventure")
        )
        return

    matching_session = None
    other_battle_locations = []
    for candidate in candidate_sessions:
        party_members = [p for p in candidate.participants if candidate.sides.get(p["telegram_user_id"]) == "party"]
        # Real live bug (2026-08-19, Coffee: "im saying join the battle
        # and it says there is no battle... we are at the LONELY
        # CAIRN"): this used to read current_location straight off the
        # in-memory combat participant dict -- a one-time snapshot taken
        # when the fight started, never refreshed afterward. Confirmed
        # live via the real DB: Charvenna's own row genuinely said
        # "greymoor_downs_lonely_cairn" (matching Coffee's own report,
        # and matching where she and Ravenloft were actually both
        # standing), while her in-memory combat snapshot still said the
        # stale "greymoor_downs" from whenever the fight actually
        # began -- a real, live location drift the earlier v1.27.260
        # fix for the AI-companion case doesn't cover (Charvenna's a
        # real human, not an AI companion, so that fix's guard never
        # applied to her at all). Rather than trying to hunt down every
        # possible way this snapshot can drift, this now reads each
        # party-side member's REAL, CURRENT database row instead of the
        # frozen-in-time in-memory copy -- the one genuinely
        # authoritative source for "where is this person right now,"
        # matching what "join the battle" is actually asking.
        # A real human's own row is the more trustworthy source when
        # both exist: they can't be silently relocated by anything else
        # (an AI companion's row can still drift for other, unrelated
        # reasons even after v1.27.260's fix -- e.g. it hadn't rushed in
        # yet before that fix landed, or a still-unknown path this bug
        # class hasn't surfaced yet). Real humans checked first, AI
        # companions only as a fallback when no real human is fighting.
        battle_location = None
        for p in sorted(party_members, key=lambda p: p.get("is_ai", False)):
            live_row = db.get_character(p["telegram_user_id"], chat_id)
            if live_row and live_row.get("current_location"):
                battle_location = live_row["current_location"]
                break
        if battle_location is None:
            battle_location = next((p.get("current_location") for p in party_members if p.get("current_location")), None)
        if battle_location is not None and character["current_location"] == battle_location:
            matching_session = candidate
            break
        if battle_location is not None:
            other_battle_locations.append(battle_location)
    if matching_session is None:
        # Real, recurring live report (2026-08-12, dev-bridge: "This user
        # said this twice and for some reason they have not been put
        # into battle" -- confirmed via the live sessions snapshot: the
        # real fight was at Glimmerdeep Grotto, but this player had
        # explicitly traveled to and stayed at the Sunken Root Caverns,
        # a real but completely different location, before every one of
        # 7 "join the battle" attempts across 5 real days): this
        # rejection never said WHERE the actual fight was, leaving the
        # player to guess. Names the real location(s) of whatever fight
        # IS active in this chat, deduped, when there's at least one --
        # never invents a location, only ever reports real session data
        # already being read just above.
        location_names = []
        for loc_id in dict.fromkeys(other_battle_locations):
            loc = cl.get_location(CAMPAIGN, loc_id)
            location_names.append(loc["name"] if loc else loc_id)
        if location_names:
            hint = f" The real fight right now is at {', '.join(location_names)} — head there first."
        else:
            hint = " You'd need to go there first."
        await update.effective_chat.send_message(
            f"There's no fight happening at your current location.{hint}",
            message_thread_id=topics.thread_id_for(update.effective_chat.id, "adventure"),
        )
        return

    async with sessions.get_session_lock(matching_session.session_id):
        session = sessions.get_session_by_id(matching_session.session_id)
        if session is None:
            await update.effective_chat.send_message(
                "That fight just ended.", message_thread_id=topics.thread_id_for(update.effective_chat.id, "adventure")
            )
            return
        if any(p["telegram_user_id"] == telegram_user_id for p in session.participants):
            await update.effective_chat.send_message(
                "You're already part of this fight.", message_thread_id=topics.thread_id_for(update.effective_chat.id, "adventure")
            )
            return

        sessions.join_session(session, character, "party")
        await _safe_send(update, f"⚔️ **{character['name']}** joins the battle!")
        await _notify_main_topic(update, f"⚔️ **{character['name']}** joined an in-progress battle!")
        # Real live bug (2026-08-10, Coffee: "im not seeing the
        # formations in our current battle"): joining an ALREADY-running
        # fight never refreshed the formation image at all -- it's only
        # ever sent at the fight's own start (_do_start_combat) and on
        # each completed round (_resolve_ai_turns' wrapper) -- so a
        # player who joined mid-fight, and everyone else, kept seeing a
        # stale roster missing the new arrival until the next round
        # happened to complete. One refresh right here, same real,
        # never-invented session.living_on_side data every other
        # formation-image send already uses.
        await _maybe_send_battle_formation_image(update, session)


async def _do_wild_shape(update: Update) -> None:
    """
    Real Druid class feature (level 2+, task #91 audit 2026-07-19: Druid
    was found to have ZERO unique mechanical features of its own, the
    only one of the 12 classes with nothing here at all -- spellcasting
    alone). 2 uses per rest (real 5E). The `wild_shaped` flag lives on
    the LIVE combat participant dict, same in-memory, combat-only
    convention as `raging` (see _do_rage) -- grants bonus claw/bite
    damage (wild_shape_damage_bonus) and a chunk of real temp_hp
    (wild_shape_temp_hp, the same mechanic Dark One's Blessing already
    uses), simplified from real 5E's actual separate beast statblock
    since this engine has no such system for any class. The real
    tradeoff (real 5E: a shapeshifted Druid can't cast spells) is
    enforced in _do_cast_spell, mirroring the existing `silenced`
    condition block there.
    """
    character = db.get_character(update.effective_user.id, update.effective_chat.id)
    if character is None:
        await update.effective_chat.send_message(
            "You don't have a character yet!", message_thread_id=topics.thread_id_for(update.effective_chat.id, "adventure")
        )
        return
    if character["char_class"] != "Druid":
        await update.effective_chat.send_message(
            "Wild Shape is a real Druid class feature — your class doesn't have it.",
            message_thread_id=topics.thread_id_for(update.effective_chat.id, "adventure"),
        )
        return
    if character["level"] < 2:
        await update.effective_chat.send_message(
            "Wild Shape is a Druid feature starting at level 2 — you're not there yet.",
            message_thread_id=topics.thread_id_for(update.effective_chat.id, "adventure"),
        )
        return
    if db.get_feature_uses(update.effective_user.id, update.effective_chat.id, "wild_shape") >= WILD_SHAPE_MAX_USES:
        await update.effective_chat.send_message(
            f"You've already used Wild Shape {WILD_SHAPE_MAX_USES} times since your last rest.",
            message_thread_id=topics.thread_id_for(update.effective_chat.id, "adventure"),
        )
        return

    session = sessions.get_session_for_user(update.effective_chat.id, update.effective_user.id)
    if session is None:
        await update.effective_chat.send_message(
            "You can only Wild Shape in combat.", message_thread_id=topics.thread_id_for(update.effective_chat.id, "adventure")
        )
        return
    participant = next(
        (p for p in session.participants if p["telegram_user_id"] == update.effective_user.id), None
    )
    if participant is None:
        await update.effective_chat.send_message(
            "You're not part of the current fight.", message_thread_id=topics.thread_id_for(update.effective_chat.id, "adventure")
        )
        return
    if participant.get("wild_shaped"):
        await update.effective_chat.send_message(
            "You're already Wild Shaped.", message_thread_id=topics.thread_id_for(update.effective_chat.id, "adventure")
        )
        return

    participant["wild_shaped"] = True
    bonus_temp_hp = _wild_shape_bonus_temp_hp(character)
    participant["temp_hp"] = max(participant.get("temp_hp", 0), bonus_temp_hp)
    db.use_feature(update.effective_user.id, update.effective_chat.id, "wild_shape")

    await _safe_send(
        update,
        f"🐾 **{character['name']}** shifts into a beast — {bonus_temp_hp} temporary HP and "
        f"clawed, biting attacks for the rest of this fight, but no spellcasting while shifted!",
    )
    await _maybe_send_ability_image(update, "Wild Shape", "a druid shifting into a wild beast form", "🐾")


async def _do_action_surge(update: Update) -> None:
    """
    Real Fighter class feature (level 2+, 2026-07-16 level-2-10 audit):
    take an additional action on your turn, once per rest. Adapted to
    this engine's turn structure as doubling this turn's full attack
    sequence (real 5E: a Fighter with Extra Attack gets their WHOLE
    attack sequence again, not just one more swing) -- a flag on the
    live combat participant dict, same convention as `raging`, consumed
    (popped, not just read) by _do_attack's own attack_count
    calculation the very next time this Fighter attacks, so it can only
    ever double one attack sequence per use.
    """
    character = db.get_character(update.effective_user.id, update.effective_chat.id)
    if character is None:
        await update.effective_chat.send_message(
            "You don't have a character yet!", message_thread_id=topics.thread_id_for(update.effective_chat.id, "adventure")
        )
        return
    if character["char_class"] != "Fighter":
        await update.effective_chat.send_message(
            "Action Surge is a real Fighter class feature — your class doesn't have it.",
            message_thread_id=topics.thread_id_for(update.effective_chat.id, "adventure"),
        )
        return
    if character["level"] < 2:
        await update.effective_chat.send_message(
            "Action Surge is a Fighter feature starting at level 2 — you're not there yet.",
            message_thread_id=topics.thread_id_for(update.effective_chat.id, "adventure"),
        )
        return
    if db.get_feature_uses(update.effective_user.id, update.effective_chat.id, "action_surge") >= 1:
        await update.effective_chat.send_message(
            "You've already used Action Surge since your last rest.",
            message_thread_id=topics.thread_id_for(update.effective_chat.id, "adventure"),
        )
        return

    session = sessions.get_session_for_user(update.effective_chat.id, update.effective_user.id)
    if session is None:
        await update.effective_chat.send_message(
            "You can only use Action Surge in combat.", message_thread_id=topics.thread_id_for(update.effective_chat.id, "adventure")
        )
        return
    participant = next(
        (p for p in session.participants if p["telegram_user_id"] == update.effective_user.id), None
    )
    if participant is None:
        await update.effective_chat.send_message(
            "You're not part of the current fight.", message_thread_id=topics.thread_id_for(update.effective_chat.id, "adventure")
        )
        return
    if participant.get("action_surge_active"):
        await update.effective_chat.send_message(
            "Action Surge is already active for your next attack.", message_thread_id=topics.thread_id_for(update.effective_chat.id, "adventure")
        )
        return

    participant["action_surge_active"] = True
    db.use_feature(update.effective_user.id, update.effective_chat.id, "action_surge")

    await _safe_send(
        update,
        f"⚡ **{character['name']}** surges with action — their next attack this turn "
        f"comes as a full extra sequence!",
    )
    await _maybe_send_ability_image(update, "Action Surge", "a fighter surging with sudden explosive energy", "⚡")


