def _monster_danger_line(monster_keys: list[str]) -> str:
    """
    Real difficulty signal for "look around" (2026-08-01, per Coffee:
    "show the lv of the enemies... it will give us an idea if we are
    over our heads or not"). A monster with no real "level" field of
    its own gets one inferred the same way scaled_enemy_count already
    reasons about fights, by finding the highest real 5E DMG "medium
    encounter" XP threshold (MEDIUM_ENCOUNTER_XP_PER_CHARACTER) this
    monster's own xp_reward clears, i.e. "a medium fight for a
    level-N character" -- not an invented number.

    Real live bug + correction (2026-08-15, per Coffee, dev-bridge):
    the level-3/26 fix in v1.27.232 initially showed a boss's real
    level once it had been through the Encounter Ledger pass -- Coffee
    corrected this immediately after ("(???) still please"): EVERY
    boss keeps the "???" mystery, hand-authored or not -- that was
    never the bug. The only real bug was trash monsters (Goblin,
    Goblin Shaman, ...) not reflecting their real authored level yet,
    which is what's actually fixed here; bosses are untouched from
    their original 2026-08-01 behavior.
    """
    parts = []
    for key in monster_keys:
        template = cl.get_monster_template(CAMPAIGN, key)
        if template is None:
            continue
        name = template["name"]
        if template.get("is_boss"):
            parts.append(f"{name} (???)")
            continue
        authored_level = template.get("level")
        if authored_level is not None:
            parts.append(f"{name} (Lv. {authored_level})")
            continue
        xp = template.get("xp_reward", 0)
        level = 1
        for lvl, threshold in sorted(MEDIUM_ENCOUNTER_XP_PER_CHARACTER.items()):
            if xp >= threshold:
                level = lvl
            else:
                break
        parts.append(f"{name} (Lv. {level})")
    return ", ".join(parts)


async def _do_look(update: Update) -> None:
    character = db.get_character(update.effective_user.id, update.effective_chat.id)
    if character is None:
        await update.effective_chat.send_message(
            "You don't have a character yet!", message_thread_id=topics.thread_id_for(update.effective_chat.id, "adventure")
        )
        return
    location = cl.get_location(CAMPAIGN, character["current_location"])
    if location is None:
        await update.effective_chat.send_message(
            f"**{character['name']}** seems to be nowhere in particular. That's... concerning.",
            message_thread_id=topics.thread_id_for(update.effective_chat.id, "adventure"),
        )
        return

    already_visited = character["current_location"] in (character.get("visited_locations") or [])
    db.mark_visited(update.effective_user.id, update.effective_chat.id, character["current_location"])

    # Names the looker (task #139, 2026-07-17): in a shared chat, a bare
    # "📍 Location Name" reply doesn't say WHO just looked around --
    # same ambiguous-actor problem already fixed for combat/skill-check
    # narration (#107/#115), just never applied to this deterministic
    # (non-AI) reply path.
    lines = [f"👁️ **{character['name']}** looks around.", f"📍 **{location['name']}** ({location['layer']})"]
    lines.append(f"🌤️ {world_clock.conditions_line(location['layer'])}")
    # Darkness (2026-08-04, per Coffee): without Darkvision, a torch/
    # lantern, or an active light spell, an underground location shows
    # nothing but the fact that you can't see -- a real hint to equip a
    # light source or cast one, not just flavor text layered over a
    # description you'd see anyway.
    if _location_is_dark(location, character, update.effective_chat.id):
        lines.append(
            "🌑 **It is too dark. You cannot see...** (equip a torch, or cast a spell like Dancing Lights, to see here.)"
        )
        connections = location.get("connections", [])
        if connections:
            conn_names = [cl.get_location(CAMPAIGN, c)["name"] for c in connections]
            lines.append(f"You can still feel your way to: {', '.join(conn_names)}")
        await _safe_send(update, "\n".join(lines))
        return
    lines.append(location["description"])
    extra_lines, reply_markup = _location_extra_detail(character, location, character["current_location"], update.effective_chat.id)
    lines.extend(extra_lines)

    # Confirmed live 2026-07-14 (Coffee): TTS was silently skipped for
    # "look around" -- this reply went straight to
    # update.effective_chat.send_message, bypassing _safe_send
    # entirely, and _maybe_speak (TTS) is only ever hooked in there.
    # This is one of many direct-send call sites in this file (~195 of
    # them vs 64 through _safe_send) -- most are short refusal/error
    # messages that were never meant to be narrated aloud, but "look"
    # is real player-facing narration and should have gone through
    # _safe_send like every other primary action reply already does.
    await _safe_send(update, "\n".join(lines), reply_markup=reply_markup)
    await _maybe_send_location_image(update, location, character["current_location"], already_visited)


def _lockable_callout_lines(location: dict, chat_id: int) -> list[str]:
    """
    Shared room-description callout for every lockable present, used by
    both the overworld's own `_location_extra_detail` and the
    Labyrinth's `_do_labyrinth_look` (2026-09-02, Phase L2) -- generic
    over a plain `location: dict`, confirmed CAMPAIGN-agnostic, exactly
    like `_lockable_is_open`/`_find_lockable` already are.
    """
    lines = []
    lockable_emoji = {
        "door": "🔒", "chest": "🔒", "lever": "🔧", "switch": "🔷", "pressure_plate": "⚖️",
        "breakable_wall": "💥", "breakable_floor": "💥", "multi_switch_gate": "🔶",
        "carry_object": "🪨", "pillar": "🏛️", "hint_statue": "🗿",
    }
    for lockable in location.get("lockables", []):
        if lockable.get("hidden"):
            continue
        kind = lockable.get("kind")
        # switch/pressure_plate/multi_switch_gate/pillar/hint_statue are
        # deliberately NEVER skipped here even once used -- a statue
        # never "resolves" (it can be examined any number of times),
        # and the other four can be toggled back off (or, for a pillar,
        # are just a standing fact about the room either way), unlike
        # every other kind which "resolves" into an open path once
        # picked. carry_object is likewise never skipped -- it's a
        # real, permanently-present object, not something used up.
        if kind not in ("switch", "pressure_plate", "multi_switch_gate", "carry_object", "pillar", "hint_statue") and _lockable_is_open(location, lockable["id"], chat_id):
            continue
        emoji = lockable_emoji.get(kind, "🔒")
        if kind == "lever":
            state = "waiting to be pulled"
        elif kind == "switch":
            active = _lockable_is_open(location, lockable["id"], chat_id)
            element = lockable.get("element", "")
            # Real live request (2026-09-03, Coffee, dev-bridge
            # screenshot: circled the generic blue diamond shown for
            # every switch regardless of its own real element/state --
            # "find appropriate emojis for the elemental colors"). The
            # real per-element emoji already exists and is already used
            # correctly in the activation narration (_do_activate_
            # switch) -- this was simply the one other place a switch's
            # icon still used the generic kind-level default instead.
            # Inactive stays a plain dark circle regardless of element
            # (an unlit crystal doesn't show its own color yet).
            emoji = _SWITCH_ELEMENT_EMOJI.get(element, "🔷") if active else "⚫"
            state = f"{'glowing' if active else 'dark'}{f' {element}' if element else ''}, {'active' if active else 'inactive'}"
        elif kind == "pressure_plate":
            active = _lockable_is_open(location, lockable["id"], chat_id)
            state = "pressed down, active" if active else "raised, waiting for something heavy or the right liquid"
        elif kind == "multi_switch_gate":
            active = _lockable_is_open(location, lockable["id"], chat_id)
            state = "every switch answering it, active" if active else "still waiting on one or more of its switches"
        elif kind in ("breakable_wall", "breakable_floor"):
            state = "cracked, looks breakable"
        elif kind == "carry_object":
            state = "heavy, but carriable"
        elif kind == "pillar":
            active = _lockable_is_open(location, lockable["id"], chat_id)
            state = "already struck" if active else "waiting for a real blow with something heavy"
        elif kind == "hint_statue":
            state = "watching over the entry, worth a closer look"
        else:
            state = "locked"
        lines.append(f"{emoji} {lockable['name'].capitalize()} is here, {state}.")
    return lines


def _location_extra_detail(character: dict, location: dict, location_id: str, chat_id: int) -> tuple[list[str], "InlineKeyboardMarkup | None"]:
    """
    Everything "look around" shows beyond the location's own name and
    description: who/what's here, how to leave, and any quest hook.
    Extracted (2026-08-07, per Coffee: "prompt 'look around' ... once
    we arrive there to keep the narration flowing") so _do_move's
    real-player arrival narration can show this same detail without a
    player needing to separately type "look around" every time they
    walk into a room -- previously _do_move only ever showed the
    location's bare name/description, none of this. Kept as a
    lines-only helper (never sends anything, never sends the location
    image) so BOTH callers stay in full control of exactly one combined
    send/image per arrival -- calling the full _do_look from _do_move
    directly was considered and rejected specifically because it would
    have sent the same location image a second time back to back.
    """
    lines = []
    npcs_here = _npcs_at_location(location_id, chat_id)
    npc_names = []
    if npcs_here:
        npc_names = [cl.get_npc(CAMPAIGN, n)["name"] for n in npcs_here if cl.get_npc(CAMPAIGN, n)]
    # Real gap found 2026-08-11 (dev-topic report: "Pan is there too but
    # it doesn't mention that they are present when I looked around") --
    # confirmed live: Pan is a real player character (is_ai=0), not a
    # campaign NPC, whose current_location genuinely matched the
    # reporting player's. "People here" only ever listed campaign.json
    # NPCs (_npcs_at_location), never other real players/companions
    # actually standing at the same location -- exactly the kind of gap
    # CLAUDE.md's "never lets the game distinguish human from AI" design
    # would call a real miss, since a human party member is just as
    # real a presence here as an AI one. _get_combat_eligible_party_members
    # already has the exact right filter (active, not resting, actually
    # AT this location) since it's used to decide who can join a fight
    # breaking out here -- reused as-is, excluding the viewer themselves.
    other_people_here = [
        p["name"] for p in _get_combat_eligible_party_members(location_id, chat_id)
        if p.get("telegram_user_id") != character.get("telegram_user_id")
    ]
    # Real live bug (2026-08-13, dev-topic screenshot): "People here:
    # Grask Emberscale, ..., Grask Emberscale, ..." -- a recruited
    # companion (db.create_ai_companion always names them identically
    # to their source NPC, see _do_recruit_npc) never gets removed from
    # their origin location's static campaign.json npcs list, so once
    # recruited they're counted TWICE here: once as the static "fixture
    # NPC" (npc_names, above) and again as a real, present party member
    # (other_people_here, just above) whenever the party happens to be
    # back at that NPC's own home location. dict.fromkeys preserves
    # first-seen order (the static flavor name wins the position) while
    # dropping the later duplicate -- the same real person should only
    # ever be listed once.
    people_names = list(dict.fromkeys(npc_names + other_people_here))
    if people_names:
        lines.append(f"People here: {', '.join(people_names)}")
    # Real live request (2026-08-29, Coffee: bosses shouldn't even show
    # up as "danger here" before their own quest can be reached -- see
    # _monster_visible_to_character's own docstring).
    monsters_here = [k for k in location.get("monsters", []) if _monster_visible_to_character(k, character)]
    if monsters_here:
        lines.append(f"You sense danger here: {_monster_danger_line(monsters_here)}")
    connections = location.get("connections", [])
    if connections:
        # Sensory travel descriptions (task #220, per Coffee: "explain
        # to them how/why they can go there" instead of just naming a
        # destination) -- an optional, purely additive per-connection
        # sentence, layered the same way "directions" already is over
        # the real connections list. Only written for a handful of
        # major, farther-off destinations so far (not every short
        # interior hop needs one); anything without a sensory line
        # keeps falling back to the flat name list exactly as before.
        sensory_for_dest = location.get("sensory_connections", {})
        sensory_conns = [c for c in connections if c in sensory_for_dest]
        for c in sensory_conns:
            lines.append(f"👀 {sensory_for_dest[c]}")

        # Compass labels (world-expansion pass, 2026-07-19): "directions" is
        # a pure display layer over the real "connections" reachability list
        # -- inverted here so a connection with a compass word shows it
        # (e.g. "North: The Deep Glade"), while any connection still without
        # one (every pre-expansion location) falls back to the plain name,
        # exactly as before.
        plain_conns = [c for c in connections if c not in sensory_for_dest]
        if plain_conns:
            direction_for_dest = {dest: word.capitalize() for word, dest in location.get("directions", {}).items()}
            conn_labels = [
                f"{direction_for_dest[c]}: {cl.get_location(CAMPAIGN, c)['name']}" if c in direction_for_dest
                else cl.get_location(CAMPAIGN, c)["name"]
                for c in plain_conns
            ]
            lines.append(f"You can travel to: {', '.join(conn_labels)}")
    if "descends_to" in location:
        below = cl.get_location(CAMPAIGN, location["descends_to"])
        if _character_can_currently_reach(character, below):
            lines.append(f"You could descend to: {below['name']}")
    if "ascends_to" in location:
        above = cl.get_location(CAMPAIGN, location["ascends_to"])
        if _character_can_currently_reach(character, above):
            lines.append(f"You could ascend to: {above['name']}")
    interactables = location.get("interactables", {})
    if interactables:
        names = [i["name"] for i in interactables.values()]
        lines.append(f"Things worth a closer look: {', '.join(names)}")
    # Real live feature request (2026-08-31, dev-bridge, Coffee: "make
    # sure they are clear in the look around narrations and descriptions
    # of the rooms maybe with an appropriate emoji beside it so it pops
    # out to the player ... if its a hidden item dont use an emoji tho").
    # A visible, not-yet-unlocked lockable (a real door/chest/lever a
    # player could plausibly walk right past, per the exact confusion
    # the Ember Hall floor-text bug and the "look for a lever" reports
    # both came from) now calls itself out plainly with a distinguishing
    # emoji, same "pop out" ask. Explicitly opt-in `hidden: true` (no
    # real lockable sets this yet -- this game's lockables have never
    # had a genuine hidden/undiscovered state, confirmed by
    # _mentions_hidden_passage's own docstring) skips the callout
    # entirely until the player actually finds it via examine/search,
    # so a future genuinely-hidden mechanism doesn't spoil itself here.
    # Once unlocked, the ordinary connections/travel-button listing
    # already covers the now-open path -- no need to keep calling out a
    # lockable that no longer blocks anything.
    lines.extend(_lockable_callout_lines(location, chat_id))
    resource_nodes = location.get("resource_nodes", [])
    if resource_nodes:
        node_names = [n["name"] for n in resource_nodes]
        lines.append(f"Resources here: {', '.join(node_names)}")
        sensed = [
            n for n in resource_nodes
            if RESOURCE_SENSE_CLASS.get(n["ability"]) == character["char_class"]
        ]
        if sensed:
            sensed_materials = ", ".join(
                items_module.get_item(n["material"])["name"] for n in sensed
            )
            lines.append(
                f"Your {character['char_class']} training picks {sensed_materials} out "
                f"at a glance — most people would walk right past it."
            )

    # Quest hints on "look around" (2026-07-16, per Coffee): a location
    # with a quest tied to it, or a board quest posted, used to give no
    # sign of either -- players had to separately think to ask "check
    # quests" even at a place clearly meant to offer one. Story quests
    # have no structured NPC field in campaign.json (see
    # _npc_quest_facts's own comment on this), so any NPC actually
    # present is the approximation used to point players at someone to
    # talk to. Board quests are generated here too (not just shown),
    # matching check_quests's own behavior, so the FIRST person to see
    # this detail (whether via "look around" or now arrival too) is the
    # one who reveals what's posted.
    story_offer = _offerable_quest_at_location(character, location_id)
    if story_offer:
        if npcs_here:
            lines.append(f"📜 {npc_names[0]} looks like they could use your help with something.")
        else:
            lines.append("📜 There's a task tied to this place, though no one's here to ask about it right now.")

    # Real live report (2026-08-26, Coffee: "i only see [Borin's quest]
    # in the affinity menu, it needs to be more clear to be able to be
    # found"). A recruited companion's own personal quest -- unlike the
    # location quests above, which only ever get an approximated "some
    # NPC here" hint -- has a real, exact giver_npc, so this can name
    # them directly. Shown regardless of npcs_here/story_offer above,
    # since a recruited companion travels with the party rather than
    # staying tied to any one location.
    companion_offer = _offerable_companion_quest(character)
    if companion_offer:
        _, quest = companion_offer
        giver_name = CAMPAIGN["npcs"].get(quest["giver_npc"], {}).get("name", "someone in your party")
        lines.append(f"📜 {giver_name} has something to ask of you — try talking to them.")

    board_quests_here = board_quests_module.get_or_generate_all_board_quests(CAMPAIGN, location_id, chat_id)
    unclaimed_board_quests = [q for q in board_quests_here if not q.get("accepted_by")]
    if unclaimed_board_quests:
        lines.append("📋 There's a bounty posted on the board here — say \"check quests\" to see it.")

    return lines, _look_action_keyboard(location, unclaimed_board_quests, chat_id, character)


async def _do_check_weather(update: Update) -> None:
    """
    Weather/day-night (task #84): a direct query ("what's the weather
    like") separate from a full "look around" -- same real, deterministic
    world_clock.conditions_line already shown there, just without the
    rest of the location description.
    """
    character = db.get_character(update.effective_user.id, update.effective_chat.id)
    if character is None:
        await _safe_send(update, "You don't have a character yet!", speak=False)
        return
    location = cl.get_location(CAMPAIGN, character["current_location"])
    if location is None:
        await _safe_send(update, "Hard to say — you don't seem to be anywhere in particular.", speak=False)
        return
    conditions = world_clock.conditions_line(location["layer"])
    if location["layer"] == "underground":
        await _safe_send(update, f"🌤️ {conditions} — no real weather reaches this deep, just the dark.", speak=False)
        return

    lines = [f"🌤️ {conditions} at **{location['name']}**."]
    # Real forecast (task, per Coffee, 2026-07-21): the exact same
    # deterministic (day, region) weather roll current_weather already
    # uses, just walked forward -- tomorrow's forecast really is
    # tomorrow's real weather, never a separate invented guess.
    upcoming = world_clock.forecast(location["layer"], days=3)[1:]
    if upcoming:
        forecast_line = ", ".join(f"{date} — {weather}" for date, weather in upcoming)
        lines.append(f"📅 Forecast: {forecast_line}")
    if world_clock.is_hazardous(location["layer"]):
        lines.append("⚠️ Underfoot's slick out there — footing hazards are real right now.")
    if world_clock.is_night():
        lines.append("🌙 Whatever's out there tonight is hunting with more bite than usual.")
    await _safe_send(update, "\n".join(lines), speak=False)


def _find_interactable(location: dict, text: str) -> tuple[str, dict] | None:
    """
    Fuzzy-ish lookup of a real, campaign-defined interactable object at
    this location, matched against free text (e.g. "examine the old
    barrel" -> the marked_barrel entry at tavern_cellar). Same
    name-appears-in-text approach as items.find_item_mentioned_in_text,
    for the same reason: trusting a real substring match over asking
    the small classifier model to extract the object name exactly.
    """
    interactables = location.get("interactables", {})
    # Real live bug (2026-07-19, confirmed live: "Look at maren's brass
    # scale" -- a real, described interactable -- failed even though a
    # longer phrasing of the exact same request succeeded): a phone
    # keyboard's smart-quote autocorrect sends a curly apostrophe (’,
    # U+2019), which never equals the straight one (') this game's own
    # stored names use, so "maren's" from the player's own message could
    # never match the word "Maren's" in "Old Maren's brass scale" at
    # all -- same single-character-collision shape as the existing
    # armour/armor and fishing rod/pole normalizations, just a
    # punctuation mark instead of a whole word this time.
    lowered = text.strip().lower().replace("’", "'")
    ordered = sorted(interactables.items(), key=lambda kv: -len(kv[1]["name"]))
    for obj_id, data in ordered:
        if data["name"].lower() in lowered or obj_id.replace("_", " ") in lowered:
            return obj_id, data

    # Fallback 1: ignore a leading article and compound-word spacing --
    # confirmed live 2026-07-14 (Coffee): "Read the guest book on the
    # landing table" didn't match the real stored name "a guestbook on
    # the landing table" at all -- both the leading "a" and the missing
    # space in "guestbook" were never how a player would naturally type
    # it, so the exact-substring check above failed even though this
    # was clearly the same object.
    # "old" added 2026-07-19 (same live "brass scale" bug as the
    # apostrophe fix above): "Old Maren's brass scale" is a 4-word name
    # where "old" is a throwaway descriptor, not a distinguishing word --
    # the exact same reasoning the NPC-name matcher's own
    # _NPC_NAME_FILLER_WORDS already applies to "old" for "Old Maren"
    # herself. Without excluding it, a shorter (but perfectly clear)
    # phrasing that skips "old" needs 3 of the remaining words just to
    # clear the same >half-the-words bar a distinctive object should
    # pass easily.
    stopwords = {"a", "an", "the", "of", "at", "on", "in", "to", "old"}
    for obj_id, data in ordered:
        name = data["name"].lower()
        for article in ("a ", "an ", "the "):
            if name.startswith(article):
                name = name[len(article):]
                break
        if name in lowered or name.replace(" ", "") in lowered.replace(" ", ""):
            return obj_id, data

    # Fallback 2: majority word-overlap -- confirmed live the same day:
    # "look at the door down the hall" didn't match the real "the door
    # at the end of the hall" at all (genuinely different wording, not
    # just spacing/articles), even though it's clearly the same door.
    # Picks whichever interactable's significant words (stopwords/short
    # words excluded) overlap the input the most, but only when there's
    # a single clear leader with OVER HALF its words present -- a weak
    # or tied overlap is left unmatched rather than guessed, same
    # "don't guess when ambiguous" philosophy as every other word-level
    # fallback in this codebase (NPC names, location names).
    candidate_words: dict = {}
    for obj_id, data in ordered:
        # Real bug, live-caught 2026-07-19 (Coffee: "a player is looking
        # at the wide-boled tree and its not working"): .split() left
        # punctuation stuck to whichever word precedes it in the stored
        # name (e.g. "an ancient, wide-boled tree" -> "ancient," with
        # the comma attached) -- \bword\b then could never match, since
        # a trailing comma-to-space transition has no word boundary at
        # all. That silently dropped "ancient" from the overlap count
        # entirely, so even "examine the ancient tree" (a perfectly
        # normal shortening, zero typos) fell one word short of the
        # >half threshold and matched nothing.
        # Real live bug (2026-07-19, same day as the "wide-boled tree"
        # fix above, same root shape but the opposite direction): "a
        # boarded up stall" (no hyphen, the natural way to type it)
        # never matched the stored "a boarded-up stall" -- the comma-
        # stripping fix above only ever handled a stray TRAILING
        # punctuation mark, not a hyphen genuinely joining two words
        # into one token, so "boarded-up" stayed a single unsplittable
        # word no plain space-separated phrasing could ever equal.
        # Splitting on hyphens the same as whitespace before stripping
        # trailing punctuation means "boarded-up" contributes "boarded"
        # to the overlap count same as if the stored name used a space.
        words = [
            w.strip(".,;:!?\"'()") for w in data["name"].lower().replace("-", " ").split()
        ]
        words = [w for w in words if w and w not in stopwords and len(w) >= 3]
        if words:
            candidate_words[obj_id] = (data, words)

    # Real live bug (2026-07-19, same "old strongbox" session): "Old
    # Maren's locked strongbox" (3 significant words after "old" is
    # excluded) needed 2 of them to clear the plain >half threshold
    # below, but "strongbox" -- the one word that actually NAMES the
    # object, a real head noun -- should be a confident match on its
    # own, the same distinction items.find_item_mentioned_in_text
    # already draws between a head-noun match and a mere modifier.
    # Checked as its own pass, before the general overlap threshold, so
    # it can only ever ADD a match a shorter phrasing would otherwise
    # miss, never take one away.
    # Real live bug (2026-07-22, Coffee, escalated dev-topic report --
    # "the third response now I have not gotten a reply"): "Take the
    # scrap of paper off the corkboard" never matched "the corkboard by
    # the door" -- the head-word check above only ever tried the LAST
    # significant word ("door", a generic location descriptor here, not
    # the actual object), so a name shaped "OBJECT by/behind/under the
    # LOCATION" (this campaign has several: "the corkboard by the
    # door", "the heavy ledger behind the bar") could never head-match
    # on the word that actually names the object. Generalized to try
    # EVERY one of a candidate's significant words, not just the last
    # -- a word only counts if it's unique to exactly one candidate at
    # this location (never ambiguously shared by two), same "don't
    # guess when ambiguous" discipline as the rest of this function.
    head_matches = []
    for obj_id, (data, words) in candidate_words.items():
        for word in words:
            if not re.search(r"\b" + re.escape(word) + r"\b", lowered):
                continue
            shared = any(
                other_id != obj_id and word in other_words
                for other_id, (_, other_words) in candidate_words.items()
            )
            if not shared:
                head_matches.append((obj_id, data))
            break
    if len(head_matches) == 1:
        return head_matches[0]

    best_obj, best_score, ambiguous = None, 0, False
    for obj_id, (data, words) in candidate_words.items():
        matches = sum(1 for w in words if re.search(r"\b" + re.escape(w) + r"\b", lowered))
        if matches > len(words) / 2:
            if matches > best_score:
                best_obj, best_score, ambiguous = (obj_id, data), matches, False
            elif matches == best_score:
                ambiguous = True
    if best_obj and not ambiguous:
        return best_obj

    return None


def _plural_forms(word: str) -> list[str]:
    """
    Cheap English pluralization for matching a monster's singular
    template name against a player's naturally-plural phrasing ("the
    wolves") -- confirmed live 2026-07-17 (Coffee): a plain substring
    check against "Wolf" never matches "wolves" at all (not a simple
    "+s" plural), so the very first live use of this monster-matching
    fix silently failed the exact case it was built for. Covers regular
    "+s"/"+es" and the common f/fe -> ves irregular (wolf -> wolves).

    Real live bug (2026-08-11, dev-topic screenshot, Coffee: "This
    triggered the wrong battle. It should've been a battle with the
    goblin shamans"): "Attack the goblin shamens" -- a real, common
    mispluralization (by false analogy with policeman/policemen,
    woman/women) -- matched none of "goblin shaman"'s real forms
    (shaman/shamans/shamanes), so _find_monster_mentioned_in_text fell
    through past it entirely and matched the shorter, unrelated plain
    "Goblin" template instead (a real word-boundary substring of the
    same input). Confirmed live via direct repro against the real
    Goblin Warrens location data. "-man" nouns also getting a "-men"/
    "-mens" candidate covers this and any future monster name with the
    same suffix, not just this one word.
    """
    forms = [word, word + "s", word + "es"]
    if word.endswith("f"):
        forms.append(word[:-1] + "ves")
    elif word.endswith("fe"):
        forms.append(word[:-2] + "ves")
    if word.endswith("man"):
        forms.append(word[:-3] + "men")
        forms.append(word[:-3] + "mens")
    return forms


def _find_monster_mentioned_in_text(location: dict, text: str, character: dict | None = None) -> tuple[str, dict] | None:
    """
    Matches a real monster type actually present at this location
    (location["monsters"], a list of monster_keys) against free text --
    same real-substring-match philosophy as _find_interactable, just
    for a different real fact source (task from Coffee, 2026-07-17).

    Real live bug (2026-08-11, Coffee, live: "i jus typed fight a
    shamen and it didnt work again... says no active combat"): even
    the CORRECT spelling ("Fight a Shaman", no "goblin" prefix) failed
    -- every candidate was always built from the monster's FULL name
    ("goblin shaman"/"goblin_shaman"), so a bare last-word reference
    never matched at all, regardless of spelling or pluralization (the
    same day's earlier fix only helped once "goblin" was ALSO present
    in the text). Second pass below: if the full name doesn't match
    anything, try just the LAST WORD of each multi-word name (its real
    distinguishing part -- "shaman", not "goblin", the part shared by
    every monster here) -- but ONLY when that word is unique among
    this location's own monsters, so "the boss" can't accidentally
    guess between two different, differently-typed bosses if this
    location ever has more than one.

    `character` is optional (backward-compatible for any caller with
    no character in scope) -- when given, a quest-tied monster this
    character can't legitimately face yet (or has already defeated) is
    filtered out before matching at all, see _monster_visible_to_
    character's own docstring for the real live bug this closes.
    """
    lowered = text.strip().lower()
    monster_keys = location.get("monsters", [])
    if character is not None:
        monster_keys = [k for k in monster_keys if _monster_visible_to_character(k, character)]
    templates = [(key, cl.get_monster_template(CAMPAIGN, key)) for key in monster_keys]
    templates = [(key, t) for key, t in templates if t is not None]
    templates.sort(key=lambda kt: -len(kt[1]["name"]))
    last_words = [t["name"].lower().split()[-1] for _, t in templates]
    words = [w for w in re.findall(r"[a-z]+", lowered) if len(w) >= 4]

    # Real live bug (2026-08-11, Coffee, live, multiple rounds: "fight a
    # shamen" / "Fight a Shaman" / "Fight a goblin shame" all failing or
    # (worse) matching the wrong, shorter monster) -- checking every
    # template fully (exact full name -> exact last word -> fuzzy last
    # word) BEFORE moving to the next was critical: three separate
    # global passes over every template let a shorter, unrelated exact
    # match (plain "Goblin", since "goblin" is literally in "goblin
    # shame") win before a longer template's OWN fuzzy chance was ever
    # reached, even with templates sorted longest-name-first. Now each
    # template (still longest-first, so "Goblin Shaman" is always tried
    # before plain "Goblin") gets its full fair shot -- exact, then
    # fuzzy -- before falling through to a shorter, less specific one.
    for monster_key, template in templates:
        name = template["name"].lower()
        last_word = name.split()[-1]
        candidates = _plural_forms(name) + _plural_forms(monster_key.replace("_", " "))
        if any(re.search(r"\b" + re.escape(c) + r"\b", lowered) for c in candidates):
            return monster_key, template
        if last_words.count(last_word) > 1 or len(last_word) < 4:
            continue  # ambiguous among this location's own monsters, or too short to fuzzy-match safely
        if any(re.search(r"\b" + re.escape(c) + r"\b", lowered) for c in _plural_forms(last_word)):
            return monster_key, template
        # A real word from the player's own text within real edit
        # distance of this monster's last word also counts (tolerance
        # scales with word length -- 1 edit for a short word, 2 for a
        # longer one, so short common words can't fuzzy-collide with
        # something unrelated).
        tolerance = 2 if len(last_word) >= 6 else 1
        if any(_levenshtein(w, last_word) <= tolerance for w in words):
            return monster_key, template
    return None


def _levenshtein(a: str, b: str) -> int:
    """Standard edit distance (insert/delete/substitute), used only for the small monster-name fuzzy-match pass above -- these strings are always short."""
    if a == b:
        return 0
    prev = list(range(len(b) + 1))
    for i, ca in enumerate(a, 1):
        curr = [i] + [0] * len(b)
        for j, cb in enumerate(b, 1):
            cost = 0 if ca == cb else 1
            curr[j] = min(prev[j] + 1, curr[j - 1] + 1, prev[j - 1] + cost)
        prev = curr
    return prev[-1]


def _format_item_stats_line(item: dict) -> str | None:
    """
    Real computed stats for a magic/generated item, not just flavor
    text (2026-08-02, per Coffee, live in the Development topic: "How
    can I see the stats in the details of this? I have no idea how
    strong it is or what it does" -- there was genuinely no way to see
    a generated magic item's real affixes anywhere in the game before
    this). Built from whatever real fields are already present on the
    materialized item dict (rules/item_generator.py's rolled items and
    items.py's hand-authored ones like pandoras_answer share the exact
    same shape), so this works for either without special-casing.
    Returns None for a plain item with nothing stat-worthy to show
    (e.g. a scroll or a common potion) -- callers should just fall back
    to flavor text alone in that case.
    """
    parts = []
    rarity = item.get("rarity")
    item_type = item.get("type")
    if rarity and item_type:
        parts.append(f"{rarity.replace('_', ' ').title()} {item_type}")
    # Real live gap (2026-08-06, per Coffee: "im not seeing the attack
    # strength ... elements ... when i look at weapons") -- every real
    # weapon (hand-authored in items.py and generated by
    # rules/item_generator.py alike) carries a real damage_dice field,
    # but this function never read it at all, so a plain Longsword's
    # stats line said nothing whatsoever about how hard it actually
    # hits. damage_dice is the pure base value; damage_bonus (when
    # present) is a SEPARATE affix-derived bonus on generated items
    # only -- hand-authored weapons already bake any bonus straight
    # into damage_dice's own string (e.g. "1d6+2"), so it's shown
    # in addition to, never instead of, damage_dice.
    if item.get("damage_dice"):
        dtype = item.get("damage_type") or "physical"
        element_label = "" if dtype == "physical" else f" {dtype}"
        bonus_label = f" +{item['damage_bonus']}" if item.get("damage_bonus") else ""
        parts.append(f"{item['damage_dice']}{bonus_label}{element_label} damage")
    elif item.get("damage_bonus"):
        parts.append(f"+{item['damage_bonus']} damage")
    if item.get("ability") and item_type == "weapon":
        parts.append(f"uses {item['ability'].capitalize()}")
    if item.get("ac_base"):
        parts.append(f"AC {item['ac_base']}")
    if item.get("ac_bonus"):
        parts.append(f"+{item['ac_bonus']} AC")
    if item.get("damage_type") and item["damage_type"] != "physical" and not item.get("damage_dice"):
        parts.append(f"deals {item['damage_type']} damage")
    if item.get("resistances"):
        parts.append(f"resistance to {', '.join(item['resistances'])}")
    if item.get("vulnerabilities"):
        parts.append(f"vulnerable to {', '.join(item['vulnerabilities'])}")
    if item.get("immunities"):
        parts.append(f"immune to {', '.join(item['immunities'])}")
    if item.get("grants_spell"):
        spell_name = item["grants_spell"].replace("_", " ").title()
        parts.append(f"grants {spell_name} ({item.get('grants_spell_uses', 1)}/rest)")
    for pb in item.get("profession_bonuses") or []:
        parts.append(f"+{pb['value']} {pb['profession']}")
    if item.get("ignores_resistance"):
        parts.append("ignores enemy resistance")
    if item.get("free_extra_attack"):
        parts.append("grants an extra attack")
    if item.get("regen_bonus"):
        parts.append(f"+{item['regen_bonus']} HP regen")
    # Real weapon/armor proficiency category (2026-08-14, per Coffee:
    # "when we view an equipable item please say what the requirements
    # are to be able to equip it") -- every weapon/armor/shield already
    # has a real category (weapon_category/armor_category) that
    # db._meets_proficiency_requirement checks at equip time (blocking
    # the swap for a non-proficient class, 2026-08-13), but nothing
    # ever showed that category on the item's own view. Shown for
    # every weapon/armor/shield, not just the restrictive categories --
    # "light" armor looks universal at a glance but Monks/Sorcerers/
    # Wizards actually get NO armor proficiency at all in this build's
    # class_features.ARMOR_PROFICIENCIES, so even "light" is real,
    # class-dependent information, not a safe one to omit.
    if item_type == "weapon":
        category = item.get("weapon_category", "simple")
        parts.append(f"requires {category} weapon proficiency")
    elif item_type in ("armor", "shield"):
        category = item.get("armor_category", "shield" if item_type == "shield" else "light")
        parts.append(f"requires {category} armor proficiency")
    if item.get("rarity") in db.ATTUNEMENT_TIERS:
        parts.append(f"requires attunement (max {db.ATTUNEMENT_SLOT_CAP} at once)")
    equip_req = item.get("equip_requirement")
    if equip_req:
        # Real conditions, not the old vague placeholder (2026-08-14,
        # same request) -- "any_of" means proving progression ANY one
        # of these ways, not all at once (see db._meets_equip_
        # requirement's own docstring), so this reads as an OR list.
        req_bits = []
        for condition in equip_req.get("any_of", []):
            kind, value = condition.get("kind"), condition.get("value")
            if kind == "rebirth_count":
                req_bits.append(f"{value}+ rebirth{'s' if value != 1 else ''}")
            elif kind == "echo_trial_tier":
                req_bits.append(f"Echo Trial tier {value}+")
            elif kind == "completed_quest":
                quest = CAMPAIGN.get("quests", {}).get(value)
                req_bits.append(f"having completed \"{quest['title'] if quest else value}\"")
        if req_bits:
            parts.append(f"requires {' OR '.join(req_bits)} to equip")
    # Real worth, shown for equipables specifically (2026-08-03, per
    # Coffee: "in the description of the items can u show what it is
    # worth? do this for equipables") -- consumables/scrolls/materials
    # already show their price at the point of buying/selling them, so
    # this is scoped to the gear types where "what's this actually
    # worth" is the real open question (an equipped item's price is
    # otherwise invisible until you try to sell it).
    if item_type in ("weapon", "armor", "shield", "ring", "amulet", "wondrous") and item.get("price"):
        parts.append(f"worth {item['price']}g")
    if not parts:
        return None
    return "; ".join(parts)


def _format_item_detail_block(item: dict) -> str:
    """
    Structured, multi-line item-view breakdown (2026-08-15, per Coffee,
    with a Diablo-style item tooltip screenshot as a reference example:
    "I want this to be very clear like this example as to what is on
    the weapon"). Reads the exact same real fields
    _format_item_stats_line already does -- this is purely a visual
    reorganization of the same real data into labeled sections, same
    "make it more visually appealing" treatment the bestiary redesign
    (v1.27.220, _format_bestiary_entry) already got, never a second,
    drifting source of truth. _format_item_stats_line itself is kept
    unchanged for compact contexts (market listings, loot captions)
    where a single summary line is more appropriate than a full
    breakdown.
    """
    lines = []
    header_bits = []
    if item.get("rarity"):
        header_bits.append(item["rarity"].replace("_", " ").title())
    if item.get("type"):
        header_bits.append(item["type"].title())
    if header_bits:
        lines.append(" ".join(header_bits))

    combat_bits = []
    if item.get("damage_dice"):
        dtype = item.get("damage_type") or "physical"
        element_label = "" if dtype == "physical" else f" {dtype}"
        bonus_label = f" +{item['damage_bonus']}" if item.get("damage_bonus") else ""
        combat_bits.append(f"⚔️ {item['damage_dice']}{bonus_label}{element_label} damage")
    elif item.get("damage_bonus"):
        combat_bits.append(f"⚔️ +{item['damage_bonus']} damage")
    if item.get("ability") and item.get("type") == "weapon":
        combat_bits.append(f"🎯 Uses {item['ability'].capitalize()}")
    if item.get("ac_base"):
        combat_bits.append(f"🛡️ AC {item['ac_base']}")
    if item.get("ac_bonus"):
        combat_bits.append(f"🛡️ +{item['ac_bonus']} AC")
    if item.get("damage_type") and item["damage_type"] != "physical" and not item.get("damage_dice"):
        combat_bits.append(f"🔥 Deals {item['damage_type']} damage")
    if combat_bits:
        lines.append("\n**Base Stats**")
        lines.extend(combat_bits)

    affix_bits = []
    if item.get("resistances"):
        affix_bits.append(f"🌡️ Resistance to {', '.join(item['resistances'])}")
    if item.get("vulnerabilities"):
        affix_bits.append(f"⚠️ Vulnerable to {', '.join(item['vulnerabilities'])}")
    if item.get("immunities"):
        affix_bits.append(f"✨ Immune to {', '.join(item['immunities'])}")
    if item.get("grants_spell"):
        spell_name = item["grants_spell"].replace("_", " ").title()
        affix_bits.append(f"📜 Grants {spell_name} ({item.get('grants_spell_uses', 1)}/rest)")
    for pb in item.get("profession_bonuses") or []:
        affix_bits.append(f"🔧 +{pb['value']} {pb['profession']}")
    if item.get("ignores_resistance"):
        affix_bits.append("🗡️ Ignores enemy resistance")
    if item.get("free_extra_attack"):
        affix_bits.append("⚡ Grants an extra attack")
    if item.get("regen_bonus"):
        affix_bits.append(f"💚 +{item['regen_bonus']} HP regen")
    if affix_bits:
        lines.append("\n**Bonuses**")
        lines.extend(affix_bits)

    req_bits = []
    item_type = item.get("type")
    if item_type == "weapon":
        category = item.get("weapon_category", "simple")
        req_bits.append(f"🔒 Requires {category} weapon proficiency")
    elif item_type in ("armor", "shield"):
        category = item.get("armor_category", "shield" if item_type == "shield" else "light")
        req_bits.append(f"🔒 Requires {category} armor proficiency")
    if item.get("rarity") in db.ATTUNEMENT_TIERS:
        req_bits.append(f"🔒 Requires attunement (max {db.ATTUNEMENT_SLOT_CAP} at once)")
    equip_req = item.get("equip_requirement")
    if equip_req:
        cond_bits = []
        for condition in equip_req.get("any_of", []):
            kind, value = condition.get("kind"), condition.get("value")
            if kind == "rebirth_count":
                cond_bits.append(f"{value}+ rebirth{'s' if value != 1 else ''}")
            elif kind == "echo_trial_tier":
                cond_bits.append(f"Echo Trial tier {value}+")
            elif kind == "completed_quest":
                quest = CAMPAIGN.get("quests", {}).get(value)
                cond_bits.append(f"having completed \"{quest['title'] if quest else value}\"")
        if cond_bits:
            req_bits.append(f"🔒 Requires {' OR '.join(cond_bits)} to equip")
    if req_bits:
        lines.append("\n**Requirements**")
        lines.extend(req_bits)

    if item_type in ("weapon", "armor", "shield", "ring", "amulet", "wondrous") and item.get("price"):
        lines.append(f"\n💰 Worth {item['price']}g")

    return "\n".join(lines)


async def itemview_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """
    Handles every tap on the item-view system (2026-08-03, per Coffee:
    "put a button so we can click and view the item" / "put a button to
    sell, put market equip, or give"). "show" (the loot announcement's
    own button) is read-only -- anyone in the party can view an item's
    real stats+image regardless of who actually looted it. Every other
    action (equip/sell/market/give) operates on the TAPPING player's own
    inventory, same as the equivalent free-text command already does --
    a party member tapping "Equip" on gear they don't personally own
    just gets the same honest "you don't have that" refusal typing
    "equip X" would already give them, no special-casing needed.
    """
    query = update.callback_query
    parts = (query.data or "").split("|")
    action = parts[1] if len(parts) > 1 else ""
    item_id = parts[2] if len(parts) > 2 else ""
    await _safe_answer(query)

    character = db.get_character(update.effective_user.id, update.effective_chat.id)
    if character is None:
        return
    item = items_module.get_item(item_id)
    if item is None:
        await _safe_send(update, "That item no longer exists.")
        return

    if action == "show":
        # Structured, section-by-section breakdown (2026-08-15, per
        # Coffee, Diablo tooltip screenshot as a reference example:
        # "when we view the weapons, I want to be very clear like this
        # example as to what is on the weapon"). Telegram photo
        # captions cap at 1024 chars -- falls back to the older compact
        # single-line summary for the rare maximally-affixed item where
        # the full breakdown wouldn't fit, rather than risking a
        # rejected sendPhoto call.
        detail_block = _format_item_detail_block(item)
        caption = f"🎒 **{item['name']}**\n{detail_block}" if detail_block else f"🎒 {item['name']}"
        if len(caption) > 1024:
            stats_line = _format_item_stats_line(item)
            caption = f"🎒 {item['name']}" + (f"\n📊 {stats_line}" if stats_line else "")
        prompt = _item_image_prompt(item_id, item)
        sent = await _send_generated_image(
            update, prompt, caption, seed=_deterministic_image_seed(f"item:{item_id}"), log_key=item_id,
            reply_markup=_item_actions_keyboard(item_id),
        )
        if not sent:
            # Real live bug (2026-08-05, Coffee: "i clicked to view the
            # item and its not processing") -- a failed image generation
            # used to silently drop BOTH the picture and the stats/
            # action-buttons caption that would have gone with it,
            # leaving the player with no response at all. This is a real
            # request they just tapped a button for, so it always gets a
            # real reply now, image or not.
            await _safe_send(update, caption, reply_markup=_item_actions_keyboard(item_id))
        return

    owns_it = character.get("inventory", {}).get(item_id, 0) > 0
    if action == "equip":
        if not owns_it:
            await _safe_send(update, f"You don't have the {item['name']} to equip.")
            return
        _ok, msg, _updated = db.equip_item(update.effective_user.id, update.effective_chat.id, item_id)
        await _safe_send(update, msg)
    elif action == "reforge":
        if not owns_it:
            await _safe_send(update, f"You don't have the {item['name']} to reforge.")
            return
        await _forge_item_core(update, item_id, item, f"forge my {item['name']}")
    elif action == "sell":
        if not owns_it:
            await _safe_send(update, f"You don't have the {item['name']} to sell.")
            return
        _ok, msg = shop_module.sell_item(update.effective_user.id, update.effective_chat.id, item_id, 1)
        await _safe_send(update, msg)
    elif action == "dismantle":
        if not owns_it:
            await _safe_send(update, f"You don't have the {item['name']} to dismantle.")
            return
        if item.get("type") not in DISMANTLE_ELIGIBLE_TYPES:
            await _safe_send(update, f"The {item['name']} can't be dismantled.")
            return
        await _apply_dismantle(update, character, item_id, item)
    elif action == "market":
        if not owns_it:
            await _safe_send(update, f"You don't have the {item['name']} to list.")
            return
        price = max(int(item.get("price", 0) * 1.5), 1)
        removed, _updated = db.remove_item(update.effective_user.id, update.effective_chat.id, item_id, 1)
        if not removed:
            await _safe_send(update, "Something went wrong listing that item.")
            return
        listing_id = db.create_market_listing(update.effective_user.id, update.effective_chat.id, character["name"], item_id, 1, price)
        message = (
            f"🏷️ **{character['name']}** lists **{item['name']}** for **{price} gold** (listing #{listing_id}). "
            f"Listed by mistake? \"/cancel_market {listing_id}\" pulls it back."
        )
        stats_line = _format_item_stats_line(item)
        if stats_line:
            message += f"\n\n📊 **Stats:** {stats_line}"
        await _safe_send(update, message)
    elif action == "give":
        if not owns_it:
            await _safe_send(update, f"You don't have the {item['name']} to give.")
            return
        candidates = [
            p for p in _get_combat_eligible_party_members(character["current_location"], character["chat_id"])
            if p["telegram_user_id"] != character["telegram_user_id"]
        ]
        if not candidates:
            await _safe_send(update, "There's nobody else here to give it to.")
            return
        keyboard = InlineKeyboardMarkup([
            [InlineKeyboardButton(p["name"], callback_data=f"itemview|giveto|{item_id}|{p['telegram_user_id']}")]
            for p in candidates
        ])
        await _safe_send(update, f"Give the {item['name']} to whom?", reply_markup=keyboard)
    elif action == "giveto":
        if not owns_it:
            await _safe_send(update, f"You don't have the {item['name']} to give anymore.")
            return
        recipient_id = int(parts[3])
        removed, _updated = db.remove_item(update.effective_user.id, update.effective_chat.id, item_id, 1)
        if not removed:
            await _safe_send(update, "Something went wrong giving that item.")
            return
        db.add_item(recipient_id, update.effective_chat.id, item_id, 1)
        recipient = db.get_character(recipient_id, update.effective_chat.id)
        recipient_name = recipient["name"] if recipient else "them"
        await _safe_send(update, f"🤝 **{character['name']}** gives the {item['name']} to **{recipient_name}**.")


async def _do_examine_owned_item(update: Update, character: dict, location: dict, item_match: str | None) -> bool:
    """
    Narrates examining a real owned inventory item, given an already-
    resolved item_match id (or None). Returns True if it actually
    handled the examine (an item was found), False otherwise, so both
    of _do_examine's call sites (the explicit "in my inventory" fast
    path, and the ordinary interactable-miss fallback) share one real
    implementation instead of two copies drifting apart over time.
    """
    if not item_match:
        return False
    item_data = items_module.get_item(item_match)
    # Real live report (2026-08-12, dev-bridge screenshot, same player
    # who hit the "view" misclassification gap): "Looking at the
    # herbalism guide didn't work we need to be able to read it so we
    # can see the contents of the book the recipes" -- examining a
    # recipe book (Cook Book/Herbalism Guide/Crafting Book, 2026-08-11)
    # only ever gave generic flavor narration from the item's own
    # description field, never its real recipe contents -- those
    # already exist, real and grounded (_do_read_recipe_book, built
    # from rules.crafting.RECIPES), but were only ever reachable via
    # "use the X", not the far more natural "examine"/"view"/"look
    # at"/"read" phrasing a player actually reaches for when they want
    # to see what's written in a book they own. Routes book-type items
    # here instead of falling through to the generic description path.
    if item_data.get("type") == "book":
        await _do_read_recipe_book(update, item_data)
        return True
    # Real live crash (2026-08-02, caught via a Development-topic
    # report): a generated magic item (rules/item_generator.py, e.g.
    # "Runed Dagger of Embers") has no "description" field at all --
    # only hand-authored items.py entries ever set one. Direct indexing
    # here KeyError'd on every attempt to examine any generated item,
    # the exact case this whole system exists to make keepable. Falls
    # back to the generator's own "note" field, then a bare generic
    # line, rather than assuming either key exists.
    description = item_data.get("description") or item_data.get("note") \
        or f"a {(item_data.get('type') or 'item')}, worked with real craftsmanship."
    narration = await asyncio.to_thread(
        narrate_examine, character, location["name"], item_data["name"], description
    )
    message = f"🔍 **{character['name']}** examines their {item_data['name']}: {narration}"
    stats_line = _format_item_stats_line(item_data)
    if stats_line:
        message += f"\n\n📊 **Stats:** {stats_line}"
    await _safe_send(update, message)
    return True


async def _do_examine(update: Update, target_text: str) -> None:
    character = db.get_character(update.effective_user.id, update.effective_chat.id)
    if character is None:
        await update.effective_chat.send_message(
            "You don't have a character yet!", message_thread_id=topics.thread_id_for(update.effective_chat.id, "adventure")
        )
        return
    location = cl.get_location(CAMPAIGN, character["current_location"])
    if location is None:
        await update.effective_chat.send_message(
            f"**{character['name']}** seems to be nowhere in particular. That's... concerning.",
            message_thread_id=topics.thread_id_for(update.effective_chat.id, "adventure"),
        )
        return

    # Dev-topic feedback (Coffee, 2026-07-19): "If a player wants to look
    # at stalls and shopfronts in market row - please give a description
    # and then open the shop." A GENERIC "the stalls"/"the shopfronts"
    # phrase shouldn't be forced onto one specific named interactable
    # (market_row's own "shuttered_stall" is deliberately the one
    # abandoned, nailed-shut stall -- examining that specifically should
    # still just describe it, not open Maren's shop), so this only
    # matches the generic plural/collective wording, checked before the
    # normal interactable lookup.
    generic_shop_words = {"stall", "stalls", "shopfront", "shopfronts", "store", "stores", "shop", "shops"}
    shop_id = location.get("shop")
    if shop_id and target_text:
        lowered_target = target_text.lower()
        target_words = set(re.findall(r"[a-z]+", lowered_target))
        if target_words & generic_shop_words and "shuttered" not in lowered_target:
            await _safe_send(
                update,
                f"🔍 **{character['name']}** takes in the stalls and shopfronts lining {location['name']} "
                f"before stepping up to see what's actually for sale.",
            )
            await _do_list_shop(update)
            return

    interactables = location.get("interactables", {})
    if not target_text or not target_text.strip():
        if interactables:
            names = [i["name"] for i in interactables.values()]
            await update.effective_chat.send_message(
                f"🔍 **{character['name']}**, examine what, exactly? Things worth a closer look here: {', '.join(names)}",
                message_thread_id=topics.thread_id_for(update.effective_chat.id, "adventure"),
            )
        else:
            await update.effective_chat.send_message(
                f"🔍 **{character['name']}** finds nothing here that catches the eye for a closer look.",
                message_thread_id=topics.thread_id_for(update.effective_chat.id, "adventure"),
            )
        return

    # Real live report (2026-08-28, dev-bridge, Charvenna: "That's not
    # what I asked for") -- "Look at torn ledger pages in my inventory"
    # matched crossroads_tavern's own "the heavy ledger behind the bar"
    # interactable instead, since _find_interactable ran BEFORE the
    # inventory-item fallback below and both real names share the word
    # "ledger". Same shape as the enemy-name/weapon-name collision fixed
    # in _do_attack this same day. An explicit "in my inventory" (or
    # "in/from inventory") is an unambiguous signal of real player
    # intent -- checked first, so it can never be shadowed by a
    # same-word location interactable again.
    lowered_target_text = target_text.lower()
    if any(phrase in lowered_target_text for phrase in ("in my inventory", "in inventory", "from my inventory", "from inventory")):
        owned_item_ids = list((character.get("inventory") or {}).keys())
        item_match = items_module.find_item_mentioned_in_text(target_text, candidate_ids=owned_item_ids)
        if await _do_examine_owned_item(update, character, location, item_match):
            return
        await _safe_send(
            update, f"🔍 **{character['name']}** checks their inventory, but isn't carrying anything like that.",
        )
        return

    found = _find_interactable(location, target_text)
    if found is None:
        # Real bug, caught live 2026-07-17 (Coffee): "Look at the wolves
        # in the whispering wood - give me detail about them" got "Ravenloft
        # doesn't spot anything like that here" even though wolves are a
        # real, active threat at this exact location (location["monsters"]
        # and the "Trouble with Wolves" board quest both confirm it) --
        # examine only ever checked interactables, never real monsters
        # present. Fixed: match against location["monsters"] too, and
        # give real bestiary stats if already fought, or an honest
        # "here, but not yet known" line if not -- same fog-of-war
        # boundary the bestiary itself already keeps, never inventing
        # stats the player hasn't actually earned by fighting it.
        monster_match = _find_monster_mentioned_in_text(location, target_text, character)
        if monster_match:
            monster_key, template = monster_match
            if monster_key in (character.get("known_monsters") or []):
                bestiary_text = _format_bestiary_entry(
                    monster_key, template, character.get("rebirth_count", 0),
                    defeated=monster_key in (character.get("defeated_monsters") or []),
                )
                await _safe_send(
                    update,
                    f"🔍 **{character['name']}** studies the {template['name'].lower()} here, "
                    f"drawing on what they already know:\n{bestiary_text}",
                )
            else:
                await _safe_send(
                    update,
                    f"🔍 **{character['name']}** spots a real threat here — a {template['name'].lower()} — "
                    f"but hasn't fought one yet to know more. Check the bestiary once you have.",
                )
            return

        # Real bug, confirmed live via a Development-topic screenshot
        # (Coffee, 2026-07-30: "Look at the tattered underground chart"
        # -- an item he actually owned -- got "doesn't spot anything
        # like that here" every time): examine only ever checked
        # location interactables and monsters present, never the
        # character's own carried inventory at all, so a real item you
        # own could never be examined, regardless of phrasing. Fixed by
        # falling back to a real inventory-item match (items.py's own
        # find_item_mentioned_in_text, scoped to only what this
        # character actually carries) before giving up -- narrated the
        # same way an interactable is, using the item's own real
        # description (every item in items.py now has one).
        owned_item_ids = list((character.get("inventory") or {}).keys())
        item_match = items_module.find_item_mentioned_in_text(target_text, candidate_ids=owned_item_ids)
        if await _do_examine_owned_item(update, character, location, item_match):
            return

        # Real live feature request (2026-08-31, dev-bridge, Elduinn: "I
        # don't know if this area has a lever but if it doesn't, you
        # should tell us"). Reuses _find_lockable's own real resolution
        # (id/name match, or its kind-word fallback when exactly one
        # lockable is here) -- purely informative, never rolls or
        # triggers anything, so asking "is there a lever here?" can
        # never accidentally pull one or spend a turn. Real, honest
        # state too: already-open, key-only, or a plain pickable lock
        # each get their own real line, not a generic "there's a thing".
        lockable_match = _find_lockable(location, target_text)
        if lockable_match:
            kind = lockable_match.get("kind")
            # Real owl-statue-style hint (2026-09-03, Phase L4, item 4,
            # ported from the Labyrinth's identical mechanic) -- reveals
            # every real, honest, non-spoiler fact about this dungeon
            # at once, not the generic lockable state line below.
            if kind == "hint_statue":
                hint_text = " ".join(lockable_match.get("hint_lines", []))
                await _safe_send(update, f"🗿 **{character['name']}** studies the worn statue. {hint_text}")
                return
            is_open = _lockable_is_open(location, lockable_match["id"], update.effective_chat.id)
            if kind == "switch":
                element = lockable_match.get("element", "")
                state = f"{'glowing' if is_open else 'dark'}{f' {element}' if element else ''} — hit it, or cast the right kind of magic at it, to toggle it"
            elif kind == "pressure_plate":
                state = f"{'pressed down' if is_open else 'raised'} — push something heavy onto it, or fill it with the right liquid, to toggle it"
            elif is_open:
                state = "already open" if kind not in ("breakable_wall", "breakable_floor") else "already broken open"
            elif kind == "lever":
                state = "waiting to be pulled"
            elif kind in ("breakable_wall", "breakable_floor"):
                state = "cracked — it looks like it could be broken open, by force or the right kind of magic"
            elif lockable_match.get("requires_key_item"):
                state = "sealed shut — it won't budge without something specific, not brute force or a steady hand"
            else:
                state = "locked, but it looks pickable"
            await _safe_send(update, f"🔍 **{character['name']}** spots {lockable_match['name']} here — {state}.")
            return

        names = [i["name"] for i in interactables.values()]
        hint = f" Things worth a closer look here: {', '.join(names)}" if names else ""
        await update.effective_chat.send_message(
            f"🔍 **{character['name']}** doesn't spot anything like that here.{hint}",
            message_thread_id=topics.thread_id_for(update.effective_chat.id, "adventure"),
        )
        return

    _, obj_data = found
    narration = await asyncio.to_thread(
        narrate_examine, character, location["name"], obj_data["name"], obj_data["description"]
    )
    await _safe_send(update, f"🔍 **{character['name']}** examines {obj_data['name']}: {narration}")
    await _maybe_send_interactable_image(update, obj_data)


async def _do_show_map(update: Update) -> None:
    """
    Renders a fog-of-war map: only locations this character has actually
    visited (character['visited_locations'], persisted in the DB) are
    shown by name; connections leading to somewhere unvisited are shown
    as an unexplored direction rather than revealing the destination.

    Task #141: map_revealed_locations (a real location NAME purchased/
    found via a "map" item, see _do_use_item) is a genuinely separate,
    weaker fog-of-war layer -- rendered with its own marker and NO
    connection info at all, since connections are the actual spoiler a
    revealed-but-unvisited location must never leak. Never merged into
    visited_locations itself; a revealed location still needs to be
    physically visited to unlock its real connections here.
    """
    character = db.get_character(update.effective_user.id, update.effective_chat.id)
    if character is None:
        await update.effective_chat.send_message(
            "You don't have a character yet!", message_thread_id=topics.thread_id_for(update.effective_chat.id, "adventure")
        )
        return

    visited = set(character["visited_locations"])
    revealed = set(character["map_revealed_locations"]) - visited
    if not visited and not revealed:
        await update.effective_chat.send_message(
            "You haven't explored anywhere yet.", message_thread_id=topics.thread_id_for(update.effective_chat.id, "adventure")
        )
        return

    # Real dev-topic confusion (2026-07-22, Coffee: "?!! What is this")
    # -- the map's own notation (📍/•/→/"N unexplored path(s)") was
    # never actually explained anywhere, just used. Not a bug (the data
    # itself was always correct), but a real, fixable UX gap -- a one-
    # line legend costs nothing and removes the ambiguity outright.
    lines = [
        "🗺️ **Your map** (📍 = where you are now, • = a place you've "
        "visited, → its known connections, \"N unexplored path(s)\" = "
        "routes leading somewhere you haven't been yet)",
    ]
    for layer, layer_locations in CAMPAIGN["locations"].items():
        visited_here = [loc_id for loc_id in layer_locations if loc_id in visited]
        revealed_here = [loc_id for loc_id in layer_locations if loc_id in revealed]
        if not visited_here and not revealed_here:
            continue
        lines.append(f"\n**{layer.title()}**")
        for loc_id in visited_here:
            loc = layer_locations[loc_id]
            marker = "📍" if loc_id == character["current_location"] else "•"
            connections = loc.get("connections", [])
            known = [cl.get_location(CAMPAIGN, c)["name"] for c in connections if c in visited]
            unknown_count = sum(1 for c in connections if c not in visited)
            conn_bits = list(known)
            if unknown_count:
                conn_bits.append(f"{unknown_count} unexplored path{'s' if unknown_count != 1 else ''}")
            conn_text = f" → {', '.join(conn_bits)}" if conn_bits else ""
            lines.append(f"{marker} {loc['name']}{conn_text}")
        for loc_id in revealed_here:
            lines.append(f"❓ {layer_locations[loc_id]['name']} *(marked on a map, not yet visited)*")

    await _safe_send(update, "\n".join(lines), speak=False)


def _character_layer_content(character: dict) -> dict[str, tuple[set, set]]:
    """
    {layer_name: (visited_ids_in_layer, revealed_ids_in_layer)} for
    every layer (CAMPAIGN["locations"] key) this character has any
    real content in at all -- either actually visited, or revealed via
    a purchased/found "map" item (map_revealed_locations, see
    _do_use_item's "map" branch). A layer with neither is omitted
    entirely, same "don't show what isn't there" rule _do_show_map's
    text version already follows.
    """
    visited = set(character.get("visited_locations") or [])
    revealed = set(character.get("map_revealed_locations") or []) - visited
    result = {}
    for layer, layer_locations in CAMPAIGN["locations"].items():
        v = {loc_id for loc_id in layer_locations if loc_id in visited}
        r = {loc_id for loc_id in layer_locations if loc_id in revealed}
        if v or r:
            result[layer] = (v, r)
    return result


def _map_layer_keyboard(character: dict, current_layer: str) -> InlineKeyboardMarkup | None:
    """
    Task #11, per Coffee: "if u have above and below locations have
    button available" -- one button per OTHER layer (surface/
    underground/sky) this character has real content in, so switching
    between them is always one tap away regardless of whether the
    current location itself has a direct descends_to/ascends_to link.
    None (no keyboard at all) when this is the only layer with content.
    """
    other_layers = sorted(l for l in _character_layer_content(character) if l != current_layer)
    if not other_layers:
        return None
    buttons = [[InlineKeyboardButton(f"🗺️ {layer.title()} Map", callback_data=f"map|{layer}")] for layer in other_layers]
    return InlineKeyboardMarkup(buttons)


# Real live request (2026-08-30, Coffee: "i want each dungeon to have
# its own minimap"), display names only -- membership itself is read
# straight off each location's real `dungeon_id` field (see
# _dungeon_locations), never duplicated here as a prefix/exclude list.
_DUNGEON_DISPLAY_NAMES = {
    "wrathflame_vault": "The Wrathflame Vault",
    "deep_root_vault": "The Deep Root Vault",
    "the_first_city": "The First City",
    "unmoored_isle": "The Unmoored Isle",
    "goblin_warrens": "The Goblin Warrens",
    "sunken_root_caverns": "The Sunken Root Caverns",
    "stonearch_bridge": "Stonearch Gorge",
    "greymoor_downs": "Greymoor Downs",
}


def _dungeon_locations(dungeon_id: str) -> dict:
    """Every CAMPAIGN["locations"][layer] entry carrying this dungeon_id, merged across whichever real layer(s) it spans (Stonearch Gorge: surface + underground) -- location ids are globally unique so a plain merge is safe."""
    merged = {}
    for layer_locs in CAMPAIGN["locations"].values():
        for loc_id, loc in layer_locs.items():
            if loc.get("dungeon_id") == dungeon_id:
                merged[loc_id] = loc
    return merged


def _dungeon_map_keyboard(
    layer_name: str, dungeon_id: str | None = None, available_floors: list[int] | None = None, current_floor: int | None = None,
) -> InlineKeyboardMarkup:
    """
    One button back to the whole layer map -- reuses map_menu_callback/
    _send_layer_map exactly as the layer-switch buttons already do.

    Real floor-switcher (2026-09-02, per Coffee: "do that for the
    overworld dungeons too" -- extending the Labyrinth's own floor
    buttons to real, persistent multi-floor dungeons like Greymoor
    Downs). Only ever shown once `available_floors` (map_render.
    available_floors, real attained floor levels) has more than one
    entry -- a single-floor dungeon's keyboard is completely unaffected.
    """
    rows = []
    if dungeon_id and available_floors and len(available_floors) > 1:
        floor_label = lambda f: "Ground" if f == 0 else (f"F{f}" if f > 0 else f"B{-f}")
        rows.append([
            InlineKeyboardButton(f"{'📍 ' if f == current_floor else ''}{floor_label(f)}", callback_data=f"dungeonmap|{dungeon_id}|{f}")
            for f in available_floors
        ])
    rows.append([InlineKeyboardButton(f"🗺️ Full {layer_name.title()} Map", callback_data=f"map|{layer_name}")])
    return InlineKeyboardMarkup(rows)


async def _send_dungeon_map(update: Update, character: dict, dungeon_id: str, floor: int | None = None) -> None:
    """
    Real render (map_render.render_dungeon_map), scoped to just one
    dungeon's rooms -- see _send_layer_map for the whole-layer
    equivalent this mirrors.

    floor (2026-09-02, Phase L3 follow-up): when the dungeon has more
    than one real attained floor (map_render.available_floors), only
    that one floor is rendered at a time, with a real floor-switcher
    row -- defaults to whichever floor the character is CURRENTLY
    standing on if they're inside this dungeon, else Ground (0).
    """
    dungeon_locations = _dungeon_locations(dungeon_id)
    visited = set(character.get("visited_locations") or [])
    revealed = set(character.get("map_revealed_locations") or [])
    display_name = _DUNGEON_DISPLAY_NAMES.get(dungeon_id, dungeon_id.replace("_", " ").title())
    current_location_id = character.get("current_location")
    layer_name = next(
        (layer for layer, locs in CAMPAIGN["locations"].items() if current_location_id in locs),
        "surface",
    )
    available = map_render.available_floors(dungeon_locations, visited)
    floor_filter = None
    if len(available) > 1:
        if floor is not None and floor in available:
            floor_filter = floor
        elif current_location_id in dungeon_locations:
            floor_filter = map_render.floor_of(dungeon_locations, visited, current_location_id)
        else:
            floor_filter = 0
    try:
        png_bytes = await asyncio.to_thread(
            map_render.render_dungeon_map, dungeon_id, display_name, dungeon_locations, visited, revealed,
            current_location_id, CAMPAIGN["monsters"], CAMPAIGN["quests"], floor_filter,
        )
    except Exception as e:
        logger.warning(f"[map_render] dungeon map failed: {e!r}")
        await update.effective_chat.send_message(
            "Couldn't render the map right now.", message_thread_id=topics.thread_id_for(update.effective_chat.id, "adventure")
        )
        return
    await update.effective_chat.send_photo(
        photo=png_bytes, caption=f"🗺️ {display_name} — explored so far.",
        message_thread_id=topics.thread_id_for(update.effective_chat.id, "adventure"),
        reply_markup=_dungeon_map_keyboard(layer_name, dungeon_id, available, floor_filter),
    )


async def dungeon_map_menu_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Handles taps on _dungeon_map_keyboard's floor-switch row -- re-renders the same dungeon map at a different real, attained floor."""
    query = update.callback_query
    parts = (query.data or "").split("|")
    await _safe_answer(query)
    if len(parts) < 3:
        return
    dungeon_id = parts[1]
    try:
        floor = int(parts[2])
    except ValueError:
        return
    character = db.get_character(update.effective_user.id, update.effective_chat.id)
    if character is None:
        return
    await _send_dungeon_map(update, character, dungeon_id, floor)


async def _send_layer_map(update: Update, character: dict, layer_name: str) -> None:
    """Real render (map_render.render_layer_map), shared by the initial /visual_map send and the layer-switch button tap."""
    layer_locations = CAMPAIGN["locations"].get(layer_name, {})
    visited = set(character.get("visited_locations") or [])
    revealed = set(character.get("map_revealed_locations") or [])
    try:
        png_bytes = await asyncio.to_thread(
            map_render.render_layer_map, layer_name, layer_locations, visited, revealed, character.get("current_location"),
            CAMPAIGN["monsters"], CAMPAIGN["quests"], None, True,
        )
    except Exception as e:
        logger.warning(f"[map_render] layer map failed: {e!r}")
        await _safe_send(update, "Couldn't render the map right now.")
        return
    # Real live crash (2026-09-08, error log): a raw send_photo with no
    # RetryAfter retry -- same recurring bug class already fixed
    # reactively elsewhere (_do_show_labyrinth_map and siblings, see
    # _safe_send_photo's own docstring).
    await _safe_send_photo(
        update, png_bytes, caption="🗺️ Your explored world, so far.",
        reply_markup=_map_layer_keyboard(character, layer_name),
    )


async def _do_show_visual_map(update: Update) -> None:
    """
    Task #11, real live request (2026-08-09, Coffee via Development-
    topic screenshot): "This does not look like a map. I want an
    accurate map... use circles and names with labels" -- the previous
    version (task #221) generated atmospheric Pollinations.ai art from
    a text list of visited location names, honestly scoped at the time
    since no image model reliably renders legible labels, but never an
    accurate schematic. Now renders a real, local, deterministic map
    (map_render.render_layer_map) instead -- same fog-of-war rule
    _do_show_map's text version already enforces (only real visited/
    revealed locations, never anything undiscovered), plus a button to
    switch layers when the character has content in more than one.
    Starts on whichever layer the character is CURRENTLY standing in,
    falling back to any other layer with content if that one somehow
    has none (shouldn't happen -- being somewhere means it's visited).
    """
    character = db.get_character(update.effective_user.id, update.effective_chat.id)
    if character is None:
        await update.effective_chat.send_message(
            "You don't have a character yet!", message_thread_id=topics.thread_id_for(update.effective_chat.id, "adventure")
        )
        return
    content = _character_layer_content(character)
    if not content:
        await update.effective_chat.send_message(
            "You haven't explored anywhere yet.", message_thread_id=topics.thread_id_for(update.effective_chat.id, "adventure")
        )
        return
    current_location_id = character.get("current_location")
    current_location = cl.get_location(CAMPAIGN, current_location_id) if current_location_id else None
    if current_location and current_location.get("dungeon_id"):
        await _send_dungeon_map(update, character, current_location["dungeon_id"])
        return
    current_layer = next(
        (layer for layer, locs in CAMPAIGN["locations"].items() if current_location_id in locs and layer in content),
        next(iter(content)),
    )
    await _send_layer_map(update, character, current_layer)


def _labyrinth_map_floor_keyboard(visited_floors: list[int], current_floor: int) -> InlineKeyboardMarkup | None:
    """
    Real floor-switcher (2026-09-02, Phase L3 -- a live segment now
    genuinely holds 5 real floors at once, so "the map" is no longer
    just one flat image). Only ever offers a button for a floor this
    party has actually physically attained (run["visited_floors"]) --
    never a spoiler for a deeper, ungenerated-to-them floor in the same
    segment, matching the same fog-of-war discipline the overworld map
    already applies.
    """
    if len(visited_floors) <= 1:
        return None
    rows = [
        [InlineKeyboardButton(f"{'📍 ' if f == current_floor else ''}Floor {f}", callback_data=f"labyrinth|mapfloor|{f}")]
        for f in sorted(visited_floors)
    ]
    return InlineKeyboardMarkup(rows)


async def _do_show_labyrinth_map(update: Update, floor: int | None = None) -> None:
    """
    Phase L2h (2026-09-02) -- the /map and /visual_map intents, when a
    character's current_location is LABYRINTH_LOCATION_SENTINEL,
    dispatch here instead of _do_show_map/_do_show_visual_map: those
    both key off CAMPAIGN/character["visited_locations"], neither of
    which describes a Labyrinth run's own live, ephemeral rooms_json.
    Uses map_render.render_labyrinth_map -- a small, purpose-built
    renderer, not render_layer_map (see that function's own docstring
    for why the two engines are deliberately separate).

    `floor`: real Phase L3 fix -- a live segment holds 5 real floors at
    once, each with its own independent grid_position space (every
    floor's own hub sits at its own local (0, 0)); passing the WHOLE
    segment's `rooms` dict to the renderer in one call would overlap
    every floor's rooms on top of each other. Defaults to whichever
    floor the party is actually standing on; the floor-switcher
    keyboard lets them look at any OTHER floor they've attained without
    physically walking back to it.
    """
    character = db.get_character(update.effective_user.id, update.effective_chat.id)
    if character is None:
        await update.effective_chat.send_message(
            "You don't have a character yet!", message_thread_id=topics.thread_id_for(update.effective_chat.id, "adventure")
        )
        return
    run = db.get_labyrinth_run(update.effective_chat.id, _labyrinth_party_key(character))
    if run is None:
        await update.effective_chat.send_message(
            "You're not in the Labyrinth right now.", message_thread_id=topics.thread_id_for(update.effective_chat.id, "adventure")
        )
        return
    current_floor = run["rooms"][run["current_room_id"]].get("floor", run["floor"])
    visited_floors = run.get("visited_floors") or [current_floor]
    target_floor = floor if floor in visited_floors else current_floor
    floor_rooms = {rid: r for rid, r in run["rooms"].items() if r.get("floor") == target_floor}
    # Only the floor the party is ACTUALLY standing on gets a real
    # "you are here" marker -- viewing another attained floor's map
    # never fakes a current-location claim (no room id here will match
    # anything in floor_rooms, so render_labyrinth_map's is_current
    # check simply never fires).
    current_room_id = run["current_room_id"] if target_floor == current_floor else None
    # Real live confusion (2026-09-02, Coffee: "the map is showing a
    # north location but its not available to travel too") -- a real,
    # honestly-revealed room gated behind a still-unsolved switch
    # puzzle was drawn identically to every genuinely reachable one.
    # Any room that's the target of some OTHER room's locked_
    # connections, whose lockable isn't open yet, gets marked so the
    # renderer can show it dashed instead of solid.
    locked_room_ids = {
        dest_id
        for room in floor_rooms.values()
        for dest_id, lockable_id in room.get("locked_connections", {}).items()
        if dest_id in floor_rooms and not _lockable_is_open(room, lockable_id, update.effective_chat.id)
    }
    # Real fog-of-war (2026-09-03, per Coffee: "i want fog of war in
    # the labyrinth - specially if they get larger, we shud be
    # exploring them"). A room is only ever marked "visited" the
    # instant a real arrival happens (_do_enter_labyrinth/_do_labyrinth_
    # move/_do_descend_labyrinth) -- reused directly here rather than a
    # second, separate tracking structure.
    visited_room_ids = {rid for rid, r in floor_rooms.items() if r.get("visited")}
    # Real live request (2026-09-03, Coffee, dev-bridge screenshot:
    # circled the generic blue diamond shown for every switch -- "find
    # appropriate emojis for the elemental colors... some kind of label
    # colour or indication"). map_render.py has no chat-state access of
    # its own (by design), so the real current on/off state of every
    # switch/multi_switch_gate lockable on this floor is computed here
    # and passed in as plain data.
    switch_states = {
        lockable["id"]: _lockable_is_open(room, lockable["id"], update.effective_chat.id)
        for room in floor_rooms.values()
        for lockable in room.get("lockables", [])
        if lockable.get("kind") in ("switch", "multi_switch_gate")
    }
    # Real "honeycomb" segment strip (2026-09-03, per Coffee's own
    # earlier "5 levels of honeycombing" framing, dev-bridge: "I want
    # our dungeons and labyrinth to have maps like this"). Every floor
    # in the CURRENT segment is real and already generated up front
    # (generate_segment builds all SEGMENT_SIZE at once) -- cheap to
    # derive fresh here, no new storage needed.
    segment_number = labyrinth_module.segment_number_for_floor(target_floor)
    segment_start = labyrinth_module.segment_start_floor(segment_number)
    segment_floors = list(range(segment_start, segment_start + labyrinth_module.SEGMENT_SIZE))
    try:
        png_bytes = await asyncio.to_thread(
            map_render.render_labyrinth_map, target_floor, floor_rooms, current_room_id, locked_room_ids, visited_room_ids,
            switch_states, segment_floors,
        )
    except Exception as e:
        logger.warning(f"[map_render] labyrinth map failed: {e!r}")
        await update.effective_chat.send_message(
            "Couldn't render the map right now.", message_thread_id=topics.thread_id_for(update.effective_chat.id, "adventure")
        )
        return
    # Real live request (2026-09-03, Coffee: "if u are not going to use
    # images for it put the name of the location in there so we can
    # read it better") -- a real generated room name can be longer than
    # a grid cell's own label ever fits (_fit_label_to_width truncates
    # with "..."), so the full, untruncated name for every room the
    # fog-of-war has actually revealed is also listed in plain text.
    # Real live ask (2026-09-04, per Coffee: "can u show our current
    # seed beside the labyrinth info in quests and in achievements?
    # where else is it located so players can see it?") -- the map is
    # a natural third spot: it's real, chat-scoped, per-party context
    # every time someone actually looks, not spammed onto every plain
    # look/move message.
    caption = f"🌀 The Labyrinth — Floor {target_floor} (seed `{run['seed']}`)."
    visited_names = [
        f"{r['name']}{' (you are here)' if rid == current_room_id else ''}"
        for rid, r in floor_rooms.items() if rid in visited_room_ids or rid == current_room_id
    ]
    if visited_names:
        caption += "\n\n📍 Rooms explored so far:\n" + "\n".join(f"• {name}" for name in visited_names)
    sent = await _safe_send_photo(
        update, png_bytes, caption=caption,
        reply_markup=_labyrinth_map_floor_keyboard(visited_floors, target_floor),
    )
    if not sent:
        await _safe_send(update, "Couldn't send the map right now — Telegram's acting up. Try again in a moment.")


async def map_menu_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Handles taps on _map_layer_keyboard's layer-switch buttons."""
    query = update.callback_query
    parts = (query.data or "").split("|")
    layer_name = parts[1] if len(parts) > 1 else ""
    await _safe_answer(query)
    character = db.get_character(update.effective_user.id, update.effective_chat.id)
    if character is None or layer_name not in CAMPAIGN["locations"]:
        return
    await _send_layer_map(update, character, layer_name)


def _format_bestiary_entry(monster_key: str, template: dict, viewer_rebirth_count: int = 0, defeated: bool = False) -> str:
    """
    Real bestiary compendium entry (2026-07-16 original), redesigned
    2026-08-14 per Coffee's own back-to-back requests: (1) show a
    monster's real spells/signature mechanics too, not just its raw
    stats and boolean resistances -- reuses bot._boss_ability_facts
    directly (already the single real source of truth for known_spells
    + every Synergy Phase 9-11 mechanic flag, built for narration) rather
    than re-deriving a second, partial copy of the same facts; (2) "The
    World Evolves" (v1.27.218/219) means a monster's real toughness now
    depends on the VIEWING character's own rebirth_count, which this
    function couldn't know about before -- `viewer_rebirth_count`
    (default 0, so any caller that hasn't been updated yet degrades to
    the old always-zero behavior rather than erroring) lets the entry
    show what this monster ACTUALLY carries against THIS player right
    now, not just its frozen campaign.json baseline; (3) visually
    reorganized into real labeled sections instead of one dense
    paragraph, per "make the bestiary more visually appealing."

    `defeated` (2026-08-15, per Coffee, Encounter Ledger follow-up:
    "make the bosses the same lvl as the ledger but dont show it to the
    player until they beat the boss, then include it in bestiary") --
    a boss's real hand-authored level is a genuine spoiler (same "???"
    convention _monster_danger_line uses on arrival) until this specific
    character has actually WON against it at least once (db.
    defeated_monsters, distinct from known_monsters' looser "merely
    fought it" fact) -- default False so a caller that hasn't been
    updated degrades to hiding it, never accidentally leaking one.
    A non-boss monster's level was never a spoiler in the first place
    (danger_line already shows it on arrival), so it's shown here
    unconditionally once known.
    """
    boss_tag = " 👑" if template.get("is_boss") else ""
    lines = [f"**{template['name']}**{boss_tag}"]
    lines.append(
        f"❤️ HP {template['hp_max']}  🛡️ AC {template['armor_class']}  "
        f"💪 STR {template['strength']}  🏃 DEX {template['dexterity']}  ⭐ XP {template.get('xp_reward', 0)}"
    )
    authored_level = template.get("level")
    if authored_level is not None and (defeated or not template.get("is_boss")):
        lines.append(f"🎯 Level {authored_level}")
    if template.get("on_hit_condition"):
        lines.append(f"🩸 Inflicts **{template['on_hit_condition']}** on a hit")
    # Real spells/signature mechanics (2026-08-14) -- the exact same
    # narration-grounding fact-builder every boss intro/defeat/decision
    # line already uses, so the bestiary and the narration can never
    # drift apart into two different descriptions of the same monster.
    ability_facts = _boss_ability_facts(template)
    if ability_facts:
        lines.append(f"✨ {ability_facts}")
    # Real, learned resistance profile (2026-07-26 gap audit): only
    # shown once genuinely known, same fog-of-war boundary as every
    # other bestiary fact here -- never a spoiler for an unfought
    # monster.
    resist_bits = []
    if template.get("immunities"):
        resist_bits.append(f"immune to {', '.join(template['immunities'])}")
    if template.get("resistances"):
        resist_bits.append(f"resistant to {', '.join(template['resistances'])}")
    if template.get("vulnerabilities"):
        resist_bits.append(f"vulnerable to {', '.join(template['vulnerabilities'])}")
    if resist_bits:
        lines.append(f"🌡️ {'; '.join(resist_bits)}")
    # Elemental resistance stacking (2026-08-10) -- a creature "strong in
    # an element" enough to nullify or even heal from it is exactly the
    # kind of build-diversity fact a player needs to actually SEE.
    elemental_bits = []
    for dtype, pct in (template.get("elemental_resistance_pct") or {}).items():
        if pct >= 150:
            elemental_bits.append(f"heals from {dtype} damage")
        elif pct >= 100:
            elemental_bits.append(f"nullifies {dtype} damage")
        else:
            elemental_bits.append(f"strongly resistant to {dtype} ({pct:.0f}%)")
    if elemental_bits:
        lines.append(f"🔥❄️ {'; '.join(elemental_bits)}")
    # "The World Evolves" (2026-08-14): the SAME real per-encounter bonus
    # bot._do_start_combat stamps onto a live combat participant,
    # recomputed fresh here from the VIEWING character's current
    # rebirth_count (not a stale snapshot from whenever they last fought
    # it) -- see rules.leveling.world_resistance_pct/world_damage_
    # multiplier's own docstrings for why this is deliberately uncapped.
    world_resist = world_resistance_pct(viewer_rebirth_count)
    if world_resist > 0:
        world_dmg_pct = (world_damage_multiplier(viewer_rebirth_count) - 1) * 100
        lines.append(
            f"🌍 Also carries +{world_resist:.0f}% resistance to every damage type and hits "
            f"{world_dmg_pct:.0f}% harder against you, matching your own {viewer_rebirth_count} rebirth(s)."
        )
    # Real stealable-item listing (2026-08-11) -- same fog-of-war
    # boundary as everything else here, and the SAME real weights
    # bot._do_steal_from_enemy actually rolls against, never a separate
    # made-up hint list. Sorted so the common item(s) list before rare.
    stealable = template.get("stealable_items")
    if stealable:
        ranked = sorted(stealable, key=lambda e: -e["weight"])
        parts = []
        for entry in ranked:
            name = items_module.get_item(entry["item_id"])["name"]
            rarity_tag = "common" if entry["weight"] >= 50 else "rare"
            parts.append(f"{name} ({rarity_tag})")
        lines.append(f"🎒 Can steal: {', '.join(parts)}")
    return "\n".join(lines)


async def _do_bestiary(update: Update) -> None:
    """
    Bestiary / monster compendium (2026-07-16, per Coffee's backlog):
    fog-of-war discovery, same convention as the map above -- only
    monster types this character has actually fought (known_monsters,
    see db.mark_known_monster, set from _do_start_combat) are shown,
    with their REAL stats pulled straight from the campaign's monster
    templates, not invented flavor text.
    """
    character = db.get_character(update.effective_user.id, update.effective_chat.id)
    if character is None:
        await update.effective_chat.send_message(
            "You don't have a character yet!", message_thread_id=topics.thread_id_for(update.effective_chat.id, "adventure")
        )
        return

    known = character.get("known_monsters") or []
    if not known:
        await update.effective_chat.send_message(
            "Your bestiary is empty — fight something to start learning about it.",
            message_thread_id=topics.thread_id_for(update.effective_chat.id, "adventure"),
        )
        return

    defeated = set(character.get("defeated_monsters") or [])
    entries = []
    for monster_key in known:
        template = cl.get_monster_template(CAMPAIGN, monster_key)
        if template is None:
            continue
        entries.append(_format_bestiary_entry(
            monster_key, template, character.get("rebirth_count", 0), defeated=monster_key in defeated,
        ))

    # Visual pass (2026-08-14, per Coffee: "make the bestiary more
    # visually appealing") -- a real divider between entries instead of
    # everything running together into one wall of text, and the real
    # known-count up front instead of a bare title.
    lines = [f"📖 **Bestiary** — {len(entries)} creature{'s' if len(entries) != 1 else ''} known"]
    lines.append("\n━━━━━━━━━━━━━━━\n".join(entries))

    await _safe_send(update, "\n\n".join(lines), speak=False)


def _achievement_condition_met(character: dict, check: dict) -> bool:
    """
    Titles & Achievements (task #73): every check type here reads a
    real, already-existing field on the character dict -- no new
    counter was invented just to support this feature. See
    achievements.py's module docstring for the full list of types.
    """
    check_type = check["type"]
    if check_type == "min_level":
        return character.get("level", 1) >= check["value"]
    if check_type == "min_gold":
        return character.get("gold", 0) >= check["value"]
    if check_type == "min_known_monsters":
        return len(character.get("known_monsters") or []) >= check["value"]
    if check_type == "min_completed_quests":
        return len(character.get("completed_quests") or []) >= check["value"]
    if check_type == "min_board_quests_completed":
        return character.get("board_quests_completed", 0) >= check["value"]
    if check_type == "min_rebirth_count":
        return character.get("rebirth_count", 0) >= check["value"]
    if check_type == "has_guild":
        return bool(character.get("guild"))
    if check_type == "well_equipped":
        return bool(character.get("equipped_weapon")) and bool(
            character.get("equipped_armor") or character.get("equipped_shield")
        )
    if check_type == "master_of_any_profession":
        # Per Coffee ("continue with professions"): a real milestone
        # for reaching the top practiced_bonus rank (rules/proficiency.
        # MAX_PRACTICE_BONUS, 15 uses) in ANY of the 7 real professions
        # (ALL_PROFESSIONS) -- same skill_uses data the new "check my
        # professions" screen already reads, just the first achievement
        # tied to it.
        skill_uses = character.get("skill_uses") or {}
        return any(practiced_bonus(skill_uses.get(p, 0)) >= MAX_PRACTICE_BONUS for p in ALL_PROFESSIONS)
    if check_type == "completed_specific_quest":
        # The true ending (2026-07-25, rebirth-3 gated content): unlike
        # every other check type here, this one is tied to a single named
        # quest rather than a general milestone -- deliberate, since the
        # whole point is a distinct, unmistakable achievement for reaching
        # this one specific moment (defeating The Unbegun), not a
        # reusable threshold. Still just reads the same real
        # completed_quests field every other quest-count check already
        # uses.
        return check["quest_id"] in (character.get("completed_quests") or [])
    if check_type == "hidden_synergy":
        # Task #134: real, undocumented emergent-build achievements --
        # a genuine multi-system combo (alignment extreme + a real
        # skill-tree investment + an existing level milestone), never
        # hinted at in any visible text.
        good_evil = character.get("alignment_good_evil", 0)
        has_upgrade = bool(character.get("skill_tree_upgrades"))
        is_legendary = "legendary" in (character.get("achievements") or [])
        if check["variant"] == "elect":
            return good_evil >= 60 and has_upgrade and is_legendary
        if check["variant"] == "damned":
            return good_evil <= -60 and has_upgrade and is_legendary
        return False
    if check_type == "min_bound_remnants":
        return len(character.get("bound_remnants") or []) >= check["value"]
    if check_type == "has_secondary_guild":
        return bool(character.get("secondary_guilds"))
    if check_type == "min_labyrinth_checkpoint":
        # Phase L3 (2026-09-02): a real, permanent milestone -- reuses
        # the same load-bearing labyrinth_checkpoint_floor field
        # _do_enter_labyrinth itself reads to decide where a fresh run
        # resumes, not a separate counter invented for this achievement.
        return character.get("labyrinth_checkpoint_floor", 0) >= check["value"]
    if check_type == "reached_location":
        # Chapter 3-8 expansion follow-up (2026-08-30, per Coffee: an
        # achievement for reaching a dungeon's own real safe waypoint).
        # Reuses the same real, already-existing visited_locations
        # field every other fog-of-war/map feature already relies on --
        # no new counter invented.
        return check["location_id"] in (character.get("visited_locations") or [])
    return False


# Login streak rewards (task #78) -- days played in a row -> (gold, XP).
# Board quests already provide a real repeatable daily quest per
# location (see CLAUDE.md/campaign design), so this is deliberately
# scoped to just the streak-reward half of the original ask.
_STREAK_MILESTONES = {3: (30, 15), 7: (75, 40), 14: (150, 80), 30: (350, 200)}


async def _maybe_award_streak_bonus(update: Update, streak_days: int) -> None:
    reward = _STREAK_MILESTONES.get(streak_days)
    if reward is None:
        return
    gold, xp = reward
    telegram_user_id = update.effective_user.id
    character = db.get_character(telegram_user_id, update.effective_chat.id)
    if character is None:
        return
    db.update_character(telegram_user_id, update.effective_chat.id, gold=character["gold"] + gold)
    await _award_xp_and_announce_level_up(update, telegram_user_id, update.effective_chat.id, xp)
    await _safe_send(
        update,
        f"🔥 **{streak_days}-day login streak!** {character['name']} earns {gold} gold and {xp} XP "
        f"for playing {streak_days} days in a row.",
    )
    await _check_and_award_achievements(update, db.get_character(telegram_user_id, update.effective_chat.id))


async def _mark_location_cleared_for_party(update: Update, session: sessions.Session) -> None:
    """
    Sequential dungeon gating (2026-07-24, Coffee: "make it so we cant
    progress to certain areas ... until we complete the dungeons or
    missions in sequence"): marks wherever this fight actually happened
    as "cleared" for every real party-side combatant, the moment the
    party wins -- same real combat-victory checkpoint as
    _check_achievements_for_combat_party (called right alongside it at
    every one of this game's 5 combat-resolution sites), never on a
    loss or a fled fight. Consumed by _check_story_gate's
    requires_cleared_location check so a deeper connection stays
    blocked until whatever's in the room before it has actually been
    fought, not just walked past.
    """
    # Real "Advanced Dungeons" repeated gate, ported to evolved
    # overworld dungeons (2026-09-06, per Coffee: "keep going" --
    # a reference repeat-encounter dungeon's own real pattern, already shipped for the
    # Labyrinth in v1.27.534). No monster-respawn logic is needed here
    # at all: unlike the Labyrinth's own per-run room dict, an evolved
    # dungeon room's `monsters` list is shared, campaign-wide state
    # that's NEVER cleared on a real victory -- the exact same
    # encounter is already still there to fight again. This only ever
    # gates WHEN `mark_location_cleared` actually fires, via a real
    # per-character defeat counter (db.bump_location_defeat_count),
    # narrated once per real win short of the requirement.
    flee_line = None
    for pid in session.turn_order:
        if session.sides.get(pid) != "party":
            continue
        character = db.get_character(pid, update.effective_chat.id)
        if character is None:
            continue
        location_id = character["current_location"]
        if location_id in character["cleared_locations"]:
            continue
        location = _real_campaign_location(location_id)
        repeat_required = location.get("repeat_required") if location else None
        if repeat_required:
            count = db.bump_location_defeat_count(pid, update.effective_chat.id, location_id)
            if count < repeat_required:
                flee_line = (
                    f"💨 Wounded, it flees deeper before {character['name']} can finish it off -- "
                    f"you'll have to catch it again ({count}/{repeat_required})."
                )
                continue
        db.mark_location_cleared(pid, update.effective_chat.id, location_id)
    if flee_line:
        await _safe_send(update, flee_line)


async def _check_achievements_for_combat_party(update: Update, session: sessions.Session) -> None:
    """Re-fetches each real party-side combatant fresh from the DB (post-XP-award) and checks them."""
    for pid in session.turn_order:
        if session.sides.get(pid) != "party":
            continue
        character = db.get_character(pid, update.effective_chat.id)
        if character is not None:
            await _check_and_award_achievements(update, character)


async def _check_guild_quest_completion(update: Update, session: sessions.Session) -> None:
    """
    Guild quests (task #77): any real guild member wins their guild's
    quest for the day the moment they win ANY fight, same checkpoint as
    achievements. Announces into the guild's own real Telegram topic
    (config.GUILD_TOPIC_IDS), not Adventure -- that's the whole point of
    having a real guild-only channel. Silently no-ops for AI characters
    and anyone with no guild.
    """
    for pid in session.turn_order:
        if session.sides.get(pid) != "party":
            continue
        character = db.get_character(pid, update.effective_chat.id)
        if character is None or character.get("is_ai") or not character.get("guild"):
            continue
        quest = GUILD_QUESTS.get(character["guild"])
        if quest is None:
            continue
        claimed = db.claim_guild_quest_if_unclaimed_today(pid, update.effective_chat.id, quest["reward_gold"], quest["reward_xp"])
        if not claimed:
            continue
        topic_id = config.GUILD_TOPIC_IDS.get(character["guild"])
        if topic_id:
            await _safe_send(
                update,
                f"📜 **{quest['title']} complete!** {character['name']} earns "
                f"{quest['reward_gold']} gold and {quest['reward_xp']} XP for today.",
                thread_id=topic_id,
            )


async def _do_check_guild_quest(update: Update, guild_id: str) -> None:
    character = db.get_character(update.effective_user.id, update.effective_chat.id)
    if character is None:
        return
    quest = GUILD_QUESTS.get(guild_id)
    if quest is None:
        return
    today = datetime.now(timezone.utc).date().isoformat()
    claimed_today = character.get("last_guild_quest_date") == today
    status = "✅ already claimed today" if claimed_today else "not yet claimed today — win any fight to complete it"
    # Replies in whichever topic asked (Adventure or the guild's own
    # topic) -- only the completion announcement (_check_guild_quest_
    # completion) deliberately targets the guild topic specifically.
    await _safe_send(
        update,
        f"📜 **{quest['title']}**\n{quest['description']}\n"
        f"Reward: {quest['reward_gold']} gold, {quest['reward_xp']} XP\nStatus: {status}",
        thread_id=update.effective_message.message_thread_id, speak=False,
    )


GUILD_CURRICULUM_DICE_KEYWORDS = ["try my luck", "attempt the trial", "roll for it", "take the trial"]
GUILD_CURRICULUM_STATUS_KEYWORDS = ["my curriculum", "guild training", "next lesson", "curriculum", "training"]


def _guild_curriculum_step_index(character: dict, guild_id: str) -> int:
    """Current curriculum step for `guild_id`, whether it's the primary or a secondary ("doubled up") guild."""
    if guild_id == character.get("guild"):
        return character["guild_curriculum_step"]
    return (character.get("secondary_guild_curriculum_steps") or {}).get(guild_id, 0)


def _guild_curriculum_unlocked_at(character: dict, guild_id: str) -> str | None:
    if guild_id == character.get("guild"):
        return character.get("guild_curriculum_step_unlocked_at")
    return (character.get("secondary_guild_curriculum_unlocked_at") or {}).get(guild_id)


def _guild_curriculum_waiting_reminder_shown(character: dict, guild_id: str) -> bool:
    """Whether _check_guild_curriculum_progress already told this character its CURRENT step is satisfied but still on cooldown."""
    if guild_id == character.get("guild"):
        return bool((character.get("guild_curriculum_state") or {}).get("waiting_reminder_shown"))
    return bool((character.get("secondary_guild_curriculum_state") or {}).get(guild_id, {}).get("waiting_reminder_shown"))


def _mark_guild_curriculum_waiting_reminder_shown(telegram_user_id: int, chat_id: int, character: dict, guild_id: str) -> None:
    """
    Real live bug (2026-08-14, dev-bridge: "You don't have to keep
    telling the user this you only have to mention it once"): a
    satisfied-but-still-cooling-down step's real objective (reach a
    location, gather a material, ...) can naturally keep re-firing
    during ordinary play -- farming iron ore for "First Ore" gathers it
    over and over, and _check_guild_curriculum_progress used to repeat
    the SAME "won't credit for Xh Ym" reminder every single time. Stamps
    a one-time flag into the same real guild_curriculum_state/secondary_
    guild_curriculum_state scratch dict already reserved for per-step
    state (cleared automatically once the step actually advances --
    _compute_guild_curriculum_advance resets it to {} -- so the
    reminder naturally re-arms fresh for the NEXT step).
    """
    if guild_id == character.get("guild"):
        db.update_character(
            telegram_user_id, chat_id,
            guild_curriculum_state={**(character.get("guild_curriculum_state") or {}), "waiting_reminder_shown": True},
        )
        return
    all_secondary_state = dict(character.get("secondary_guild_curriculum_state") or {})
    all_secondary_state[guild_id] = {**all_secondary_state.get(guild_id, {}), "waiting_reminder_shown": True}
    db.update_character(telegram_user_id, chat_id, secondary_guild_curriculum_state=all_secondary_state)


def _guild_curriculum_step_ready(character: dict, guild_id: str | None = None) -> bool:
    """
    True once GUILD_CURRICULUM_STEP_COOLDOWN_HOURS have really passed
    since the character's CURRENT step unlocked -- the real "must grind
    it out" pacing gate (per Coffee), enforced on CREDITING a step, not
    on attempting it (a member can work toward it immediately, they just
    can't be recognized for it until real time has actually passed).
    `guild_id` defaults to the primary guild, matching every pre-existing
    call site's behavior exactly; pass a secondary ("doubled up") guild's
    id to check that guild's own step instead.
    """
    unlocked_at = _guild_curriculum_unlocked_at(character, guild_id or character.get("guild"))
    if not unlocked_at:
        return True
    elapsed = datetime.now(timezone.utc) - datetime.fromisoformat(unlocked_at)
    return elapsed >= timedelta(hours=guild_curriculum_module.GUILD_CURRICULUM_STEP_COOLDOWN_HOURS)


def _guild_curriculum_time_remaining_note(character: dict, guild_id: str | None = None) -> str:
    unlocked_at = _guild_curriculum_unlocked_at(character, guild_id or character.get("guild"))
    if not unlocked_at:
        return "a while"
    elapsed = datetime.now(timezone.utc) - datetime.fromisoformat(unlocked_at)
    remaining = timedelta(hours=guild_curriculum_module.GUILD_CURRICULUM_STEP_COOLDOWN_HOURS) - elapsed
    if remaining <= timedelta(0):
        return "a moment"
    hours = int(remaining.total_seconds() // 3600)
    minutes = max(int((remaining.total_seconds() % 3600) // 60), 1)
    return f"{hours}h {minutes}m" if hours else f"{minutes}m"


async def _check_guild_curriculum_cooldowns(bot) -> None:
    """
    Periodic sweep (same architecture as _check_pending_loot_votes/
    _check_combat_timeouts, run from the same background loop) for a
    real reported gap (2026-08-14, dev-bridge screenshot): "The guilds
    havent updated anything new for us. I thought we were supposed to
    have something new after six hours.?!" Root cause: crediting a
    guild curriculum step only ever happens at the exact moment its
    trigger event fires (arrival, a successful gather, a kill, ...) --
    if the character satisfied the objective before
    GUILD_CURRICULUM_STEP_COOLDOWN_HOURS had elapsed since the step
    unlocked, _check_guild_curriculum_progress just tells them to wait
    and returns, with nothing ever re-checking once the cooldown
    actually clears. A player standing right at the required location
    (or still holding the required material) the whole time reasonably
    expects the guild to recognize that automatically once "six hours"
    is up, not require them to walk away and back (or re-gather) to
    re-fire the same event.

    Only reach_location and gather_material are handled here -- these
    are the two trigger types that are a pure PRESENT STATE (standing
    somewhere / holding an item count) rather than a one-off event, so
    they're the only ones honestly re-checkable without the character
    doing anything new. defeat_monster/npc_dialogue/solve_puzzle/
    dice_challenge/alignment_choice remain action-triggered, unchanged
    -- a player naturally re-triggers those by acting again (dice/
    puzzle/choice are typed directly in the guild's own topic anyway).
    """
    for chat_id in db.get_all_chat_ids():
        # get_all_characters_in_chat, NOT _get_party_members -- see that
        # function's own docstring (2026-08-14): _get_party_members only
        # ever returns whichever ONE character slot each player currently
        # has active, so a multi-character player's other real characters
        # (each with their own real, standing curriculum progress) were
        # completely invisible to this sweep until switched back to.
        for character in db.get_all_characters_in_chat(chat_id):
            for guild_id in held_guild_ids(character):
                step_index = _guild_curriculum_step_index(character, guild_id)
                step = guild_curriculum_module.get_step(guild_id, step_index)
                if step is None or character["level"] < step["min_level"]:
                    continue
                trigger = step["trigger"]
                if trigger["type"] not in ("reach_location", "gather_material"):
                    continue
                if not _guild_curriculum_step_ready(character, guild_id):
                    continue
                if trigger["type"] == "reach_location":
                    # Real live bug (2026-08-14, dev-bridge: "I have already
                    # done this training for some reason it's not showing me
                    # a new one" -- follow-up to the exact report that led to
                    # this whole sweep existing): checking ONLY current_
                    # location meant a member who visited the required spot
                    # DURING the cooldown window (a totally reasonable thing
                    # to do -- nothing stops working toward a step early) but
                    # then moved on with their day never got auto-credited,
                    # since by the time the cooldown cleared they were
                    # somewhere else and this sweep would just skip them
                    # forever. visited_locations is this character's real,
                    # permanent visit history (bot._do_move already appends
                    # to it on arrival) -- "you were there at some point
                    # since it unlocked" is what a player actually means by
                    # "I already did this," not "you are standing there at
                    # this exact tick."
                    matched = trigger["location"] in character["visited_locations"]
                else:
                    matched = character["inventory"].get(trigger["material"], 0) >= trigger.get("count", 1)
                if not matched:
                    continue
                update_like = _AiPlayerUpdate(bot, chat_id, character["telegram_user_id"], "")
                # character_id=character["character_id"] is required here, NOT
                # optional -- this character may not be the one its owner
                # currently has active (that's the whole point of this sweep
                # now using get_all_characters_in_chat), so crediting through
                # the plain telegram_user_id/chat_id path would silently land
                # on whichever OTHER character that same player has active.
                await _complete_guild_curriculum_step(
                    update_like, character["telegram_user_id"], chat_id, step, guild_id=guild_id,
                    character_id=character["character_id"],
                )


# A real riddle answer is almost always said plainly, optionally behind
# one of these short lead-ins -- stripped before the exact-match check in
# _guild_curriculum_riddle_answer_matches below.
_RIDDLE_ANSWER_PREFIXES = (
    "i think it's ", "i think its ", "i think it is ", "the answer is ",
    "answer is ", "it's ", "its ", "is it ", "maybe it's ", "maybe its ",
    "could it be ", "i believe it's ", "i believe its ",
)


def _guild_curriculum_riddle_answer_matches(text: str, accepted_answers: list[str]) -> bool:
    """
    Real live bug (2026-08-12, caught by topic-activity monitoring, TWICE
    in the same day -- see both the original fix and this hardening
    pass): a guild topic ALSO carries ordinary member chat -- unlike
    campaign.json's own puzzle system (bot._do_answer_puzzle), which only
    ever runs against text the AI/keyword layer already classified as an
    "answer_puzzle" attempt, this riddle check runs against EVERY message
    sent in the guild's topic while a solve_puzzle step is current.

    First real repro: a plain substring check let "Does anyone have a
    map of the outer ward we could look at later?" instantly finish "The
    First Riddle". Fixed with a 6-word cap -- but that cap alone still let
    a second real case through: "What are the next steps here?" is
    exactly 6 words and still contains "steps" (one of the Thieves'
    Guild riddle's accepted answers) as a whole word, so it would STILL
    have falsely completed that riddle. A word-count cap can never fully
    rule out an ordinary short sentence that happens to contain a short,
    common answer word like "steps" or "map".

    Real fix: require the message, once a short natural lead-in
    ("I think it's ", "the answer is ", ...) is stripped, to EXACTLY
    equal one of the accepted answers (punctuation-insensitive) -- this
    is genuinely how a player states a riddle answer in chat ("map",
    "a map", "I think it's fire"), and an unrelated sentence built around
    the word essentially never happens to equal the bare answer exactly.
    """
    normalized = re.sub(r"[^\w\s']", "", text.lower()).strip()
    normalized = re.sub(r"\s+", " ", normalized)
    for prefix in _RIDDLE_ANSWER_PREFIXES:
        if normalized.startswith(prefix):
            normalized = normalized[len(prefix):].strip()
            break
    accepted_normalized = {re.sub(r"[^\w\s']", "", a.lower()).strip() for a in accepted_answers}
    return normalized in accepted_normalized


def _format_guild_curriculum_step_objective(step: dict) -> str:
    """
    Real live report (2026-08-12, dev-bridge screenshot + "How do we
    complete the quests?"): reach_location/defeat_monster/gather_material
    objectives told a member WHAT to do but never WHERE to do it, unlike
    solve_puzzle/npc_dialogue/dice_challenge/alignment_choice, which all
    explicitly say "in the Adventure topic" or "right here" -- a real,
    confirmed gap (this exact player's own guild topic screenshot showed
    "Travel to Market Row." with no such hint) since these steps are
    posted in the GUILD topic but must actually be acted on in Adventure,
    same as any other move/gather/combat action.
    """
    trigger = step["trigger"]
    ttype = trigger["type"]
    if ttype == "reach_location":
        location = cl.get_location(CAMPAIGN, trigger["location"])
        return f"Travel to {location['name'] if location else trigger['location']}, in the Adventure topic."
    if ttype == "defeat_monster":
        template = cl.get_monster_template(CAMPAIGN, trigger["monster"])
        name = template["name"] if template else trigger["monster"]
        return f"Defeat {trigger.get('count', 1)}x {name}, in the Adventure topic."
    if ttype == "gather_material":
        item = items_module.get_item(trigger["material"])
        name = item["name"] if item else trigger["material"]
        return f"Gather {trigger.get('count', 1)}x {name}, in the Adventure topic."
    if ttype == "solve_puzzle":
        return "Answer the riddle above, right here in this topic."
    if ttype == "npc_dialogue":
        npc = CAMPAIGN["npcs"].get(trigger["npc"])
        name = npc["name"] if npc else trigger["npc"]
        return f"Speak with {name} about it, in the Adventure topic."
    if ttype == "dice_challenge":
        threshold = trigger.get("threshold", guild_curriculum_module.DICE_CHALLENGE_DEFAULT_THRESHOLD)
        return f"Say \"try my luck\" here when you're ready to roll (need {threshold}+ on 2d6)."
    if ttype == "alignment_choice":
        return "A real decision awaits — say \"my curriculum\" here to see it."
    return ""


def _format_guild_curriculum_step_announcement(step: dict) -> str:
    """
    Real bug caught proactively (direct reproduction, not a live
    report): this used to skip the 🎯 objective line entirely for an
    alignment_choice step, on the reasoning that its real setup/choices
    shouldn't be spoiled in the auto-posted announcement -- but
    _format_guild_curriculum_step_objective already has its own SAFE,
    separate hint text for that exact case ("A real decision awaits —
    say \"my curriculum\"...") that reveals nothing. Skipping the whole
    line meant the announcement posted+pinned for every alignment_choice
    step (one per guild, 7 total) gave a member NO indication at all
    that anything was expected of them next -- confirmed via direct
    reproduction: the real output was just the title and flavor text,
    with no call to action anywhere in it.
    """
    lines = [f"📖 **Guild Training: {step['title']}**", step["flavor"]]
    lines.append(f"🎯 {_format_guild_curriculum_step_objective(step)}")
    reward_parts = []
    if step.get("reward_xp"):
        reward_parts.append(f"{step['reward_xp']} XP")
    if step.get("reward_gold"):
        reward_parts.append(f"{step['reward_gold']} gold")
    if reward_parts:
        lines.append(f"💰 Reward: {', '.join(reward_parts)}.")
    return "\n".join(lines)


def _guild_curriculum_choice_keyboard(guild_id: str, step_index: int, step: dict) -> InlineKeyboardMarkup:
    buttons = [
        [InlineKeyboardButton(choice["label"], callback_data=f"gcurr|{guild_id}|{step_index}|{choice_id}")]
        for choice_id, choice in step["trigger"]["choices"].items()
    ]
    return InlineKeyboardMarkup(buttons)


async def _post_and_pin_guild_curriculum_step(
    update: Update, chat_id: int, guild_id: str, text: str, step: dict | None = None,
) -> None:
    """
    Posts the next unlocked step into the guild's own real Telegram
    topic and pins it (per Coffee: "daily pinned per-guild quest
    chains... posted to each guild's own Telegram topic"), unpinning
    whichever step this same mechanism pinned last (tracked via
    db.get_setting/set_setting, same pattern scripts/announce_deploy.py's
    pin_update already uses for its own single global pin) -- scoped per
    (chat_id, guild_id) since curriculum steps are per-character and a
    guild can have many members each at a different step; the pin
    surfaces whichever member's step was most recently unlocked, keeping
    "the next thing to do" visible without pretending one pin can
    represent every member's own progress at once.

    Real live request (2026-08-20, Coffee, dev-bridge screenshots): the
    same image treatment story-arc openings and (now) individual quest
    offers get (_maybe_send_arc_opening_image/_quest_offer_image_prompt)
    extended to guild curriculum steps too. Sent as its own flavor
    message ahead of the pinned announcement text -- never routed
    through the pin/unpin bookkeeping itself, so a failed/slow image
    generation can never affect whether the real announcement gets
    posted and pinned.
    """
    if step is not None:
        prompt = (
            f"{step['title']}, {step['flavor']}, fantasy RPG guild training illustration, "
            f"atmospheric establishing shot, digital painting, dramatic lighting, no text or labels"
        )
        topic_id_for_image = config.GUILD_TOPIC_IDS.get(guild_id)
        image_thread_id = topic_id_for_image if topic_id_for_image is not None else update.effective_message.message_thread_id
        await _send_generated_image(
            update, prompt, f"🎓 {step['title']}",
            seed=_deterministic_image_seed(f"curriculum:{guild_id}:{step['id']}"), log_key=step["id"],
            thread_id=image_thread_id,
        )
    topic_id = config.GUILD_TOPIC_IDS.get(guild_id)
    reply_thread_id = topic_id if topic_id is not None else update.effective_message.message_thread_id
    clean_text = _truncate_for_telegram_limit(text)
    clean_text, entities = _build_message_entities(clean_text, db.list_all_active_real_players(chat_id))
    try:
        sent = await update.effective_chat.send_message(clean_text, message_thread_id=reply_thread_id, entities=entities or None)
    except Exception:
        logger.warning("[guild_curriculum] failed to post next step for guild %s", guild_id, exc_info=True)
        return
    if topic_id is None:
        return
    pin_key = f"guild_curriculum_pin_{chat_id}_{guild_id}"
    old_message_id = db.get_setting(pin_key)
    if old_message_id:
        try:
            await update.effective_chat.unpin_message(message_id=int(old_message_id))
        except Exception:
            pass
    try:
        await sent.pin(disable_notification=True)
        db.set_setting(pin_key, str(sent.message_id))
    except Exception:
        pass


async def _complete_guild_curriculum_step(
    update_like, telegram_user_id: int, chat_id: int, step: dict, extra_note: str = "", guild_id: str | None = None,
    character_id: int | None = None,
) -> None:
    """
    Grants one guild curriculum step's real reward (XP/gold, and an
    optional profession-mastery bump tying it back into the real
    grindable mastery system, [[project_crafting_mastery_v1_27_144]]),
    advances the character's step counter, and posts+pins the next step
    (or a completion banner if the curriculum's exhausted) into the
    guild's own topic. `step` may be a step dict as authored, OR (for an
    alignment_choice) the step merged with the CHOSEN branch's own
    reward fields overriding the top-level ones, since a branching
    step's real reward depends on which option was picked.
    `guild_id` defaults to the primary guild (every pre-existing call
    site's exact prior behavior); pass a secondary ("doubled up") guild
    id to credit that guild's own curriculum instead.

    `character_id`, when given, targets that EXACT character row
    directly instead of "whichever slot telegram_user_id has active
    right now" -- real live bug (2026-08-14, dev-bridge screenshots:
    Coffee proved a step was satisfied and its cooldown long cleared,
    yet never credited): bot._check_guild_curriculum_cooldowns sweeps
    EVERY character in a chat now (db.get_all_characters_in_chat), not
    just each player's currently-active slot, specifically so a
    satisfied-but-dormant alt still gets credited in the background --
    but crediting it through the plain telegram_user_id/chat_id path
    would silently write the reward onto whichever OTHER character that
    same player currently has active instead (same class of bug already
    fixed once for shrine revival, see db.update_character_by_id's own
    docstring). Every pre-existing call site omits this and keeps its
    exact prior active-character-only behavior.
    """
    character = db.get_character_by_id(character_id) if character_id is not None else db.get_character(telegram_user_id, chat_id)
    if character is None:
        return
    guild_id = guild_id or character["guild"]
    reward_xp = step.get("reward_xp", 0)
    reward_gold = step.get("reward_gold", 0)
    if reward_xp:
        if character_id is not None:
            await _award_xp_and_announce_level_up_by_id(update_like, character_id, chat_id, reward_xp)
        else:
            await _award_xp_and_announce_level_up(update_like, telegram_user_id, chat_id, reward_xp)
    if reward_gold:
        fresh = db.get_character_by_id(character_id) if character_id is not None else db.get_character(telegram_user_id, chat_id)
        if character_id is not None:
            db.update_character_by_id(character_id, gold=fresh["gold"] + reward_gold)
        else:
            db.update_character(telegram_user_id, chat_id, gold=fresh["gold"] + reward_gold)
    mastery_profession = step.get("reward_mastery_profession")
    mastery_pct = step.get("reward_mastery_pct")
    if mastery_profession and mastery_pct:
        fresh = db.get_character_by_id(character_id) if character_id is not None else db.get_character(telegram_user_id, chat_id)
        current = fresh["profession_mastery_pct"].get(mastery_profession, PROFICIENCY_STARTING_PCT)
        updated_pct = {**fresh["profession_mastery_pct"], mastery_profession: min(current + mastery_pct, PROFICIENCY_MAX_PCT)}
        if character_id is not None:
            db.update_character_by_id(character_id, profession_mastery_pct=updated_pct)
        else:
            db.update_character(telegram_user_id, chat_id, profession_mastery_pct=updated_pct)

    if character_id is not None:
        updated_character = db.advance_guild_curriculum_step_by_id(character_id, guild_id)
    else:
        updated_character = db.advance_guild_curriculum_step(telegram_user_id, chat_id, guild_id)
    topic_id = config.GUILD_TOPIC_IDS.get(guild_id)
    reply_thread_id = topic_id if topic_id is not None else update_like.effective_message.message_thread_id

    reward_parts = []
    if reward_xp:
        reward_parts.append(f"{reward_xp} XP")
    if reward_gold:
        reward_parts.append(f"{reward_gold} gold")
    reward_text = ", ".join(reward_parts) or "real progress"
    await _safe_send(
        update_like, f"✅ **{updated_character['name']}** completes \"{step['title']}\" — {reward_text}.{extra_note}",
        thread_id=reply_thread_id,
    )

    next_step = guild_curriculum_module.get_step(guild_id, _guild_curriculum_step_index(updated_character, guild_id))
    if next_step is None:
        await _safe_send(
            update_like,
            f"🏅 **{updated_character['name']}** has completed {GUILDS[guild_id]['name']}'s full training curriculum!",
            thread_id=reply_thread_id,
        )
        return
    announcement = _format_guild_curriculum_step_announcement(next_step)
    await _post_and_pin_guild_curriculum_step(update_like, chat_id, guild_id, announcement, step=next_step)


async def _check_guild_curriculum_progress(update_like, telegram_user_id: int, chat_id: int, event_type: str, **event_data) -> None:
    """
    Shared checkpoint for reach_location/defeat_monster/gather_material/
    npc_dialogue curriculum steps -- called from the SAME real event
    checkpoints campaign quests and board quests already use (arrival,
    combat victory, a successful gather, a successful NPC conversation),
    never a new polling loop. solve_puzzle and dice_challenge are
    resolved directly in guild_topic_handler instead (they're genuinely
    driven by what's typed IN the guild's own topic, not an Adventure-
    side action); alignment_choice is resolved via guild_curriculum_callback.

    Checks EVERY guild currently held (2026-08-13: primary AND any
    "doubled up" secondary guilds, see guilds.held_guild_ids) rather
    than just the primary -- an evolved character training toward a
    second guild's own curriculum needs the exact same real-event
    checkpoints to be able to progress it at all.
    """
    character = db.get_character(telegram_user_id, chat_id)
    if character is None:
        return
    for guild_id in held_guild_ids(character):
        step_index = _guild_curriculum_step_index(character, guild_id)
        step = guild_curriculum_module.get_step(guild_id, step_index)
        if step is None or character["level"] < step["min_level"]:
            continue
        trigger = step["trigger"]
        if trigger["type"] != event_type:
            continue

        matched = False
        if event_type == "reach_location":
            matched = trigger["location"] == event_data.get("location_id")
        elif event_type == "defeat_monster":
            matched = trigger["monster"] in event_data.get("monster_keys", set())
        elif event_type == "gather_material":
            matched = (
                trigger["material"] == event_data.get("material_id")
                and character["inventory"].get(trigger["material"], 0) >= trigger.get("count", 1)
            )
        elif event_type == "npc_dialogue":
            text_lower = (event_data.get("text") or "").lower()
            matched = trigger["npc"] == event_data.get("npc_id") and any(kw in text_lower for kw in trigger.get("keywords", []))
        if not matched:
            continue

        if not _guild_curriculum_step_ready(character, guild_id):
            if not _guild_curriculum_waiting_reminder_shown(character, guild_id):
                remaining = _guild_curriculum_time_remaining_note(character, guild_id)
                await _safe_send(
                    update_like,
                    f"📖 That satisfies **{step['title']}** — but the guild won't credit it for another {remaining}. "
                    f"Real training takes real time.",
                )
                _mark_guild_curriculum_waiting_reminder_shown(telegram_user_id, chat_id, character, guild_id)
            return
        await _complete_guild_curriculum_step(update_like, telegram_user_id, chat_id, step, guild_id=guild_id)
        return


async def _do_guild_curriculum_dice_challenge(update: Update, step: dict, guild_id: str | None = None) -> None:
    """`guild_id` defaults to the primary guild; pass a secondary ("doubled up") guild id to credit that one instead."""
    character = db.get_character(update.effective_user.id, update.effective_chat.id)
    dice_roll = roll(2, 6)
    total = sum(dice_roll)
    threshold = step["trigger"].get("threshold", guild_curriculum_module.DICE_CHALLENGE_DEFAULT_THRESHOLD)
    won = total >= threshold
    roll_line = f"🎲 **{character['name']}** rolls {dice_roll[0]} + {dice_roll[1]} = **{total}** (needed {threshold}+)"
    if not won:
        await _safe_send(update, f"{roll_line}. No credit this time — try again whenever you're ready.")
        return
    if not _guild_curriculum_step_ready(character, guild_id):
        remaining = _guild_curriculum_time_remaining_note(character, guild_id)
        await _safe_send(update, f"{roll_line} — a real win! But the guild won't credit it for another {remaining}.")
        return
    await _safe_send(update, f"{roll_line} — a real win!")
    await _complete_guild_curriculum_step(update, update.effective_user.id, update.effective_chat.id, step, guild_id=guild_id)


async def _do_check_guild_curriculum(update: Update, guild_id: str) -> None:
    """`guild_id` is the guild whose topic this was asked in -- may be the primary or a secondary ("doubled up") guild."""
    character = db.get_character(update.effective_user.id, update.effective_chat.id)
    reply_thread_id = update.effective_message.message_thread_id
    if character is None or guild_id not in held_guild_ids(character):
        return
    step_index = _guild_curriculum_step_index(character, guild_id)
    step = guild_curriculum_module.get_step(guild_id, step_index)
    if step is None:
        await update.effective_chat.send_message(
            f"🏅 You've completed {GUILDS[guild_id]['name']}'s full training curriculum. Nothing left to teach you here.",
            message_thread_id=reply_thread_id,
        )
        return
    if character["level"] < step["min_level"]:
        await update.effective_chat.send_message(
            f"📖 **{step['title']}** is next, but you need to be level {step['min_level']} first.",
            message_thread_id=reply_thread_id,
        )
        return
    if step["trigger"]["type"] == "alignment_choice":
        keyboard = _guild_curriculum_choice_keyboard(guild_id, step_index, step)
        await _safe_send(
            update, f"📖 **{step['title']}**\n{step['flavor']}\n\n{step['trigger']['setup']}",
            reply_markup=keyboard, thread_id=reply_thread_id,
        )
        return
    text = _format_guild_curriculum_step_announcement(step)
    if not _guild_curriculum_step_ready(character, guild_id):
        remaining = _guild_curriculum_time_remaining_note(character, guild_id)
        text += f"\n⏳ Not creditable for another {remaining}, even once done."
    await _safe_send(update, text, thread_id=reply_thread_id)


async def guild_curriculum_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """
    Resolves an alignment_choice curriculum step's 2-button decision
    (per Coffee: real consequences, but "dont tell them what the quest
    allignment is tho" -- the buttons only ever show the two labeled
    options themselves, never which alignment axis or direction either
    one nudges).
    """
    query = update.callback_query
    parts = (query.data or "").split("|")
    guild_id = parts[1] if len(parts) > 1 else ""
    step_index = int(parts[2]) if len(parts) > 2 and parts[2].isdigit() else -1
    choice_id = parts[3] if len(parts) > 3 else ""
    await _safe_answer(query)

    character = db.get_character(update.effective_user.id, update.effective_chat.id)
    if (
        character is None
        or guild_id not in held_guild_ids(character)
        or _guild_curriculum_step_index(character, guild_id) != step_index
    ):
        await _safe_send(update, "That decision isn't yours to make anymore.")
        return
    step = guild_curriculum_module.get_step(guild_id, step_index)
    if step is None or step["trigger"]["type"] != "alignment_choice":
        return
    choice = step["trigger"]["choices"].get(choice_id)
    if choice is None:
        return
    if not _guild_curriculum_step_ready(character, guild_id):
        remaining = _guild_curriculum_time_remaining_note(character, guild_id)
        await _safe_send(update, f"Not yet — the guild won't recognize this decision for another {remaining}.")
        return

    db.update_character(
        update.effective_user.id, update.effective_chat.id,
        alignment_law_chaos=max(-100, min(100, character["alignment_law_chaos"] + choice.get("alignment_law_chaos_delta", 0))),
        alignment_good_evil=max(-100, min(100, character["alignment_good_evil"] + choice.get("alignment_good_evil_delta", 0))),
    )
    resolved_step = {
        **step, "reward_xp": choice.get("reward_xp", 0), "reward_gold": choice.get("reward_gold", 0),
        "reward_mastery_profession": choice.get("reward_mastery_profession"), "reward_mastery_pct": choice.get("reward_mastery_pct"),
    }
    await _complete_guild_curriculum_step(
        update, update.effective_user.id, update.effective_chat.id, resolved_step,
        extra_note=f"\n{choice['outcome']}", guild_id=guild_id,
    )


async def _maybe_resolve_guild_curriculum_from_text(update: Update, character: dict, text: str) -> bool:
    """
    Real live report (2026-08-29, dev-bridge, Charvenna: "Why isn't
    this working?" after saying "Try my luck" four separate times over
    ~90 minutes, each one silently classified as 'chat'). Root cause:
    a guild curriculum dice-trial/riddle step's own "try my luck"/
    riddle-answer handling only ever existed in guild_topic_handler
    below -- reachable ONLY when the message is sent in that guild's
    OWN dedicated topic. But the quest card announcing the step (e.g.
    "Reading the Odds ... say 'try my luck' here when you're ready to
    roll") is shown and answered right in Adventure, with no hint a
    different topic is required -- so the exact phrase the game itself
    told her to type just fell through to ordinary intent
    classification and read as small talk, forever.
    Checked from adventure_master_handler, before ordinary intent
    classification, for every guild the character actually holds (not
    just their primary) -- same logic as guild_topic_handler's own
    riddle/dice-trial block, just reachable from wherever the player
    actually replies. Returns True (message handled) only when a real
    current curriculum step's own trigger actually matches; otherwise
    False, so ordinary classification proceeds untouched.
    """
    lowered = text.lower()
    for guild_id in held_guild_ids(character):
        current_step = guild_curriculum_module.get_step(guild_id, _guild_curriculum_step_index(character, guild_id))
        if current_step is None or character["level"] < current_step["min_level"]:
            continue
        trigger = current_step["trigger"]
        if trigger["type"] == "solve_puzzle" and _guild_curriculum_riddle_answer_matches(text, trigger["accepted_answers"]):
            if _guild_curriculum_step_ready(character, guild_id):
                await _complete_guild_curriculum_step(update, update.effective_user.id, update.effective_chat.id, current_step, guild_id=guild_id)
            else:
                remaining = _guild_curriculum_time_remaining_note(character, guild_id)
                await _safe_send(update, f"That's the right answer — but the guild won't credit it for another {remaining}.")
            return True
        if trigger["type"] == "dice_challenge" and any(w in lowered for w in GUILD_CURRICULUM_DICE_KEYWORDS):
            await _do_guild_curriculum_dice_challenge(update, current_step, guild_id)
            return True
    return False


async def guild_topic_handler(update: Update, context: ContextTypes.DEFAULT_TYPE, guild_id: str) -> None:
    """
    Task #77's real guild-only channel: this topic exists in the group
    like any other, but the bot only ever engages with someone whose
    real character['guild'] matches -- a non-member typing here gets a
    clear, honest redirect instead of the bot pretending the topic is
    open to everyone. Ordinary chat between real members needs no
    processing at all (Telegram already delivers it); "check guild
    quest" and the real guild curriculum (2026-08-12, "my curriculum" /
    riddle answers / "try my luck") are the real commands surfaced here.
    """
    character = db.get_character(update.effective_user.id, update.effective_chat.id)
    guild = GUILDS.get(guild_id)
    if character is None or guild_id not in held_guild_ids(character):
        await update.effective_chat.send_message(
            f"This topic is for real {guild['name']} members only — join in Adventure first "
            f"(\"join {guild['name']}\") if you're eligible.",
            message_thread_id=update.effective_message.message_thread_id,
        )
        return

    lowered = update.message.text.lower()
    if any(w in lowered for w in ["guild quest", "check quest", "today's quest", "todays quest"]):
        await _do_check_guild_quest(update, guild_id)
        return
    if any(w in lowered for w in GUILD_CURRICULUM_STATUS_KEYWORDS):
        await _do_check_guild_curriculum(update, guild_id)
        return
    # Riddle answers and "try my luck" only ever apply to the character's
    # CURRENT curriculum step, checked here (not as a generic keyword
    # dispatch below) so a riddle's own free-text answer never has to
    # collide with anything else this topic already listens for.
    # _guild_curriculum_step_index (not the bare character["guild_
    # curriculum_step"] field) so this also works for a SECONDARY
    # ("doubled up") guild's own curriculum, not just the primary.
    current_step = guild_curriculum_module.get_step(guild_id, _guild_curriculum_step_index(character, guild_id))
    if current_step is not None and character["level"] >= current_step["min_level"]:
        trigger = current_step["trigger"]
        if trigger["type"] == "solve_puzzle" and _guild_curriculum_riddle_answer_matches(update.message.text, trigger["accepted_answers"]):
            if _guild_curriculum_step_ready(character, guild_id):
                await _complete_guild_curriculum_step(update, update.effective_user.id, update.effective_chat.id, current_step, guild_id=guild_id)
            else:
                remaining = _guild_curriculum_time_remaining_note(character, guild_id)
                await _safe_send(update, f"That's the right answer — but the guild won't credit it for another {remaining}.")
            return
        if trigger["type"] == "dice_challenge" and any(w in lowered for w in GUILD_CURRICULUM_DICE_KEYWORDS):
            await _do_guild_curriculum_dice_challenge(update, current_step, guild_id)
            return
    if guild_id == "arcane_circle" and any(w in lowered for w in ["learn", "secret", "teach"]):
        await _do_learn_guild_spell(update, update.message.text)
        return
    if guild_id == "enchanters_guild" and any(w in lowered for w in ["enchant", "imbue", "embue", "ladder", "tiers"]):
        await _safe_send(
            update,
            "The Guild doesn't commission enchantments for you anymore — it teaches you to do the work "
            "yourself. Bring a real magic item and materials, then say what you want enchanted "
            "(e.g. \"enchant my ring with a greater flame ward\"). The ladder climbs with your own "
            "guild standing and rebirths: Journeyman wards are open to any member; Master, "
            "Grandmaster, and the true Godsforged work demand rebirth #1, #2, and #3 respectively — "
            "the last needs a Godshard, found only in a boss's remains.",
            thread_id=update.effective_message.message_thread_id,
        )
        return
    if guild_id == "adventurers_guild" and any(
        w in lowered for w in ["job board", "job", "work", "what's next", "whats next", "where should i go", "any leads"]
    ):
        await _do_check_job_board(update)


async def _do_check_job_board(update: Update) -> None:
    """
    Adventurers' Guild job board (2026-08-11, per Coffee: give the
    guild a real reason to exist -- this answers "what should I do
    next?" with REAL, already-posted board quests, never an invented
    destination. Scoped to character["visited_locations"] on purpose --
    same fog-of-war boundary examine/the map already respect -- so this
    never spoils a location the player hasn't found on their own yet.
    """
    character = db.get_character(update.effective_user.id, update.effective_chat.id)
    reply_thread_id = update.effective_message.message_thread_id
    leads = []
    for location_id in character["visited_locations"]:
        location = cl.get_location(CAMPAIGN, location_id)
        if location is None:
            continue
        for quest in board_quests_module.get_or_generate_all_board_quests(CAMPAIGN, location_id, update.effective_chat.id):
            if quest.get("completed_at") or quest.get("accepted_by"):
                continue
            leads.append(f"📍 **{location['name']}** — {quest['title']}: {quest['description']}")
    if not leads:
        await update.effective_chat.send_message(
            "No fresh work posted anywhere you've already been — explore a bit further, or check back "
            "after finishing what's out there now.",
            message_thread_id=reply_thread_id,
        )
        return
    await update.effective_chat.send_message(
        "📋 **Real work posted right now:**\n" + "\n".join(leads[:5]),
        message_thread_id=reply_thread_id,
    )


async def _do_learn_guild_spell(update: Update, text: str) -> None:
    """
    Per Coffee (2026-07-25): "let them learn new spells not otherwise
    available unless in the guilds" -- the Arcane Circle's own
    exclusive spells (guilds.ARCANE_CIRCLE_EXCLUSIVE_SPELLS,
    spells.py's SPELLS), gated on real Circle membership and never
    reachable through the normal per-level auto-unlock every other
    spell in this game uses (spells_module.spells_unlocked_at_level).
    Still respects the same real character-level gate every other
    spell already does (max_spell_level_for_character_level), so a
    fresh level-3 joiner can't walk out with the level-5 capstone.
    """
    # This is only ever reached from guild_topic_handler, so replies stay
    # in whichever real topic the request came from (the Arcane Circle's
    # own topic) rather than defaulting to Adventure.
    reply_thread_id = update.effective_message.message_thread_id
    character = db.get_character(update.effective_user.id, update.effective_chat.id)
    if character is None:
        await update.effective_chat.send_message(
            "You don't have a character yet!", message_thread_id=reply_thread_id
        )
        return
    if "arcane_circle" not in held_guild_ids(character):
        await update.effective_chat.send_message(
            "Only Arcane Circle members can learn the Circle's secret spells — join first.",
            message_thread_id=reply_thread_id,
        )
        return
    known = character.get("known_spells", [])
    candidates = [sid for sid in ARCANE_CIRCLE_EXCLUSIVE_SPELLS if sid not in known]
    if not candidates:
        await update.effective_chat.send_message(
            "You already know every secret the Circle has to teach.",
            message_thread_id=reply_thread_id,
        )
        return
    lowered = text.lower()
    spell_id = next(
        (sid for sid in candidates if spells_module.get_spell(sid)["name"].lower() in lowered), None
    )
    if spell_id is None:
        if len(candidates) == 1:
            spell_id = candidates[0]
        else:
            names = ", ".join(spells_module.get_spell(sid)["name"] for sid in candidates)
            await update.effective_chat.send_message(
                f"Which secret do you want to learn? {names}",
                message_thread_id=reply_thread_id,
            )
            return
    spell = spells_module.get_spell(spell_id)
    max_level = spells_module.max_spell_level_for_character_level(character["level"])
    if spell["level"] > max_level:
        await update.effective_chat.send_message(
            f"**{spell['name']}** is a level {spell['level']} secret — you're not experienced enough "
            f"yet (character level {character['level']}).",
            message_thread_id=reply_thread_id,
        )
        return
    db.learn_spell(update.effective_user.id, update.effective_chat.id, spell_id)
    await _safe_send(
        update,
        f"📖 **{character['name']}** learns the Circle's secret: **{spell['name']}** "
        f"({spell['damage_dice']} {spell['damage_type']} damage).",
        thread_id=reply_thread_id,
    )



async def _check_and_award_achievements(update: Update, character: dict | None) -> None:
    """
    Called at natural real-progress checkpoints (combat victory, quest
    turn-in, level-up, guild join, equip) -- never on a timer or a
    generic per-message hook, so it only ever fires right when a real
    condition could have just become true. Silently no-ops for AI
    characters (companions/autonomous party) -- achievements are a
    real-player feature. character may be None (a caller re-fetching
    after a mutation found nothing) -- also a silent no-op.
    """
    if character is None or character.get("is_ai"):
        return
    already = set(character.get("achievements") or [])
    for achievement_id, data in achievements_module.ACHIEVEMENTS.items():
        if achievement_id in already:
            continue
        if _achievement_condition_met(character, data["check"]):
            db.unlock_achievement(character["telegram_user_id"], update.effective_chat.id, achievement_id)
            await _safe_send(
                update,
                f"🏅 **{character['name']}** earns achievement: **{data['name']}**\n{data['description']}\n"
                f"Title earned: \"{data['title']}\" — say \"set my title to {data['title']}\" to wear it.",
            )


def _labyrinth_progress_line(character: dict) -> str | None:
    """Real Labyrinth progress for the achievements screen (2026-09-02, per Coffee: "under achievements you can list there progress in the labarythn"), grounded only in the two permanent, already-existing fields -- best floor ever reached (bragging rights, can exceed the checkpoint) and the last checkpoint actually cleared (the real, load-bearing resume point)."""
    best = character.get("labyrinth_best_floor", 0)
    checkpoint = character.get("labyrinth_checkpoint_floor", 0)
    if not best:
        return None
    line = f"🌀 **Labyrinth:** deepest floor reached {best} · last waystation cleared: floor {checkpoint or 'none yet'}"
    # Real live ask (2026-09-04, per Coffee: "can u show our current
    # seed beside the labyrinth info in quests and in achievements?")
    # -- the seed only means anything while a real run is actually
    # live (labyrinth_runs is deleted on leave, see db.py's own
    # comment on that table), so this is silent otherwise rather than
    # showing a stale/misleading number.
    if character.get("current_location") == LABYRINTH_LOCATION_SENTINEL:
        run = db.get_labyrinth_run(character["chat_id"], _labyrinth_party_key(character))
        if run is not None:
            line += f" · current seed: `{run['seed']}`"
    return line


async def _do_check_achievements(update: Update) -> None:
    character = db.get_character(update.effective_user.id, update.effective_chat.id)
    if character is None:
        await _safe_send(update, "You don't have a character yet!", speak=False)
        return
    unlocked = character.get("achievements") or []
    labyrinth_line = _labyrinth_progress_line(character)
    if not unlocked:
        base = (
            "No achievements unlocked yet. Say \"check achievements\" any time to see your progress "
            "as you play — nothing's spoiled here, they unlock naturally as you go."
        )
        await _safe_send(update, f"{base}\n\n{labyrinth_line}" if labyrinth_line else base, speak=False)
        return
    lines = ["🏅 **Your achievements:**"]
    for achievement_id in unlocked:
        data = achievements_module.get_achievement(achievement_id)
        if data is None:
            continue
        marker = " *(active title)*" if character.get("active_title") == data["title"] else ""
        lines.append(f"• **{data['name']}** — \"{data['title']}\"{marker}")
    if labyrinth_line:
        lines.append(f"\n{labyrinth_line}")
    if character.get("active_title"):
        lines.append(f"\nCurrent title: \"{character['active_title']}\"")
    else:
        lines.append("\nNo title set — say \"set my title to <title>\" to wear one you've earned.")
    await _safe_send(update, "\n".join(lines), reply_markup=_title_keyboard(character, unlocked), speak=False)


def _title_keyboard(character: dict, unlocked: list[str]) -> InlineKeyboardMarkup | None:
    """
    Real dev-topic feedback (2026-07-22, Sugar: "I earned the title and
    want to set my title") -- setting a title required typing its exact
    text verbatim with no way to just pick from what's actually earned.
    One tappable button per real unlocked achievement's title, same
    "reuse the real handler, never a separate path" convention as every
    other push-button menu this session.
    """
    buttons = []
    for achievement_id in unlocked:
        data = achievements_module.get_achievement(achievement_id)
        if data is None or data["title"] == character.get("active_title"):
            continue
        buttons.append([InlineKeyboardButton(f"🏅 {data['title']}", callback_data=f"title|set|{achievement_id}")])
    return InlineKeyboardMarkup(buttons) if buttons else None


async def title_menu_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Handles taps on _title_keyboard -- dispatches through the same real _do_set_title free text already uses."""
    query = update.callback_query
    parts = (query.data or "").split("|")
    action = parts[1] if len(parts) > 1 else ""
    await _safe_answer(query)
    if action != "set" or len(parts) < 3:
        return
    data = achievements_module.get_achievement(parts[2])
    if data is None:
        return
    await _do_set_title(update, data["title"])


_INLINE_TITLE_RE = re.compile(r"title\s+to\s+(.+)|title[^:]*:\s*(.+)", re.IGNORECASE)


def _extract_inline_title(text: str) -> str | None:
    """
    Handles "set my title to the Battle-Tested" and "title: the Wealthy".
    "clear"/"remove my title" phrasing is recognized directly so it
    reaches _do_set_title's real clear branch rather than being
    misread as a title with no content.
    """
    lowered = text.lower()
    if any(w in lowered for w in ["clear my title", "remove my title", "no title"]):
        return "clear"
    match = _INLINE_TITLE_RE.search(text)
    if match:
        candidate = (match.group(1) or match.group(2) or "").strip()
        return candidate or None
    return None


async def _do_set_title(update: Update, title_text: str) -> None:
    user_id = update.effective_user.id
    character = db.get_character(user_id, update.effective_chat.id)
    if character is None:
        await _safe_send(update, "You don't have a character yet!")
        return

    clean = title_text.strip().strip("\"")
    if not clean or clean.lower() in ("clear", "none", "remove"):
        db.set_active_title(user_id, update.effective_chat.id, None)
        await _safe_send(update, "Title cleared.")
        return

    unlocked = character.get("achievements") or []
    earned_titles = {
        achievements_module.get_achievement(a)["title"].lower()
        for a in unlocked
        if achievements_module.get_achievement(a)
    }
    if clean.lower() not in earned_titles:
        await _safe_send(
            update,
            f"You haven't earned the title \"{clean}\" yet. Say \"check achievements\" to see "
            "which titles you've unlocked.",
        )
        return

    # Store the title with its real canonical casing, not whatever
    # casing the player happened to type.
    canonical = next(
        achievements_module.get_achievement(a)["title"]
        for a in unlocked
        if achievements_module.get_achievement(a) and achievements_module.get_achievement(a)["title"].lower() == clean.lower()
    )
    db.set_active_title(user_id, update.effective_chat.id, canonical)
    await _safe_send(update, f"✅ Title set: \"{canonical}\"")


async def _do_leaderboard(update: Update) -> None:
    """
    Hall of Fame (2026-07-17, per Coffee, task #74): real XP ranking
    across every player's currently-active character -- see
    db.get_leaderboard's own docstring for why is_autonomous (the
    AI-played party) counts the same as anyone else, but is_ai=1
    (combat-only companions) doesn't.
    """
    ranked = db.get_leaderboard(update.effective_chat.id, limit=10)
    if not ranked:
        await update.effective_chat.send_message(
            "Nobody's made it onto the board yet.", message_thread_id=topics.thread_id_for(update.effective_chat.id, "adventure")
        )
        return

    medals = {0: "🥇", 1: "🥈", 2: "🥉"}
    lines = ["🏆 **Hall of Fame**"]
    for i, character in enumerate(ranked):
        rank_marker = medals.get(i, f"{i + 1}.")
        title_suffix = f" \"{character['active_title']}\"" if character.get("active_title") else ""
        lines.append(
            f"{rank_marker} **{character['name']}**{title_suffix} — Level {character['level']} "
            f"{character['race']} {character['char_class']} ({character['xp']} XP)"
        )

    await _safe_send(update, "\n".join(lines), speak=False)


def _move_party_stragglers_along(mover_telegram_user_id: int, party_id: int, chat_id: int, destination_id: str) -> None:
    """
    Shared by _do_move (on-foot) and _do_fast_travel (waypoint warp): who
    else gets physically relocated along with whoever just moved. Used to
    be two independently-hand-written copies of this same block -- real
    bug found live 2026-08-01 ("It's not letting me send to wren, who is
    in my party") was exactly that divergence, on-foot travel already
    dragging AI companions along while fast-travel silently didn't yet.
    Extracted here (2026-08-18) after a SECOND real divergence bug of the
    same shape (see the downed-real-player case below) so there's only
    ever one place this logic can drift out of sync again.

    Two real cases:
    - An AI companion (is_ai, not dead) always travels with whoever
      recruited them -- their own location is flavor/wandering, never a
      deliberate choice to be left behind.
    - A real human party member who is unconscious-but-not-dead (0 HP,
      is_dead still 0) literally cannot move themselves, so the party
      carries them along too -- otherwise they're stranded exactly where
      they fell, unreachable by any location-gated heal/revive mechanic
      (real dev-bridge report, 2026-08-18: Ravenloft left behind at the
      old fight's location while the rest of the party walked to the
      shrine, so neither the shrine's revive (is_dead-gated, correctly
      not applicable) nor its bless-the-present-party fallback
      (location-gated) had anything to work with).
    A genuinely DEAD member is the one case that stays put on purpose --
    same as a dead real player, their body has to be recovered, not
    carried -- matching the documented death rule (bot.py's "3rd failed
    death save" handling).

    Real live bug (2026-08-19, Coffee: "im saying join the battle and
    it says there is no battle" -- confirmed live via the actual
    sessions_snapshot.json + DB: Sarah and Bram Ashfield, both AI
    companions, were genuinely mid-combat against Kess at
    greymoor_downs at that exact moment -- but their DB current_location
    had ALREADY been dragged to greymoor_downs_lonely_cairn by this
    exact function, because Ravenloft (same party, not himself in that
    fight) had walked there unrelated to the battle. An AI companion
    can't actually BE in two places at once -- physically fighting
    Kess per the live session, yet "standing" somewhere else per the
    DB -- and _do_join_battle's own location match (bot.py) reads
    exactly that now-wrong DB column, not the real combat snapshot, so
    Ravenloft's own "join the battle" correctly (if confusingly) found
    a location mismatch caused by this bug, not his own actual
    position. An AI companion already mid-fight is exactly as frozen
    in place as a dead one until it resolves -- same real principle,
    now checked the same way.
    """
    for member in db.get_party_members_by_id(party_id):
        if member["telegram_user_id"] == mover_telegram_user_id or member.get("is_dead"):
            continue
        if member.get("is_ai"):
            if _in_active_combat(member["telegram_user_id"], chat_id):
                continue
            db.move_character(member["telegram_user_id"], chat_id, destination_id)
        elif (
            member.get("hp_current", 1) <= 0
            and member["character_id"] == db.get_active_character_id(member["telegram_user_id"], chat_id)
        ):
            db.move_character(member["telegram_user_id"], chat_id, destination_id)


def _find_location_by_name_fragment(fragment: str) -> str | None:
    lowered = fragment.strip().lower()
    for loc_id in cl.get_all_location_ids(CAMPAIGN):
        loc = cl.get_location(CAMPAIGN, loc_id)
        if lowered in loc_id.lower() or lowered in loc["name"].lower():
            return loc_id
    return None


def _reveal_dungeon_teaser(telegram_user_id: int, chat_id: int, teaser_location_ids: list[str]) -> None:
    """
    Writes a dungeon's own designated gated-room ids into the real
    character-scoped map_revealed_locations field, the same field the
    random layer-wide "map" item type already writes (_do_use_item) --
    only targeted at exactly this dungeon's own teaser rooms instead of
    a random pick across a whole layer. Idempotent: never re-adds ids
    the character has already visited or already had revealed.
    """
    character = db.get_character(telegram_user_id, chat_id)
    if character is None:
        return
    revealed = set(character.get("map_revealed_locations") or [])
    visited = set(character.get("visited_locations") or [])
    new_ids = [loc_id for loc_id in teaser_location_ids if loc_id not in revealed and loc_id not in visited]
    if not new_ids:
        return
    db.update_character(telegram_user_id, chat_id, map_revealed_locations=sorted(revealed | set(new_ids)))


async def _do_move(update: Update, text: str) -> None:
    character = db.get_character(update.effective_user.id, update.effective_chat.id)
    if character is None:
        await _safe_send(update, "You don't have a character yet!")
        return

    current = cl.get_location(CAMPAIGN, character["current_location"])
    # Real carry-and-collapse-style structural puzzle, ported to the
    # overworld generator (2026-09-04, per Coffee: "the warp and other
    # things was a misclassification -- they are supposed to be in the
    # generator, not in the final chapter also the final chapter does
    # use them, i want them in the generator too"). A
    # `collapsing_connections` entry is the INVERSE of locked_
    # connections -- it starts OPEN (a plain connections entry) and
    # becomes BLOCKED once its own trigger (a real multi_switch_gate)
    # is solved -- mirrors _do_labyrinth_move's own identical handling
    # line for line, since the underlying data shape is identical.
    collapsed_ids = {
        dest_id for dest_id, trigger_id in current.get("collapsing_connections", {}).items()
        if _lockable_is_open(current, trigger_id, update.effective_chat.id)
    }
    reachable = [loc_id for loc_id in current.get("connections", []) if loc_id not in collapsed_ids]
    if "descends_to" in current:
        reachable.append(current["descends_to"])
    if "ascends_to" in current:
        reachable.append(current["ascends_to"])
    # Locked-door destinations (see locked_connections) are real,
    # nameable travel targets too — just blocked until picked. Without
    # this they're silently invisible to move, indistinguishable from a
    # location with no connection at all.
    reachable.extend(
        loc_id for loc_id in current.get("locked_connections", {}) if loc_id not in reachable
    )
    # Real warp shortcut, same port as the collapse puzzle just above --
    # a genuine second exit list, never pretending to be an ordinary
    # lateral connection (see rules/labyrinth.py's own generate_floor
    # docstring for why it's stored separately from `connections`).
    reachable.extend(w for w in current.get("warps", []) if w not in reachable)

    destination_id = None
    lowered = text.lower()

    # Real classic-action-adventure-style visible pit mechanic (2026-09-01, per Coffee: a
    # character can jump down a gap to the floor below, but it must be
    # STATED whether they can see what's below or not). Deliberately
    # v1-scoped to VISIBLE pits only -- the room's own description
    # already tells the player honestly a real gap is here (same
    # "state it if it's visible" rule the switches/breakables use), so
    # "jump down"/"jump into the gap" needs no roll, no destination
    # name, no damage -- just a direct one-way move via the location's
    # own `pit_down_to` field. A genuinely HIDDEN pit (the player falls
    # through one they didn't know was there) is explicitly out of
    # scope for this pass -- it would need a real perception/search
    # system this game doesn't have yet.
    if re.search(r"\bjump\b.*\b(?:down|through|into)\b.*\b(?:gap|hole|pit|opening|chasm)\b|\bjump down\b", lowered) and current.get("pit_down_to"):
        destination_id = current["pit_down_to"]

    # Compass navigation (world-expansion pass, 2026-07-19): "directions"
    # is an optional per-location dict (compass word -> location id) that
    # sits alongside "connections" -- checked first since it's unambiguous
    # by construction (one destination per word), before the name-matching
    # below that's still how a player naming a destination directly (or any
    # pre-expansion location with no directions at all) always worked.
    direction_words = current.get("directions", {})
    if direction_words and destination_id is None:
        words_in_text = set(re.findall(r"[a-z]+", lowered))
        for word, loc_id in direction_words.items():
            if word in words_in_text and loc_id in reachable:
                destination_id = loc_id
                break

    for loc_id in reachable:
        if destination_id is not None:
            break
        loc = cl.get_location(CAMPAIGN, loc_id)
        if loc_id.replace("_", " ") in lowered or loc["name"].lower() in lowered:
            destination_id = loc_id
            break

    if destination_id is None:
        # Word-level fallback for multi-word location names -- confirmed
        # live 2026-07-12: "Go to the cellar" never matched "The Tavern
        # Cellar" at all, since neither the full name nor the location
        # id appears verbatim in that phrasing (same root cause/fix
        # shape as the earlier NPC full-name-only matching bug). Only
        # accepts a single word when it's unique among the destinations
        # actually reachable right now -- e.g. "cellar" uniquely picks
        # "The Tavern Cellar" even though "tavern" alone would be
        # ambiguous between it and "The Tavern's Upper Rooms", so an
        # ambiguous shared word is deliberately left unmatched rather
        # than guessed.
        stopwords = {"the", "a", "of", "in", "at", "on"}
        word_sets = {}
        for loc_id in reachable:
            name = cl.get_location(CAMPAIGN, loc_id)["name"]
            words = {w.strip("'s").lower() for w in name.replace("'", " ").split()}
            word_sets[loc_id] = {w for w in words if w and w not in stopwords and len(w) >= 3}
        for loc_id, words in word_sets.items():
            for word in words:
                unique = all(word not in other for other_id, other in word_sets.items() if other_id != loc_id)
                if unique and word in lowered:
                    destination_id = loc_id
                    break
            if destination_id:
                break

    # Generic "leave"/"go back"/"exit" phrasing names no specific
    # destination at all -- confirmed live 2026-07-12: a real player
    # saying "Leave the tavern cellar and go back upstairs" named
    # neither "crossroads tavern" nor "The Crossroads Tavern" (the only
    # real connection out of the cellar), so the name-matching loop
    # above never found it, leaving them stuck. Six real locations in
    # this campaign (tavern_cellar, tavern_upstairs, the_arcane_nook,
    # hollow_stump_shrine, goblin_warrens, the_first_city) are exactly
    # this kind of dead end with a SINGLE connection back out -- when
    # that's true, "leave"/"go back"/"exit"/"upstairs"/"outside" is
    # unambiguous regardless of exact wording, so resolve it directly
    # rather than requiring the destination's literal name. Left
    # multi-exit locations alone since guessing which way "leave" means
    # there would be wrong as often as right.
    generic_leave_words = ["leave", "exit", "go back", "head back", "back upstairs",
                            "back outside", "back out", "step out", "walk out", "get out",
                            "upstairs", "downstairs", "outside"]
    if destination_id is None and len(reachable) == 1 and any(w in lowered for w in generic_leave_words):
        destination_id = reachable[0]

    if destination_id is None:
        # A location is never its own connection, so "go to X" while
        # already AT X always fell through to the generic can't-get-
        # there message below — confirmed live 2026-07-11 as the actual
        # cause of an AI party member repeatedly spamming that message
        # in Adventure (it kept trying to "head to" its own current
        # location). Worth its own clearer reply for human players too.
        if character["current_location"].replace("_", " ") in lowered or current["name"].lower() in lowered:
            await _safe_send(update, f"You're already at {current['name']}.")
            return
        reachable_names = ", ".join(cl.get_location(CAMPAIGN, r)["name"] for r in reachable)
        await _safe_send(
            update,
            f"**{character['name']}** can't get there directly from {current['name']}. "
            f"From here you can reach: {reachable_names}",
        )
        return

    destination = cl.get_location(CAMPAIGN, destination_id)
    # Real live feature (2026-09-04, per Coffee: "if there are battles,
    # you can gate it so we cant go certain directions until enemies
    # are beaten... add these things to the generators"). Scoped
    # narrowly to a real generated dungeon room (`dungeon_interior`,
    # the same marker every dungeon_evolve.add_room call already
    # stamps) -- an ordinary town/wilderness location with wandering
    # monsters is completely unaffected, this never becomes a
    # game-wide combat-avoidance change. Only a real, deliberately-
    # flagged encounter gates movement -- see _is_gated_combat_room's
    # own docstring for why this is never "any room with monsters."
    # Only NEW ground is blocked; retreating anywhere already visited
    # always stays open, so a fled or lost fight can never turn this
    # into a permanent trap -- same exact rule and reasoning as
    # _do_labyrinth_move's own identical gate.
    #
    # Real live bug found while building Phase B (2026-09-04): unlike
    # the Labyrinth's own per-run room dict, an overworld location's
    # `monsters` list is SHARED campaign-wide state that nothing ever
    # clears on victory (a real player can still re-fight the same
    # ambient goblin later, and other players' own progress shouldn't
    # vanish that goblin out from under them) -- so gating purely on
    # `_is_gated_combat_room(current)` would never lift once triggered,
    # a genuine permanent softlock at any real boss/miniboss/gated-
    # encounter room in a generated dungeon. `_mark_location_cleared_
    # for_party` already records a real, PER-PLAYER "cleared" flag on
    # every party-side combatant at the exact moment they win (db.
    # mark_location_cleared, called from every combat-resolution site)
    # -- checking it here is the correct, already-existing mechanism,
    # not a new one: this player's own win lifts the gate for them
    # without touching the shared monster list other players still see.
    if (
        current.get("dungeon_interior") and _is_gated_combat_room(current)
        and destination_id not in (character.get("visited_locations") or [])
        and character["current_location"] not in (character.get("cleared_locations") or [])
    ):
        await _safe_send(update, "Enemies bar the other paths — deal with them first, or retreat the way you came.")
        return
    if destination.get("requires_item") and destination["requires_item"] not in character["inventory"]:
        await _safe_send(update, f"Something stops **{character['name']}** from going any further — missing something needed first.")
        return

    if not _meets_location_level(character, destination):
        await _send_level_gate_message(update, destination)
        return

    if not _meets_rebirth_requirement(character, destination):
        await _send_rebirth_gate_message(update, destination)
        return

    locked_connections = current.get("locked_connections", {})
    lockable_id = locked_connections.get(destination_id)
    if lockable_id:
        block_message = _lockable_block_message(current, destination["name"], lockable_id, update.effective_chat.id)
        if block_message:
            await _safe_send(update, block_message)
            return

    story_gate_message = _check_story_gate(character, current, destination_id)
    if story_gate_message:
        await _safe_send(update, story_gate_message)
        return

    destination_already_visited = destination_id in (character.get("visited_locations") or [])
    db.move_character(update.effective_user.id, update.effective_chat.id, destination_id)
    db.mark_visited(update.effective_user.id, update.effective_chat.id, destination_id)

    # Real live request (2026-08-30, dev-bridge, Coffee: "when they
    # reach those 'safe place' type locations can u give them an
    # achievement... use this only in dungeons"). Checked here, right
    # after the real visited_locations write, using the same generic
    # "reached_location" check type / _check_and_award_achievements
    # every other achievement already goes through -- re-fetches fresh
    # so the just-arrived destination is actually reflected.
    if not destination_already_visited and destination.get("dungeon_checkpoint"):
        await _check_and_award_achievements(update, db.get_character(update.effective_user.id, update.effective_chat.id))

    # Dungeon redesign, "visual tease" beat (2026-08-30, per Coffee's own
    # reference material: "place rewards or major doors... in the hub
    # room so players can see them long before they can reach them").
    # Deterministic and dungeon-scoped -- unlike the random layer-wide
    # map-item reveal (_do_use_item's "map" branch), this targets exactly
    # the 1-2 room ids a dungeon's own hub wants shown, once, the first
    # time a character actually stands in that hub.
    if not destination_already_visited and destination.get("dungeon_hub") and destination.get("dungeon_teaser_locations"):
        _reveal_dungeon_teaser(update.effective_user.id, update.effective_chat.id, destination["dungeon_teaser_locations"])

    # Real bug found live (2026-07-17, Coffee): recruited companions
    # (is_ai=1, is_autonomous=0) are supposed to be traveling WITH
    # whoever recruited them, but this only ever moved the acting
    # player -- companions just stood still forever. Only moves real
    # companions sharing this player's party_id. See
    # _move_party_stragglers_along's own docstring for the full,
    # current set of who's dragged along and why (also covers the
    # 2026-07-24 is_autonomous flag bug and the 2026-08-18
    # downed-real-player fix).
    if character.get("party_id"):
        _move_party_stragglers_along(
            update.effective_user.id, character["party_id"], update.effective_chat.id, destination_id,
        )

    # Per Coffee (2026-07-14): TTS coverage audit -- _do_move's primary
    # reply never went through _safe_send, so this (one of the most
    # common actions in the game) always silently skipped TTS.
    # Darkness (2026-08-04): arriving somewhere too dark to see, without
    # a real light source, shows neither the description nor the
    # location image -- same rule _do_look already applies, just also
    # covering the OTHER place a location's real detail gets revealed.
    updated_character_for_light = db.get_character(update.effective_user.id, update.effective_chat.id)

    # Real live request (2026-09-02, Coffee: "when we enter any dungeon,
    # make a message or a prompt so players know its a dungeon") --
    # fires only on the real THRESHOLD crossing (arriving somewhere with
    # a dungeon_id from somewhere that had none, or a DIFFERENT one),
    # never on ordinary room-to-room movement once already inside one.
    # Reuses the exact same dungeon_id/display-name convention the real
    # dungeon minimap already established (_DUNGEON_DISPLAY_NAMES).
    dungeon_entry_note = ""
    # Real live confusion (2026-09-05, Coffee: "why is the stonearch
    # bridge considered a dungeon? i thought we werent supposed to be
    # able to enter dungeons until it is time"). Root cause: this used
    # to key off `dungeon_id` alone, which is really just a map/asset
    # GROUPING label shared by every room in a complex, including the
    # freely-open surface entrance (Stonearch Bridge, Greymoor Downs,
    # The First City all have one but are ordinary overworld zones, not
    # gated dungeons) -- `dungeon_interior` is the real "you are
    # actually inside a dungeon now" flag, only ever set on the deeper
    # rooms (e.g. Stonearch Bridge's own Weeping Well), so only THAT
    # should ever trigger this banner.
    if destination.get("dungeon_interior") and destination.get("dungeon_id") != current.get("dungeon_id"):
        dungeon_display_name = _DUNGEON_DISPLAY_NAMES.get(
            destination["dungeon_id"], destination["dungeon_id"].replace("_", " ").title()
        )
        dungeon_entry_note = f"\n\n🏰 **You've entered a dungeon: {dungeon_display_name}.** Tread carefully."

    if _location_is_dark(destination, updated_character_for_light, update.effective_chat.id):
        await _safe_send(
            update,
            f"🚶 **{character['name']}** travels to **{destination['name']}**.\n"
            f"🌑 **It is too dark. You cannot see...** (equip a torch, or cast a spell like Dancing Lights, to see here.)"
            f"{dungeon_entry_note}",
        )
    else:
        await _safe_send(update, f"🚶 **{character['name']}** travels to **{destination['name']}**.\n{destination['description']}{dungeon_entry_note}")
        await _maybe_send_location_image(update, destination, destination_id, destination_already_visited)
        # Auto "look around" on arrival (2026-08-07, per Coffee: "prompt
        # 'look around' in that area once we arrive there to keep the
        # narration flowing"). Real players only (never an AI
        # companion's own autonomous move -- would spam the Adventure
        # feed with a full room listing for every AI step) -- confirmed
        # is_ai is false for a real player's own character row. Skipped
        # entirely in the dark branch above, matching _do_look's own
        # darkness gate: you can't see who/what's here either.
        if not updated_character_for_light.get("is_ai"):
            extra_lines, reply_markup = _location_extra_detail(
                updated_character_for_light, destination, destination_id, update.effective_chat.id
            )
            if extra_lines:
                await _safe_send(update, "\n".join(extra_lines), reply_markup=reply_markup)

    updated_character = db.get_character(update.effective_user.id, update.effective_chat.id)
    await _maybe_trigger_npc_encounter(update, updated_character, destination)
    await _check_quest_completions_reach_location(update, update.effective_user.id, destination_id)
    await _check_board_quest_turnin(update, update.effective_user.id, destination_id)
    if not updated_character.get("is_ai"):
        story_offer = _offerable_quest_at_location(updated_character, destination_id)
        if story_offer:
            offer_quest_id, offer_quest = story_offer
            await _maybe_push_quest_offer(update, updated_character, offer_quest_id, offer_quest)


def _npc_id_for_companion_name(name: str) -> str | None:
    """Reverse-looks-up a recruited companion's campaign.json npc_id by name -- companion character rows never store it directly (matched by name at recruit time too, see _do_recruit_npc)."""
    for npc_id, data in CAMPAIGN["npcs"].items():
        if data["name"] == name:
            return npc_id
    return None


def _maybe_boost_companion_affinity_for_support(
    update, character: dict, target, boost: int, verb: str,
) -> None:
    """
    Real request (2026-08-23, Coffee: "make a way we can build trust.
    how about by doing quests for them?" -> shipped as a one-time
    quest-completion boost, then a same-session follow-up: "how about
    when we heal them it raises affinity and when we cast supportive
    spells onto them it does that too. things like defening, countering,
    shilding, too" and, separately, "reviving also"). Unlike the quest
    boost, this is small and repeatable -- it can fire many times a
    fight. Only fires for an actual recruited companion (never self,
    never a live-combat-only summon, which has no real npc_id) --
    reuses the exact same _npc_id_for_companion_name lookup
    the_first_city's own real story gate already relies on.
    `target` may be a live session participant dict or a plain DB
    character row; both carry telegram_user_id/name/is_ai.
    """
    if target is None:
        return
    target_id = target.get("telegram_user_id")
    if target_id is None or target_id == character.get("telegram_user_id"):
        return
    if not target.get("is_ai"):
        return
    npc_id = _npc_id_for_companion_name(target.get("name", ""))
    if not npc_id:
        return
    db.adjust_affinity(
        character["telegram_user_id"], update.effective_chat.id, npc_id, boost,
        event=f"{character['name']} {verb} them.",
    )


def _companion_favor_giver_is_in_party(character: dict, npc_id: str | None) -> bool:
    """
    Companion Favors (2026-08-23) travel with the party, not a
    location -- a favor only stays creditable while the companion who
    asked for it is still actually recruited into this player's own
    party (never a stale favor for someone who's since left/been
    benched off the roster entirely).
    """
    if not npc_id or not character.get("party_id"):
        return False
    return any(
        m.get("is_ai") and _npc_id_for_companion_name(m["name"]) == npc_id
        for m in db.get_party_members_by_id(character["party_id"])
    )


def _accepted_companion_favors_for_party(character: dict) -> list[dict]:
    """
    Real dev-bridge report (2026-08-23, Coffee: "i am not seeing
    current accepted affinity tasks in 'My Quests' menu"). Root cause:
    Companion Favors are already a real, shared, party-wide mechanic
    (any real party member's kill/gather can credit one, and any real
    party member's affinity is what's actually raised -- see the
    v1.27.328 crediting fix), but "My Quests" only ever showed the
    VIEWER's own accepted list -- if a party-mate happened to be the
    one who tapped Accept, the viewer never saw it at all, even though
    they could just as easily complete it. Returns every currently
    accepted (not yet completed) favor for every real (non-AI) member
    of this character's own party, de-duplicated, not just the
    viewer's own.
    """
    party_id = character.get("party_id")
    real_pids = {character["telegram_user_id"]}
    if party_id:
        real_pids |= {
            m["telegram_user_id"] for m in db.get_party_members_by_id(party_id) if not m.get("is_ai")
        }
    favors, seen_ids = [], set()
    for pid in real_pids:
        for bq in db.get_accepted_board_quests_for_user(pid, character["chat_id"]):
            if (bq["location_id"].startswith(board_quests_module.COMPANION_FAVOR_LOCATION_PREFIX)
                    and bq["board_quest_id"] not in seen_ids):
                favors.append(bq)
                seen_ids.add(bq["board_quest_id"])
    return favors


def _complete_companion_favor(update: Update, character: dict, board_quest: dict, gathered_by: dict | None = None) -> str:
    """
    Companion Favors auto-complete the instant their objective is met
    -- unlike a normal board quest, there's no "place" to walk back to
    for a companion who travels with the party, so this skips
    _check_board_quest_turnin's arrival-gated flow entirely. Removes
    the gathered material from inventory (same "delivered, not kept"
    fix _check_board_quest_turnin already applies to real board
    quests) and grants the real, small affinity reward. Returns the
    confirmation line to append to the caller's own message.

    `character` is whoever gets the real affinity reward -- the
    ACCEPTER of the favor, matching the defeat_monster crediting
    path's own precedent (credit goes to whoever accepted it, not
    necessarily whoever landed the killing blow). `gathered_by`
    defaults to `character` (the common case: the accepter gathered
    it themselves) and only needs to differ for a real party-wide
    credit (2026-08-23) -- the gathered material always has to come
    out of whoever's OWN backpack it actually landed in, which is the
    real gatherer, not necessarily the favor's accepter.
    """
    actor = gathered_by or character
    if board_quest["objective_type"] == "gather_material":
        db.remove_item(
            actor["telegram_user_id"], update.effective_chat.id,
            board_quest["objective_target"], board_quest["objective_count"],
        )
    db.complete_board_quest(board_quest["board_quest_id"])
    npc_id = board_quest["giver_npc"]
    npc_data = CAMPAIGN["npcs"].get(npc_id)
    npc_name = npc_data["name"] if npc_data else npc_id
    # Real live request (2026-08-23, Coffee: "give the affinity real
    # in-game purpose"). Favors stay affinity-ONLY reward (Coffee's own
    # earlier explicit call when this system shipped, board_quests.py
    # ~155-163 -- no gold/XP added here either), but the ONE number it
    # pays out now compounds with existing trust: a companion who
    # already trusts you goes further out of their way for you, same
    # Trusted(40)/Loyal(60) boundaries as everywhere else in this
    # mechanic (_trust_tier_label). Read BEFORE the award so the bonus
    # reflects the trust that was already there, not trust this same
    # favor is about to grant.
    current_affinity = db.get_relationship(character["telegram_user_id"], update.effective_chat.id, npc_id)["affinity"]
    tier_bonus = 5 if current_affinity >= 60 else 2 if current_affinity >= 40 else 0
    db.adjust_affinity(
        character["telegram_user_id"], update.effective_chat.id, npc_id,
        board_quest["reward_affinity"] + tier_bonus, event=f"Did a favor: \"{board_quest['title']}\".",
    )
    return f"\n💞 **{npc_name}** — favor done: **{board_quest['title']}**. Trust grows a little."


def _check_story_gate(character: dict, current: dict, destination_id: str) -> str | None:
    """
    Full-storyline plan, Phase 1: a third gate type on a location
    connection, alongside min_level and locked_connections. Checked the
    same way locked_connections is -- read off the CURRENT location's
    story_gates dict, keyed by destination id. Returns an in-fiction
    rejection message if blocked, or None if the gate passes (or there's
    no story_gates entry at all for this connection). All conditions
    present, when present, must be met -- this reuses completed_quests
    (no new "defeated" flag) and the existing npc_relationships.affinity
    column (no new trust system).

    A fourth condition, requires_cleared_location (2026-07-24, sequential
    dungeon gating), reuses character["cleared_locations"] instead -- a
    location_id the character must have actually won a real fight in
    (see db.mark_location_cleared / bot.py's
    _mark_location_cleared_for_party) before this connection opens.
    Unlike requires_defeated_monster this needs no quest to exist at
    all, so it also covers the many world-expansion branch locations
    that were never given their own quest.

    requires_defeated_monster also accepts a LIST of monster ids, not
    just a single one (2026-07-25, the true hidden final boss: gated on
    having genuinely defeated every one of this game's other secret
    final bosses first, not just one) -- ALL of them must be defeated,
    each checked exactly like the single-monster case above. A plain
    string still works identically to before (wrapped into a one-item
    list), so every existing single-monster gate is unaffected.
    """
    gate = current.get("story_gates", {}).get(destination_id)
    if not gate:
        return None

    monster_ids = gate.get("requires_defeated_monster")
    if monster_ids:
        if isinstance(monster_ids, str):
            monster_ids = [monster_ids]
        for monster_id in monster_ids:
            defeating_quest_ids = {
                quest_id for quest_id, quest in CAMPAIGN["quests"].items()
                if quest.get("trigger", {}).get("type") == "defeat_monster"
                and quest["trigger"].get("monster") == monster_id
            }
            if not defeating_quest_ids & set(character["completed_quests"]):
                return (
                    "Something down here isn't done with you yet — you can feel "
                    "it's not safe to go any further until whatever's wrong is dealt with."
                )

    cleared_gate = gate.get("requires_cleared_location")
    if cleared_gate and cleared_gate not in character.get("cleared_locations", []):
        return (
            "Whatever's living in here hasn't been dealt with yet — pushing on deeper "
            "while it's still at your back doesn't feel like it'll end well."
        )

    # A fifth condition (2026-08-30, bonus vault dungeons, per Coffee:
    # "make sure we cannot enter these dungeons early, we must do a
    # quest -- be creative on how we have to get in"). The existing 3
    # gate types (requires_defeated_monster/requires_cleared_location/
    # requires_companion_trust) cover a lot, but none of them fit
    # "solved a specific puzzle" or any other quest whose trigger isn't
    # a defeat_monster -- this is the plain, generic form: any real
    # completed quest id, by name, no trigger-shape assumption at all.
    required_quest_id = gate.get("requires_completed_quest")
    if required_quest_id and required_quest_id not in character.get("completed_quests", []):
        return (
            "Something here isn't ready to let you through yet — there's clearly "
            "unfinished business standing between you and whatever's deeper in."
        )

    trust_gate = gate.get("requires_companion_trust")
    if trust_gate:
        # Real live request (2026-08-23, Coffee, after v1.27.340 fixed
        # this gate's message: "if its only in one place thats abit
        # pointless of a mechanic... use this for other places as
        # well... have another spot where 3 chars need to be affinity
        # of 60, then another spot requiring two members that 'get
        # along'"). This ONE trust_gate dict now supports 3 real
        # shapes, all keyed on the same min_affinity/_trust_tier_label
        # number scale (bot.py's Trusted=40/Loyal=60 boundaries):
        #   {"min_affinity": N}                  -- any ONE companion (original, e.g. The Hush Below's 40 -- kept as the
        #                                            simplest form deliberately, since it's most players' first encounter
        #                                            with this mechanic)
        #   {"min_affinity": N, "count": K}       -- at least K distinct companions each individually at/above N
        #   {"pair": [npc_a, npc_b], "min_affinity": N} -- two SPECIFIC companions, both recruited, both at/above N
        min_affinity = trust_gate.get("min_affinity", 0)
        companion_npc_ids = []
        party_id = character.get("party_id")
        if party_id:
            for member in db.get_party_members_by_id(party_id):
                if member.get("is_ai"):
                    npc_id = _npc_id_for_companion_name(member["name"])
                    if npc_id:
                        companion_npc_ids.append(npc_id)

        pair = trust_gate.get("pair")
        if pair:
            npc_a, npc_b = pair
            both_trusted = (
                npc_a in companion_npc_ids and npc_b in companion_npc_ids
                and all(
                    db.get_relationship(character["telegram_user_id"], character["chat_id"], npc_id)["affinity"] >= min_affinity
                    for npc_id in pair
                )
            )
            if not both_trusted:
                name_a = CAMPAIGN["npcs"].get(npc_a, {}).get("name", npc_a)
                name_b = CAMPAIGN["npcs"].get(npc_b, {}).get("name", npc_b)
                return (
                    f"**{name_a}** and **{name_b}** need to be traveling with you, both trusting you "
                    f"**{min_affinity}+**, before this goes any further. Type **affinity** to check where "
                    f"everyone stands."
                )
        else:
            required_count = trust_gate.get("count", 1)
            trusted_count = sum(
                1 for npc_id in companion_npc_ids
                if db.get_relationship(character["telegram_user_id"], character["chat_id"], npc_id)["affinity"] >= min_affinity
            )
            if trusted_count < required_count:
                if required_count <= 1:
                    # Real dev-bridge request (2026-08-23, Coffee): the
                    # old line was deliberately vague in-fiction flavor
                    # text with no real number and no hint how to check
                    # it -- min_affinity is interpolated directly (not
                    # hardcoded 40) so this stays correct if the gate's
                    # own value ever changes.
                    return (
                        f"None of your companions are ready to go any further — at least one needs "
                        f"**{min_affinity}+ affinity** with you first. Type **affinity** to check where "
                        f"everyone stands."
                    )
                return (
                    f"Your party isn't ready to go any further — at least **{required_count}** companions need "
                    f"**{min_affinity}+ affinity** with you first (currently {trusted_count}). Type **affinity** "
                    f"to check where everyone stands."
                )

    return None


def _character_can_currently_reach(character: dict, destination: dict) -> bool:
    """
    Real live report (2026-08-26, Coffee: "in the first city you have a
    location showing (sky) but the location is for a evolved 3
    character... please not even show it until it is time for the
    player to go there, that way they dont get stuck by travelling
    then not able to get back to the ground layer"). the_first_city's
    real "You could ascend to: The Unmoored Isle" line
    (_location_extra_detail) was unconditional -- shown regardless of
    whether the character actually held the isle's requires_item
    (shard_of_dim_light) or met its requires_rebirth_count -- even
    though the isle itself has no path back down to the_first_city in
    its own "directions" (only deeper sky content), so a player who
    saw and followed that line before they were really ready could
    genuinely strand themselves. Same three real gates _do_move already
    enforces at actual travel time, factored out so the DISPLAY can
    check them too instead of just the enforcement.
    """
    if destination.get("requires_item") and destination["requires_item"] not in character.get("inventory", {}):
        return False
    return _meets_location_level(character, destination) and _meets_rebirth_requirement(character, destination)


def _meets_location_level(character: dict, destination: dict) -> bool:
    """
    Real level-gating for the campaign's deepest, hidden endgame locations
    (currently the_hush_below and the_first_city -- confirmed via
    campaign.json these are the only two locations already marked
    "hidden": true, which was never actually enforced anywhere in code
    before this; the game's design clearly intended them as special/deep
    content, this just wires that intent up). Coffee asked directly: a
    level-1 character shouldn't be able to reach endgame content. Any
    location with no "min_level" set (i.e. everything else in the
    campaign) is unaffected.
    """
    min_level = destination.get("min_level")
    return min_level is None or character.get("level", 1) >= min_level


async def _send_level_gate_message(update: Update, destination: dict) -> None:
    await update.effective_chat.send_message(
        f"A deep, wordless dread stops you at the threshold of **{destination['name']}** — "
        f"whatever waits there, you can feel you're not ready for it yet "
        f"(recommended level {destination['min_level']}+).",
        message_thread_id=topics.thread_id_for(update.effective_chat.id, "adventure"),
    )


def _meets_rebirth_requirement(character: dict, destination: dict) -> bool:
    """
    Rebirth-gated content (2026-07-25, per the standing damage-type/
    rebirth plan's Phase 3): a location can set requires_rebirth_count
    (an int) alongside min_level -- same additive, independent-gate
    pattern as every other location restriction in this file. Any
    location with no requires_rebirth_count set (i.e. everything in
    the campaign before this phase) is completely unaffected.
    """
    required = destination.get("requires_rebirth_count")
    return required is None or character.get("rebirth_count", 0) >= required


async def _send_rebirth_gate_message(update: Update, destination: dict) -> None:
    required = destination["requires_rebirth_count"]
    await update.effective_chat.send_message(
        f"Something about **{destination['name']}** refuses to fully resolve in front of you — "
        f"as if the world itself doesn't think you've lived enough of it yet "
        f"(requires {required} rebirth{'s' if required != 1 else ''}).",
        message_thread_id=topics.thread_id_for(update.effective_chat.id, "adventure"),
    )


def _is_fast_travel_eligible(location: dict) -> bool:
    """
    Real live request (2026-08-30, dev-bridge, Coffee: "make sure
    players cannot fast travel in the dungeons or to the dungeons.
    They must use the safe way points... I want this area to be the
    waypoint for dungeon one... make sure the other locations are
    removed"). A location opts OUT of ordinary fast-travel eligibility
    via "dungeon_interior": true -- the whole rest of the game (every
    location without that flag) is completely unaffected, exactly as
    fast-travel has always behaved. The one real exception per dungeon
    is its own designated "dungeon_checkpoint": true room (an already-
    real, hand-authored safe room -- the Ember Font, the Weeping
    Spring, etc.), which stays reachable so a party can warp back to
    where they left off without re-clearing the whole crawl.
    """
    if not location.get("dungeon_interior"):
        return True
    return bool(location.get("dungeon_checkpoint"))


async def _do_fast_travel(update: Update, text: str) -> None:
    """
    Warp directly to any location this character has already visited
    (character['visited_locations'], the same fog-of-war data driving
    _do_show_map) — skipping the walk and its connection-graph
    constraints entirely. Ordinary _do_move (on-foot, connection-by-
    connection, fully narrated) is untouched; this is purely a
    convenience for places already discovered the hard way.

    Real live request (2026-08-30): dungeon interior rooms are excluded
    from this convenience entirely except each dungeon's own real
    checkpoint room -- see _is_fast_travel_eligible.
    """
    telegram_user_id = update.effective_user.id
    character = db.get_character(telegram_user_id, update.effective_chat.id)
    if character is None:
        await _safe_send(update, "You don't have a character yet!", speak=False)
        return

    # Real live bug (2026-07-22, Sugar: "I'm not in battle why can't I
    # travel?"): this only ever checked whether ANY combat session
    # existed anywhere in the shared chat -- since sessions.py's
    # _ACTIVE_SESSIONS is one Session per chat_id (this whole game
    # shares a single Adventure chat), a fight happening to a DIFFERENT
    # character entirely (confirmed live: Sarah fighting a Giant Spider
    # while Sugar's own character was elsewhere, uninvolved) blocked
    # every other player in the game from fast-traveling too. Now only
    # blocks a character who's actually a real participant in that
    # session -- someone else's fight elsewhere no longer stops you.
    active_session = sessions.get_session_for_user(update.effective_chat.id, telegram_user_id)
    if active_session is not None and telegram_user_id in active_session.turn_order:
        await _safe_send(update, "You can't fast-travel in the middle of combat.", speak=False)
        return

    # Phase L3 (2026-09-02, per Coffee: "add the way points/safe places
    # to our waypoints so we can fast travel in and out" / "we need a
    # way they can return") -- the Labyrinth's own checkpoint isn't a
    # real CAMPAIGN location, so it can never be reached by the ordinary
    # visited_locations loop below; recognized here as its own free-text
    # destination, same as the button _waypoint_keyboard now offers.
    checkpoint_floor = character.get("labyrinth_checkpoint_floor", 0)
    lowered_travel_text = text.lower()
    if checkpoint_floor and character["current_location"] != LABYRINTH_LOCATION_SENTINEL:
        # "labyrinth waypoints" (2026-09-09, real dev-bridge request):
        # plural/list phrasing opens the real sub-menu of every
        # personally-earned checkpoint instead of always resuming at
        # the party's furthest progress -- checked BEFORE the singular
        # match just below so "labyrinth waypoints" doesn't fall
        # through to the resume-only branch first.
        if re.search(r"\blabyrinth\s+way\s?points?\b", lowered_travel_text):
            await _do_show_labyrinth_waypoints(update)
            return
        if re.search(r"\b(labyrinth|waystation|way station)\b", lowered_travel_text):
            await _do_enter_labyrinth(update)
            return

    # Real live crash (2026-09-04, error log, Sheri/Charvenna, count=3):
    # LABYRINTH_LOCATION_SENTINEL is never a real CAMPAIGN location, so
    # every lookup below this point (visited_locations filtering,
    # `current = cl.get_location(...)`) assumed something that isn't
    # true while genuinely inside the Labyrinth, crashing instead of
    # ever reaching a clean refusal. Fast-traveling OUT of the
    # Labyrinth to an ordinary overworld waypoint isn't a supported
    # move today (the waystation/checkpoint case just above is the
    # real, supported way back in) -- refuse honestly instead.
    if character["current_location"] == LABYRINTH_LOCATION_SENTINEL:
        await _safe_send(update, "You're deep in the Labyrinth right now — leave it first, or fast-travel to the waystation/labyrinth to return to your last checkpoint.", speak=False)
        return

    visited = [
        loc_id for loc_id in character["visited_locations"]
        if (loc := cl.get_location(CAMPAIGN, loc_id)) and _is_fast_travel_eligible(loc)
    ]
    lowered = text.lower()
    destination_id = None
    for loc_id in visited:
        loc = cl.get_location(CAMPAIGN, loc_id)
        if loc and (loc_id.replace("_", " ") in lowered or loc["name"].lower() in lowered):
            destination_id = loc_id
            break

    if destination_id is None:
        # A more precise rejection when the text actually names a real,
        # already-visited dungeon room that's just not fast-travel
        # eligible -- "you haven't been there" would be actively wrong.
        for loc_id in character["visited_locations"]:
            loc = cl.get_location(CAMPAIGN, loc_id)
            if loc and not _is_fast_travel_eligible(loc) and (loc_id.replace("_", " ") in lowered or loc["name"].lower() in lowered):
                await _safe_send(
                    update,
                    f"You can't fast-travel directly to {loc['name']} — it's deep inside a real dungeon. "
                    f"Travel there on foot, or warp to that dungeon's own safe waypoint if you've found it.",
                    speak=False,
                )
                return
        known_names = ", ".join(cl.get_location(CAMPAIGN, loc_id)["name"] for loc_id in visited)
        await _safe_send(
            update, f"You can only fast-travel somewhere you've actually been. Waypoints you've discovered: {known_names}",
            speak=False,
        )
        return

    if destination_id == character["current_location"]:
        await _safe_send(update, "You're already there.", speak=False)
        return

    destination = cl.get_location(CAMPAIGN, destination_id)
    if destination.get("requires_item") and destination["requires_item"] not in character["inventory"]:
        await _safe_send(
            update, f"Something stops **{character['name']}** from going any further — missing something needed first.",
            speak=False,
        )
        return

    if not _meets_location_level(character, destination):
        await _send_level_gate_message(update, destination)
        return

    if not _meets_rebirth_requirement(character, destination):
        await _send_rebirth_gate_message(update, destination)
        return

    current = cl.get_location(CAMPAIGN, character["current_location"])

    locked_connections = current.get("locked_connections", {})
    lockable_id = locked_connections.get(destination_id)
    if lockable_id:
        block_message = _lockable_block_message(current, destination["name"], lockable_id, update.effective_chat.id)
        if block_message:
            await _safe_send(update, block_message, speak=False)
            return

    story_gate_message = _check_story_gate(character, current, destination_id)
    if story_gate_message:
        await _safe_send(update, story_gate_message, speak=False)
        return

    db.move_character(telegram_user_id, update.effective_chat.id, destination_id)
    # Real live bug found investigating Coffee's report ("It's not
    # letting me send to wren, who is in my party" -- 2026-08-01):
    # _do_move (on-foot travel) has always moved real AI companions
    # along with the party via this exact block; fast_travel (waypoint
    # warp) never got the same fix, so warping anywhere silently left
    # every AI companion behind at the old location -- indistinguishable
    # from them just vanishing, and exactly why Wren wasn't "here"
    # anymore for a give/equip/anything-location-scoped action. Now
    # shared with _do_move via _move_party_stragglers_along (2026-08-18)
    # so the two paths can't diverge like this a second time -- see that
    # helper's docstring for the full current logic.
    if character.get("party_id"):
        _move_party_stragglers_along(telegram_user_id, character["party_id"], update.effective_chat.id, destination_id)
    # Real live bug (2026-08-13, dev-topic screenshot, Coffee: "Instead
    # of saying, you fast travel, can you include the player's name?"):
    # the on-foot travel message (_do_move, just below) already names
    # the real character ("**{character['name']}** travels to...");
    # this waypoint-warp path was the one place left still saying the
    # generic "You" instead, inconsistent with every other arrival/
    # action message in this game.
    dungeon_entry_note = ""
    # Real live confusion (2026-09-05, Coffee: "why is the stonearch
    # bridge considered a dungeon? i thought we werent supposed to be
    # able to enter dungeons until it is time"). Root cause: this used
    # to key off `dungeon_id` alone, which is really just a map/asset
    # GROUPING label shared by every room in a complex, including the
    # freely-open surface entrance (Stonearch Bridge, Greymoor Downs,
    # The First City all have one but are ordinary overworld zones, not
    # gated dungeons) -- `dungeon_interior` is the real "you are
    # actually inside a dungeon now" flag, only ever set on the deeper
    # rooms (e.g. Stonearch Bridge's own Weeping Well), so only THAT
    # should ever trigger this banner.
    if destination.get("dungeon_interior") and destination.get("dungeon_id") != current.get("dungeon_id"):
        dungeon_display_name = _DUNGEON_DISPLAY_NAMES.get(
            destination["dungeon_id"], destination["dungeon_id"].replace("_", " ").title()
        )
        dungeon_entry_note = f"\n\n🏰 **You've entered a dungeon: {dungeon_display_name}.** Tread carefully."
    await _safe_send(update, f"🌀 **{character['name']}** fast-travels to **{destination['name']}**.\n{destination['description']}{dungeon_entry_note}")

    updated_character = db.get_character(telegram_user_id, update.effective_chat.id)
    # Auto "look around" on arrival (2026-08-07, per Coffee: "prompt
    # 'look around' ... once we arrive there" -- covers the waypoint-
    # button warp too, not just walking there via _do_move). Real
    # players only, same reasoning as _do_move's own version of this.
    if not updated_character.get("is_ai"):
        extra_lines, reply_markup = _location_extra_detail(
            updated_character, destination, destination_id, update.effective_chat.id
        )
        if extra_lines:
            await _safe_send(update, "\n".join(extra_lines), reply_markup=reply_markup)
    await _maybe_trigger_npc_encounter(update, updated_character, destination)
    await _check_quest_completions_reach_location(update, update.effective_user.id, destination_id)
    await _check_board_quest_turnin(update, update.effective_user.id, destination_id)
    if not updated_character.get("is_ai"):
        story_offer = _offerable_quest_at_location(updated_character, destination_id)
        if story_offer:
            offer_quest_id, offer_quest = story_offer
            await _maybe_push_quest_offer(update, updated_character, offer_quest_id, offer_quest)


def _location_neighbors(location_id: str) -> list[str]:
    location = cl.get_location(CAMPAIGN, location_id)
    if not location:
        return []
    neighbors = list(location.get("connections", []))
    if "descends_to" in location:
        neighbors.append(location["descends_to"])
    if "ascends_to" in location:
        neighbors.append(location["ascends_to"])
    return neighbors


def _nearest_shop_location(start_location_id: str) -> tuple[str, int] | None:
    """BFS over the real location graph for the closest location with a real shop. Returns (location_id, hops)."""
    start = cl.get_location(CAMPAIGN, start_location_id)
    if start and start.get("shop"):
        return start_location_id, 0

    visited = {start_location_id}
    queue = [(start_location_id, 0)]
    while queue:
        current_id, dist = queue.pop(0)
        for neighbor_id in _location_neighbors(current_id):
            if neighbor_id in visited:
                continue
            visited.add(neighbor_id)
            neighbor = cl.get_location(CAMPAIGN, neighbor_id)
            if neighbor and neighbor.get("shop"):
                return neighbor_id, dist + 1
            queue.append((neighbor_id, dist + 1))
    return None


async def _do_find_merchant(update: Update) -> None:
    character = db.get_character(update.effective_user.id, update.effective_chat.id)
    if character is None:
        await update.effective_chat.send_message(
            "You don't have a character yet!", message_thread_id=topics.thread_id_for(update.effective_chat.id, "adventure")
        )
        return

    result = _nearest_shop_location(character["current_location"])
    if result is None:
        await update.effective_chat.send_message(
            "There's no known merchant reachable from here.", message_thread_id=topics.thread_id_for(update.effective_chat.id, "adventure")
        )
        return

    location_id, hops = result
    location = cl.get_location(CAMPAIGN, location_id)
    shop = cl.get_shop(CAMPAIGN, location["shop"])
    owner = CAMPAIGN["npcs"].get(shop.get("owner_npc")) if shop else None
    owner_name = owner["name"] if owner else None

    if hops == 0:
        line = f"🛒 You're already at a merchant — {owner_name or 'the shop'} is right here."
    else:
        stops = "stop" if hops == 1 else "stops"
        owner_line = f", run by {owner_name}" if owner_name else ""
        line = f"🛒 Closest merchant: **{location['name']}**{owner_line} — {hops} {stops} from here."
    await _safe_send(update, line)


async def _do_give_item(update: Update, text: str) -> None:
    """
    Player-to-player item trading (2026-07-15 backlog item): hand a
    carried item to another real player or AI companion. Scoped to
    whoever's actually active at the giver's own current_location, same
    "physically present" convention already used for who can join a
    fight (_get_combat_eligible_party_members) -- not restricted to a
    formed party, since trading with anyone standing in the same room
    is the more natural reading of "give my potion to X".
    """
    character = db.get_character(update.effective_user.id, update.effective_chat.id)
    if character is None:
        await update.effective_chat.send_message(
            "You don't have a character yet!", message_thread_id=topics.thread_id_for(update.effective_chat.id, "adventure")
        )
        return

    candidates = [
        p for p in _get_combat_eligible_party_members(character["current_location"], character["chat_id"])
        if p["telegram_user_id"] != character["telegram_user_id"]
    ]
    recipient = _match_member_by_name_or_username(text, candidates)
    if recipient is None:
        # Real live bug (2026-08-16, Sugar/Charvenna, dev-bridge: "Ossian
        # vane is there with me. Why can't I give him the scroll?"): this
        # function was always scoped to real party members only (a real
        # player or AI companion), never NPCs -- but the old rejection
        # ("Name someone real who's actually here with you") flatly
        # implied Ossian Vane wasn't real or wasn't present, when he
        # demonstrably was both (she'd just been talking to him). Checks
        # whether the named recipient is a real NPC actually standing
        # here first, so the message can be honest about the ACTUAL
        # limitation (item trading doesn't reach NPCs yet) instead of
        # denying a person's own existence.
        text_lower = text.lower()
        npc_here = next(
            (
                npc["name"] for npc_id in _npcs_at_location(character["current_location"], character["chat_id"])
                if (npc := cl.get_npc(CAMPAIGN, npc_id)) and npc["name"].lower() in text_lower
            ),
            None,
        )
        if npc_here:
            await update.effective_chat.send_message(
                f"**{character['name']}**: {npc_here} can't carry items yet — trading is between real party "
                f"members (players and companions) only, not NPCs.",
                message_thread_id=topics.thread_id_for(update.effective_chat.id, "adventure"),
            )
        else:
            await update.effective_chat.send_message(
                f"**{character['name']}**: give it to whom? Name someone real who's actually here with you.",
                message_thread_id=topics.thread_id_for(update.effective_chat.id, "adventure"),
            )
        return

    items_wanted = _extract_item_list(text, list(character["inventory"].keys()))
    if not items_wanted:
        await update.effective_chat.send_message(
            f"Give {recipient['name']} what, exactly? Name something you're actually carrying.",
            message_thread_id=topics.thread_id_for(update.effective_chat.id, "adventure"),
        )
        return

    given = []
    for item_id, quantity in items_wanted:
        removed, _ = db.remove_item(update.effective_user.id, update.effective_chat.id, item_id, quantity)
        item_name = items_module.get_item(item_id)["name"]
        if not removed:
            have = character["inventory"].get(item_id, 0)
            given.append(f"You don't have {quantity}x {item_name} to give — you only have {have}.")
            continue
        db.add_item(recipient["telegram_user_id"], update.effective_chat.id, item_id, quantity)
        given.append(f"🤝 **{character['name']}** gives {quantity}x {item_name} to **{recipient['name']}**.")

    await _safe_send(update, "\n".join(given))


async def _do_use_item(update: Update, text: str) -> None:
    """
    Real bug from the reverse-playthrough sweep (2026-07-15): NOTHING in
    this entire codebase ever read a consumable item's "heal_dice" or
    "effect" field -- Healing Potions, Greater Healing Potions, and
    Antitoxin were all completely non-functional. A player could buy
    one for real gold and there was no action anywhere to ever drink
    it. Fixed by adding this handler, following the exact same
    rules-decide/bot.py-narrates split as every other outcome (heal
    amount rolled via rules.dice.roll_damage, never invented).

    Combat-turn awareness (2026-07-18, real live incident): this used
    to have NO idea a combat session existed at all -- confirmed live,
    a player tried "Eat ration" mid-combat (silently misclassified as
    chat at the time, see task #166's fix) and, separately, even a
    real use_item call here would have done nothing to the encounter:
    no turn-order check, no advance_turn(). Using a consumable is a
    real action in 5E, so it now blocks out-of-turn the same way
    _do_attack does, and consumes the actor's turn (advance_turn +
    resolve AI turns) when it succeeds during active combat -- exactly
    like finishing an attack. Out of combat, behaves exactly as before.
    """
    character = db.get_character(update.effective_user.id, update.effective_chat.id)
    if character is None:
        await _safe_send(update, "You don't have a character yet!", speak=False)
        return

    chat_id = update.effective_chat.id
    user_id = update.effective_user.id
    session = sessions.get_session_for_user(chat_id, user_id)
    in_combat = session is not None and user_id in session.turn_order
    if in_combat and session.current_participant_id() != user_id:
        current_name = session.current_participant()["name"]
        await _safe_send(update, f"It's not your turn — it's **{current_name}**'s turn.", speak=False)
        return

    # Task #141: map items (type "map") are usable the same way a
    # consumable is -- read it, it does its one-time thing, it's gone --
    # so they share this same dispatch path rather than a separate command.
    consumable_ids = [
        item_id for item_id in character["inventory"]
        if (items_module.get_item(item_id) or {}).get("type") in ("consumable", "map", "book")
    ]
    item_id = items_module.find_item_mentioned_in_text(text, candidate_ids=consumable_ids)
    if item_id is None:
        # Real live bug (2026-08-13, topic-activity monitoring): "Use
        # sneak attack on colosseum champion 4" was retried 3 times in
        # a row (once even adding "with my great axe" in a genuine
        # attempt to make it match), each time hitting this exact
        # generic fallback -- Sneak Attack is an AUTOMATIC bonus
        # rules/combat.py's resolve_attack applies to a Rogue's own
        # attack roll when it has advantage (see sneak_attack_die
        # there), never a separate "use"-able ability with its own
        # command, so no amount of rephrasing "use X" could ever match
        # it. A player's natural instinct to try "use" for a named
        # class feature is reasonable (that's exactly how activated
        # abilities like Second Wind/Rage/Action Surge DO work in this
        # game), so the honest fix is telling them it's automatic
        # instead of leaving them to keep guessing at phrasing.
        if character["char_class"].lower() == "rogue" and "sneak attack" in text.lower():
            await _safe_send(
                update,
                f"🗡️ Sneak Attack isn't something **{character['name']}** activates separately — it's automatic "
                f"bonus damage on a normal attack roll whenever you have advantage (e.g. an ally next to your "
                f"target, or the target can't see you). Just say \"Attack\" when you have advantage and it "
                f"applies on its own.",
            )
            return
        await _safe_send(update, "Use what, exactly? Name a consumable you're actually carrying.", speak=False)
        return

    item = items_module.get_item(item_id)
    # Recipe books (2026-08-11, per Coffee: a "Cook Book"/"Herbalism
    # Guide"/"Crafting Book" real players can buy and read for the real
    # level-1 (ungated) recipes of a profession). Deliberately NOT
    # consumed on use (a reference book is reused, unlike a potion or a
    # one-shot map) and short-circuits out here, before the combat-turn
    # machinery below -- reading a book isn't a real combat action, and
    # it never mutates game state, so it never needs to consume a turn.
    if item.get("type") == "book":
        await _do_read_recipe_book(update, item)
        return
    # Real bug caught live (2026-07-24, Coffee: "revival can't see
    # inactive characters... shrine, tent, cabin, house, it all needs
    # to work this way"): _find_party_target_by_name only ever sees a
    # player's currently ACTIVE character, so a dead party member whose
    # owner has since switched to play someone else (a real, intended
    # option while dead) was invisible here too, same root cause/fix as
    # the shrine offering's get_party_members_by_id_including_inactive_slots.
    party_id = character.get("party_id")
    all_party_members = (
        db.get_party_members_by_id_including_inactive_slots(party_id) if party_id else []
    )
    effect = item.get("effect", "none")
    # Real feature (2026-08-10, per Coffee: "healing type potions hurt
    # the Undead", "life potions can kill Undead", confirmed "combat
    # only works"): a heal-type item can ALSO be aimed at a live,
    # hostile UNDEAD enemy mid-fight -- real 5E rule, positive/life
    # energy hurts (and can genuinely kill) undead instead of healing
    # them. Checked before the normal party lookup so this never needs
    # to touch that path at all; only fires when the text actually names
    # a living undead enemy currently in this fight.
    undead_enemy_target = None
    if effect == "heal" and session is not None and user_id in session.turn_order:
        opposing = session.living_on_side(session.opposing_side(user_id))
        undead_opposing = [p for p in opposing if p.get("monster_key") in UNDEAD_MONSTER_KEYS]
        if undead_opposing:
            undead_enemy_target = _match_member_by_name_or_username(text, undead_opposing)

    # Real dev-bridge report (2026-08-23, Coffee, screenshot: "I just
    # tried to heal one of the lesser spirits, and for some reason it
    # healed me?"): confirmed via the real callback log --
    # `bm|usetarget|greater_healing_potion|A Lesser Spirit` correctly
    # named the summon, but the target lookup below only ever searched
    # `all_party_members` (a pure DB query, db.get_party_members_by_id_
    # including_inactive_slots) -- a live combat-only summon (negative
    # telegram_user_id, no DB row at all) can never be found there, so
    # it silently fell through to `or character`, healing the CASTER
    # instead every time, for 0 HP since Elduinn was already full.
    # Same real gap _do_cast_spell's heal branch already had and fixed
    # 2026-08-21 (Coffee: "we can heal them") via
    # _find_live_summon_by_name -- reused here unchanged.
    is_summon_target = False
    if undead_enemy_target is not None:
        target = undead_enemy_target
        is_self = False
        target_note = f" on **{target['name']}**"
    else:
        target = None
        if session is not None and user_id in session.turn_order:
            target = _find_live_summon_by_name(text, session, session.sides.get(user_id))
            is_summon_target = target is not None
        if target is None:
            target = _match_member_by_name_or_username(text, all_party_members) or character
        is_self = not is_summon_target and target["telegram_user_id"] == character["telegram_user_id"]
        target_note = "" if is_self else f" on **{target['name']}**"

    removed, _ = db.remove_item(update.effective_user.id, update.effective_chat.id, item_id, 1)
    if not removed:
        await _safe_send(update, f"You don't have a {item['name']} to use.", speak=False)
        return

    combat_ended_by_undead_kill = False
    if effect == "heal" and item.get("heal_dice") and undead_enemy_target is not None:
        # "Life potions can kill Undead" -- the exact heal_dice roll
        # every other use of this item already rolls, applied as REAL
        # damage instead of healing, flavored as radiant (positive
        # energy) so it correctly interacts with any real radiant
        # vulnerability this undead already has (verge_wraith/
        # bone_legionnaire/cairn_watcher/etc. -- see rules.combat.
        # UNDEAD_MONSTER_KEYS's own comment) -- a big potion against a
        # radiant-vulnerable undead can be a genuine, literal kill.
        # Enemies have no DB row (negative synthetic telegram_user_id,
        # no character_id) -- mutates the live session participant dict
        # only, same as every other enemy HP change in this game.
        healing = roll_damage(item["heal_dice"])
        damage_dealt = apply_damage_type_modifier(healing["total"], "radiant", target, character)
        target["hp_current"] = max(target["hp_current"] - damage_dealt, 0)
        message = (
            f"✨ **{character['name']}** hurls a {item['name']}{target_note} — the life energy "
            f"burns it for **{damage_dealt} damage** ({target['hp_current']}/"
            f"{target.get('hp_max', target['hp_current'])} HP)."
        )
        if target["hp_current"] <= 0:
            message += f" **{target['name']}** is destroyed!"
        await _safe_send(update, message)

        defeated_removed = session.remove_defeated()
        await _announce_defeats(update, session, defeated_removed)
        if session.is_combat_over():
            combat_ended_by_undead_kill = True
            winner = _determine_winner(session)
            xp_summary, level_up_notes = await _award_victory_xp(update, session) if winner == "party" else ("", [])
            if winner == "party":
                await _check_quest_completions_defeat_monster(update, session)
                await _mark_location_cleared_for_party(update, session)
                await _check_achievements_for_combat_party(update, session)
                await _check_guild_quest_completion(update, session)
                await _check_echo_trial_progress(update, session)
                await _check_labyrinth_progress(update, session)
                await _check_overworld_key_drop(update, session)
                await _check_overworld_rune_drop(update, session)
            await _safe_send(update, f"🏆 **Combat over!** The {winner} side is victorious!{xp_summary}")
            for note in level_up_notes:
                await _notify_main_topic(update, note)
            sessions.end_session(chat_id, session)
        # Already sent above (before the possible "Combat over!"
        # follow-up) -- the shared send/advance-turn tail below must not
        # repeat it or try to advance a session that may have just ended.
        message = None
    elif effect == "heal" and item.get("heal_dice"):
        # Real bug (2026-07-23, live report: "healing 0 HP (11/11)" posted
        # for a companion the roster showed at 3/11 both before and after):
        # target came straight from _find_party_target_by_name -> a plain
        # DB row, but HP during active combat lives on the session's live
        # participant dict instead (mutated in place, only synced to the DB
        # at specific checkpoints -- see _sync_player_to_db) -- so mid-fight
        # this read stale, already-full HP and healed for 0. Mirrors the
        # cure_poison branch below, which already looks up the live
        # participant correctly.
        live_target = None
        if session is not None:
            live_target = next(
                (p for p in session.participants if p["telegram_user_id"] == target["telegram_user_id"]), None,
            )
        hp_source = live_target if live_target is not None else target
        healing = roll_damage(item["heal_dice"])
        # Real live request (2026-08-26, per Coffee: "use this
        # proficiency for healing type scrolls, magic, and abilities
        # that heal characters... make healing proficiency like an
        # element"). The DRINKER's own healing mastery, not the
        # target's -- same "the caster's own practice" convention every
        # other mastery bonus in this game follows (Bardic Inspiration/
        # Lay on Hands don't scale off who they're cast ON either).
        healed_amount = int(healing["total"] * _mastery_overflow_multiplier(_grind_heal_mastery(character)))
        hp_before = hp_source["hp_current"]
        hp_max = hp_source.get("hp_max", hp_before)
        new_hp = min(hp_before + healed_amount, hp_max)
        if live_target is not None:
            live_target["hp_current"] = new_hp
        # A summon has no DB row to write -- live_target above already
        # mutated the real session.participants dict in place, so the
        # live combat state is already correct. character_id, not
        # telegram_user_id, for a real target -- see update_character_
        # by_id's docstring (2026-07-24): target might be an alive-but-
        # inactive party member (their owner is currently playing
        # someone else), which update_character would silently
        # misdirect to the wrong, actually-active character.
        if not is_summon_target:
            db.update_character_by_id(target["character_id"], hp_current=new_hp)
            _maybe_boost_companion_affinity_for_support(update, character, target, 2, "healed")
        message = (
            f"🧪 **{character['name']}** uses a {item['name']}{target_note}, "
            f"healing {new_hp - hp_before} HP ({new_hp}/{hp_max})."
        )
    elif item.get("type") == "map":
        # Task #141: a genuine partial reveal -- adds up to reveals_count
        # random location NAMES from the item's one real layer to
        # map_revealed_locations (a separate fog-of-war layer from
        # visited_locations, see db.py's migration comment), never all of
        # them at once and never a location already visited/revealed.
        # _do_show_map renders these distinctly, name only, no connections
        # -- that's the actual spoiler, and it stays earned by walking there.
        layer = item.get("reveals_layer")
        layer_locations = CAMPAIGN["locations"].get(layer, {})
        already_known = set(character["visited_locations"]) | set(character["map_revealed_locations"])
        candidates = [loc_id for loc_id in layer_locations if loc_id not in already_known]
        if not candidates:
            message = (
                f"📜 **{character['name']}** unrolls the {item['name']} — but it shows nothing "
                f"you haven't already found on your own."
            )
        else:
            newly_revealed = random.sample(candidates, min(item.get("reveals_count", 1), len(candidates)))
            db.update_character(
                character["telegram_user_id"], update.effective_chat.id,
                map_revealed_locations=character["map_revealed_locations"] + newly_revealed,
            )
            revealed_names = ", ".join(layer_locations[loc_id]["name"] for loc_id in newly_revealed)
            message = (
                f"📜 **{character['name']}** unrolls the {item['name']} — it marks the rough "
                f"location of {revealed_names}, though you'll still need to find your own way there."
            )
    elif effect == "heal_and_revive":
        # Per Coffee (2026-07-24): "add items like tents and cabins and
        # houses to reviving and healing characters to full" -- a
        # stronger, pricier alternative to Revivify/Scroll of Revivify
        # (which only restore 1 HP): this fully heals AND revives,
        # tiered by how many party members it reaches at once via
        # item["revive_targets"] (1 = just the one you named, matching
        # every other single-target consumable; a number = up to that
        # many; None = the whole party) -- same "physically present"
        # scoping _do_give_item/_do_equip_item already use, since this
        # is meant to be used once the party's actually gathered, not
        # reach across the map.
        max_targets = item.get("revive_targets", 1)
        if max_targets == 1:
            recipients = [target]
        else:
            present = [
                p for p in _get_combat_eligible_party_members(character["current_location"], character["chat_id"])
                if character.get("party_id") and p.get("party_id") == character["party_id"]
            ] or [character]
            # A dead party member isn't "physically present" anywhere
            # meaningful (they're incapacitated, not standing around),
            # so location-based presence is the wrong gate for THEM --
            # same real bug/fix as the single-target case above, added
            # in regardless of location so a Cabin/House can revive
            # someone even if their last-known location doesn't match
            # where the party is gathered now.
            dead_anywhere = [m for m in all_party_members if m.get("is_dead")]
            combined = {p["character_id"]: p for p in present}
            for m in dead_anywhere:
                combined.setdefault(m["character_id"], m)
            recipients = list(combined.values())
            if max_targets is not None:
                recipients = recipients[:max_targets]
        healed_lines = []
        for recipient in recipients:
            live_target = None
            if session is not None:
                live_target = next(
                    (p for p in session.participants if p["telegram_user_id"] == recipient["telegram_user_id"]), None,
                )
            hp_source = live_target if live_target is not None else recipient
            hp_max = hp_source.get("hp_max", hp_source["hp_current"])
            was_dead = bool(recipient.get("is_dead"))
            # character_id, not telegram_user_id -- see
            # update_character_by_id's docstring. Without this, reviving
            # someone who isn't their owner's active character silently
            # updated the WRONG (already-alive) character instead.
            db.update_character_by_id(
                recipient["character_id"], hp_current=hp_max, is_dead=0, died_at=None,
                death_save_successes=0, death_save_failures=0,
            )
            if live_target is not None:
                live_target["hp_current"] = hp_max
            revive_note = " — brought back from death" if was_dead else ""
            healed_lines.append(f"**{recipient['name']}** fully restored{revive_note} ({hp_max}/{hp_max} HP)")
            _maybe_boost_companion_affinity_for_support(
                update, character, recipient, 10 if was_dead else 2, "revived" if was_dead else "healed",
            )
        message = f"🏕️ **{character['name']}** sets up the {item['name']} — " + "; ".join(healed_lines) + "."

    elif effect == "restore_spell_slots":
        # Per Coffee (2026-08-10): a genuine in-battle way to recover
        # spell slots, since the real game rule (see Support's
        # deterministic answer in ai/support_agent.py) is that nothing
        # else does -- resting is otherwise the only option, and that
        # only works out of combat. Mirrors the heal branch's live-vs-DB
        # sourcing exactly (spell_slots_current can be mid-combat-fresh
        # only on the in-memory participant dict, same reasoning as the
        # 2026-07-23 HP bug this file already fixed above).
        live_target = None
        if session is not None:
            live_target = next(
                (p for p in session.participants if p["telegram_user_id"] == target["telegram_user_id"]), None,
            )
        slot_source = live_target if live_target is not None else target
        slots_before = slot_source.get("spell_slots_current", 0)
        slots_max = slot_source.get("spell_slots_max", slots_before)
        new_slots = slots_max if item.get("restore_all") else min(
            slots_before + item.get("restore_spell_slots_amount", 0), slots_max
        )
        if live_target is not None:
            live_target["spell_slots_current"] = new_slots
        # Real live crash (2026-08-25, error-log finding): a summoned
        # participant (e.g. "A Spirit") has no DB row at all -- live_target
        # above already mutated the real session.participants dict in
        # place, so the live combat state is already correct. Mirrors the
        # "heal" branch's own is_summon_target guard just above, which
        # already gets this right; this branch was simply missing it.
        if not is_summon_target:
            db.update_character_by_id(target["character_id"], spell_slots_current=new_slots)
        restored = new_slots - slots_before
        message = (
            f"✨ **{character['name']}** drinks a {item['name']}{target_note}, restoring "
            f"{restored} spell slot{'s' if restored != 1 else ''} ({new_slots}/{slots_max})."
        )

    elif effect == "cure_poison":
        cured = False
        if session is not None:
            live_target = next(
                (p for p in session.participants if p["telegram_user_id"] == target["telegram_user_id"]), None,
            )
            if live_target and "poisoned" in live_target.get("conditions", []):
                live_target["conditions"].remove("poisoned")
                cured = True
        message = (
            f"🧪 **{character['name']}** uses a {item['name']}{target_note} — the poison is neutralized."
            if cured else
            f"🧪 **{character['name']}** uses a {item['name']}{target_note}, just in case."
        )

    elif effect == "cure_condition":
        # Real live gap (2026-08-26, per Coffee: "create an item and a
        # spell to cure silence -- check other status effects and make
        # sure there is items and spells to cure them also"). Generic,
        # data-driven cure -- driven by the item's own "cures" list
        # (Vocal Tonic: silenced; Clarifying Drops: blinded) -- rather
        # than a bespoke branch per condition, same shape as
        # dispel_magic's own "removed = [c for c in conditions if c in
        # (...)]" pattern (bot.py's _cast_utility_spell). Antitoxin's
        # existing cure_poison branch above is untouched.
        cured_conditions = []
        if session is not None:
            live_target = next(
                (p for p in session.participants if p["telegram_user_id"] == target["telegram_user_id"]), None,
            )
            if live_target:
                cured_conditions = [c for c in live_target.get("conditions", []) if c in item.get("cures", [])]
                for c in cured_conditions:
                    live_target["conditions"].remove(c)
        message = (
            f"🧪 **{character['name']}** uses a {item['name']}{target_note} — clears: {', '.join(cured_conditions)}."
            if cured_conditions else
            f"🧪 **{character['name']}** uses a {item['name']}{target_note}, just in case."
        )
    else:
        # Flavor-only consumables (rations, ale, torch, etc.) -- real 5E
        # items this game has no mechanic for (hunger, light radius), same
        # honesty convention as every other unmodeled mechanic in this build.
        message = f"🧺 **{character['name']}** uses a {item['name']}{target_note}."

    if message is not None:
        await _safe_send(update, message)

    if in_combat and not combat_ended_by_undead_kill:
        async with _held_session(chat_id, user_id) as session:
            if session is not None:
                await _advance_turn_and_resolve_ai_turns(update, session)


HOLLOW_STUMP_SHRINE_OFFERING_COST = 100
# Blessing (2026-07-24, per Coffee: "if no players need reiving u can
# offer a blessing for cheaper to heal the party to full like 'holy
# water'") -- the no-one's-dead alternative to the revival offering
# above, same shrine, same real gold cost, cheaper since it isn't
# fighting death itself.
HOLLOW_STUMP_SHRINE_BLESSING_COST = 50


async def _do_drink_water(update: Update) -> None:
    """
    Per Coffee (2026-07-24): "make spots in the game with 'holy water'
    so party can heal - jus suggest there is water dont tell them if
    its holy or not they have to find out." A location opts in via a
    plain "healing_water": true flag never mentioned in its own
    description/interactable text -- that's the whole point. The
    Weeping Well is the first real one, already primed by its own
    "strange warmth" mystery quest (the_weeping_wells_secret). The
    narration is identical whether or not anything actually happened --
    a player only ever finds out by noticing their own HP change (or
    not) afterward. Limited to once per rest via the same feature_uses/
    use_feature pattern Arcane Recovery already uses, so this can't
    become a free substitute for potions/the shrine. Heals the same
    real dice as an ordinary healing potion (heal_dice), not an
    invented number.
    """
    character = db.get_character(update.effective_user.id, update.effective_chat.id)
    if character is None:
        await _safe_send(update, "You don't have a character yet!", speak=False)
        return
    location = cl.get_location(CAMPAIGN, character["current_location"])
    if location is None or not location.get("healing_water"):
        await _safe_send(update, "There's no water to drink here.", speak=False)
        return
    if db.get_feature_uses(update.effective_user.id, update.effective_chat.id, "healing_water") < 1:
        db.use_feature(update.effective_user.id, update.effective_chat.id, "healing_water")
        heal_dice = items_module.get_item("healing_potion")["heal_dice"]
        healed = min(roll_damage(heal_dice)["total"], character["hp_max"] - character["hp_current"])
        if healed > 0:
            db.update_character(update.effective_user.id, update.effective_chat.id, hp_current=character["hp_current"] + healed)
    await _safe_send(update, f"💧 **{character['name']}** cups a handful of water and drinks.")


async def _do_labyrinth_checkpoint_offering(update: Update, text: str) -> None:
    """
    Phase L3 (2026-09-02, per Coffee: "we shud not be getting it each
    time we enter the location, but u can put a shrine there for us to
    pray or give an offering of spring water" -- the checkpoint's own
    one-time arrival reward, _resolve_labyrinth_checkpoint, fires
    exactly once; this is the REPEATABLE way to top back up on later
    visits). Two real tiers, same "pray is free but modest, an offering
    is stronger but costs something real" shape as the overworld's own
    Hollow Stump Shrine blessing: a bare "pray" heals half of whatever's
    missing, free; naming "water"/"offering" additionally consumes one
    real spring_water item (sold right here by the checkpoint's own
    wandering trader) for a full party HP + spell-slot refill.
    """
    chat_id = update.effective_chat.id
    character = db.get_character(update.effective_user.id, chat_id)
    if character is None:
        return
    run = db.get_labyrinth_run(chat_id, _labyrinth_party_key(character))
    if run is None:
        return
    room = run["rooms"].get(run["current_room_id"])
    if room is None or not room.get("is_checkpoint"):
        await _safe_send(update, "There's no shrine to pray at here.", speak=False)
        return
    members = _labyrinth_active_party_members(character)
    wants_offering = bool(re.search(r"\b(water|offer|offering)\b", text.lower()))
    if wants_offering:
        if character["inventory"].get("spring_water", 0) < 1:
            await _safe_send(update, "You don't have any spring water to offer. The trader here sells it.", speak=False)
            return
        db.remove_item(update.effective_user.id, chat_id, "spring_water", 1)
        for m in members:
            db.update_character_by_id(m["character_id"], hp_current=m["hp_max"], spell_slots_current=m["spell_slots_max"])
        await _safe_send(
            update,
            f"💧 **{character['name']}** pours out a vial of spring water at the shrine. "
            f"The whole party is fully healed, spell slots restored.",
        )
        return
    for m in members:
        healed = (m["hp_max"] - m["hp_current"] + 1) // 2
        if healed > 0:
            db.update_character_by_id(m["character_id"], hp_current=min(m["hp_max"], m["hp_current"] + healed))
    await _safe_send(update, f"🕯️ **{character['name']}** prays quietly at the shrine. The party feels a little steadier.")


async def _do_give_offering(update: Update, text: str) -> None:
    """
    Per Coffee (2026-07-24): "a local church we can go to pray and give
    an offering to the dead which revives the characters too." Grounded
    in the Hollow Stump Shrine, an EXISTING location already described
    as a place where "offerings left here are never touched by
    animals" with a real "offering_line" interactable -- not an
    invented new church. A non-caster-accessible alternative to
    Revivify: costs real gold instead of a spell slot/scroll, but only
    works at this one real place, and (same as Revivify itself) only
    brings someone back at 1 HP -- the stronger full-heal-and-revive
    effect stays exclusive to the pricier Tent/Cabin/House items (see
    effect="heal_and_revive" in _do_use_item), so there's a real reason
    to pick one over the other rather than this just being a free copy.
    """
    character = db.get_character(update.effective_user.id, update.effective_chat.id)
    if character is None:
        await _safe_send(update, "You don't have a character yet!", speak=False)
        return
    if character["current_location"] == LABYRINTH_LOCATION_SENTINEL:
        await _do_labyrinth_checkpoint_offering(update, text)
        return
    # Real live follow-up (2026-08-30, dev-bridge, Coffee: "shudnt i be
    # able to pray at it?" -- the Ember Font, right after the drink_
    # water fix landed): this used to hardcode ONE literal location id,
    # but the Chapter 3-8 expansion has since built several other real,
    # hand-authored shrine rooms (the Weeping Spring, the Kept Shrine,
    # the Silent Shrine) with the same restorative purpose in their own
    # flavor text -- there's no real reason revival stays exclusive to
    # the original one. Generalized to a real "real_shrine" location
    # flag, same shape as drink_water's own "healing_water" flag, so
    # any future shrine just opts in with one line of data instead of
    # needing this function touched again.
    location = cl.get_location(CAMPAIGN, character["current_location"])
    if location is None or not location.get("real_shrine"):
        await _safe_send(update, "There's no shrine to give an offering at here.", speak=False)
        return
    # Real bug caught live (2026-07-24, Coffee: "she's currently dead"
    # but the shrine kept saying nobody was): _find_party_target_by_name
    # (like every OTHER caller of _get_party_members) only ever sees a
    # player's CURRENTLY ACTIVE character -- a real player who dies and
    # switches to another character in the meantime (their documented,
    # intended option while dead) makes their dead character invisible
    # to this lookup entirely, forever, since it's no longer anyone's
    # active slot. Scoped to the CALLER's own real party_id instead
    # (via the new inclusive lookup), so a dead party member still
    # shows up regardless of what their owner is currently playing.
    party_members = (
        db.get_party_members_by_id_including_inactive_slots(character["party_id"])
        if character.get("party_id") else []
    )
    # Real live bug (2026-08-06, Coffee via dev-topic screenshot: "It's
    # not letting me revive my player"): confirmed live -- his character
    # "Pan" died at The Colosseum with no party_id at all (party_id IS
    # NULL), so it was NEVER visible to this lookup no matter which of
    # his OTHER characters he brought to the shrine, since party_members
    # only ever reflects the CALLER's current party (and Pan wasn't in
    # one). A player's own dead alt characters need to always be
    # revivable here regardless of party membership -- merged in via
    # list_characters, deduped by character_id so a party member who's
    # ALSO the caller's own character isn't listed twice.
    own_characters = db.list_characters(update.effective_user.id, update.effective_chat.id)
    combined = {m["character_id"]: m for m in party_members}
    for c in own_characters:
        combined.setdefault(c["character_id"], c)
    party_members = list(combined.values())
    target = _match_member_by_name_or_username(text, party_members)
    if target is None or not target.get("is_dead"):
        # Real live bug (2026-07-24, Coffee: "I pray at the shrine" then
        # got told to name someone, but had already been trying to pray
        # FOR a specific fallen ally the whole time -- he just didn't
        # repeat her name in the exact same message as "pray"). When no
        # name is given, auto-resolve to the sole dead party member if
        # there's only one -- unambiguous by construction, same
        # "resolve automatically when there's only one real answer"
        # convention this codebase already uses elsewhere (_pick_target
        # defaulting to the only enemy present, single-word location
        # matching when it's the only candidate, etc.) -- only ask for a
        # name when there's genuine ambiguity (more than one fallen ally).
        dead_members = [m for m in party_members if m.get("is_dead")]
        if target is None and len(dead_members) == 1:
            target = dead_members[0]
        elif target is None and len(dead_members) > 1:
            # Per Coffee (2026-07-24: "make it so when i pray its for
            # all of them"): a prayer with no specific name now revives
            # every fallen party member in one offering instead of
            # asking which single one was meant -- naming someone
            # specifically (handled above) still targets just them.
            await _apply_shrine_offering_all(update, character, dead_members)
            return
        elif not dead_members:
            # Nobody to revive at all -- per Coffee, this is exactly when
            # the cheaper blessing applies instead of asking for a name
            # that doesn't exist to give.
            await _apply_shrine_blessing(update, character)
            return
        else:
            await _safe_send(update, "Name a dead party member to pray for — there's no one to bring back right now.", speak=False)
            return
    await _apply_shrine_offering(update, character, target)


async def _do_shrine_offering_menu(update: Update) -> None:
    """
    Per Coffee (2026-07-24): "in the shrine buttons when clicked show
    players who are dead and give a button so they can revive them" --
    the tap-driven counterpart to _do_give_offering's free-text path,
    listing every real fallen party member as its own tap-to-revive
    button instead of needing their name typed at all.
    """
    character = db.get_character(update.effective_user.id, update.effective_chat.id)
    if character is None:
        await _safe_send(update, "You don't have a character yet!", speak=False)
        return
    location = cl.get_location(CAMPAIGN, character["current_location"])
    if location is None or not location.get("real_shrine"):
        await _safe_send(update, "There's no shrine to give an offering at here.", speak=False)
        return
    # Same real bug/fix as _do_give_offering above -- _get_party_members
    # only ever shows a player's currently active character, so a dead
    # real player who's switched to a different one in the meantime
    # would never show up here at all.
    party_members = (
        db.get_party_members_by_id_including_inactive_slots(character["party_id"])
        if character.get("party_id") else []
    )
    # Real live bug (2026-08-06, Coffee: "It's not letting me revive my
    # player") -- same fix as _do_give_offering's identical merge above:
    # a dead character with no party_id at all (e.g. Pan, confirmed live)
    # was invisible here no matter which other character brought the
    # offering.
    own_characters = db.list_characters(update.effective_user.id, update.effective_chat.id)
    combined = {m["character_id"]: m for m in party_members}
    for c in own_characters:
        combined.setdefault(c["character_id"], c)
    party_members = list(combined.values())
    dead_members = [m for m in party_members if m.get("is_dead")]
    if not dead_members:
        # Nobody to revive -- offer the cheaper blessing instead (per
        # Coffee, 2026-07-24), same tap-driven convenience as the revive
        # buttons above rather than only being reachable via free text.
        await update.effective_chat.send_message(
            "No one to bring back right now — everyone in your party is alive and well.",
            reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton(
                f"💧 Bless the Party ({HOLLOW_STUMP_SHRINE_BLESSING_COST}g)", callback_data="shrine|bless",
            )]]),
            message_thread_id=topics.thread_id_for(update.effective_chat.id, "adventure"),
        )
        return
    rows = [
        [InlineKeyboardButton(
            f"🕯️ Revive {m['name']} ({HOLLOW_STUMP_SHRINE_OFFERING_COST}g)",
            # character_id, not telegram_user_id (2026-07-24, same
            # incident as update_character_by_id): a dead party member
            # might not be their owner's active character right now --
            # exactly the case this whole feature exists for -- so the
            # tap target has to be resolved by exact character_id, never
            # "whichever character is active for this owner".
            callback_data=f"shrine|revive|{m['character_id']}",
        )]
        for m in dead_members
    ]
    if len(dead_members) > 1:
        # Per Coffee (2026-07-24: "make it so when i pray its for all
        # of them"; 2026-07-25: flat cost, not per-person): the same
        # all-at-once revival free text now offers, as a real tap, for
        # one flat HOLLOW_STUMP_SHRINE_OFFERING_COST no matter how many
        # are down.
        rows.append([InlineKeyboardButton(
            f"🕯️ Revive All ({HOLLOW_STUMP_SHRINE_OFFERING_COST}g)", callback_data="shrine|revive_all",
        )])
    await update.effective_chat.send_message(
        f"Who do you want to pray for? The offering calls for {HOLLOW_STUMP_SHRINE_OFFERING_COST} gold.",
        reply_markup=InlineKeyboardMarkup(rows),
        message_thread_id=topics.thread_id_for(update.effective_chat.id, "adventure"),
    )


async def shrine_menu_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Handles taps on _do_shrine_offering_menu's Revive rows -- dispatches through the exact same real offering logic free text already uses."""
    query = update.callback_query
    parts = (query.data or "").split("|")
    action = parts[1] if len(parts) > 1 else ""
    await _safe_answer(query)
    character = db.get_character(update.effective_user.id, update.effective_chat.id)
    if character is None:
        return
    if action == "bless":
        await _apply_shrine_blessing(update, character)
        return
    if action == "revive_all":
        party_members = (
            db.get_party_members_by_id_including_inactive_slots(character["party_id"])
            if character.get("party_id") else []
        )
        dead_members = [m for m in party_members if m.get("is_dead")]
        if not dead_members:
            await update.effective_chat.send_message(
                "No one left to bring back — everyone in your party is alive and well.",
                message_thread_id=topics.thread_id_for(update.effective_chat.id, "adventure"),
            )
            return
        await _apply_shrine_offering_all(update, character, dead_members)
        return
    if action != "revive" or len(parts) < 3:
        return
    target = db.get_character_by_id(int(parts[2]))
    if target is None or not target.get("is_dead"):
        await update.effective_chat.send_message(
            "That party member isn't waiting to be revived anymore.",
            message_thread_id=topics.thread_id_for(update.effective_chat.id, "adventure"),
        )
        return
    await _apply_shrine_offering(update, character, target)


def _bless_present_party_to_full(character: dict, exclude_character_ids: set[int] | int | None = None) -> list[str]:
    """
    Heals every real party member actually AT the shrine right now (same
    party_id, same current_location -- identical "physically present"
    scoping to _do_use_item's heal_and_revive multi-target case) to full
    HP, via update_character_by_id so this never accidentally lands on
    whichever character an owner currently has active instead of the
    one actually standing there. exclude_character_ids skips anyone
    already handled elsewhere (the just-revived target(s) in
    _apply_shrine_offering/_apply_shrine_offering_all, healed there with
    their own message) -- a single int or a set of them. Returns one
    "Name (X/X HP)" line per person actually healed, for narration.
    """
    if isinstance(exclude_character_ids, int):
        exclude_character_ids = {exclude_character_ids}
    exclude_character_ids = exclude_character_ids or set()
    present = [
        p for p in _get_combat_eligible_party_members(character["current_location"], character["chat_id"])
        if character.get("party_id") and p.get("party_id") == character["party_id"]
    ] or [character]
    lines = []
    for member in present:
        if member["character_id"] in exclude_character_ids:
            continue
        hp_max = member.get("hp_max", member["hp_current"])
        db.update_character_by_id(member["character_id"], hp_current=hp_max)
        lines.append(f"**{member['name']}** ({hp_max}/{hp_max} HP)")
    return lines


async def _apply_shrine_offering(update: Update, character: dict, target: dict) -> None:
    """
    Shared real logic behind both the shrine's free-text prayer and its
    tap-to-revive buttons -- gold cost, the actual revival, then (per
    Coffee, 2026-07-24: "make it so we cant... heal the players party
    in full after reviving") blessing the whole present party to full
    HP in the same offering, not just the one person prayed for.
    """
    if character["gold"] < HOLLOW_STUMP_SHRINE_OFFERING_COST:
        await update.effective_chat.send_message(
            f"The offering calls for {HOLLOW_STUMP_SHRINE_OFFERING_COST} gold — "
            f"you only have {character['gold']}.",
            message_thread_id=topics.thread_id_for(update.effective_chat.id, "adventure"),
        )
        return
    db.update_character(character["telegram_user_id"], update.effective_chat.id, gold=character["gold"] - HOLLOW_STUMP_SHRINE_OFFERING_COST)
    # Real bug caught live (2026-07-24): update_character always writes
    # to whichever character is CURRENTLY ACTIVE for a telegram_user_id
    # -- if target isn't their owner's active slot (exactly the case
    # this whole fix exists for), this would silently revive the WRONG,
    # already-alive character instead while claiming success. Targets
    # the exact character_id directly. Revives straight to full HP
    # (not the old 1-HP trickle) since the same offering now blesses
    # the whole party to full anyway.
    target_hp_max = target.get("hp_max", target["hp_current"])
    db.update_character_by_id(
        target["character_id"], is_dead=0, hp_current=target_hp_max, died_at=None,
        death_save_successes=0, death_save_failures=0,
    )
    _maybe_boost_companion_affinity_for_support(update, character, target, 10, "revived")
    rest_of_party = _bless_present_party_to_full(character, exclude_character_ids=target["character_id"])
    blessing_note = f" The rest of the party is blessed to full HP too: {'; '.join(rest_of_party)}." if rest_of_party else ""
    await _safe_send(
        update,
        f"🕯️ **{character['name']}** kneels at the shrine and lays {HOLLOW_STUMP_SHRINE_OFFERING_COST} gold "
        f"among the offerings, praying for **{target['name']}**'s return — breath returns, and they're "
        f"restored to full ({target_hp_max}/{target_hp_max} HP).{blessing_note}",
    )


async def _apply_shrine_offering_all(update: Update, character: dict, dead_members: list[dict]) -> None:
    """
    Per Coffee (2026-07-24: "make it so when i pray its for all of
    them"; cost fixed 2026-07-25: "i want it to cost 100 in total for
    the whole party") -- a prayer at the shrine with more than one
    fallen party member and no specific name now revives every one of
    them in a single offering, rather than asking which single one was
    meant, for one flat HOLLOW_STUMP_SHRINE_OFFERING_COST regardless of
    how many are down -- not per person. Same full-party blessing as
    the single-target path once everyone named is back up.
    """
    total_cost = HOLLOW_STUMP_SHRINE_OFFERING_COST
    if character["gold"] < total_cost:
        await update.effective_chat.send_message(
            f"Reviving the whole party calls for {total_cost} gold — "
            f"you only have {character['gold']}.",
            message_thread_id=topics.thread_id_for(update.effective_chat.id, "adventure"),
        )
        return
    db.update_character(character["telegram_user_id"], update.effective_chat.id, gold=character["gold"] - total_cost)
    revived_lines = []
    revived_ids = set()
    for target in dead_members:
        target_hp_max = target.get("hp_max", target["hp_current"])
        db.update_character_by_id(
            target["character_id"], is_dead=0, hp_current=target_hp_max, died_at=None,
            death_save_successes=0, death_save_failures=0,
        )
        revived_lines.append(f"**{target['name']}** ({target_hp_max}/{target_hp_max} HP)")
        revived_ids.add(target["character_id"])
        _maybe_boost_companion_affinity_for_support(update, character, target, 10, "revived")
    rest_of_party = _bless_present_party_to_full(character, exclude_character_ids=revived_ids)
    blessing_note = f" The rest of the party is blessed to full HP too: {'; '.join(rest_of_party)}." if rest_of_party else ""
    await _safe_send(
        update,
        f"🕯️ **{character['name']}** kneels at the shrine and lays {total_cost} gold among the offerings, "
        f"praying for everyone fallen to return — breath returns to each of them: "
        f"{'; '.join(revived_lines)}.{blessing_note}",
    )


async def _apply_shrine_blessing(update: Update, character: dict) -> None:
    """
    The no-one's-dead alternative to _apply_shrine_offering (per Coffee:
    "if no players need reiving u can offer a blessing for cheaper to
    heal the party to full like 'holy water'") -- same shrine, cheaper
    real gold cost, heals the whole present party to full HP with
    nothing to revive.
    """
    if character["gold"] < HOLLOW_STUMP_SHRINE_BLESSING_COST:
        await update.effective_chat.send_message(
            f"The blessing calls for {HOLLOW_STUMP_SHRINE_BLESSING_COST} gold — "
            f"you only have {character['gold']}.",
            message_thread_id=topics.thread_id_for(update.effective_chat.id, "adventure"),
        )
        return
    db.update_character(character["telegram_user_id"], update.effective_chat.id, gold=character["gold"] - HOLLOW_STUMP_SHRINE_BLESSING_COST)
    healed = _bless_present_party_to_full(character)
    healed_note = "; ".join(healed) if healed else f"**{character['name']}**"
    await _safe_send(
        update,
        f"💧 **{character['name']}** offers {HOLLOW_STUMP_SHRINE_BLESSING_COST} gold for a blessing of holy "
        f"water at the shrine — the party is healed to full: {healed_note}.",
    )


async def _do_equip_item(update: Update, text: str) -> None:
    """
    Real bug from the same reverse-playthrough finding as _do_use_item
    (2026-07-15): items.py's weapon (damage_dice/ability), armor
    (ac_base), and shield (ac_bonus) fields existed the whole time but
    nothing ever equipped anything, so combat always used one
    hardcoded default weapon and armor_class never changed after
    character creation regardless of what was bought. db.equip_item
    does the real work (validation, armor_class recompute); this just
    parses which item, and for whom, from free text.

    Supports helping another party member gear up too (per Coffee:
    "equip Sarah with the longbow") -- same location-scoped "physically
    present" lookup as _do_give_item, defaulting to the caller's own
    character when no other real party member is named. The item comes
    from the TARGET's own inventory, not the caller's -- this is
    "help them equip what they're already carrying," not a transfer.
    """
    character = db.get_character(update.effective_user.id, update.effective_chat.id)
    if character is None:
        await update.effective_chat.send_message(
            "You don't have a character yet!", message_thread_id=topics.thread_id_for(update.effective_chat.id, "adventure")
        )
        return

    target = character
    others = [
        p for p in _get_combat_eligible_party_members(character["current_location"], character["chat_id"])
        if p["telegram_user_id"] != character["telegram_user_id"]
    ]
    named_other = _match_member_by_name_or_username(text, others)
    if named_other is not None:
        target = named_other

    equippable_ids = [
        item_id for item_id in target["inventory"]
        if (items_module.get_item(item_id) or {}).get("type") in ("weapon", "armor", "shield", "ring", "amulet", "wondrous")
    ]
    items_wanted = _extract_item_list(text, equippable_ids)
    if not items_wanted:
        who = "you" if target is character else target["name"]
        await update.effective_chat.send_message(
            f"Equip what, exactly? Name a weapon, armor, shield, ring, amulet, or wondrous item "
            f"{who} actually {'are' if who == 'you' else 'is'} carrying.",
            message_thread_id=topics.thread_id_for(update.effective_chat.id, "adventure"),
        )
        return

    prefix = "" if target is character else f"**{target['name']}**: "
    lines = []
    equipped_item_ids = []
    for item_id, _quantity in items_wanted:
        success, message, updated = db.equip_item(target["telegram_user_id"], update.effective_chat.id, item_id)
        lines.append(f"⚔️ {prefix}{message}" if success else message)
        if success:
            equipped_item_ids.append(item_id)
            # Real live bug fix (2026-08-20, Charvenna) -- see
            # _sync_live_combat_equipment's own docstring.
            if updated:
                _sync_live_combat_equipment(target["telegram_user_id"], update.effective_chat.id, updated)
    await _safe_send(update, "\n".join(lines))
    for item_id in equipped_item_ids:
        item_data = items_module.get_item(item_id)
        if item_data:
            await _maybe_send_item_image(update, item_id, item_data)
    await _check_and_award_achievements(update, db.get_character(target["telegram_user_id"], update.effective_chat.id))


