async def _do_unequip_item(update: Update, text: str) -> None:
    """
    Real, previously-missing feature (2026-08-02, magic item system
    Phase 5): a player could equip a ring/amulet/wondrous item but never
    take it back off -- confirmed by grep before this, no such code path
    existed anywhere. Needed for a set bonus to be meaningfully real (a
    bonus that could only ever be gained, never lost, would have no
    trustworthy "off" state), but genuinely useful on its own too.
    Accessories only for now, same scope db.unequip_accessory's own
    docstring explains -- weapon/armor/shield are single-slot columns
    already correctly replaced by equipping something else.
    """
    character = db.get_character(update.effective_user.id, update.effective_chat.id)
    if character is None:
        await update.effective_chat.send_message(
            "You don't have a character yet!", message_thread_id=topics.thread_id_for(update.effective_chat.id, "adventure")
        )
        return

    worn_ids = character.get("equipped_accessories", [])
    items_wanted = _extract_item_list(text, worn_ids)
    if not items_wanted:
        await update.effective_chat.send_message(
            "Take off what, exactly? Name a ring, amulet, or wondrous item you're actually wearing.",
            message_thread_id=topics.thread_id_for(update.effective_chat.id, "adventure"),
        )
        return

    lines = []
    for item_id, _quantity in items_wanted:
        success, message, updated = db.unequip_accessory(update.effective_user.id, update.effective_chat.id, item_id)
        lines.append(f"🎽 {message}" if success else message)
        # Real live bug fix (2026-08-20, Charvenna) -- see
        # _sync_live_combat_equipment's own docstring.
        if success and updated:
            _sync_live_combat_equipment(update.effective_user.id, update.effective_chat.id, updated)
    await _safe_send(update, "\n".join(lines))


_AUTO_EQUIP_PARTY_WORDS = ["party", "everyone", "everybody", "all of us", "the team", "my group"]


async def _do_auto_equip_gear(update: Update, text: str) -> None:
    """
    Auto-equip (2026-07-15, per Coffee): picks the real best weapon/
    armor/shield out of whatever's actually carried and equips all of
    them, via db.auto_equip_best_gear -- so a player doesn't need to
    know every item's exact damage die or AC to get sensible gear on.
    Supports naming another real party member ("help Borin gear up"),
    same location-scoped lookup as _do_equip_item/_do_give_item.

    Extended (2026-07-24, per Coffee: "make it so we can say 'auto
    equip' the party"): "auto equip the party"/"equip everyone" runs
    this for every combat-eligible party member at once (self plus any
    present companions, real or AI) instead of requiring one name at a
    time -- checked before the single-name match below so a party
    member who happens to share a word with these phrases (unlikely,
    but same discipline as other ambiguous-phrase fixes in this file)
    doesn't accidentally shadow it.
    """
    character = db.get_character(update.effective_user.id, update.effective_chat.id)
    if character is None:
        await update.effective_chat.send_message(
            "You don't have a character yet!", message_thread_id=topics.thread_id_for(update.effective_chat.id, "adventure")
        )
        return

    others = [
        p for p in _get_combat_eligible_party_members(character["current_location"], character["chat_id"])
        if p["telegram_user_id"] != character["telegram_user_id"]
    ]

    lowered = text.lower()
    if any(w in lowered for w in _AUTO_EQUIP_PARTY_WORDS):
        lines = []
        for member in [character] + others:
            summary, _ = db.auto_equip_best_gear(member["telegram_user_id"], update.effective_chat.id)
            prefix = "" if member is character else f"**{member['name']}**: "
            lines.append(f"⚔️ {prefix}{summary}")
            await _check_and_award_achievements(update, db.get_character(member["telegram_user_id"], update.effective_chat.id))
        await _safe_send(update, "\n".join(lines))
        return

    target = character
    named_other = _match_member_by_name_or_username(text, others)
    if named_other is not None:
        target = named_other

    summary, _ = db.auto_equip_best_gear(target["telegram_user_id"], update.effective_chat.id)
    prefix = "" if target is character else f"**{target['name']}**: "
    await _safe_send(update, f"⚔️ {prefix}{summary}")
    await _check_and_award_achievements(update, db.get_character(target["telegram_user_id"], update.effective_chat.id))


_QUANTITY_WORDS = {
    "one": 1, "couple": 2, "two": 2, "three": 3, "four": 4,
    "five": 5, "six": 6, "seven": 7, "eight": 8, "nine": 9, "ten": 10,
}


_ITEM_LIST_SPLIT_PATTERN = re.compile(r",\s*(?:and\s+)?|\s+and\s+")


def _extract_item_list(text: str, candidate_ids: list[str]) -> list[tuple[str, int]]:
    """
    Real fix for task #147 (2026-07-17, live-confirmed by Coffee):
    "Buy 10 torches, 1 shears, 1 pickaxe, 1 fishing pole, 5 bait." used
    to only ever buy the torches -- find_item_mentioned_in_text and
    _extract_quantity each only ever resolve ONE match for a whole
    message, and ai/intent_parser.py's compound-message splitter used
    to mis-route the other bare "<qty> <item>" segments into unrelated
    actions (one even misfired as "gather" -- "1 pickaxe" contains
    "pick"). parse_intents now keeps a shopping-list message as ONE
    action instead of splitting it; this is the other half -- splitting
    the raw text into per-item phrases the same way a shopping list
    reads, and resolving each phrase's own item + quantity independently
    so every item actually named gets processed, not just the first.
    A plain single-item message (no comma/"and") is one "phrase" and
    behaves exactly as before.
    """
    phrases = [p.strip() for p in _ITEM_LIST_SPLIT_PATTERN.split(text) if p.strip()]
    pairs: list[tuple[str, int]] = []
    for phrase in phrases:
        item_id = items_module.find_item_mentioned_in_text(phrase, candidate_ids=candidate_ids)
        if item_id is None:
            continue
        quantity = _extract_quantity(phrase)
        pairs.append((item_id, quantity))
    return pairs


def _extract_quantity(text: str) -> int:
    """
    Real number of items to buy/sell mentioned anywhere in the sentence,
    e.g. "buy two potions" -> 2, "sell 3 rations" -> 3. Confirmed live
    2026-07-12: _do_buy/_do_sell always silently bought/sold exactly 1
    regardless of what the player actually said (shop.buy_item/sell_item
    already fully support a real quantity, this was purely a wiring gap
    -- the number was just never read out of the text). Defaults to 1,
    the previous behavior, when no number is found. Deliberately no
    "a"/"an" entry -- since the default is already 1, adding them would
    only risk shadowing a REAL number word appearing later in the same
    sentence (e.g. "buy a couple potions" stopping at "a" before ever
    reaching "couple").
    """
    words = [w.strip(".,!?").lower() for w in text.split()]
    for word in words:
        if word.isdigit():
            return max(1, int(word))
    for word in words:
        if word in _QUANTITY_WORDS:
            return _QUANTITY_WORDS[word]
    return 1


def _shop_keyboard(shop_data: dict) -> InlineKeyboardMarkup | None:
    """
    Task #176 (per Coffee: extend the battle-menu button pattern to
    out-of-combat browsing surfaces) -- one button per real stocked item,
    grounded in the same shop_data/items.py lookup _do_list_shop already
    uses right above. Tapping dispatches through the SAME _do_buy handler
    free-text "buy X" already uses (see shop_menu_callback below), never
    duplicated purchase logic. Own callback-data namespace ("shop|", not
    "bm|") so this can never collide with the combat battle menu.
    """
    buttons = []
    for item_id in shop_data["inventory"]:
        item = items_module.get_item(item_id)
        if item:
            buttons.append([InlineKeyboardButton(
                f"{item['name']} — {item['price']}g", callback_data=f"shop|qty|{item_id}",
            )])
    if buttons:
        # Per Coffee (2026-07-25): "make sure players that can steal...
        # has buttons they can use to do these things" -- a real tap,
        # dispatching through the exact same _do_steal free text already
        # uses (own DC roll, own real ban-on-failure consequence, no
        # shortcut around any of it).
        buttons.append([InlineKeyboardButton("🗝️ Steal Something", callback_data="shop|steal")])
    return InlineKeyboardMarkup(buttons) if buttons else None


def _quantity_keyboard(item_id: str) -> InlineKeyboardMarkup:
    """
    Per Coffee (2026-07-20): "when they select the item can you prompt
    with click buttons for those selections" -- picking an item in the
    shop now asks HOW MANY via real tap buttons instead of always
    buying a single one, same reuse-the-existing-handler pattern as
    every other button in this game (_do_buy already parses "buy 5 X").
    """
    return InlineKeyboardMarkup([[
        InlineKeyboardButton(str(qty), callback_data=f"shop|buy|{item_id}|{qty}")
        for qty in (1, 5, 10)
    ]])


async def shop_menu_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """
    Handles taps on _shop_keyboard/_quantity_keyboard. Re-resolves the
    shop from the TAPPER's own current location (never trusts anything
    about the shop from the button itself) so this behaves identically
    to typing "buy X" -- same real _do_buy handler, same stock/gold/
    inventory checks. Tapping an item first shows a quantity picker
    (1/5/10); tapping a quantity actually buys.
    """
    query = update.callback_query
    parts = (query.data or "").split("|")
    action = parts[1] if len(parts) > 1 else ""
    item_id = parts[2] if len(parts) > 2 else None
    await _safe_answer(query)
    if action == "steal":
        await _do_steal(update, "")
        return
    item = items_module.get_item(item_id) if item_id else None
    if item is None:
        return
    if action == "qty":
        await _safe_send(update, f"How many {item['name']}?", reply_markup=_quantity_keyboard(item_id))
        return
    if action == "buy":
        qty = int(parts[3]) if len(parts) > 3 else 1
        await _do_buy(update, f"buy {qty} {item['name']}")


def _market_sell_picker_keyboard(character: dict) -> InlineKeyboardMarkup | None:
    """
    One button per carried item. Routes to market|sellpick|<id> (NOT
    itemview_callback's fixed qty=1 "market" action) so a stackable
    item (Silverleaf Herb, etc.) can actually be sold as more than a
    single unit -- see market_menu_callback's "sellpick" branch and
    _PENDING_MARKET_SELL's own comment for the real quantity+price
    prompt this leads into.

    Real live report (2026-08-20, Coffee, screenshot): a long generated
    item name (e.g. "Frostwoven Chain Mail Armor of the Tempest") plus
    the "💰 " emoji plus a "(have 1)" suffix on EVERY row overflowed
    Telegram's button width and got truncated mid-word ("Frostwoven
    Ch...Tempest"), hiding the exact name a player needs to pick the
    right item. Dropped the emoji and only show "(have N)" when N > 1
    -- the common case is a single unique piece of gear, where "(have
    1)" was pure redundant padding, not real information; a genuinely
    stacked item (Silverleaf Herb x5) still shows its real count, since
    that IS decision-relevant there. Every character byte given back
    to the real item name reduces truncation risk on real device
    widths -- there's no way to guarantee zero truncation for an
    arbitrarily long generated name inside a fixed-width Telegram
    button, so this is a real, meaningful reduction, not a full fix.
    """
    if not character.get("inventory"):
        return None
    buttons = [
        [InlineKeyboardButton(
            f"{items_module.get_item(item_id)['name']}" + (f" (have {qty})" if qty > 1 else ""),
            callback_data=f"market|sellpick|{item_id}",
        )]
        for item_id, qty in character["inventory"].items() if qty > 0 and items_module.get_item(item_id)
    ]
    return InlineKeyboardMarkup(buttons) if buttons else None


def _format_market_listing_detail(listing: dict) -> str | None:
    """
    Full item-detail view for a market listing (2026-08-20, per Coffee:
    "we also need to be able to full view the items on market too --
    all stats, buffs, elements, + to stats, seller, cost of the item,
    and requirements to equip"). Reuses _format_item_detail_block
    verbatim for the item's own real stats/bonuses/requirements (same
    grounded data the 🎒 Items "show" view already renders -- never a
    second, drifting item-description path), then appends the two
    facts that are genuinely listing-specific, not item-specific:
    who's selling it and what it costs.
    """
    item = items_module.get_item(listing["item_id"])
    if item is None:
        return None
    detail = _format_item_detail_block(item)
    header = f"🔍 **{listing['quantity']}x {item['name']}**"
    footer = f"\n\n🏷️ **{listing['price']} gold** total — seller: **{listing['seller_name']}** (listing #{listing['listing_id']})"
    return f"{header}\n{detail}{footer}" if detail else f"{header}{footer}"


async def market_menu_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """
    Handles taps on _market_keyboard -- dispatches through the same
    _do_buy_market/_do_cancel_market a typed "/buy_market <#>"/
    "/cancel_market <#>" already use. Extended 2026-08-20 (per Coffee's
    real buy/sell/unlist/search/full-view button request) with unlist,
    sell (item picker -> reuses itemview_callback's existing real
    "market" action, not a second listing code path), filter, view, and
    (same day, live follow-up) sellerfilter/"My Listings".
    """
    query = update.callback_query
    parts = (query.data or "").split("|")
    action = parts[1] if len(parts) > 1 else ""
    await _safe_answer(query)

    if action == "buy" and len(parts) >= 3:
        await _do_buy_market(update, [parts[2]])
        return

    if action == "unlist" and len(parts) >= 3:
        await _do_cancel_market(update, [parts[2]])
        return

    if action == "filter":
        filter_type = parts[2] if len(parts) > 2 else "all"
        await _do_check_market(update, filter_type=None if filter_type == "all" else filter_type)
        return

    if action == "sellerfilter" and len(parts) >= 3:
        await _do_check_market(update, filter_seller_id=int(parts[2]))
        return

    if action == "view" and len(parts) >= 3:
        listing = db.get_market_listing(int(parts[2]), update.effective_chat.id)
        if listing is None:
            await _safe_send(update, "That listing doesn't exist — it may have already been bought or cancelled.")
            return
        detail = _format_market_listing_detail(listing)
        await _safe_send(update, detail or "That item no longer exists.", speak=False)
        return

    if action == "sell":
        character = db.get_character(update.effective_user.id, update.effective_chat.id)
        keyboard = _market_sell_picker_keyboard(character) if character else None
        if keyboard is None:
            await _safe_send(update, "You don't have anything in your backpack to list right now.")
            return
        await _safe_send(
            update, "Which item would you like to list on the market?", reply_markup=keyboard,
        )
        return

    if action == "sellpick" and len(parts) >= 3:
        item_id = parts[2]
        item = items_module.get_item(item_id)
        character = db.get_character(update.effective_user.id, update.effective_chat.id)
        held = character["inventory"].get(item_id, 0) if character else 0
        if item is None or held <= 0:
            await _safe_send(update, "You don't have that item anymore.")
            return
        _chat_scoped_dict(_PENDING_MARKET_SELL, update.effective_chat.id)[update.effective_user.id] = item_id
        await _safe_send(
            update,
            f"How many **{item['name']}** (you have {held}), and for how much total gold? Reply like "
            f"\"3 for 50 gold\" to sell 3 for 50g total, or \"50 gold\" to sell 1 for 50g.",
        )


async def _do_list_shop(update: Update) -> None:
    """
    Real shop-browse action (2026-07-16, per Coffee): lists a shop's
    ACTUAL stocked items (real names/prices from items.py), grounded,
    not invented -- confirmed live the same night that with no such
    action to reach for, "I want to shop" was silently swallowed as
    chat and "I want to see the items in the shop" got guessed by the
    raw model as check_sheet with a hallucinated target name. buy_item
    still handles purchasing a SPECIFIC named item; this just answers
    "what do you even have."
    """
    character = db.get_character(update.effective_user.id, update.effective_chat.id)
    if character is None:
        await update.effective_chat.send_message(
            "You don't have a character yet!", message_thread_id=topics.thread_id_for(update.effective_chat.id, "adventure")
        )
        return
    location = cl.get_location(CAMPAIGN, character["current_location"])
    shop_id = location.get("shop") if location else None
    if not shop_id:
        await update.effective_chat.send_message(
            "There's no shop here.", message_thread_id=topics.thread_id_for(update.effective_chat.id, "adventure")
        )
        return
    shop_data = cl.get_shop(CAMPAIGN, shop_id)
    # Real gap (2026-08-20, per Coffee: "when we visit shops show how
    # much gold we have somewhere (its not shown as far as i know)")
    # -- confirmed true: this screen listed every real price but never
    # the player's own real gold to weigh them against.
    lines = [
        f"🛒 **{cl.get_location(CAMPAIGN, character['current_location'])['name']}**",
        f"💰 Your gold: {character['gold']}",
    ]
    if shop_data.get("description"):
        lines.append(shop_data["description"])
    # Per Coffee (2026-07-21): "make different shops for the
    # appropriate items (weapons, armour, Magic, General Items)...
    # describe the stalls and say what each store is." Rather than
    # splitting one location into several separately-walkable shops (a
    # bigger change to the one-shop-per-location structure this whole
    # game already relies on), this groups a shop's real stock into
    # real labeled sections -- the same effect players actually asked
    # for (a Maren's Wares that clearly separates its weapon rack from
    # its armor rack from its general goods) without touching how
    # buying/location resolution work at all.
    for header, item_ids in _grouped_shop_inventory(shop_data["inventory"]).items():
        lines.append(f"\n{header}")
        for item_id in item_ids:
            item = items_module.get_item(item_id)
            lines.append(f"{item['name']} — {item['price']} gold")
    await _safe_send(update, "\n".join(lines), reply_markup=_shop_keyboard(shop_data), speak=False)


_SHOP_SECTION_FOR_TYPE = {
    "weapon": "⚔️ Weapons",
    "armor": "🛡️ Armor & Shields",
    "shield": "🛡️ Armor & Shields",
    "tool": "🧰 Tools",
    "consumable": "🧪 Consumables",
    "scroll": "📜 Scrolls",
    "ring": "🔮 Magic Items",
    "amulet": "🔮 Magic Items",
    "wondrous": "🔮 Magic Items",
    "map": "🗺️ Maps",
}
_SHOP_SECTION_ORDER = [
    "⚔️ Weapons", "🛡️ Armor & Shields", "🧰 Tools", "🧪 Consumables",
    "📜 Scrolls", "🔮 Magic Items", "🗺️ Maps", "📦 Other",
]


def _grouped_shop_inventory(item_ids: list[str]) -> dict[str, list[str]]:
    """Groups a shop's real inventory by item type into real, labeled sections, always in the same reader-friendly order."""
    sections: dict[str, list[str]] = {}
    for item_id in item_ids:
        item = items_module.get_item(item_id)
        if not item:
            continue
        header = _SHOP_SECTION_FOR_TYPE.get(item.get("type"), "📦 Other")
        sections.setdefault(header, []).append(item_id)
    return {header: sections[header] for header in _SHOP_SECTION_ORDER if header in sections}


async def _do_buy(update: Update, text: str) -> None:
    character = db.get_character(update.effective_user.id, update.effective_chat.id)
    if character is None:
        await update.effective_chat.send_message(
            "You don't have a character yet!", message_thread_id=topics.thread_id_for(update.effective_chat.id, "adventure")
        )
        return
    # Labyrinth checkpoint/rest-stop shop (2026-09-08, task #5): a
    # Labyrinth room's own "shop" field (the checkpoint's real
    # wandering-trader shop, and now a rest stop's identical one) was
    # never actually reachable via this real buy path before -- it only
    # ever checked cl.get_location, a CAMPAIGN lookup that always
    # returns None for the Labyrinth's sentinel current_location.
    if character["current_location"] == LABYRINTH_LOCATION_SENTINEL:
        run = db.get_labyrinth_run(update.effective_chat.id, _labyrinth_party_key(character))
        room = run["rooms"].get(run["current_room_id"]) if run else None
        shop_id = room.get("shop") if room else None
    else:
        location = cl.get_location(CAMPAIGN, character["current_location"])
        shop_id = location.get("shop") if location else None
    if not shop_id:
        await update.effective_chat.send_message(
            "There's no shop here.", message_thread_id=topics.thread_id_for(update.effective_chat.id, "adventure")
        )
        return
    shop_data = cl.get_shop(CAMPAIGN, shop_id)

    items_wanted = _extract_item_list(text, shop_data["inventory"])
    if not items_wanted:
        await update.effective_chat.send_message(
            "Not sure what item you mean — try naming it more directly.",
            message_thread_id=topics.thread_id_for(update.effective_chat.id, "adventure"),
        )
        return

    # Names the buyer explicitly (task #139, 2026-07-17, per Coffee):
    # "Bought 10x Torch for 10 gold" reads fine in a 1:1 test but is
    # genuinely ambiguous the moment more than one player is shopping in
    # the same busy chat -- same "who does 'you' mean" problem already
    # fixed for combat/skill-check narration (#107/#115).
    if len(items_wanted) == 1:
        item_id, quantity = items_wanted[0]
        ok, msg = shop_module.buy_item(update.effective_user.id, update.effective_chat.id, shop_data, item_id, quantity)
        await _safe_send(update, f"🛒 **{character['name']}**: {msg}")
        return

    lines = []
    for item_id, quantity in items_wanted:
        ok, msg = shop_module.buy_item(update.effective_user.id, update.effective_chat.id, shop_data, item_id, quantity)
        lines.append(msg)
    await _safe_send(update, f"🛒 **{character['name']}**:\n" + "\n".join(lines))


async def _do_sell(update: Update, text: str) -> None:
    character = db.get_character(update.effective_user.id, update.effective_chat.id)
    if character is None:
        await update.effective_chat.send_message(
            "You don't have a character yet!", message_thread_id=topics.thread_id_for(update.effective_chat.id, "adventure")
        )
        return

    items_wanted = _extract_item_list(text, list(character["inventory"].keys()))
    items_wanted = [(item_id, qty) for item_id, qty in items_wanted if item_id in character["inventory"]]
    if not items_wanted:
        await update.effective_chat.send_message(
            "You're not carrying anything by that name.", message_thread_id=topics.thread_id_for(update.effective_chat.id, "adventure")
        )
        return

    if len(items_wanted) == 1:
        item_id, quantity = items_wanted[0]
        ok, msg = shop_module.sell_item(update.effective_user.id, update.effective_chat.id, item_id, quantity)
        await _safe_send(update, f"🛒 **{character['name']}**: {msg}")
        return

    lines = []
    for item_id, quantity in items_wanted:
        ok, msg = shop_module.sell_item(update.effective_user.id, update.effective_chat.id, item_id, quantity)
        lines.append(msg)
    await _safe_send(update, f"🛒 **{character['name']}**:\n" + "\n".join(lines))


async def _do_steal(update: Update, text: str, forced_roll: int | None = None) -> None:
    """
    A real, dice-resolved theft attempt (DC 15 — harder than an ordinary
    skill check) with a genuine, persistent consequence on failure: the
    shopkeeper bans this player from their shop forever (db.set_banned_
    by_npc, enforced in shop.buy_item), their affinity toward this
    player craters, the specific event is remembered (db.adjust_affinity's
    `event`), and their whole faction's standing with this player drops.
    Success carries no penalty — nobody noticed.
    """
    telegram_user_id = update.effective_user.id
    character = db.get_character(telegram_user_id, update.effective_chat.id)
    if character is None:
        await update.effective_chat.send_message(
            "You don't have a character yet!", message_thread_id=topics.thread_id_for(update.effective_chat.id, "adventure")
        )
        return

    # Enemy pickpocketing (2026-08-11, per Coffee: "give every enemy a
    # stealable item... make it hard to steal but allow a proficiency to
    # level up"). Checked BEFORE the shop-only logic below -- a player
    # mid-fight typing "steal" obviously means the enemy in front of
    # them, not a shop that may not even be at this location.
    session = sessions.get_session_for_user(update.effective_chat.id, telegram_user_id)
    if session is not None and telegram_user_id in session.turn_order:
        await _do_steal_from_enemy(update, character, session, text, forced_roll)
        return

    location = cl.get_location(CAMPAIGN, character["current_location"])
    shop_id = location.get("shop") if location else None
    if not shop_id:
        await update.effective_chat.send_message(
            "There's nothing here worth stealing.", message_thread_id=topics.thread_id_for(update.effective_chat.id, "adventure")
        )
        return

    shop_data = cl.get_shop(CAMPAIGN, shop_id)
    owner_npc = shop_data.get("owner_npc")
    owner_name = CAMPAIGN["npcs"][owner_npc]["name"] if owner_npc else "the shopkeeper"

    if owner_npc and db.is_banned_by_npc(telegram_user_id, update.effective_chat.id, owner_npc):
        await update.effective_chat.send_message(
            f"{owner_name} is already watching you like a hawk after last time — not worth the risk.",
            message_thread_id=topics.thread_id_for(update.effective_chat.id, "adventure"),
        )
        return

    item_id = items_module.find_item_mentioned_in_text(text, candidate_ids=shop_data["inventory"])
    if item_id is None:
        item_id = min(shop_data["inventory"], key=lambda i: items_module.get_item(i).get("price", 0))
    item = items_module.get_item(item_id)

    if forced_roll is None and character.get("manual_dice_enabled") and not character.get("is_ai"):
        forced_roll = _extract_combined_roll(text)
    if forced_roll is None and character.get("manual_dice_enabled") and not character.get("is_ai"):
        _chat_scoped_dict(_PENDING_DICE_ROLLS, update.effective_chat.id)[telegram_user_id] = _new_pending_roll("steal", text, update.effective_chat.id)
        # Task #187: _safe_send, not a raw send_message -- see the attack
        # site's comment above for why.
        await _safe_send(update, f"🎲 **{character['name']}**, roll a d20 for your theft attempt and tell me the result (you have 1 minute, or I'll roll for you).")
        return

    result = roll_ability_check(character, "dexterity", proficient=False, forced_roll=forced_roll)
    bonus = _practiced_bonus_for(telegram_user_id, update.effective_chat.id, "dexterity")
    # Thieves' Guild membership benefit (2026-07-25, per Coffee): a real
    # +3 on top of the usual practiced bonus -- the Ledger's own trade
    # secrets, not available outside it. Real live bug (2026-08-13,
    # synergy pass): checked primary guild only -- held_guild_ids also
    # covers a Promotion-earned secondary guild.
    if "thieves_guild" in held_guild_ids(character):
        bonus += THIEVES_GUILD_STEAL_BONUS
    # Rogue's Thief subclass hook (2026-07-25): the same real +3, this
    # time for actually having chosen the archetype named for exactly
    # this -- stacks with the guild bonus above (different sources,
    # same spirit), same as every other subclass/guild bonus in this
    # game stacking rather than overriding.
    if character.get("subclass") == "Thief":
        bonus += THIEF_SUBCLASS_STEAL_BONUS
    bonus += _steal_proficiency_bonus(character)
    bonus += _effective_ability_check_bonus(character, "dexterity")
    result["total"] += bonus
    result["practiced_bonus"] = bonus
    success = result["total"] >= STEAL_DC

    if success:
        db.record_skill_use(telegram_user_id, update.effective_chat.id, "dexterity")
        _grind_steal_proficiency(telegram_user_id, update.effective_chat.id, character)
        db.add_item(telegram_user_id, update.effective_chat.id, item_id, 1)
        consequence_line = f"\n🤫 You slip away with **{item['name']}** — nobody noticed."
    else:
        db.add_item(telegram_user_id, update.effective_chat.id, item_id, 1)  # still takes it, just gets caught
        consequence_line = f"\n🚨 **Caught!** {owner_name} won't sell to you ever again."
        if owner_npc:
            db.adjust_affinity(
                telegram_user_id, update.effective_chat.id, owner_npc, -40,
                event=f"Was caught stealing {item['name']} from {owner_name}'s shop.",
            )
            db.set_banned_by_npc(telegram_user_id, update.effective_chat.id, owner_npc, True)
            faction_id = _faction_for_npc(owner_npc)
            if faction_id:
                _adjust_faction_standing(
                    telegram_user_id, update.effective_chat.id, faction_id, -15, _faction_starting_standing(faction_id)
                )

    flavor = await asyncio.to_thread(
        narrate_skill_check, character, text, "dexterity",
        {**result, "ability": "dexterity", "dc": STEAL_DC, "success": success},
    )
    message = _format_skill_check_result(flavor, result, "dexterity", STEAL_DC, success) + consequence_line
    await _safe_send(update, message)


async def _do_steal_from_enemy(
    update: Update, character: dict, session: sessions.Session, text: str, forced_roll: int | None = None,
) -> None:
    """
    Pickpocketing a live enemy mid-fight (2026-08-11, per Coffee: "give
    every enemy a stealable item... make it hard to steal but allow a
    proficiency to level up for them... only give each enemy 1-2 items
    at the most, if its a rare item make the % small to get that item").
    Real 5E-style action -- a genuine turn-consuming combat action, same
    "1d20 + bonus vs DC" shape and turn-order/target-resolution as every
    other combat action (_do_shove is the closest twin). The item
    itself, if any, comes off the target's own real monster template
    (campaign.json's "stealable_items", authored per monster tier) --
    never invented, same grounding discipline as every other real drop
    in this game. A monster with nothing listed there gives an honest
    refusal instead of a made-up excuse, and doesn't consume the turn --
    there was nothing to actually attempt.
    """
    chat_id = update.effective_chat.id
    user_id = update.effective_user.id
    if session.current_participant_id() != user_id:
        await _self_heal_stuck_ai_turn(update, session)
        session = sessions.get_session_for_user(chat_id, user_id)
        if session is None:
            await update.effective_chat.send_message(
                "Combat had stalled and just resolved itself — nothing active right now.",
                message_thread_id=topics.thread_id_for(chat_id, "adventure"),
            )
            return
    if session.current_participant_id() != user_id:
        current_name = session.current_participant()["name"]
        await update.effective_chat.send_message(
            f"It's not your turn — it's **{current_name}**'s turn.",
            message_thread_id=topics.thread_id_for(chat_id, "adventure"),
        )
        return

    attacker = session.current_participant()
    if attacker["hp_current"] <= 0:
        await update.effective_chat.send_message(
            "You're unconscious (0 HP) and can't act until healed.",
            message_thread_id=topics.thread_id_for(chat_id, "adventure"),
        )
        return

    opposing = session.living_on_side(session.opposing_side(user_id))
    if not opposing:
        if not await _try_end_stale_combat(update, session):
            await update.effective_chat.send_message(
                "No valid targets remain.", message_thread_id=topics.thread_id_for(chat_id, "adventure")
            )
        return
    target = _pick_target(text, opposing)

    template = cl.get_monster_template(CAMPAIGN, target.get("monster_key")) if target.get("monster_key") else None
    stealable = template.get("stealable_items", []) if template else []
    if not stealable and target.get("is_labyrinth_run"):
        # Real gap (2026-09-08, per Coffee): 45 of 107 real non-boss
        # monster templates carry an empty stealable_items list --
        # scoped fallback, see LABYRINTH_STEAL_FALLBACK_POOL's own
        # comment above. 1 or 2 items, RNG, per Coffee's own spec.
        count = random.choice([1, 2])
        stealable = random.sample(LABYRINTH_STEAL_FALLBACK_POOL, k=min(count, len(LABYRINTH_STEAL_FALLBACK_POOL)))
        # Tier-2 elemental scroll, real "steal" channel (2026-09-08,
        # task #3, per Coffee: "the next lvl of scrools shud be
        # avaialbe in harder dungeons as a find, steal, or loot").
        # Small weight, same "rare item -> small %" spirit real
        # stealable_items entries already use.
        run = db.get_labyrinth_run(chat_id, _labyrinth_party_key(character))
        if run and run.get("floor", 0) > labyrinth_module.GREATER_ELEMENTAL_SCROLL_FLOOR_THRESHOLD:
            scroll_id = random.choice(labyrinth_module.GREATER_ELEMENTAL_SCROLL_IDS)
            stealable = stealable + [{"item_id": scroll_id, "weight": 10}]
    if not stealable:
        await update.effective_chat.send_message(
            f"**{target['name']}** isn't carrying anything worth stealing.",
            message_thread_id=topics.thread_id_for(chat_id, "adventure"),
        )
        return

    if forced_roll is None and attacker.get("manual_dice_enabled") and not attacker.get("is_ai"):
        forced_roll = _extract_combined_roll(text)
    if forced_roll is None and attacker.get("manual_dice_enabled") and not attacker.get("is_ai"):
        _chat_scoped_dict(_PENDING_DICE_ROLLS, chat_id)[user_id] = _new_pending_roll("steal", text, chat_id)
        await _safe_send(update, f"🎲 **{attacker['name']}**, roll a d20 for your theft attempt and tell me the result (you have 1 minute, or I'll roll for you).")
        return

    result = roll_ability_check(character, "dexterity", proficient=False, forced_roll=forced_roll)
    bonus = _practiced_bonus_for(user_id, chat_id, "dexterity")
    # Real live bug (2026-08-13, synergy pass): checked primary guild
    # only -- held_guild_ids also covers a Promotion-earned secondary.
    if "thieves_guild" in held_guild_ids(character):
        bonus += THIEVES_GUILD_STEAL_BONUS
    if character.get("subclass") == "Thief":
        bonus += THIEF_SUBCLASS_STEAL_BONUS
    bonus += _steal_proficiency_bonus(character)
    bonus += _effective_ability_check_bonus(character, "dexterity")
    result["total"] += bonus
    result["practiced_bonus"] = bonus
    success = result["total"] >= STEAL_FROM_ENEMY_DC

    if success:
        db.record_skill_use(user_id, chat_id, "dexterity")
        _grind_steal_proficiency(user_id, chat_id, character)
        item_id = random.choices(
            [entry["item_id"] for entry in stealable], weights=[entry["weight"] for entry in stealable],
        )[0]
        db.add_item(user_id, chat_id, item_id, 1)
        item = items_module.get_item(item_id)
        consequence_line = f"\n🤫 You lift **{item['name']}** off {target['name']} without them noticing."
    else:
        consequence_line = f"\n👊 {target['name']} feels the attempt and shoves you back — nothing taken."

    flavor = await asyncio.to_thread(
        narrate_skill_check, character, text, "dexterity",
        {**result, "ability": "dexterity", "dc": STEAL_FROM_ENEMY_DC, "success": success},
    )
    message = _format_skill_check_result(flavor, result, "dexterity", STEAL_FROM_ENEMY_DC, success) + consequence_line
    await _safe_send(update, message)

    await _advance_turn_and_resolve_ai_turns(update, session)


EMPOWERED_SPELL_MAX_USES = 1


def _apply_empowered_spell(telegram_user_id: int, character: dict, spell: dict, result: dict, target: dict | None = None) -> dict:
    """
    Sorcerer's Metamagic: Empowered Spell (real 5E, level 3+, previously
    pure flavor text in class_features.py) -- automatically rerolls any
    1s and 2s among a damage spell's dice once per rest, keeping the
    new roll ("the roll is already decided, this refines it before
    it's ever reported" -- the same rules-then-narration order every
    other outcome in this game follows). Real 5E spends a Sorcery Point
    (a resource this engine has no equivalent of) and lets the caster
    choose which dice to reroll and whether to use it at all;
    simplified to the same once-per-rest feature_uses economy every
    other class feature already shares, applied automatically to the
    first damage spell a Sorcerer casts each rest rather than adding a
    whole separate opt-in command just for this one choice.
    """
    if character.get("char_class") != "Sorcerer" or character.get("level", 1) < 3:
        return result
    if db.get_feature_uses(telegram_user_id, character["chat_id"], "empowered_spell") >= EMPOWERED_SPELL_MAX_USES:
        return result
    # Synergy Phase 11 counters_empowered_spell (2026-08-14, The Spire's
    # Grace -- "something up there still believes" its own light can't
    # be refined by a second roll): unlike counters_rage/counters_wild_
    # shape's "first use still lands, every use after doesn't" shape,
    # Empowered Spell is a once-PER-REST resource (EMPOWERED_SPELL_MAX_
    # USES), so there's rarely a real "second attempt in the same fight"
    # to negate -- this boss simply resists the reroll outright, every
    # time, whether it's the caster's first attempt or their last this
    # rest. The real feature_uses charge is still spent below (the
    # Sorcerer genuinely tried; the target's own resistance is what
    # fizzled it, same "you still used your resource" logic every other
    # spent-resource mechanic in this game already follows).
    if target and target.get("counters_empowered_spell"):
        db.use_feature(telegram_user_id, character["chat_id"], "empowered_spell")
        return result
    match = re.match(r"(\d+)d(\d+)", spell.get("damage_dice", ""))
    if not match:
        return result
    sides = int(match.group(2))
    old_rolls = result["rolls"]
    new_rolls = [r if r > 2 else roll(1, sides)[0] for r in old_rolls]
    if new_rolls == old_rolls:
        return result
    db.use_feature(telegram_user_id, character["chat_id"], "empowered_spell")
    return {**result, "rolls": new_rolls, "damage_dealt": result["damage_dealt"] + (sum(new_rolls) - sum(old_rolls))}


ELDRITCH_SMITE_DICE = "2d6"


def _apply_eldritch_smite(telegram_user_id: int, character: dict, spell_id: str, result: dict) -> dict:
    """
    Real gap (2026-08-13, per Coffee, dev-bridge: asked whether
    Eldritch Blast should cost a slot "so ethers are relevant for all
    characters" -- investigated live: cantrips correctly staying free
    is real 5E, not a bug, Coffee agreed to keep that rule and find
    another lever instead. Root cause of the actual complaint, traced
    separately: spells.CLASS_SPELL_LISTS["warlock"] has ZERO damage
    spells -- every leveled Warlock spell is situational utility
    (Hex, Hold Person, ...), so a Warlock can fight indefinitely on
    free Eldritch Blast alone and never actually need a spell-slot-
    restoring tonic, unlike every other caster class. See memory
    project_warlock_tonic_relevance_open.md's own "how to apply" note
    for the two options it left open; this is option (b) -- a real
    slot-spending damage boost, the exact "spend a slot for bonus
    damage" pattern Divine Smite already established for Paladins
    (bot.py's DIVINE_SMITE_DICE_BY_SLOT_LEVEL/_do_divine_smite).

    A deliberate house addition -- no real 5E Eldritch Invocation
    works this way -- flagged honestly, same as every other departure
    in this file. Automatically spends ONE spell slot for +2d6 force
    damage the next time a level 2+ Warlock lands Eldritch Blast, but
    ONLY when a slot would still remain afterward (never silently
    drains their last slot without asking -- Divine Smite protects the
    same way, by only ever spending on an actual hit) and only once
    per rest, same feature_uses economy every other limited ability
    already shares.
    """
    if spell_id != "eldritch_blast" or character.get("char_class") != "Warlock" or character.get("level", 1) < 2:
        return result
    if character.get("spell_slots_current", 0) < 2:
        return result
    if db.get_feature_uses(telegram_user_id, character["chat_id"], "eldritch_smite") >= 1:
        return result
    db.update_character(telegram_user_id, character["chat_id"], spell_slots_current=character["spell_slots_current"] - 1)
    db.use_feature(telegram_user_id, character["chat_id"], "eldritch_smite")
    bonus = roll_damage(ELDRITCH_SMITE_DICE)["total"]
    return {**result, "damage_dealt": result["damage_dealt"] + bonus, "eldritch_smite_bonus": bonus}


def _with_menu_button(keyboard: InlineKeyboardMarkup | None) -> InlineKeyboardMarkup:
    """
    Appends a single "📖 Menu" row (callback_data "menu|root") to any
    existing keyboard, or returns a keyboard with just that row if there
    wasn't one -- per Coffee: "make it a complete menu system." Used on
    every real menu section's own reply (sheet/story/quests/inventory/
    equip) so every screen loops back to the root menu instead of being
    a dead end, without needing its own separate rendering path.
    """
    rows = list(keyboard.inline_keyboard) if keyboard else []
    rows.append([InlineKeyboardButton("📖 Menu", callback_data="menu|root")])
    return InlineKeyboardMarkup(rows)


def _main_menu_keyboard(character: dict) -> InlineKeyboardMarkup:
    """
    Per Coffee (2026-07-19 dev-topic feedback): "Only show level up when
    we have points to distribute. Otherwise it serves no purpose." The
    Level Up row now only appears once pending_asi_points is real and
    positive -- the rest of the menu is unconditional either way.
    """
    rows = [
        [InlineKeyboardButton("🧙 Character Sheet", callback_data="menu|sheet")],
        [InlineKeyboardButton("📖 Story So Far", callback_data="menu|story")],
        [InlineKeyboardButton("📋 Quests", callback_data="menu|quests")],
        [InlineKeyboardButton("🎒 Inventory", callback_data="menu|inventory")],
        [InlineKeyboardButton("🔮 Magic", callback_data="menu|magic")],
        [InlineKeyboardButton("⚔️ Equip Gear", callback_data="menu|equip")],
        [InlineKeyboardButton("👥 Party", callback_data="menu|party")],
        [InlineKeyboardButton("🛠️ Professions", callback_data="menu|professions")],
        [InlineKeyboardButton("🎭 Switch Character", callback_data="menu|roster")],
        [InlineKeyboardButton("🧭 Waypoints", callback_data="menu|waypoints")],
        [InlineKeyboardButton("🌳 Skill Tree", callback_data="menu|skilltree")],
        [InlineKeyboardButton("🏅 Achievements", callback_data="menu|achievements")],
        [InlineKeyboardButton("🏛️ Market", callback_data="menu|market")],
        [InlineKeyboardButton("📚 Bestiary", callback_data="menu|bestiary")],
        [InlineKeyboardButton("🔮 Remnants", callback_data="menu|remnants")],
        [InlineKeyboardButton("🌤️ Weather", callback_data="menu|weather")],
        [InlineKeyboardButton("🏆 Leaderboard", callback_data="menu|leaderboard")],
        [InlineKeyboardButton("🗺️ Visual Map", callback_data="menu|visualmap")],
    ]
    if character.get("pending_asi_points", 0) > 0:
        rows.append([InlineKeyboardButton("📈 Level Up", callback_data="menu|level")])
    # Auto Level-Up Party (2026-07-25, per Coffee: "does me saying auto
    # level up the party... work? make a button for us"). Shown
    # whenever the requester either has their own points banked, or is
    # in a real party at all (cheap to check -- whether OTHER members
    # have something banked isn't checked here just to decide button
    # visibility; the button itself is a no-op with a plain message if
    # there's genuinely nothing to apply).
    if character.get("pending_asi_points", 0) > 0 or character.get("party_id"):
        rows.append([InlineKeyboardButton("🎯 Auto Level-Up Party", callback_data="menu|autolevelparty")])
    # Rebirth/hybrid (2026-07-22): same "only show it when it actually
    # applies" convention as Level Up above -- Rebirth only appears at
    # MAX_LEVEL (it would just reject the tap otherwise), and Hybrid
    # Class only once it's actually unlocked (after a first rebirth).
    if character.get("level", 1) >= MAX_LEVEL:
        rows.append([InlineKeyboardButton("✨ Rebirth", callback_data="menu|rebirth")])
    if hybrid_tier(character.get("rebirth_count", 0)) > 0:
        rows.append([InlineKeyboardButton("🌟 Hybrid Class", callback_data="menu|hybrid")])
    return InlineKeyboardMarkup(rows)


def _hybrid_keyboard(character: dict) -> InlineKeyboardMarkup:
    """Every OTHER real class as a tappable hybrid pick -- never your own char_class, which _do_choose_hybrid would reject anyway."""
    buttons = [
        [InlineKeyboardButton(cls, callback_data=f"hybrid|choose|{cls}")]
        for cls in HYBRID_CLASS_FEATURES if cls != character.get("char_class")
    ]
    return InlineKeyboardMarkup(buttons)


async def _do_show_hybrid_menu(update: Update) -> None:
    character = db.get_character(update.effective_user.id, update.effective_chat.id)
    if character is None:
        await update.effective_chat.send_message(
            "You don't have a character yet!", message_thread_id=topics.thread_id_for(update.effective_chat.id, "adventure")
        )
        return
    tier = hybrid_tier(character.get("rebirth_count", 0))
    if tier <= 0:
        await _safe_send(
            update, "Hybrid classes unlock after your first rebirth — say \"rebirth\" once you're level 99.",
            speak=False,
        )
        return
    current = (
        f"Current hybrid: **{character['hybrid_class']}** (tier {tier}/{HYBRID_MAX_TIER})\n\n"
        if character.get("hybrid_class") else ""
    )
    await _safe_send(
        update,
        f"🌟 **{character['name']}** — pick a hybrid class flavor:\n\n{current}Tap one below:",
        reply_markup=_with_menu_button(_hybrid_keyboard(character)),
        speak=False,
    )


async def hybrid_menu_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Handles taps on _hybrid_keyboard -- dispatches through the same real _do_choose_hybrid free text already uses."""
    query = update.callback_query
    parts = (query.data or "").split("|")
    action = parts[1] if len(parts) > 1 else ""
    await _safe_answer(query)
    if action != "choose" or len(parts) < 3:
        return
    await _do_choose_hybrid(update, parts[2])


async def _do_show_menu(update: Update) -> None:
    """
    Task #176 full menu revision, per Coffee (2026-07-19): "show things
    in menu that are needed for the game - story-so-far - quests -
    inventory - equip character - make it a complete menu system." Root
    navigational menu -- every section below dispatches through the
    SAME real handlers free text already uses (_do_check_sheet,
    _do_show_story_so_far, _do_check_quests, _do_check_inventory,
    _do_show_equip_menu), never a separate rendering path, and every
    section's own reply loops back here via _with_menu_button.
    """
    character = db.get_character(update.effective_user.id, update.effective_chat.id)
    if character is None:
        await update.effective_chat.send_message(
            "You don't have a character yet!", message_thread_id=topics.thread_id_for(update.effective_chat.id, "adventure")
        )
        return
    await _safe_send(
        update, f"📖 **{character['name']}** — what do you want to check?",
        reply_markup=_main_menu_keyboard(character), speak=False,
    )


async def menu_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Handles taps on _main_menu_keyboard and every section's own Menu button -- see _do_show_menu's docstring."""
    query = update.callback_query
    parts = (query.data or "").split("|")
    section = parts[1] if len(parts) > 1 else ""
    await _safe_answer(query)
    if section == "root":
        await _do_show_menu(update)
    elif section == "sheet":
        await _do_check_sheet(update)
    elif section == "story":
        await _do_show_story_so_far(update)
    elif section == "quests":
        await _do_check_quests(update)
    elif section == "inventory":
        await _do_check_inventory(update)
    elif section == "magic":
        await _do_show_magic_menu(update)
    elif section == "equip":
        await _do_show_equip_menu(update)
    elif section == "level":
        await _do_show_level_menu(update)
    elif section == "roster":
        await _do_list_characters(update)
    elif section == "waypoints":
        await _do_show_waypoints(update)
    elif section == "skilltree":
        await _do_show_skill_tree(update)
    elif section == "achievements":
        await _do_check_achievements(update)
    elif section == "market":
        await _do_check_market(update)
    elif section == "bestiary":
        await _do_bestiary(update)
    elif section == "remnants":
        await _do_check_remnants(update)
    elif section == "weather":
        await _do_check_weather(update)
    elif section == "leaderboard":
        await _do_leaderboard(update)
    elif section == "party":
        # Real feature request (2026-08-17, Coffee): merged the old
        # separate "Party Sheets" button in here -- _party_keyboard now
        # carries a real "View Sheet" tap per member (see its own
        # docstring), so this one screen covers both what the two
        # buttons used to. "check my party sheets" (free text) still
        # reaches the old all-at-once dump directly, unchanged.
        await _do_check_party(update)
    elif section == "professions":
        await _do_check_professions(update)
    elif section == "visualmap":
        await _do_show_visual_map(update)
    elif section == "rebirth":
        await _do_rebirth(update)
    elif section == "hybrid":
        await _do_show_hybrid_menu(update)
    elif section == "autolevelparty":
        await _do_auto_level_up_party(update)


async def story_menu_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Handles taps on _story_chapter_keyboard -- re-validates the chapter's actually been reached server-side, never trusts the button alone."""
    query = update.callback_query
    parts = (query.data or "").split("|")
    action = parts[1] if len(parts) > 1 else ""
    await _safe_answer(query)
    if action != "replay" or len(parts) < 3:
        return
    await _do_replay_chapter_intro(update, parts[2])


