AI_PARTY_TICK_INTERVAL_SECONDS = getattr(config, "AI_PARTY_TICK_INTERVAL_SECONDS", 900)
_LAST_AI_PARTY_TICK_AT: datetime | None = None

# Paused 2026-07-12 per Coffee's direct request, while reliability for
# real human players is the priority (ahead of eventually going public)
# -- does NOT delete or reset anything, existing AI companions stay in
# the party/DB exactly as they are, this just stops new autonomous
# ticks from being generated. Flip back to True to resume.
AI_PARTY_ENABLED = False


def _ensure_ai_party_exists(chat_id: int) -> None:
    """Creates the autonomous AI party once per chat, if it doesn't already exist for this chat, and forms them into their own party."""
    existing = db.get_autonomous_players(chat_id)
    if existing:
        return
    party_id = None
    for member in AI_PARTY_ROSTER:
        char = db.create_ai_companion(
            chat_id, name=member["name"], race=member["race"], char_class=member["char_class"],
            ability_scores=member["ability_scores"], hp_max=member["hp_max"],
            armor_class=member["armor_class"], gold=member["gold"], inventory=member["inventory"],
        )
        db.auto_equip_best_gear(char["telegram_user_id"], chat_id)
        db.mark_autonomous(char["telegram_user_id"], chat_id)
        if party_id is None:
            party_id = db.create_party(char["telegram_user_id"], chat_id)
        else:
            db.add_ai_companion_to_party(char["telegram_user_id"], chat_id, party_id)
    logger.info(f"[ai_party] created autonomous AI party, party_id={party_id}")


def _party_gather_needs_here(location_id: str, chat_id: int) -> list[dict]:
    """
    Real, currently-accepted party gather-quest objectives that THIS
    location's resource nodes can actually satisfy right now (2026-07-14,
    per Coffee: recruits/AI party members should recognize "the party
    has an active gather quest and I can do something about it here"
    on their own, not just wait to be told -- e.g. gathering silverleaf
    herb in the tavern cellar for a bounty posted up at the tavern
    itself). Board quests are checked across the WHOLE party, not just
    one character, since the board/progress tracking is shared -- and
    across all locations' boards, not just this one, since a quest is
    often posted somewhere else (the tavern) while the actual resource
    node lives in a connected sub-location (the cellar).
    """
    location = cl.get_location(CAMPAIGN, location_id)
    if not location:
        return []
    nodes_by_material = {n["material"]: n for n in location.get("resource_nodes", [])}
    if not nodes_by_material:
        return []
    seen_ids = set()
    needs = []
    for member in _get_party_members(chat_id):
        for q in db.get_accepted_board_quests_for_user(member["telegram_user_id"], member["chat_id"]):
            if (
                q["board_quest_id"] in seen_ids
                or q.get("objective_type") != "gather_material"
                or q["objective_target"] not in nodes_by_material
                or q["progress_count"] >= q["objective_count"]
            ):
                continue
            seen_ids.add(q["board_quest_id"])
            node = nodes_by_material[q["objective_target"]]
            item = items_module.get_item(q["objective_target"])
            needs.append({
                "quest_title": q["title"],
                "material_name": item["name"] if item else q["objective_target"],
                "remaining": q["objective_count"] - q["progress_count"],
                "node_name": node["name"],
            })
    return needs


def _build_ai_player_situation_facts(character: dict, location_id: str) -> str:
    location = cl.get_location(CAMPAIGN, location_id)
    if not location:
        return "You aren't sure where you are."

    lines = [f"Location: {location['name']} — {location['description']}"]

    # Same reasoning as every other grounding fix here: the AI was never
    # told what it's actually carrying or actually knows how to cast, so
    # "sell my X" or "I cast X" (the latter a literal hardcoded example in
    # ai/autonomous_player.py's prompt) had nothing real to check against
    # -- risking the exact same verbatim-example-parroting failure already
    # confirmed and fixed for movement ("I head to the whispering wood").
    inventory = character.get("inventory") or {}
    if inventory:
        item_names = [items_module.get_item(i)["name"] for i in inventory if items_module.get_item(i)]
        if item_names:
            lines.append(f"You're carrying: {', '.join(item_names)}")

    # Real feature (2026-08-19, per Coffee: "can the AI players place
    # weapons, armour, rings, amulutes, shield, and other items for
    # sale on the Market place? can they purchase from the market
    # place?"): grounded exactly like "Shop here sells" below -- real,
    # currently-live listings only, someone else's own (never the
    # character's own listing, which isn't a real purchase option), and
    # only the ones this character can actually afford, so a "buy"
    # example never points at something it can't real-world reach.
    # Global (not location-scoped), matching the market's own real
    # design (Task #79) -- reachable from anywhere.
    affordable_listings = [
        l for l in db.get_market_listings(character["chat_id"])
        if l["seller_id"] != character["telegram_user_id"] and l["price"] <= character.get("gold", 0)
    ]
    if affordable_listings:
        listing_bits = [
            f"{l['quantity']}x {items_module.get_item(l['item_id'])['name']} for {l['price']} gold"
            for l in affordable_listings if items_module.get_item(l["item_id"])
        ]
        if listing_bits:
            lines.append(f"The player marketplace has: {', '.join(listing_bits)}")
    known_spells = character.get("known_spells") or []
    if known_spells:
        spell_names = [spells_module.get_spell(s)["name"] for s in known_spells if spells_module.get_spell(s)]
        if spell_names:
            lines.append(f"Spells you know: {', '.join(spell_names)}")

    # Per Coffee (2026-07-14): AI-controlled characters should "naturally
    # know" what they're strong or weak at overall, not just at the one
    # resource node in front of them -- lets the model lean toward a
    # skill it's already good at when several options are open, or
    # recognize a weak/untried one as worth practicing.
    practiced_skills = {k: v for k, v in (character.get("skill_uses") or {}).items() if v > 0}
    if practiced_skills:
        strong = sorted(practiced_skills.items(), key=lambda kv: -kv[1])
        lines.append(
            "Skills you've practiced: "
            + ", ".join(f"{skill} +{practiced_bonus(uses)} ({uses} uses)" for skill, uses in strong)
        )

    # Rebirth (2026-07-25, per Coffee: make the autonomous AI party
    # actually able to progress all the way through several rebirths --
    # a maxed-out AI companion previously had no idea rebirthing was
    # even a thing it could do, and would just sit at MAX_LEVEL forever
    # instead of ever unlocking the rebirth-gated dungeons).
    if character.get("level", 1) >= MAX_LEVEL:
        lines.append(
            "You've reached the maximum level and can rebirth now for a permanent power boost "
            "(a higher ability-score ceiling, faster XP from then on, and eventually access to places "
            "that need rebirths to reach) -- say \"I rebirth\" to do it."
        )

    npcs_here = _npcs_at_location(location_id, character["chat_id"])
    if npcs_here:
        names = [CAMPAIGN["npcs"][n]["name"] for n in npcs_here if n in CAMPAIGN["npcs"]]
        lines.append(f"People here: {', '.join(names)}")
        # Same reasoning as every other grounding fix here: recruiting is
        # a real action (_do_recruit_npc), but nothing distinguished a
        # recruitable NPC from an ordinary shopkeeper/one-off character in
        # "People here", so the AI party had no way to know who could
        # actually be asked to join.
        already_in_party = {p["name"] for p in _get_party_members(character["chat_id"])}
        recruitable_here = [
            CAMPAIGN["npcs"][n]["name"] for n in npcs_here
            if n in CAMPAIGN["npcs"] and CAMPAIGN["npcs"][n].get("recruitable")
            and CAMPAIGN["npcs"][n]["name"] not in already_in_party
        ]
        if recruitable_here:
            lines.append(f"You could recruit: {', '.join(recruitable_here)}")
    # Real topic-activity finding (2026-08-24, self-improvement
    # monitoring pass): two different autonomous AI players both typed
    # "I attack crystal_spider" -- the literal snake_case monster_key,
    # not a real name -- because this line joined monsters_here's own
    # raw keys directly instead of resolving each to its real display
    # name the way every other list in this function already does
    # (items, spells, NPCs). Same "verbatim-example-parroting" failure
    # class this function's own comments already describe fixing for
    # items/movement, just missed here.
    monsters_here = location.get("monsters", [])
    if monsters_here:
        monster_names = [CAMPAIGN["monsters"][m]["name"] for m in monsters_here if m in CAMPAIGN["monsters"]]
        if monster_names:
            lines.append(f"Danger here: {', '.join(monster_names)}")
    # Mirrors _do_move's own reachable-destination computation (minus
    # locked_connections, which need an item the AI player may not have
    # and aren't unconditionally reachable) -- without descends_to/
    # ascends_to here, the AI party would never even learn sub-locations
    # like tavern_cellar/tavern_upstairs exist, since _do_move itself
    # treats those as fully reachable but this list previously only
    # looked at "connections".
    reachable = list(location.get("connections", []))
    if "descends_to" in location:
        reachable.append(location["descends_to"])
    if "ascends_to" in location:
        reachable.append(location["ascends_to"])
    # Only genuinely open destinations (2026-07-25, per Coffee: make the
    # autonomous AI party actually able to complete missions/dungeons in
    # order, all the way through several rebirths) -- filters out
    # anything gated by min_level, a required item, rebirth count, or a
    # story gate (an undefeated prerequisite monster/uncleared
    # location), the exact same real checks _do_move itself applies.
    # Without this, the AI had no way to reason about why a listed
    # destination silently refused it, and would waste turns walking
    # into the same rejection over and over.
    def _really_reachable(dest_id: str) -> bool:
        dest = cl.get_location(CAMPAIGN, dest_id)
        if dest is None:
            return False
        if dest.get("requires_item") and dest["requires_item"] not in character.get("inventory", {}):
            return False
        if not _meets_location_level(character, dest):
            return False
        if not _meets_rebirth_requirement(character, dest):
            return False
        if _check_story_gate(character, location, dest_id) is not None:
            return False
        return True

    reachable = [r for r in reachable if _really_reachable(r)]
    if reachable:
        conn_names = [cl.get_location(CAMPAIGN, c)["name"] for c in reachable]
        lines.append(f"Places reachable from here: {', '.join(conn_names)}")
    interactables = location.get("interactables", {})
    if interactables:
        lines.append(f"Things worth a closer look: {', '.join(i['name'] for i in interactables.values())}")
    resource_nodes = location.get("resource_nodes", [])
    if resource_nodes:
        # Per Coffee (2026-07-14): AI-controlled characters should
        # "naturally know" what they're already good at versus what's
        # worth practicing -- annotate each node with its skill and this
        # character's real, current proficiency (same practiced_bonus
        # mechanic shown on the character sheet), so gathering something
        # you're untried at reads as a genuine opportunity to level up,
        # not a random guess.
        skill_uses = character.get("skill_uses") or {}
        node_descriptions = []
        for n in resource_nodes:
            skill_key = n.get("skill", n.get("ability"))
            uses = skill_uses.get(skill_key, 0)
            proficiency_note = (
                f"you're not practiced in {skill_key} yet" if uses == 0
                else f"{skill_key} +{practiced_bonus(uses)}, {uses} use{'s' if uses != 1 else ''}"
            )
            node_descriptions.append(f"{n['name']} ({proficiency_note})")
        lines.append(f"Resources here: {', '.join(node_descriptions)}")

        gather_needs = _party_gather_needs_here(location_id, character["chat_id"])
        for need in gather_needs:
            lines.append(
                f"The party's quest \"{need['quest_title']}\" still needs {need['remaining']} "
                f"more {need['material_name']} -- you could gather that right here to help finish it."
            )

    # 2026-07-14, per Coffee: gathering already had grounding above, but
    # crafting and campfires (both shipped the same day) didn't -- the
    # AI party had real facts to gather materials but nothing telling it
    # what those materials could actually MAKE, or that a campfire was
    # ever an option. Same "only mention what's real right now" pattern
    # as every other fact here: only lists a recipe if the character
    # genuinely has the materials for it, and only mentions the campfire
    # if they're actually carrying wood and not already at full HP
    # (matching _do_make_campfire's own real refusal conditions exactly).
    craftable = [
        items_module.get_item(recipe["result_item"])["name"]
        for recipe in RECIPES.values()
        if has_materials(inventory, recipe) and items_module.get_item(recipe["result_item"])
    ]
    if craftable:
        lines.append(f"You have the materials to craft: {', '.join(craftable)}")
    if inventory.get("wood", 0) >= 1 and character.get("hp_current", 0) < character.get("hp_max", 0):
        lines.append("You're carrying wood and could make a campfire to recover some HP.")
    shop_id = location.get("shop")
    if shop_id:
        # Same reasoning as the descends_to/ascends_to fix above: without
        # naming what's actually for sale, the AI has nothing real to
        # reference for a "buy" action and would have to either invent an
        # item or parrot the "healing potion" example verbatim regardless
        # of whether this shop even sells one -- _do_buy only matches
        # against shop_data["inventory"], so an ungrounded guess just
        # bounces with "not sure what item you mean" instead of a real
        # purchase.
        shop_data = cl.get_shop(CAMPAIGN, shop_id)
        item_names = [items_module.get_item(i)["name"] for i in shop_data.get("inventory", []) if items_module.get_item(i)]
        if item_names:
            lines.append(f"Shop here sells: {', '.join(item_names)}")
        else:
            lines.append("There is a shop here.")

        # Real need-based shopping (2026-07-25, per Coffee: "does the AI
        # companion kno to buy items needed for battle?! they shud be
        # able to take care of themselves"): buying was already a real,
        # grounded action (see the "Shop here sells" fact above and the
        # "buy" example in ai/autonomous_player.py), but purely
        # opportunistic -- nothing ever connected it to actual need, so
        # an AI party member could walk past a shop at 0 healing
        # potions and never think to restock. Only fires when it's
        # GENUINELY true: carrying zero of any healing-effect item this
        # specific shop sells, and able to afford the cheapest one.
        healing_ids_sold_here = [
            i for i in shop_data.get("inventory", [])
            if (items_module.get_item(i) or {}).get("effect") == "heal"
        ]
        if healing_ids_sold_here and not any(inventory.get(i, 0) > 0 for i in healing_ids_sold_here):
            affordable = [
                i for i in healing_ids_sold_here
                if items_module.get_item(i)["price"] <= character.get("gold", 0)
            ]
            if affordable:
                cheapest_id = min(affordable, key=lambda i: items_module.get_item(i)["price"])
                cheapest = items_module.get_item(cheapest_id)
                lines.append(
                    f"You aren't carrying any healing items and this shop sells "
                    f"{cheapest['name']} for {cheapest['price']} gold, which you can afford -- "
                    f"worth stocking up before your next fight."
                )

    # Story quests (campaign.json's hand-authored catalog) are a
    # separate thing from the area quest board below, and were missing
    # here entirely — the AI party could see a board bounty posted, but
    # never learned a real story quest was on offer at its own location,
    # so it had no way to know "accept the quest" was ever a sensible
    # thing to say for one of those.
    story_offer = _offerable_quest_at_location(character, location_id)
    if story_offer:
        lines.append(f"A quest is on offer here: {story_offer[1]['title']}")
    else:
        # Real live gap found via direct monitoring (2026-07-22): once
        # the AI party wandered away from wherever a quest was actually
        # offered (its own starting location, in the confirmed case),
        # this fact -- and the "accepting an offered quest is the
        # single highest priority" guidance in ai/autonomous_player.py
        # -- had nothing left to trigger on, ever again, since a
        # quest's offer only ever showed while standing exactly there.
        # Surfaces a real, grounded reminder to go back for it instead.
        for quest_id, quest in CAMPAIGN.get("quests", {}).items():
            offer_location = quest.get("location")
            if not offer_location or offer_location == location_id:
                continue
            if quest_id in character["completed_quests"] or quest_id in character["active_quests"]:
                continue
            offer_loc_data = cl.get_location(CAMPAIGN, offer_location)
            if offer_loc_data:
                lines.append(
                    f"A quest (\"{quest['title']}\") is on offer back at {offer_loc_data['name']} -- "
                    "you could head there to accept it."
                )
                break

    # Per Coffee (2026-07-14): a recruited companion's own personal
    # quest should be something the AI party can choose to help with
    # too, not just something a human player notices.
    companion_offer = _offerable_companion_quest(character)
    if companion_offer:
        lines.append(f"A party companion has a personal task on offer: {companion_offer[1]['title']}")

    board_quests = board_quests_module.get_all_todays_board_quests(location_id, character["chat_id"])
    unclaimed = [q for q in board_quests if not q.get("accepted_by") and not q.get("completed_at")]
    if unclaimed:
        lines.append(f"Quest board has something posted: {', '.join(q['title'] for q in unclaimed)}")

    # Without this, an AI party member whose accepted branching quest is
    # already objective-complete has no way to know a real decision is
    # waiting on it, or what the two actual choices even are -- it would
    # just sit on it forever, since resolve_choice requires saying one of
    # the exact real labels (see _do_resolve_quest_choice), and nothing
    # else here ever surfaces what those labels are.
    ready_choices = [
        q for q in db.get_accepted_board_quests_for_user(character["telegram_user_id"], character["chat_id"])
        if q.get("branch_data") and q["progress_count"] >= q["objective_count"]
    ]
    for q in ready_choices:
        labels = ", ".join(f'"{c["label"]}"' for c in q["branch_data"]["choices"].values())
        lines.append(f"You have a decision to make on \"{q['title']}\" -- your options are: {labels}")

    if character.get("active_quests"):
        # Real live gap found via direct log monitoring (2026-07-22): the
        # AI party has been looping on the same few flavor actions
        # (examine the same tree, gather the same herb) for days without
        # ever meaningfully progressing the story -- traced to this line
        # only ever giving a bare COUNT of active quests, never WHERE one
        # actually needs to go next. A quest's own real objective_location
        # field (campaign.json) already exists for exactly this; it was
        # simply never read here. Only surfaced for quests whose
        # objective isn't already right here (otherwise the reach_location
        # trigger already fires on its own the moment they arrived, and
        # this would just be pointing at where they're already standing).
        elsewhere_quests = []
        # Real gap (2026-07-25, per Coffee: make the autonomous AI party
        # actually able to complete missions/dungeons in order, all the
        # way through several rebirths): several real story quests
        # (Hollow Verge, Wordless Choir, The Unbegun, and the true
        # hidden final boss ALL have one) use a solve_puzzle trigger,
        # and nothing here ever told the AI party a puzzle even
        # existed -- an active puzzle quest was a silent, permanent
        # dead end for it. The real riddle text (campaign.json's own
        # puzzles data) is surfaced directly, same "let it genuinely
        # attempt what a human would" spirit as everything else here --
        # never the accepted_answers themselves, so this isn't handing
        # it the solution, just the same question a player would read.
        puzzle_quests = []
        for quest_id in character["active_quests"]:
            quest = CAMPAIGN.get("quests", {}).get(quest_id)
            if not quest:
                continue
            trigger = quest.get("trigger", {})
            if trigger.get("type") == "solve_puzzle":
                puzzle = CAMPAIGN.get("puzzles", {}).get(trigger.get("puzzle_id"))
                if puzzle:
                    puzzle_quests.append((quest["title"], puzzle["riddle"]))
                continue
            objective_id = quest.get("objective_location")
            if objective_id and objective_id != location_id:
                objective_loc = cl.get_location(CAMPAIGN, objective_id)
                if objective_loc:
                    elsewhere_quests.append((quest["title"], objective_loc["name"]))
        for title, riddle in puzzle_quests:
            lines.append(f"You're trying to solve a riddle for \"{title}\": \"{riddle}\" -- say your best guess as a direct answer.")
        if elsewhere_quests:
            for title, dest_name in elsewhere_quests:
                lines.append(f"Your active quest \"{title}\" needs you to travel to {dest_name}.")
        elif not puzzle_quests:
            lines.append(f"You have {len(character['active_quests'])} active quest(s) in your journal already.")

    # Same reasoning as the reachable-places/shop/branching-choice facts
    # above: guild joining is a real, location-independent action
    # (_do_join_guild has no location check at all), but nothing here
    # ever told the AI party a guild even existed, so it could never
    # autonomously decide to join one.
    current_guild = character.get("guild")
    joinable = [
        guild["name"] for guild_id, guild in GUILDS.items()
        if guild_id != current_guild and eligible_for_guild(character, guild_id)[0]
    ]
    if joinable:
        lines.append(f"Guilds you could join: {', '.join(joinable)}")

    return "\n".join(lines)


def _build_labyrinth_ai_situation_facts(character: dict, chat_id: int) -> str:
    """
    Real gap found (2026-09-03, while designing an AI-driven Labyrinth
    playtest loop, per Coffee: "have your Test environment play it with
    AI characters"): `_build_ai_player_situation_facts` above is the
    ONLY thing that ever fed an autonomous AI companion's `choose_next_
    action` call, and it does `cl.get_location(CAMPAIGN, location_id)`
    unconditionally -- which returns None for the Labyrinth's synthetic
    sentinel location, silently falling back to "You aren't sure where
    you are." EVERY autonomous AI companion who has ever entered the
    Labyrinth has been choosing its next action COMPLETELY BLIND ever
    since Part D shipped -- no room description, no exits, no
    monsters, no mechanics. This almost certainly explains why the
    ambient-AI-misclassification bugs fixed earlier this session
    (v1.27.482-485: "chat"/"summon_remnant"/"find_merchant" swallowing
    ambiguous wandering lines like "I seek my location.") kept
    recurring one action at a time -- the AI wasn't malfunctioning, it
    was guessing with zero real information, the same root cause each
    time, only ever patched at the symptom (allowlist one more
    accidental action) rather than the actual cause.

    Reuses `_labyrinth_room_text` verbatim -- the exact same real,
    grounded description a human player already sees (name, monsters,
    every real lockable/mechanic present, real exits, the segment
    goal) -- rather than re-deriving a second, separately-maintained
    description of the same room.
    """
    run = db.get_labyrinth_run(chat_id, _labyrinth_party_key(character))
    if run is None:
        return "You aren't sure where you are."
    room = run["rooms"].get(run["current_room_id"])
    if room is None:
        return "You aren't sure where you are."
    lines = [_labyrinth_room_text(character, room, run, chat_id)]
    carrying_id = run.get("carrying")
    if carrying_id:
        carried = next(
            (lk for r in run["rooms"].values() for lk in r.get("lockables", []) if lk["id"] == carrying_id),
            None,
        )
        if carried:
            lines.append(f"You are currently carrying {carried['name']}.")
    return "\n".join(lines)


async def _maybe_auto_roll_pending_dice(bot) -> None:
    """
    Per Coffee (2026-07-19): "give the user 1 minute to roll - if not
    then auto-roll" -- runs every idle-loop tick (60s cadence, see
    _idle_inactivity_loop) and auto-resolves any _PENDING_DICE_ROLLS
    entry that's been waiting DICE_ROLL_AUTO_TIMEOUT_SECONDS or longer,
    using a real d20 roll in place of the manual one the player never
    reported -- same dispatch this'd get from a real manual reply, just
    with an auto-rolled value instead. Also incidentally bounds task
    #186's restart-survival gap: a pending roll can now only ever be
    silently lost for at most one idle-loop tick after a restart,
    instead of forever.
    """
    now = datetime.now(timezone.utc)
    expired_keys = [
        (chat_id, user_id)
        for chat_id, chat_rolls in _PENDING_DICE_ROLLS.items()
        for user_id, pending in chat_rolls.items()
        if (now - datetime.fromisoformat(pending["created_at"])).total_seconds() >= DICE_ROLL_AUTO_TIMEOUT_SECONDS
    ]
    for chat_id, user_id in expired_keys:
        pending = _chat_scoped_dict(_PENDING_DICE_ROLLS, chat_id).pop(user_id, None)
        if pending is None:
            continue
        character = db.get_character(user_id, pending["chat_id"])
        name = character["name"] if character else "Someone"
        auto_value = roll_d20()
        update_like = _AiPlayerUpdate(bot, pending["chat_id"], user_id, pending["action_text"])
        logger.info(
            f"[dice] user={user_id} auto-rolled pending {pending['kind']} roll with "
            f"{auto_value} (no manual reply within {DICE_ROLL_AUTO_TIMEOUT_SECONDS}s)"
        )
        await _safe_send(update_like, f"⏱️ **{name}** didn't roll in time — auto-rolling: 🎲 {auto_value}.")
        try:
            if pending["kind"] == "attack":
                await _do_attack(update_like, pending["action_text"], forced_roll=auto_value)
            elif pending["kind"] == "skill_check":
                await _do_skill_check(update_like, pending["ability"], pending["action_text"], forced_roll=auto_value)
            elif pending["kind"] == "gather":
                await _do_gather(update_like, pending["action_text"], forced_roll=auto_value)
            elif pending["kind"] == "shove":
                await _do_shove(update_like, pending["action_text"], forced_roll=auto_value)
            elif pending["kind"] == "flee":
                await _do_flee(update_like, pending["action_text"], forced_roll=auto_value)
            elif pending["kind"] == "steal":
                await _do_steal(update_like, pending["action_text"], forced_roll=auto_value)
        except Exception as e:
            logger.error(f"[dice] auto-roll dispatch for user={user_id} kind={pending['kind']} raised: {e!r}")


STANDALONE_AI_REVIVE_HOURS = 3
# Per Coffee (2026-07-25, re: Bram Ashfield dying in battle while not a
# member of anyone's real party): a dead character can't act OR move
# (adventure_master_handler's is_dead gate), so a standalone AI
# companion literally cannot walk itself to a shrine, and no human is
# around to pray for it there either -- every OTHER revival path in
# this game (shrine offering, Revivify) requires a real party member
# to initiate it. Left as-is, a standalone AI companion's death is
# permanent with no possible fix short of manual DB intervention. This
# is the real, distinct fix: after STANDALONE_AI_REVIVE_HOURS of real
# time (not instant -- still a genuine consequence, just not
# forever), a standalone dead AI companion recovers on its own.


def _is_standalone_ai_companion(character: dict) -> bool:
    """
    True if this AI companion isn't currently partied with any real
    human -- i.e. no one who could ever take it to a shrine or cast
    Revivify for it. A companion recruited into an active human's party
    (character.party_id shared with a real player) already has a real
    revival path and should keep needing it, same as any human death --
    this only covers the ones nothing else can ever reach.
    """
    party_id = character.get("party_id")
    if not party_id:
        return True
    return not any(not m.get("is_ai") for m in db.get_party_members_by_id(party_id))


def _maybe_revive_standalone_ai_companions() -> None:
    """Runs once per world tick — see STANDALONE_AI_REVIVE_HOURS above for why this exists."""
    now = datetime.now(timezone.utc)
    for character in db.get_ai_controlled_characters():
        if not character.get("is_dead") or not _is_standalone_ai_companion(character):
            continue
        died_at_raw = character.get("died_at")
        # No recorded died_at (2026-07-25, real case: Bram was already
        # stuck dead from before this fix shipped, with no timestamp to
        # measure from) -- treat as "died an unknown, presumably long
        # time ago" and revive on the very next tick, rather than
        # requiring a fresh death to ever recover.
        if died_at_raw:
            elapsed_hours = (now - datetime.fromisoformat(died_at_raw)).total_seconds() / 3600
            if elapsed_hours < STANDALONE_AI_REVIVE_HOURS:
                continue
        db.update_character(
            character["telegram_user_id"], character["chat_id"], is_dead=0, hp_current=character["hp_max"], died_at=None,
            death_save_successes=0, death_save_failures=0,
        )
        _log_world_event(
            character.get("current_location"), f"{character['name']} stirs and rises, alive once more.",
            character["chat_id"],
        )
        logger.info(f"[world_tick] standalone AI companion {character['name']} auto-revived after death")


async def _ai_party_autonomous_tick(bot) -> None:
    """
    Advances ONE AI-controlled character's turn per cycle PER CHAT
    (never all at once, to keep any one chat's Adventure from being
    flooded) — Phase 4b: loops over every known chat
    (db.get_all_chat_ids()) so each tenant gets its own independent
    roster and rotation instead of everything being mixed together
    under the single old _LAST_KNOWN_CHAT_ID global (which could pick
    an actor from one chat and act it out using another chat's combat/
    context state). Skips anyone currently in an active combat session
    — that already auto-resolves via the existing is_ai=1 mechanism
    with no action needed here.

    2026-07-14, per Coffee: "make recruitable able to make their own
    choices... this goes for AIs also." Previously only the separate
    hardcoded autonomous party (Zara/Bram) ever got a tick here --
    recruited companions like Sarah sat completely idle between being
    directly talked to, with no way to notice and act on something like
    an active party gather quest on their own. Broadened to every
    AI-controlled character (db.get_ai_controlled_characters), sharing
    the same one-actor-per-tick-per-chat rotation so this doesn't flood
    any chat any more than before.
    """
    global _LAST_AI_PARTY_TICK_AT
    # 2026-07-14: now a live toggle (Development-topic "turn on/off ai
    # party") instead of a hardcoded flag needing a code edit + redeploy
    # to flip. AI_PARTY_ENABLED below is just the seed default (still
    # paused) for whenever no live override has been set yet.
    if db.get_setting("ai_party_enabled", "1" if AI_PARTY_ENABLED else "0") != "1":
        return

    now = datetime.now(timezone.utc)
    if _LAST_AI_PARTY_TICK_AT and (now - _LAST_AI_PARTY_TICK_AT).total_seconds() < AI_PARTY_TICK_INTERVAL_SECONDS:
        return

    acted_this_cycle = False
    for chat_id in db.get_all_chat_ids():
        _ensure_ai_party_exists(chat_id)
        roster = [c for c in db.get_ai_controlled_characters() if c["chat_id"] == chat_id]
        if not roster:
            continue

        # Whoever's acted least recently goes next — a simple, fair rotation.
        roster.sort(key=lambda c: c.get("last_active_at") or "")
        actor = next(
            (c for c in roster
             if not c.get("is_dead") and not _in_active_combat(c["telegram_user_id"], chat_id)),
            None,
        )
        if actor is None:
            continue  # everyone's currently mid-fight or dead in this chat; nothing to do

        # Real scaling concern once more than one or two tenant chats
        # exist: each chat's turn is a real, narrated Ollama call, and
        # this loop would otherwise fire one per known chat, every
        # single tick, all sequentially competing for this box's one
        # shared generation slot (see _ollama_congested's own docstring).
        # Always advance the FIRST chat's turn (matches the original
        # single-chat behavior exactly), but stop advancing MORE chats
        # this tick once the shared resource is already under strain --
        # the skipped chats simply get their turn on a later tick.
        if acted_this_cycle and _ollama_congested():
            break

        acted_this_cycle = True
        await _ai_party_act_one_turn(bot, actor)

    if acted_this_cycle:
        _LAST_AI_PARTY_TICK_AT = now


async def _ai_party_act_one_turn(bot, actor: dict) -> None:
    user_id = actor["telegram_user_id"]
    chat_id = actor["chat_id"]

    # Party cohesion fix (2026-07-25, per Coffee, reported twice: "the
    # parties scattered all over the place... we need them to stay in
    # the players area when the player is active" / "what happened to
    # all the party members?... I'm the only one here?"): a recruited/
    # autonomous companion's own situation facts (_build_ai_player_
    # situation_facts) never told it where its human party leader
    # actually was, so choose_next_action -- an LLM call with zero
    # party-cohesion signal -- would just as happily wander off
    # exploring on its own as stay put. Confirmed real root cause, not
    # a fluke. Rather than trust the model to "choose" to stay together
    # (exactly what was already failing), deterministically snap a
    # drifted companion back to its human leader's CURRENT location
    # whenever they've drifted apart, skipping the LLM call for this
    # tick -- same guaranteed-correct instant relocation
    # _do_recruit_npc already does once at recruit time, just
    # re-applied continuously. Only while the leader is actually
    # active (not resting) -- an inactive/away leader shouldn't yank
    # their party around with them.
    party_id = actor.get("party_id")
    if party_id:
        human_leader = next(
            (m for m in db.get_party_members_by_id(party_id) if not m.get("is_ai")), None
        )
        if (human_leader and not human_leader.get("is_inactive")
                and human_leader["current_location"] != actor["current_location"]):
            db.update_character(user_id, actor["chat_id"], current_location=human_leader["current_location"])
            _log_world_event(
                human_leader["current_location"], f"{actor['name']} hurries to catch up with the party.", chat_id,
            )
            return

    # Arcane Recovery (2026-08-14, per Coffee: "I want AI to be able to
    # use all thier abilities... and anything that there character has
    # or levels up"): real Wizard class feature, but NOT a combat action
    # in real 5E (a short rest, not a turn) -- so unlike the other 7
    # class abilities (wired into _maybe_use_class_ability, decided
    # mid-combat), this is decided here instead, on the AI's own
    # downtime tick, exactly where a Wizard between fights would
    # actually use it. Deterministic short-circuit, same shape as the
    # party-cohesion snap-back above -- skips this tick's LLM call
    # entirely rather than hoping the model thinks to ask for it.
    if (actor.get("char_class") == "Wizard"
            and actor.get("spell_slots_current", 0) < actor.get("spell_slots_max", 0)
            and db.get_feature_uses(user_id, chat_id, "arcane_recovery") < 1):
        max_recoverable = (actor.get("level", 1) + 1) // 2 + _skill_points(actor, "deeper_recovery")
        missing = actor["spell_slots_max"] - actor["spell_slots_current"]
        recovered = min(max_recoverable, missing)
        if recovered > 0:
            db.update_character(user_id, chat_id, spell_slots_current=actor["spell_slots_current"] + recovered)
            db.use_feature(user_id, chat_id, "arcane_recovery")
            _log_world_event(
                actor["current_location"],
                f"{actor['name']} pores over a spellbook, recovering {recovered} spell slot"
                f"{'s' if recovered != 1 else ''} through Arcane Recovery.",
                chat_id,
            )
            return

    context_like = _chat_scoped_dict(_AI_PLAYER_CONTEXTS, chat_id).setdefault(user_id, _AiPlayerContext())
    last_action = context_like.user_data.get("last_autonomous_action")

    # Recruited companions (e.g. Sarah) aren't in the hardcoded
    # AI_PARTY_ROSTER at all -- their real personality lives in
    # campaign.json's NPC entry instead, same place their sheet-lookup
    # basic-info fallback already reads from.
    personality = next((m["personality"] for m in AI_PARTY_ROSTER if m["name"] == actor["name"]), None)
    if personality is None:
        npc = _find_campaign_npc_by_name(actor["name"])
        personality = npc.get("personality", "") if npc else ""
    if actor["current_location"] == LABYRINTH_LOCATION_SENTINEL:
        situation_facts = _build_labyrinth_ai_situation_facts(actor, chat_id)
    else:
        situation_facts = _build_ai_player_situation_facts(actor, actor["current_location"])
    # Task #222, per Coffee: a human party member can tell an AI
    # companion something mid-fight (see _do_message_ai) without it
    # counting as anyone's turn -- that message is stashed here as real
    # guidance and read exactly once, on this actor's own very next
    # autonomous decision, then cleared so it never lingers past that.
    guidance = context_like.user_data.pop("human_guidance", None)
    if guidance:
        situation_facts += f"\nA party member just told you directly: \"{guidance}\""
    action_text = await asyncio.to_thread(choose_next_action, actor, personality, situation_facts, last_action)
    # Real gap found 2026-08-12 (hunting the live log): ai/autonomous_
    # player.py's own prompt explicitly tells the model "NEVER copy a
    # bracketed example verbatim" (its few-shot examples are written
    # like "I gather [something listed under...]", brackets marking a
    # placeholder to fill in, not literal syntax) -- but the live log
    # shows this instruction isn't reliably followed: "I gather [Sulfur
    # Dust]", "I head to [The Goblin Warrens]", "I attack [crystal_
    # spider]" all appear verbatim, brackets and all. This raw text
    # becomes update_like.message.text AND is later handed straight to
    # the narration model as the character's own quoted action (see
    # ai/dm_agent.py's narrate_action/_build_prompt) -- a literal
    # leftover bracket risks either confusing that prompt or leaking
    # into the narrated prose players actually see. Same defense-in-
    # depth philosophy as the rest of this codebase: never trust the
    # model alone to follow a formatting instruction perfectly, enforce
    # it deterministically at the one place this text originates. No
    # real item/location/monster name in this game ever uses square
    # brackets, so stripping them is always safe.
    action_text = action_text.replace("[", "").replace("]", "")
    context_like.user_data["last_autonomous_action"] = action_text

    update_like = _AiPlayerUpdate(bot, chat_id, user_id, action_text)
    try:
        await adventure_master_handler(update_like, context_like)
    except Exception as e:
        logger.error(f"[ai_party] {actor['name']}'s autonomous turn raised: {e!r}")


async def _idle_inactivity_loop(application: Application) -> None:
    """
    Background loop for the automatic 5-minute-silence inactivity check
    (see _check_idle_characters). A self-managed asyncio loop rather
    than python-telegram-bot's JobQueue, since that requires an extra
    dependency (the `[job-queue]` install extra) not currently installed
    on this server — not worth adding for one simple periodic check.
    """
    while True:
        await asyncio.sleep(IDLE_CHECK_INTERVAL_SECONDS)
        try:
            await _check_idle_characters(application.bot)
        except Exception as e:
            logger.error(f"[idle_check] background loop failed this cycle: {e!r}")
        try:
            await _check_combat_timeouts(application.bot)
        except Exception as e:
            logger.error(f"[combat_timeout] background loop failed this cycle: {e!r}")
        try:
            await _check_pending_loot_votes(application.bot)
        except Exception as e:
            logger.error(f"[loot_vote] background loop failed this cycle: {e!r}")
        try:
            await _check_pending_trades(application.bot)
        except Exception as e:
            logger.error(f"[trade] background loop failed this cycle: {e!r}")
        try:
            _apply_passive_party_regen()
        except Exception as e:
            logger.error(f"[world_tick] passive party regen failed this cycle: {e!r}")
        try:
            _resync_stranded_ai_companions()
        except Exception as e:
            logger.error(f"[world_tick] stranded companion resync failed this cycle: {e!r}")
        try:
            _maybe_revive_standalone_ai_companions()
        except Exception as e:
            logger.error(f"[world_tick] standalone AI companion revival check failed this cycle: {e!r}")
        try:
            await _check_guild_curriculum_cooldowns(application.bot)
        except Exception as e:
            logger.error(f"[guild_curriculum] cooldown auto-credit sweep failed this cycle: {e!r}")

        # Phase 4b: everything below this point genuinely differs per
        # tenant chat (NPC wander state, the "meanwhile" heartbeat, the
        # hourly status post), so it runs once per real known chat_id
        # (db.get_all_chat_ids()) rather than once against the single
        # old _LAST_KNOWN_CHAT_ID global -- one tenant's failure or
        # empty world state doesn't block another's.
        # Real live bug (dev-topic screenshot, 2026-08-10, Coffee:
        # "Support topic is still not working" / "I want this working
        # in unison with the adventure topic"): a real Support question
        # starved out its whole 5-attempt retry budget (~18 real
        # minutes) because this world tick keeps firing its own Ollama
        # calls (NPC heartbeat, hourly status, AI-party turns, Moltbook
        # chatter) every 60s regardless of whether anyone's waiting on
        # an answer -- confirmed via Ollama's own request log showing
        # back-to-back /api/generate calls saturating the single
        # inference slot for the entire window, never leaving a gap
        # long enough for one of Support's attempts to land. Skip this
        # cycle's ambient AI-touching sub-calls (not the deterministic
        # ones -- NPC wander, board-quest expiry, dice auto-roll, world
        # boss spawn stay real-time) whenever a Support answer is
        # actively in flight, so it gets a real shot at the shared slot
        # instead of losing every race to background chatter. They
        # simply run next tick (60s later) once Support is done.
        # Real live finding (2026-08-11, dev-topic investigation into
        # "enemy battle banter never appears"): the mechanism itself is
        # correctly wired (confirmed live -- a direct narrate_action
        # call with include_banter=True returned real quoted dialogue),
        # but a separate call made minutes earlier, under ordinary
        # daytime load, never completed within its own 200s timeout at
        # all and silently fell back to the plain banter-less template.
        # Combat/skill-check narration (ai/dm_agent.py's narrate_action/
        # narrate_skill_check) blocks a real player's own turn exactly
        # the same way a Support answer does, but had none of Support's
        # world-tick-yielding protection -- exactly the gap this
        # project's own prior notes on this starvation pattern flagged
        # as untested. Same mechanism, extended to cover it.
        skip_ambient_ai = is_support_call_active() or is_narration_call_active()
        if skip_ambient_ai:
            logger.info("[world_tick] skipping this cycle's ambient AI calls -- a Support answer or real narration call is in flight")

        for chat_id in db.get_all_chat_ids():
            try:
                _wander_npcs(chat_id)
            except Exception as e:
                logger.error(f"[world_tick] npc wander failed this cycle (chat_id={chat_id}): {e!r}")
            if not skip_ambient_ai:
                try:
                    await _maybe_post_world_heartbeat(application.bot, chat_id)
                except Exception as e:
                    logger.error(f"[world_tick] heartbeat failed this cycle (chat_id={chat_id}): {e!r}")
                try:
                    await _maybe_post_hourly_status_update(application.bot, chat_id)
                except Exception as e:
                    logger.error(f"[hourly_update] failed this cycle (chat_id={chat_id}): {e!r}")

        try:
            await _maybe_spawn_world_boss(application.bot)
        except Exception as e:
            logger.error(f"[world_tick] world boss spawn check failed this cycle: {e!r}")
        try:
            db.expire_stale_board_quests()
        except Exception as e:
            logger.error(f"[board_quests] expiry check failed this cycle: {e!r}")
        try:
            await _maybe_auto_roll_pending_dice(application.bot)
        except Exception as e:
            logger.error(f"[dice] auto-roll check failed this cycle: {e!r}")
        if not skip_ambient_ai:
            try:
                await _ai_party_autonomous_tick(application.bot)
            except Exception as e:
                logger.error(f"[ai_party] autonomous tick failed this cycle: {e!r}")
        try:
            await _maybe_check_moltbook_activity(application.bot)
        except Exception as e:
            logger.error(f"[moltbook_heartbeat] failed this cycle: {e!r}")
        if not skip_ambient_ai:
            try:
                await _maybe_run_moltbook_social_tick(application.bot)
            except Exception as e:
                logger.error(f"[moltbook_social] tick failed this cycle: {e!r}")
        try:
            # Task #159 combat-persistence safety net (see sessions.py's
            # module docstring): a periodic snapshot rather than one on
            # every single mutation, so a redeploy loses at most ~60s of
            # combat progress instead of the WHOLE encounter (the real
            # 2026-07-18 incident this fixes). start_session/end_session
            # also snapshot immediately on their own.
            if sessions._ACTIVE_SESSIONS:
                sessions.save_snapshot()
        except Exception as e:
            logger.error(f"[sessions] periodic snapshot failed this cycle: {e!r}")


class _StartupChatStub:
    """
    Minimal effective_chat stand-in used ONLY to resolve any AI/downed
    turn a restored combat session (task #159) might already be sitting
    on at startup, when there's no real incoming Update to hang a chat
    object off of. Sends go straight through application.bot, same
    underlying call a real Chat.send_message would make.
    """
    def __init__(self, bot, chat_id: int):
        self._bot = bot
        self.id = chat_id

    async def send_message(self, text, **kwargs):
        return await self._bot.send_message(chat_id=self.id, text=text, **kwargs)

    async def send_photo(self, photo, **kwargs):
        # Real live gap, caught 2026-08-09 right after this exact
        # restore path started resolving a spider's turn: this stub
        # only ever implemented send_message, so _maybe_send_monster_
        # image/_maybe_send_battle_formation_image's own send_photo
        # call failed with a plain AttributeError (caught and logged,
        # never fatal -- combat itself kept working via send_message --
        # but the player restoring mid-fight silently lost the art a
        # normal turn would have shown). Same delegate-to-application.
        # bot pattern send_message already uses.
        return await self._bot.send_photo(chat_id=self.id, photo=photo, **kwargs)


class _StartupUpdateStub:
    """Bare Update stand-in for the same startup-only AI-turn-resolution case — see _StartupChatStub."""
    def __init__(self, bot, chat_id: int):
        self.effective_chat = _StartupChatStub(bot, chat_id)


async def _on_startup(application: Application) -> None:
    # Application.create_task ties this loop's lifecycle to the
    # application, so it's cancelled cleanly on shutdown.
    application.create_task(_idle_inactivity_loop(application))

    # Task #159 (real live incident, 2026-07-18): restore any combat
    # session(s) that were active when the bot last stopped, instead of
    # silently wiping them the way the old fully-in-memory design always
    # did. See sessions.py's save_snapshot/load_snapshot for the actual
    # persistence; this just tells anyone still mid-fight that their
    # combat survived the restart, since Coffee was rightly upset last
    # time this happened silently.
    restored = sessions.load_snapshot()
    if restored:
        logger.info(f"[sessions] restored {restored} active combat session(s) from snapshot")
        # 2026-08-01 multi-fight rewrite: _ACTIVE_SESSIONS is now keyed by
        # session_id, not chat_id -- the real chat to announce into is
        # session.chat_id, and locking/re-fetching this specific restored
        # fight uses its own session_id, never the chat-wide shims (a chat
        # can now hold more than one restored session at once).
        for session_id, session in list(sessions._ACTIVE_SESSIONS.items()):
            chat_id = session.chat_id
            try:
                current_name = session.current_participant()["name"] if session.turn_order else "?"
                await application.bot.send_message(
                    chat_id,
                    f"🔄 The bot just restarted, but this fight wasn't lost — "
                    f"combat resumes right where it left off. It's **{current_name}**'s turn.",
                    message_thread_id=topics.thread_id_for(chat_id, "adventure"),
                    parse_mode="Markdown",
                )
                # Real live incident (2026-07-19, Coffee: "the battle seemed
                # to stop"): a restore landing on an AI-controlled (or
                # downed-real-player death-save) turn used to just sit
                # there forever -- _resolve_ai_turns has ALWAYS only ever
                # run as a side-effect of a human/AI action that just
                # finished (_do_attack/_do_cast_spell/etc. each call it
                # right after advancing the turn), and a startup restore
                # is neither of those, so nothing ever kicked the fight
                # forward again. Confirmed by inspection that
                # _resolve_ai_turns only ever touches update.effective_chat
                # (via _safe_send/_notify_main_topic), never anything else
                # on Update, so a minimal synthetic stand-in built straight
                # from application.bot is enough here -- there's no real
                # incoming Update to hang one off at startup. Safe to call
                # unconditionally even when it's already a real player's
                # turn: _resolve_ai_turns just re-sends that turn's
                # announcement + battle menu and returns immediately.
                async with sessions.get_session_lock(session_id):
                    live_session = sessions.get_session_by_id(session_id)
                    if live_session is not None:
                        # Real live incident (2026-07-19, Coffee: "no
                        # enemys left standing... it stopped"): the exact
                        # deadlock _try_end_stale_combat exists to fix
                        # (see its docstring) doesn't just sit there
                        # waiting for a NEW attack to trigger the
                        # cleanup -- if the last attack before a restart
                        # was the one that got interrupted, the restored
                        # snapshot is ALREADY in the stuck state, and
                        # nothing would ever prompt a real player to try
                        # attacking again once they've given up on a
                        # fight that looks frozen. Checked here too, same
                        # startup stub as _resolve_ai_turns just below,
                        # so a restart alone is enough to un-stick it --
                        # confirmed live this exact restore left Wolf 1
                        # and Wolf 2 both at 0 HP with no resolution.
                        # Real live bug (2026-08-19, traced from Sugar's
                        # dev-bridge report "why is my character
                        # attacking in battle when I haven't had a
                        # chance to select what to do" -- the crash fix
                        # in v1.27.253 addressed the SYMPTOM, this is
                        # the actual root cause): to_json_dict/
                        # from_json_dict round-trip the participant
                        # dicts VERBATIM, including the in-memory-only
                        # `_turn_prompt_announced` flag _resolve_ai_
                        # turns sets right after sending a real player's
                        # "it's your turn" battle menu (see that
                        # function's own docstring -- it's meant to
                        # survive only a same-request retry, cleared by
                        # advance_turn() once the turn genuinely ends).
                        # A snapshot saved AFTER that flag was set (e.g.
                        # a restart landing seconds after the prompt
                        # went out) restores it still True -- so this
                        # exact restore call below correctly determines
                        # it's still a real player's turn, but then
                        # silently skips re-sending the battle menu
                        # entirely, thinking it already did. The player
                        # was left with only the bare "bot just
                        # restarted" text above (no reply_markup) and no
                        # working buttons until they thought to type a
                        # plain-text command from memory -- indistin-
                        # guishable, from their side, from the game
                        # ignoring them. Cleared here, unconditionally,
                        # for whoever's current turn actually is right
                        # now -- forces a genuinely fresh re-announce
                        # with real, working buttons on every restore,
                        # same flags advance_turn() itself already pops
                        # on an ordinary turn change.
                        if live_session.turn_order:
                            restored_current = live_session.current_participant()
                            restored_current.pop("_turn_prompt_announced", None)
                            restored_current.pop("_multiattack_announced", None)
                            restored_current.pop("_boss_decision_announced", None)
                        stub_update = _StartupUpdateStub(application.bot, chat_id)
                        if not await _try_end_stale_combat(stub_update, live_session):
                            await _resolve_ai_turns(stub_update, live_session)
            except Exception as e:
                logger.error(f"[sessions] failed to announce restored session for chat {chat_id}: {e!r}")


def build_application() -> Application:
    # concurrent_updates=True is important: without it, python-telegram-bot
    # processes updates ONE AT A TIME. If any single handler ever stalls
    # (e.g. a slow/hung network call), the ENTIRE bot goes silent across
    # every topic until it resolves — exactly the kind of total, unrelated
    # freeze that's hard to diagnose. With this enabled, a stuck handler
    # only affects the update that triggered it.
    # user_data (currently just in-progress character creation, see
    # _begin_character_creation/_continue_character_creation) is
    # otherwise pure in-memory state — a live-reported bug on 2026-07-11
    # traced a player's character creation silently losing its place mid-
    # flow (their next messages, ability score rolls, fell through to
    # generic 'chat' with no creation step to route them into) to an
    # ordinary redeploy landing between two of their messages. Restarts
    # are routine here (see CLAUDE.md's Deployment section), so this
    # needs to survive them. Combat sessions used to be the other half of
    # this same class of bug (a real 2026-07-18 restart-mid-combat
    # incident wiped an active fight outright) -- task #159 fixed that
    # via sessions.py's own separate JSON snapshot/restore (see
    # save_snapshot/load_snapshot there and _on_startup above), since
    # sessions live in a plain module dict, not in this
    # PicklePersistence-backed user_data/bot_data at all.
    persistence = PicklePersistence(filepath="bot_persistence.pickle")
    application = (
        ApplicationBuilder()
        .token(config.BOT_TOKEN)
        .concurrent_updates(True)
        .persistence(persistence)
        .post_init(_on_startup)
        # Real live bug (2026-08-06, Coffee via dev-topic screenshot: "It
        # gave two attacks. Is this a bug?" -- the exact same "Round 4"
        # battle-menu turn prompt sent twice, back to back). Confirmed
        # via bot_live_tmp.log at the exact timestamp: a genuine
        # `[message] send failed, retrying: TimedOut('Timed out')` right
        # before the duplicate. python-telegram-bot's HTTPXRequest
        # defaults to a 5s read/write/connect timeout for every outbound
        # Telegram API call -- far too tight for this box's own already-
        # documented characteristics (root filesystem on a USB flash
        # drive, plus a CPU-bound local Ollama server this same process
        # calls out to mid-request). _safe_send's retry-on-TimedOut logic
        # (by necessity -- Telegram's sendMessage has no idempotency key,
        # so there's no way to tell "genuinely failed" from "succeeded
        # but the ack was slow" apart) means a merely-slow-but-successful
        # send gets retried and duplicated. This doesn't eliminate that
        # possibility (nothing can, without Telegram-side idempotency),
        # but raising these from the 5s library default to something
        # that comfortably covers this box's real observed latency makes
        # a false-timeout meaningfully less likely -- the same reasoning
        # already applied to every Ollama call in ai/*.py (bumped to
        # 200s for the identical underlying reason; see CLAUDE.md).
        .connect_timeout(15)
        .read_timeout(30)
        .write_timeout(30)
        .pool_timeout(15)
        .build()
    )

    # Optional slash-command shortcuts.
    # Alphabetical by command name (task #122, per Coffee: "the /
    # commands are an incoherent mess") -- purely a registration-order
    # cleanup, doesn't change behavior at all.
    application.add_handler(CommandHandler("achievements", achievements_command))
    application.add_handler(CommandHandler("add_admin", add_admin_command))
    application.add_handler(CommandHandler("attack", attack_command))
    application.add_handler(CommandHandler("ban", ban_command))
